114	            ast::Statement::Rollback => {
115	                self.txn_manager.rollback(&mut self.wal)?;
116	                Ok(ResultSet {
117	                    schema: ResultSchema { columns: vec![] },
118	                    rows: vec![],
119	                    rows_affected: 0,
120	                })
121	            }
122	            ast::Statement::CreateTable(create) => self.execute_create_table(create),
123	            ast::Statement::DropTable(drop) => self.execute_drop_table(drop),
124	            ast::Statement::CreateIndex(create) => self.execute_create_index(create),
125	            ast::Statement::DropIndex(drop) => self.execute_drop_index(drop),
126	            ast::Statement::Insert(ins) => self.execute_insert(ins),
127	            ast::Statement::Select(sel) => self.execute_select(sel),
128	            ast::Statement::Update(upd) => self.execute_update(upd),
129	            ast::Statement::Delete(del) => self.execute_delete(del),
130	        }
