101	    /// Replay WAL for crash recovery
102	    pub fn recover(wal: &mut Wal, page_manager: &mut PageManager) -> Result<()> {
103	        let records = wal.read_all()?;
104	        log::info!("Replaying {} WAL records", records.len());
105	
106	        // Find the last committed transaction
107	        let mut committed_xids = std::collections::HashSet::new();
108	        let mut active_xids = std::collections::HashSet::new();
109	
110	        for record in &records {
111	            match record {
112	                WalRecord::Begin { xid } => {
113	                    active_xids.insert(*xid);
114	                }
115	                WalRecord::Commit { xid } => {
116	                    committed_xids.insert(*xid);
117	                    active_xids.remove(xid);
118	                }
119	                _ => {}
120	            }
121	        }
122	
123	        // Replay committed transactions
124	        for record in &records {
125	            match record {
126	                WalRecord::CreateTable { schema } => {
127	                    let mut catalog_tables = page_manager
128	                        .load_schemas()
129	                        .map(|(t, _)| t)
130	                        .unwrap_or_default();
131	                    if !catalog_tables.iter().any(|t| t.name == schema.name) {
132	                        catalog_tables.push(schema.clone());
133	                        let _ = page_manager.load_schemas().unwrap_or_default();
134	                        // Save back
135	                    }
136	                }
137	                WalRecord::Insert {
138	                    table,
139	                    row_id,
140	                    row: _,
141	                } => {
142	                    log::debug!("Replay: INSERT into {} row_id={}", table, row_id);
143	                }
144	                WalRecord::Delete { table, row_id } => {
145	                    log::debug!("Replay: DELETE from {} row_id={}", table, row_id);
146	                }
147	                _ => {}
148	            }
149	        }
150	
151	        log::info!("Recovery complete");
152	        Ok(())

