275	        self.file.seek(SeekFrom::Start(0))?;
276	        let mut records = Vec::new();
277	        loop {
278	            let mut len_buf = [0u8; 4];
279	            match self.file.read_exact(&mut len_buf) {
280	                Ok(_) => {}
281	                Err(ref e) if e.kind() == io::ErrorKind::UnexpectedEof => break,
282	                Err(e) => return Err(MiniDbError::IoError(e)),
283	            }
284	            let len = u32::from_le_bytes(len_buf) as usize;
285	            let mut crc_buf = [0u8; 4];
286	            self.file.read_exact(&mut crc_buf)?;
287	            let stored_crc = u32::from_le_bytes(crc_buf);
288	
289	            let mut payload = vec![0u8; len];
290	            self.file.read_exact(&mut payload)?;
291	
292	            let actual_crc = crc32fast::hash(&payload);
293	            if actual_crc != stored_crc {
294	                log::warn!("WAL CRC mismatch at offset, stopping replay");
295	                break;
296	            }
297	
298	            let record: WalRecord = serde_json::from_slice(&payload)
299	                .map_err(|e| MiniDbError::WalError(e.to_string()))?;
300	            records.push(record);
301	        }
302	        Ok(records)
303	    }

