250	    pub fn append(&mut self, record: &WalRecord) -> Result<u64> {
251	        let payload =
252	            serde_json::to_vec(record).map_err(|e| MiniDbError::WalError(e.to_string()))?;
253	        let crc = crc32fast::hash(&payload);
254	
255	        let offset = self.file.seek(SeekFrom::End(0))?;
256	
257	        // Write: length(4) + crc(4) + payload
258	        let len_bytes = (payload.len() as u32).to_le_bytes();
