389	
390	    fn execute_select_direct(&mut self, sel: ast::SelectStmt) -> Result<ResultSet> {
391	        // Resolve table name
392	        let table_name = match &sel.from {
393	            ast::FromClause::Table(name) => name.clone(),
394	            ast::FromClause::Join { left, .. } => match left.as_ref() {
395	                ast::FromClause::Table(name) => name.clone(),
396	                _ => return Err(MiniDbError::SqlError("Only simple joins supported".into())),
397	            },
398	        };
399	
400	        let schema = self.catalog.get_table(&table_name)?.clone();
401	        let heap = self
402	            .heap_files
403	            .get(&table_name)
404	            .ok_or_else(|| MiniDbError::TableNotFound(table_name.clone()))?;
405	
406	        // Collect all rows with row IDs
407	        let mut result_rows: Vec<(RowId, Row)> = heap
408	            .get_all_rows()
409	            .into_iter()
410	            .map(|(rid, row)| (rid, row.clone()))
411	            .collect();
412	
413	        // Handle JOIN
414	        if let ast::FromClause::Join { left: _, right, on } = &sel.from {
415	            let right_table = match right.as_str() {
416	                name => name,
417	            };
418	            let right_schema = self.catalog.get_table(right_table)?.clone();
419	            let right_heap = self
420	                .heap_files
421	                .get(right_table)
422	                .ok_or_else(|| MiniDbError::TableNotFound(right_table.to_string()))?;
423	            let right_rows: Vec<Row> = right_heap
424	                .get_all_rows()
425	                .into_iter()
426	                .map(|(_, row)| row.clone())
427	                .collect();
428	
429	            let mut joined_rows = Vec::new();
430	            for (left_rid, left_row) in &result_rows {
431	                for right_row in &right_rows {
432	                    let mut combined = left_row.clone();
433	                    combined.extend_from_slice(right_row);
434	                    let combined_schema = merge_schemas(&schema, &right_schema);
435	                    let cond = evaluate_expr(on, &combined, &combined_schema)?;
436	                    if cond.as_bool() == Some(true) {
437	                        joined_rows.push((*left_rid, combined));
438	                    }
439	                }
440	            }
441	            result_rows = joined_rows;
442	        }
443	
444	        // Apply WHERE filter
445	        if let Some(ref where_e) = sel.where_clause {
446	            result_rows.retain(|(_, row)| {
447	                evaluate_expr(where_e, row, &schema)
448	                    .map(|v| v.as_bool() == Some(true))
449	                    .unwrap_or(false)
450	            });
451	        }
452	
453	        // Apply ORDER BY
454	        if !sel.order_by.is_empty() {
455	            let order_by = sel.order_by.clone();
456	            result_rows.sort_by(|a, b| {
457	                for ob in &order_by {
458	                    let val_a = evaluate_expr(&ob.expr, &a.1, &schema).unwrap_or(Value::Null);
459	                    let val_b = evaluate_expr(&ob.expr, &b.1, &schema).unwrap_or(Value::Null);
460	                    let cmp = compare_values_exec(&val_a, &val_b);
461	                    if cmp != std::cmp::Ordering::Equal {
462	                        return if ob.ascending { cmp } else { cmp.reverse() };
463	                    }
464	                }
465	                std::cmp::Ordering::Equal
466	            });
467	        }
468	
469	        // Apply OFFSET
470	        let offset = sel.offset.unwrap_or(0) as usize;
471	        if offset > 0 && offset < result_rows.len() {
472	            result_rows = result_rows[offset..].to_vec();
473	        } else if offset >= result_rows.len() {
474	            result_rows.clear();
475	        }
476	
477	        // Apply LIMIT
478	        if let Some(limit) = sel.limit {
479	            let limit = limit as usize;
480	            if limit < result_rows.len() {
481	                result_rows.truncate(limit);
482	            }
483	        }
484	
485	        // Project columns
486	        let mut result_schema_cols = Vec::new();
487	        let mut projected_rows = Vec::new();
488	
489	        // Build schema and project rows
490	        let is_star = sel
491	            .columns
492	            .iter()
493	            .any(|c| matches!(c, ast::SelectColumn::Star));
494	
495	        if is_star {
496	            for c in &schema.columns {
497	                result_schema_cols.push((c.name.clone(), c.col_type));
498	            }
499	            for (_, row) in &result_rows {
500	                projected_rows.push(row.clone());
501	            }
502	        } else {
503	            // Build column schema
504	            for col in &sel.columns {
505	                match col {
506	                    ast::SelectColumn::Expr(expr, alias) => {
507	                        let col_name = alias.clone().unwrap_or_else(|| format!("{:?}", expr));
508	                        let val = if let Some((_, row)) = result_rows.first() {
509	                            evaluate_expr(expr, row, &schema)?
510	                        } else {
511	                            Value::Null
512	                        };
513	                        let col_type = val.column_type().unwrap_or(ColumnType::Text);
514	                        result_schema_cols.push((col_name, col_type));
515	                    }
516	                    _ => {}
517	                }
518	            }
519	            // Project rows
520	            for (_, row) in &result_rows {
521	                let mut projected = Vec::new();
522	                for col in &sel.columns {
523	                    match col {
524	                        ast::SelectColumn::Expr(expr, _) => {
