282	    fn try_index_scan(&self, plan: &LogicalPlan, predicate: &ast::Expr) -> Option<LogicalPlan> {
283	        // Try to extract a simple equality or range predicate on an indexed column
284	        if let LogicalPlan::Scan { table, .. } = plan {
285	            match predicate {
286	                ast::Expr::BinaryOp { left, op, right } => {
287	                    if let (ast::Expr::Column(col), ast::Expr::Literal(val)) =
288	                        (left.as_ref(), right.as_ref())
289	                    {
290	                        let scan_op = match op {
291	                            ast::BinOp::Eq => ScanOp::Eq,
292	                            ast::BinOp::Lt => ScanOp::Lt,
293	                            ast::BinOp::Le => ScanOp::Le,
294	                            ast::BinOp::Gt => ScanOp::Gt,
295	                            ast::BinOp::Ge => ScanOp::Ge,
296	                            _ => return None,
297	                        };
298	                        // Find matching index
299	                        if let Some(idx) = self
300	                            .indexes
301	                            .iter()
302	                            .find(|i| i.table == *table && i.column == *col)
303	                        {
304	                            return Some(LogicalPlan::IndexScan {
305	                                table: table.clone(),
306	                                index_name: idx.name.clone(),
307	                                column: col.clone(),
308	                                value: val.clone(),
309	                                op: scan_op,
310	                            });
311	                        }
312	                    }
313	                    // Also check reversed: literal op column
314	                    if let (ast::Expr::Literal(val), ast::Expr::Column(col)) =
315	                        (left.as_ref(), right.as_ref())
316	                    {
317	                        let scan_op = match op {
318	                            ast::BinOp::Eq => ScanOp::Eq,
319	                            ast::BinOp::Lt => ScanOp::Gt,
320	                            ast::BinOp::Le => ScanOp::Ge,
321	                            ast::BinOp::Gt => ScanOp::Lt,
322	                            ast::BinOp::Ge => ScanOp::Le,
323	                            _ => return None,
324	                        };
325	                        if let Some(idx) = self
326	                            .indexes
327	                            .iter()
328	                            .find(|i| i.table == *table && i.column == *col)
329	                        {
330	                            return Some(LogicalPlan::IndexScan {
331	                                table: table.clone(),
332	                                index_name: idx.name.clone(),
333	                                column: col.clone(),
334	                                value: val.clone(),
335	                                op: scan_op,
336	                            });
337	                        }
338	                    }
339	                }
340	                _ => {}
341	            }
342	        }
343	        None
344	    }

