219	    fn plan_select(&self, sel: ast::SelectStmt) -> Result<LogicalPlan, String> {
220	        let mut plan = self.plan_from(sel.from)?;
221	
222	        // Add filter if WHERE clause exists
223	        if let Some(where_e) = sel.where_clause.clone() {
224	            // Check if we can use an index scan
