226	                plan = index_plan;
227	            } else {
228	                plan = LogicalPlan::Filter {
229	                    input: Box::new(plan),
230	                    predicate: where_e,
231	                };
232	            }
233	        }
234	
235	        // Add sort
236	        if !sel.order_by.is_empty() {
237	            plan = LogicalPlan::Sort {
238	                input: Box::new(plan),
239	                order_by: sel.order_by,
240	            };
241	        }
242	
243	        // Add limit/offset
244	        if sel.limit.is_some() || sel.offset.is_some() {
245	            plan = LogicalPlan::Limit {
246	                input: Box::new(plan),
247	                limit: sel.limit.unwrap_or(i64::MAX),
248	                offset: sel.offset.unwrap_or(0),
249	            };
250	        }
251	
252	        // Add projection
253	        plan = LogicalPlan::Project {
254	            input: Box::new(plan),
255	            columns: sel.columns,
256	        };
257	
258	        Ok(plan)
259	    }
