198	    fn read_string(&mut self) -> Result<String, (String, usize, usize)> {
199	        let start_line = self.line;
200	        let start_col = self.column;
201	        let mut s = String::new();
202	        loop {
203	            match self.advance() {
204	                None => {
205	                    return Err((
206	                        format!("Unterminated string literal"),
207	                        start_line,
208	                        start_col,
209	                    ))
210	                }
211	                Some('\'') => {
212	                    // Check for escaped quote ''
213	                    if self.peek() == Some('\'') {
214	                        s.push('\'');
215	                        self.advance();
216	                    } else {
217	                        return Ok(s);
218	                    }
219	                }
220	                Some(ch) => s.push(ch),
221	            }
222	        }
223	    }

299	    pub fn tokenize(&mut self) -> Result<Vec<Token>, (String, usize, usize)> {
300	        let mut tokens = Vec::new();
301	        loop {
302	            self.skip_whitespace();
303	            let line = self.line;
304	            let col = self.column;
305	            match self.peek() {
306	                None => {
307	                    tokens.push(Token::Eof);
308	                    break;
309	                }
310	                Some('-') => {
311	                    self.advance();
312	                    if self.peek() == Some('-') {
313	                        self.advance();
314	                        self.skip_line_comment();
315	                    } else {
316	                        tokens.push(Token::Minus);
317	                    }
318	                }
319	                Some('/') => {
320	                    self.advance();
321	                    tokens.push(Token::Slash);
322	                }
323	                Some('+') => {
324	                    self.advance();
325	                    tokens.push(Token::Plus);
326	                }
327	                Some('*') => {
328	                    self.advance();
329	                    tokens.push(Token::Star);
330	                }
331	                Some('(') => {
332	                    self.advance();
333	                    tokens.push(Token::LParen);
334	                }
335	                Some(')') => {
336	                    self.advance();
337	                    tokens.push(Token::RParen);
338	                }
339	                Some(',') => {
340	                    self.advance();
341	                    tokens.push(Token::Comma);
342	                }
343	                Some(';') => {
344	                    self.advance();
345	                    tokens.push(Token::Semicolon);
346	                    self.at_stmt_start = true;
347	                }
348	                Some('.') => {
349	                    self.advance();
350	                    if self.at_stmt_start && self.peek().map_or(false, |c| c.is_alphabetic()) {
351	                        let mut name = String::new();
352	                        while let Some(ch) = self.peek() {
353	                            if ch.is_alphanumeric() || ch == '_' {
354	                                name.push(ch);
355	                                self.advance();
356	                            } else {
357	                                break;
358	                            }
359	                        }
360	                        tokens.push(Token::DotCommand(name));
361	                    } else {
362	                        tokens.push(Token::Dot);
363	                    }
364	                }
365	                Some('=') => {
366	                    self.advance();
367	                    tokens.push(Token::Eq);
368	                }
369	                Some('<') => {
370	                    self.advance();
371	                    if self.peek() == Some('>') {
372	                        self.advance();
373	                        tokens.push(Token::Ne);
374	                    } else if self.peek() == Some('=') {
375	                        self.advance();
376	                        tokens.push(Token::Le);
377	                    } else {
378	                        tokens.push(Token::Lt);
379	                    }
380	                }
381	                Some('>') => {
382	                    self.advance();
383	                    if self.peek() == Some('=') {
384	                        self.advance();
385	                        tokens.push(Token::Ge);
386	                    } else {
387	                        tokens.push(Token::Gt);
388	                    }
389	                }
390	                Some('|') => {
391	                    self.advance();
392	                    if self.peek() == Some('|') {
393	                        self.advance();
394	                        tokens.push(Token::Pipe);
395	                    } else {
396	                        return Err(("Unexpected character: |".into(), line, col));
397	                    }
398	                }
399	                Some('\'') => {
400	                    self.advance();
401	                    let s = self.read_string()?;
402	                    tokens.push(Token::String(s));
403	                }
404	                Some(ch) if ch.is_ascii_digit() => {
405	                    self.advance();
406	                    tokens.push(self.read_number());
407	                }
408	                Some(ch) if ch.is_alphabetic() || ch == '_' => {
409	                    self.advance();
410	                    tokens.push(self.read_ident());
411	                }
412	                Some(ch) => {
413	                    self.advance();
414	                    return Err((format!("Unexpected character: '{}'", ch), line, col));
415	                }
416	            }
417	            // After pushing any token other than Semicolon, mark that we're no longer at statement start
418	            if !matches!(tokens.last(), Some(Token::Semicolon) | Some(Token::Eof)) {
419	                self.at_stmt_start = false;
420	            }
421	        }
422	        Ok(tokens)
423	    }
424	}
