 88	    pub fn get_page(&mut self, id: PageId) -> Option<&Page> {
 89	        if self.pages.contains_key(&id) {
 90	            return self.pages.get(&id);
 91	        }
 92	        // Try to load from disk
 93	        let offset = id.0 * PAGE_SIZE as u64;
 94	        let mut page = Page::new(id);
 95	        if self.file.seek(SeekFrom::Start(offset)).is_ok() {
 96	            if self.file.read_exact(&mut page.data).is_ok() {
 97	                self.pages.insert(id, page);
 98	                return self.pages.get(&id);
 99	            }
100	        }
101	        None
102	    }
103	
104	    pub fn get_page_mut(&mut self, id: PageId) -> Option<&mut Page> {
105	        if !self.pages.contains_key(&id) {
106	            let offset = id.0 * PAGE_SIZE as u64;
107	            let mut page = Page::new(id);
108	            if self.file.seek(SeekFrom::Start(offset)).is_ok() {
109	                if self.file.read_exact(&mut page.data).is_ok() {
110	                    self.pages.insert(id, page);
111	                }
112	            }
113	        }
114	        self.pages.get_mut(&id)
115	    }
116	
117	    pub fn flush_page(&mut self, id: PageId) -> Result<()> {
118	        if let Some(page) = self.pages.get(&id) {
119	            let offset = id.0 * PAGE_SIZE as u64;
120	            self.file.seek(SeekFrom::Start(offset))?;
121	            self.file.write_all(&page.data)?;
122	        }
123	        Ok(())
124	    }
125	
126	    pub fn flush_all(&mut self) -> Result<()> {
127	        let page_ids: Vec<PageId> = self.pages.keys().cloned().collect();
128	        for id in page_ids {
129	            self.flush_page(id)?;
130	        }
131	        self.file.sync_all()?;
132	        Ok(())

