210	                    // The new rows are the last `affected` rows
211	                    let new_rows: Vec<_> = all_rows.into_iter().skip(old_count).collect();
212	                    for (rid, _) in new_rows {
213	                        self.undo_log.push(UndoEntry::Insert {
214	                            table: ins.table.clone(),
215	                            row_id: rid,
216	                        });
217	                    }
218	                }
219	
220	                if !self.txn_mgr.in_transaction() {
221	                    self.wal
222	                        .append(crate::storage::wal::WalOp::Commit { tx_id: 0 })?;
223	                }

744	            ctx.heap.insert_row(&self.table, &row)?;
745	
746	            // Update indexes
747	            let indexes: Vec<(String, String)> = ctx
748	                .catalog
749	                .all_indexes()
750	                .iter()
751	                .filter(|i| i.table == self.table)
752	                .map(|i| (i.name.clone(), i.column.clone()))
753	                .collect();
754	
755	            for (idx_name, col_name) in &indexes {
756	                if let Some(col_idx) = table_info.column_index(col_name) {
757	                    let key = row[col_idx].clone();
758	                    let all_rows = ctx.heap.scan_table(&self.table)?;
759	                    if let Some((rid, _)) = all_rows.last() {
760	                        if let Some(btree) = ctx.catalog.btree_indexes.get_mut(idx_name) {
761	                            btree.insert(key, *rid);
762	                        }
763	                    }
764	                }
765	            }
766	
767	            count += 1;
768	        }

88	    pub fn write_page(&mut self, page: &Page) -> Result<()> {
89	        if page.id.0 >= self.num_pages {
90	            self.num_pages = page.id.0 + 1;
91	        }
92	        self.file
93	            .seek(SeekFrom::Start(page.id.0 * PAGE_SIZE as u64))?;
94	        self.file.write_all(&page.data)?;
95	        self.file.flush()?;
96	        Ok(())

134	    // Open database
