763	pub fn run_eval(db: &mut MiniDb, sql: &str) -> Result<()> {
764	    let stmts: Vec<&str> = sql.split(';').filter(|s| !s.trim().is_empty()).collect();
765	
766	    for stmt_sql in &stmts {
767	        let trimmed = stmt_sql.trim();
768	        if trimmed.is_empty() {
769	            continue;
770	        }
771	
772	        if trimmed.starts_with('.') {
773	            match db.meta_command(trimmed) {
774	                Ok(Some(output)) => print!("{}", output),
775	                Ok(None) => break,
776	                Err(e) => return Err(e),
777	            }
778	            continue;
779	        }
780	
781	        match db.execute_sql(trimmed) {
782	            Ok(result) => {
783	                let output = db.format_result(&result);
784	                if !output.is_empty() {
785	                    print!("{}", output);
786	                }
787	                if !db.quiet {
788	                    match &result {
789	                        ExecResult::Rows { rows, .. } => {
790	                            eprintln!(
791	                                "ok {} {}",
792	                                rows.len(),
793	                                if rows.len() == 1 { "row" } else { "rows" }
794	                            );
795	                        }
796	                        ExecResult::Changed { rows_affected } => {
797	                            eprintln!(
798	                                "ok {} {}",
799	                                rows_affected,
800	                                if *rows_affected == 1 { "row" } else { "rows" }
801	                            );
802	                        }
803	                    }
804	                }
805	            }
806	            Err(e) => return Err(e),
807	        }

84	    pub fn execute_sql(&mut self, sql: &str) -> Result<ExecResult> {
85	        let mut lexer = Lexer::new(sql);
86	        let tokens = lexer.tokenize()?;
87	        let mut parser = Parser::new(tokens);
88	        let stmts = parser.parse_statements()?;
89	
90	        let mut last_result = None;
91	        for stmt in stmts {
92	            last_result = Some(self.execute_statement(&stmt)?);
93	        }
94	        last_result.ok_or_else(|| MiniDbError::Sql("no statement to execute".into()))
95	    }

 97	    pub fn execute_statement(&mut self, stmt: &Statement) -> Result<ExecResult> {
 98	        match stmt {
 99	            Statement::Begin => {
100	                self.txn_mgr.begin()?;
101	                self.undo_log.clear();
102	                Ok(ExecResult::Changed { rows_affected: 0 })
103	            }
104	            Statement::Commit => {
105	                let tx_id = self
106	                    .txn_mgr
107	                    .active_tx_id()
108	                    .ok_or_else(|| MiniDbError::Transaction("no active transaction".into()))?;
109	                self.txn_mgr.commit(tx_id, &mut self.wal)?;
110	                self.undo_log.clear();
111	                Ok(ExecResult::Changed { rows_affected: 0 })
112	            }
113	            Statement::Rollback => {
114	                let tx_id = self
115	                    .txn_mgr
116	                    .active_tx_id()
117	                    .ok_or_else(|| MiniDbError::Transaction("no active transaction".into()))?;
118	
119	                // Replay undo log in reverse
120	                for entry in self.undo_log.drain(..).rev() {
121	                    match entry {
122	                        UndoEntry::Insert { table, row_id } => {
123	                            let _ = self.heap.delete_row(&table, &row_id);
124	                        }
125	                        UndoEntry::Update {
126	                            table,
127	                            row_id,
128	                            old_row,
129	                        } => {
130	                            let _ = self.heap.update_row(&table, &row_id, &old_row);
131	                        }
132	                        UndoEntry::Delete {
133	                            table,
134	                            row_id: _,
135	                            old_row,
136	                        } => {
137	                            let _ = self.heap.insert_row(&table, &old_row);
138	                        }
139	                    }
140	                }
141	
142	                self.txn_mgr.rollback(tx_id, &mut self.wal)?;
143	                Ok(ExecResult::Changed { rows_affected: 0 })
144	            }
145	            Statement::CreateTable(create) => {
146	                let info = TableInfo {
147	                    name: create.name.clone(),
148	                    columns: create.columns.clone(),
149	                };
150	                self.catalog.create_table(info)?;
151	                let schema_data = bincode_serialize_columns(&create.columns);
152	                self.wal.append(crate::storage::wal::WalOp::CreateTable {
153	                    tx_id: self.txn_mgr.active_tx_id().unwrap_or(0),
154	                    table: create.name.clone(),
155	                    schema_data,
156	                })?;
157	                Ok(ExecResult::Changed { rows_affected: 0 })

189	            Statement::Select(sel) => self.execute_select(sel),
190	            Statement::Insert(ins) => {
191	                let in_txn = self.txn_mgr.in_transaction();
192	                let old_count = if in_txn {
193	                    self.heap.scan_table(&ins.table)?.len()
194	                } else {
195	                    0
196	                };
197	
198	                let mut op =
199	                    InsertOperator::new(ins.table.clone(), ins.columns.clone(), ins.rows.clone());
200	                let mut ctx = ExecContext {
201	                    catalog: &mut self.catalog,
202	                    heap: &mut self.heap,
203	                };
204	                op.execute(&mut ctx)?;
205	                let affected = op.rows_affected;
206	
207	                if in_txn {
208	                    // Record undo: find the newly inserted row(s)
209	                    let all_rows = self.heap.scan_table(&ins.table)?;
210	                    // The new rows are the last `affected` rows
211	                    let new_rows: Vec<_> = all_rows.into_iter().skip(old_count).collect();
212	                    for (rid, _) in new_rows {
213	                        self.undo_log.push(UndoEntry::Insert {
214	                            table: ins.table.clone(),
215	                            row_id: rid,
216	                        });
217	                    }
218	                }
219	
220	                if !self.txn_mgr.in_transaction() {
221	                    self.wal
222	                        .append(crate::storage::wal::WalOp::Commit { tx_id: 0 })?;
223	                }
224	
225	                Ok(ExecResult::Changed {
226	                    rows_affected: affected,
227	                })
228	            }
229	            Statement::Update(upd) => {
230	                let in_txn = self.txn_mgr.in_transaction();
231	
232	                // Capture old state for undo
233	                let old_rows: Vec<(RowId, Row)> = if in_txn {
234	                    let table_info = self.catalog.get_table(&upd.table)?;
235	                    let col_names: Vec<String> =
236	                        table_info.columns.iter().map(|c| c.name.clone()).collect();
237	                    let all_rows = self.heap.scan_table(&upd.table)?;
238	                    if let Some(ref where_expr) = upd.where_clause {
239	                        all_rows
240	                            .into_iter()
241	                            .filter(|(_, row)| {
242	                                evaluate_expr(where_expr, row, &col_names)
243	                                    .map(|v| v.as_bool().unwrap_or(false))
244	                                    .unwrap_or(false)
245	                            })
246	                            .collect()
247	                    } else {
248	                        all_rows
249	                    }
250	                } else {
251	                    vec![]
252	                };
253	
254	                let table_info = self.catalog.get_table(&upd.table)?.clone();
255	                let col_names: Vec<String> =
256	                    table_info.columns.iter().map(|c| c.name.clone()).collect();
257	                let mut op = UpdateOperator::new(
258	                    upd.table.clone(),
259	                    upd.assignments.clone(),
260	                    upd.where_clause.clone(),
261	                    col_names,
262	                );
263	                let mut ctx = ExecContext {
264	                    catalog: &mut self.catalog,
265	                    heap: &mut self.heap,
266	                };
267	                op.execute(&mut ctx)?;
268	                let affected = op.rows_affected;
269	
270	                if in_txn {
271	                    for (rid, old_row) in old_rows {
272	                        self.undo_log.push(UndoEntry::Update {
273	                            table: upd.table.clone(),
274	                            row_id: rid,
275	                            old_row,
276	                        });
277	                    }
278	                }
279	
280	                if !self.txn_mgr.in_transaction() {
281	                    self.wal
282	                        .append(crate::storage::wal::WalOp::Commit { tx_id: 0 })?;
283	                }
284	
285	                Ok(ExecResult::Changed {
286	                    rows_affected: affected,
287	                })
288	            }
289	            Statement::Delete(del) => {
290	                let in_txn = self.txn_mgr.in_transaction();
291	
292	                // Capture old state for undo
293	                let old_rows: Vec<(RowId, Row)> = if in_txn {
294	                    let table_info = self.catalog.get_table(&del.table)?;
295	                    let col_names: Vec<String> =
296	                        table_info.columns.iter().map(|c| c.name.clone()).collect();
297	                    let all_rows = self.heap.scan_table(&del.table)?;
298	                    if let Some(ref where_expr) = del.where_clause {
299	                        all_rows
300	                            .into_iter()
301	                            .filter(|(_, row)| {
302	                                evaluate_expr(where_expr, row, &col_names)
303	                                    .map(|v| v.as_bool().unwrap_or(false))
304	                                    .unwrap_or(false)
305	                            })
306	                            .collect()
307	                    } else {
308	                        all_rows
309	                    }
310	                } else {
311	                    vec![]
312	                };
313	
314	                let table_info = self.catalog.get_table(&del.table)?.clone();
315	                let col_names: Vec<String> =
316	                    table_info.columns.iter().map(|c| c.name.clone()).collect();
317	                let mut op =
318	                    DeleteOperator::new(del.table.clone(), del.where_clause.clone(), col_names);
319	                let mut ctx = ExecContext {
320	                    catalog: &mut self.catalog,
321	                    heap: &mut self.heap,
322	                };
323	                op.execute(&mut ctx)?;
324	                let affected = op.rows_affected;
325	
326	                if in_txn {
327	                    for (rid, old_row) in old_rows {
328	                        self.undo_log.push(UndoEntry::Delete {
329	                            table: del.table.clone(),
330	                            row_id: rid,
331	                            old_row,
332	                        });
333	                    }
334	                }
335	
336	                if !self.txn_mgr.in_transaction() {
337	                    self.wal
338	                        .append(crate::storage::wal::WalOp::Commit { tx_id: 0 })?;
339	                }
340	
341	                Ok(ExecResult::Changed {
342	                    rows_affected: affected,
343	                })
344	            }

34	    pub fn begin(&mut self) -> Result<u64> {
35	        if self.active_tx.is_some() {
36	            return Err(MiniDbError::Transaction(
37	                "nested transactions not supported".into(),
38	            ));
39	        }
40	        let tx_id = self.next_tx_id;
41	        self.next_tx_id += 1;
42	        self.transactions.insert(
43	            tx_id,
44	            Transaction {
45	                id: tx_id,
46	                status: TxnStatus::Active,
47	                operations: Vec::new(),
48	            },
49	        );
50	        self.active_tx = Some(tx_id);
51	        log::info!("Transaction {} started", tx_id);
52	        Ok(tx_id)
53	    }
