55	    pub fn commit(&mut self, tx_id: u64, wal: &mut Wal) -> Result<()> {
56	        let tx = self.transactions.get_mut(&tx_id).ok_or_else(|| {
57	            MiniDbError::Transaction(format!("transaction {} does not exist", tx_id))
58	        })?;
59	
60	        if tx.status != TxnStatus::Active {
61	            return Err(MiniDbError::Transaction(format!(
62	                "transaction {} is not active",
63	                tx_id
64	            )));
65	        }
66	
67	        // Write commit record to WAL
68	        wal.append(WalOp::Commit { tx_id })?;
69	
70	        tx.status = TxnStatus::Committed;
71	        if self.active_tx == Some(tx_id) {
72	            self.active_tx = None;
73	        }
74	
75	        log::info!("Transaction {} committed", tx_id);
76	        Ok(())

