124	    /// Replay WAL records to rebuild transaction state on startup
125	    pub fn replay_wal(&mut self, records: &[WalRecord]) {
126	        for record in records {
127	            match &record.op {
128	                WalOp::Begin { tx_id } => {
129	                    self.transactions.insert(
130	                        *tx_id,
131	                        Transaction {
132	                            id: *tx_id,
133	                            status: TxnStatus::Active,
134	                            operations: Vec::new(),
135	                        },
136	                    );
137	                    if *tx_id >= self.next_tx_id {
138	                        self.next_tx_id = tx_id + 1;
139	                    }
140	                }
141	                WalOp::Commit { tx_id } => {
142	                    if let Some(tx) = self.transactions.get_mut(tx_id) {
143	                        tx.status = TxnStatus::Committed;
144	                    }
145	                }
146	                WalOp::Rollback { tx_id } => {
147	                    if let Some(tx) = self.transactions.get_mut(tx_id) {
148	                        tx.status = TxnStatus::Aborted;
149	                    }
150	                }
151	                _ => {
152	                    // Record the operation in the transaction
153	                    if let Some(tx_id) = Self::tx_id_from_op(&record.op) {
154	                        if let Some(tx) = self.transactions.get_mut(&tx_id) {
155	                            tx.operations.push(record.clone());
156	                        }
157	                    }
158	                }
159	            }
160	        }
161	    }

