356	    fn read_record_from(file: &mut File) -> Result<Option<(WalRecord, usize)>> {
357	        let mut size_buf = [0u8; 4];
358	        match file.read_exact(&mut size_buf) {
359	            Ok(()) => {}
360	            Err(ref e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
361	            Err(e) => return Err(MiniDbError::Io(e.to_string())),
362	        }
363	        let record_len = u32::from_le_bytes(size_buf) as usize;
364	
365	        if record_len < 4 {
366	            return Err(MiniDbError::Storage("invalid WAL record length".into()));
367	        }
368	
369	        let mut record_buf = vec![0u8; record_len];
370	        file.read_exact(&mut record_buf)?;
371	
372	        let stored_crc =
373	            u32::from_le_bytes(record_buf[record_len - 4..record_len].try_into().unwrap());
374	        let data = &record_buf[..record_len - 4];
375	        let computed_crc = crc32_of(data);
