383	            return Err(MiniDbError::Storage(
384	                "WAL CRC mismatch - torn write detected".into(),
385	            ));
386	        }
387	
388	        let op = WalOp::decode(data)?;
389	        let total_size = 4 + record_len;
390	
391	        // Read the LSN from the record
392	        // For simplicity, we track lsn positionally
393	        Ok(Some((WalRecord { op, lsn: 0 }, total_size)))

396	    pub fn append(&mut self, op: WalOp) -> Result<WalRecord> {
397	        let data = op.encode();
398	        let crc = crc32_of(&data);
399	        let record_len = data.len() as u32 + 4; // data + crc32
400	
401	        // Write: [4-byte total_len][data][4-byte crc32]
402	        let len_buf = record_len.to_le_bytes();
403	        self.file.write_all(&len_buf)?;
404	        self.file.write_all(&data)?;
405	        self.file.write_all(&crc.to_le_bytes())?;
406	        self.file.flush()?;
407	
408	        let lsn = self.next_lsn;
409	        self.next_lsn += 1;
410	
411	        log::debug!("WAL append lsn={}: {:?}", lsn, std::mem::discriminant(&op));
412	
413	        Ok(WalRecord { op, lsn })
414	    }
