202	/// Replay WAL to recover committed-but-unflushed transactions
203	pub fn replay_wal(wal_path: &Path) -> Result<Vec<WalRecord>> {
204	    if !wal_path.exists() {
205	        return Ok(Vec::new());
206	    }
207	
208	    let mut reader = WalReader::new(wal_path)?;
209	    let records = reader.read_all()?;
210	
211	    // Find committed transactions
212	    let mut committed = std::collections::HashSet::new();
213	    for record in &records {
214	        if let WalRecord::CommitTxn { txn_id } = record {
215	            committed.insert(*txn_id);
216	        }
217	    }
218	
219	    // Only return records from committed transactions
220	    let replay_records: Vec<WalRecord> = records
221	        .into_iter()
222	        .filter(|r| {
223	            let txn_id = match r {
224	                WalRecord::BeginTxn { txn_id } => *txn_id,
225	                WalRecord::Write { txn_id, .. } => *txn_id,
226	                WalRecord::PageCreate { txn_id, .. } => *txn_id,
227	                WalRecord::CommitTxn { txn_id } => *txn_id,
228	            };
229	            committed.contains(&txn_id)
230	        })
231	        .collect();
232	
233	    debug!("WAL replay: {} records to replay", replay_records.len());
234	    Ok(replay_records)
235	}

