28	impl WalRecord {
29	    pub fn encode(&self) -> Vec<u8> {
30	        let mut buf = Vec::new();
31	        match self {
32	            WalRecord::BeginTxn { txn_id } => {
33	                buf.push(1); // type
34	                buf.extend_from_slice(&txn_id.to_le_bytes());
35	            }
36	            WalRecord::Write {
37	                txn_id,
38	                page_id,
39	                offset,
40	                data,
41	            } => {
42	                buf.push(2); // type
43	                buf.extend_from_slice(&txn_id.to_le_bytes());
44	                buf.extend_from_slice(&page_id.to_le_bytes());
45	                buf.extend_from_slice(&offset.to_le_bytes());
46	                buf.extend_from_slice(&(data.len() as u32).to_le_bytes());
47	                buf.extend_from_slice(data);
48	            }
49	            WalRecord::PageCreate { txn_id, page_id } => {
50	                buf.push(3); // type
51	                buf.extend_from_slice(&txn_id.to_le_bytes());
52	                buf.extend_from_slice(&page_id.to_le_bytes());
53	            }
54	            WalRecord::CommitTxn { txn_id } => {
55	                buf.push(4); // type
56	                buf.extend_from_slice(&txn_id.to_le_bytes());
57	            }
58	        }
59	
60	        // Add CRC32
61	        let crc = crc32fast::hash(&buf);
62	        let mut result = buf;
63	        result.extend_from_slice(&crc.to_le_bytes());
64	        result
65	    }

67	    pub fn decode(data: &[u8]) -> Result<Self> {
68	        if data.len() < 5 {
69	            return Err(MiniDbError::StorageError(
70	                "WAL record too short".to_string(),
71	            ));
72	        }
73	
74	        // Verify CRC
75	        let payload = &data[..data.len() - 4];
76	        let stored_crc = u32::from_le_bytes([
77	            data[data.len() - 4],
78	            data[data.len() - 3],
79	            data[data.len() - 2],
80	            data[data.len() - 1],
81	        ]);
82	        let computed_crc = crc32fast::hash(payload);
83	        if stored_crc != computed_crc {
84	            return Err(MiniDbError::StorageError(
85	                "WAL record CRC mismatch (torn write)".to_string(),
86	            ));
87	        }

178	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
179	        let mut records = Vec::new();
180	        loop {
181	            let mut len_buf = [0u8; 4];
182	            match self.file.read_exact(&mut len_buf) {
183	                Ok(()) => {}
184	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
185	                Err(e) => return Err(e.into()),
186	            }
187	            let len = u32::from_le_bytes(len_buf) as usize;
188	            if len > PAGE_SIZE * 2 {
189	                return Err(MiniDbError::StorageError(
190	                    "WAL record too large".to_string(),
191	                ));
192	            }
193	            let mut data = vec![0u8; len];
194	            self.file.read_exact(&mut data)?;
195	            let record = WalRecord::decode(&data)?;
196	            records.push(record);
197	        }
198	        Ok(records)

