 7	/// B-tree key: (index_key_bytes, row_id_page, row_id_slot)
 8	/// For simplicity, keys are stored as Vec<u8> (serialized values)
 9	#[derive(Debug, Clone, PartialEq, Eq)]
10	pub struct BTreeKey {
11	    pub key: Vec<u8>,
12	    pub page_id: u64,
13	    pub slot: u16,
14	}
15	
16	impl Ord for BTreeKey {
17	    fn cmp(&self, other: &Self) -> Ordering {
18	        self.key
19	            .cmp(&other.key)
20	            .then(self.page_id.cmp(&other.page_id))
21	            .then(self.slot.cmp(&other.slot))
22	    }
23	}
24	
25	impl PartialOrd for BTreeKey {
26	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
27	        Some(self.cmp(other))
28	    }
29	}

