529	                                        let evaluator = crate::exec::evaluator::ExprEvaluator::new(
530	                                            expr.clone(),
531	                                            col_names.clone(),
532	                                        );
533	                                        projected.push(evaluator.evaluate(&row)?);
534	                                    }
535	                                    _ => unreachable!(),
536	                                }
537	                            }
538	                            result_rows.push(Row::new(projected));
539	                        }
540	                    }
