547	                    } else {
548	                        columns
549	                            .iter()
550	                            .map(|c| match c {
551	                                crate::parser::ast::SelectColumn::Expr(_, alias) => {
552	                                    alias.clone().unwrap_or_else(|| "expr".to_string())
553	                                }
554	                                _ => "*".to_string(),
555	                            })
556	                            .collect()
557	                    };
558	
559	                    Ok(ExecutionResult::QueryResult {
