709	        for row in rows {
710	            for (i, val) in row.values.iter().enumerate() {
711	                if i < widths.len() {
712	                    widths[i] = widths[i].max(val.to_string().len());
713	                }
714	            }
715	        }
716	
717	        // Print header
718	        for (i, name) in schema.iter().enumerate() {
719	            if i > 0 {
720	                print!(" | ");
721	            }
722	            print!("{:width$}", name, width = widths[i]);
723	        }
724	        println!();
725	
726	        // Print separator
727	        for (i, w) in widths.iter().enumerate() {
728	            if i > 0 {
729	                print!("-+-");
730	            }
731	            print!("{}", "-".repeat(*w));
732	        }
733	        println!();
734	
735	        // Print rows
736	        for row in rows {
737	            for (i, val) in row.values.iter().enumerate() {
738	                if i > 0 {
739	                    print!(" | ");
740	                }
741	                print!("{:width$}", val, width = widths[i]);
742	            }
743	            println!();
744	        }
745	
746	        if !self.quiet {
747	            eprintln!(
748	                "{} {}",
749	                rows.len(),
750	                if rows.len() == 1 { "row" } else { "rows" }
751	            );
752	        }
753	
754	        Ok(())
