126	    pub fn insert_row(&mut self, page_id: u64, row_data: &[u8]) -> Result<u16> {
127	        let mut page = self.load_page(page_id)?;
128	
129	        let num_rows = page.read_u16(0) as usize;
130	        let mut data_end = page.read_u16(2) as usize;
131	
132	        // Data starts after the 4-byte header
133	        if data_end == 0 {
134	            data_end = 4;
135	        }
136	
137	        // New entry: 2 bytes for length + row data
138	        let entry_size = 2 + row_data.len();
139	        let new_data_end = data_end + entry_size;
140	
141	        if new_data_end > PAGE_SIZE {
142	            return Err(MiniDbError::StorageError("page full".to_string()));
143	        }
144	
145	        // Write the length prefix
146	        page.write_u16(data_end, row_data.len() as u16);
147	        // Write the row data
148	        page.write_bytes(data_end + 2, row_data);
149	
150	        // Update header
151	        page.write_u16(0, (num_rows + 1) as u16);
152	        page.write_u16(2, new_data_end as u16);
153	
154	        self.write_page(&page)?;
155	        Ok(num_rows as u16)

