 76	    fn replay_wal(
 77	        &self,
 78	        records: &[crate::storage::wal::WalRecord],
 79	        catalog: &mut Catalog,
 80	        heap: &mut HeapFile,
 81	    ) -> Result<()> {
 82	        use crate::storage::wal::WalRecord;
 83	        let mut committed_txns = std::collections::HashSet::new();
 84	        let mut active_txns = std::collections::HashSet::new();
 85	
 86	        for record in records {
 87	            match record {
 88	                WalRecord::Begin { tx_id } => {
 89	                    active_txns.insert(*tx_id);
 90	                }
 91	                WalRecord::Commit { tx_id } => {
 92	                    committed_txns.insert(*tx_id);
 93	                    active_txns.remove(tx_id);
 94	                }
 95	                WalRecord::Rollback { tx_id } => {
 96	                    active_txns.remove(tx_id);
 97	                }
 98	                _ => {}
 99	            }
100	        }
101	
102	        // Apply committed transactions
103	        for record in records {
104	            match record {
105	                WalRecord::Insert {
106	                    tx_id,
107	                    table,
108	                    row_id,
109	                    data,
110	                } if committed_txns.contains(tx_id) => {
111	                    if catalog.table_exists(table) {
112	                        let row_id = crate::storage::RowId(*row_id);
113	                        heap.add_row(table, data)?;
114	                    }
115	                }
116	                WalRecord::Delete {
117	                    tx_id,
118	                    table,
119	                    row_id,
120	                } if committed_txns.contains(tx_id) => {
121	                    if catalog.table_exists(table) {
122	                        let row_id = crate::storage::RowId(*row_id);
123	                        heap.delete_row(row_id)?;
124	                    }
125	                }
126	                _ => {}
127	            }
128	        }
129	        Ok(())

115	        let data = expression::serialize_row(&row_values);
116	        let row_id = self.heap.add_row(table, &data)?;
117	
118	        let index_names: Vec<String> = self
119	            .catalog
120	            .find_all_indexes_for_table(table)
121	            .into_iter()
122	            .map(|s| s.to_string())
123	            .collect();
124	        for idx_name in &index_names {
125	            let col_name = self.catalog.get_index(idx_name)?.column.clone();
126	            if let Some(pos) = schema.columns.iter().position(|c| c.name == col_name) {
127	                let key = IndexKey::from_value(&row_values[pos]);
128	                self.catalog.add_index_entry(idx_name, key, row_id)?;
129	            }

