207	fn crc32(data: &[u8]) -> u32 {
208	    let mut crc: u32 = 0xFFFFFFFF;
209	    for &byte in data {
210	        crc ^= byte as u32;
211	        for _ in 0..8 {
212	            if crc & 1 != 0 {
213	                crc = (crc >> 1) ^ 0xEDB88320;
214	            } else {
215	                crc >>= 1;
216	            }
217	        }
218	    }
219	    !crc
220	}

241	    fn replay_no_apply(&mut self) -> Result<Vec<WalRecord>> {
242	        let mut file = OpenOptions::new().read(true).open(&self.path)?;
243	        let mut records = Vec::new();
244	        let mut buf = Vec::new();
245	        file.read_to_end(&mut buf)?;
246	        let mut pos = 0;
247	        while pos + 8 <= buf.len() {
248	            // minimum: type(1) + crc(4) + len(2) + at least 1 byte
249	            let rec_len = u16::from_be_bytes([buf[pos + 5], buf[pos + 6]]) as usize;
250	            if pos + 7 + rec_len > buf.len() {
251	                break;
252	            }
253	            let rec_data = &buf[pos + 7..pos + 7 + rec_len];
254	            let stored_crc =
255	                u32::from_be_bytes([buf[pos + 1], buf[pos + 2], buf[pos + 3], buf[pos + 4]]);
256	            let computed_crc = crc32(rec_data);
257	            if stored_crc != computed_crc {
258	                debug!("CRC mismatch at pos {}, discarding rest of WAL", pos);
259	                break;
260	            }
261	            if let Ok(record) = WalRecord::deserialize(rec_data) {
262	                if let WalRecord::Begin { tx_id } = &record {
263	                    self.next_tx_id = self.next_tx_id.max(tx_id + 1);
264	                }
265	                records.push(record);
266	            }
267	            pos += 7 + rec_len;
268	        }
269	        Ok(records)

