306	                    }
307	                }
308	                Ok(ExecutionResult {
309	                    columns: child.columns,
310	                    column_types: child.column_types,
311	                    rows,
312	                    affected_rows: 0,
313	                    is_query: true,
314	                })
315	            }
316	            PhysicalPlan::Project {
317	                input,
318	                expressions,
319	                distinct,
320	            } => {
321	                let child = self.execute_query(&input)?;
322	                let child_schema: Vec<(String, ColumnType)> = child
323	                    .columns
324	                    .iter()
325	                    .zip(child.column_types.iter())
326	                    .map(|(n, t)| (n.clone(), t.clone()))
327	                    .collect();
328	                let mut output_schema = Vec::new();
329	                let mut rows = Vec::new();
330	                let mut seen = HashSet::new();
331	                for row in &child.rows {
332	                    let mut projected = Vec::new();
333	                    let mut has_star = false;
334	                    for expr in &expressions {
335	                        match expr {
336	                            ast::Expr::Star => {
337	                                has_star = true;
338	                                projected.extend(row.iter().cloned());
339	                            }
340	                            _ => {
341	                                projected.push(eval_expr(expr, row, &child_schema)?);
342	                            }
343	                        }
344	                    }
345	                    if !has_star && output_schema.is_empty() {
346	                        for (i, expr) in expressions.iter().enumerate() {
347	                            let name = match expr {
348	                                ast::Expr::ColumnRef {
349	                                    table: Some(t),
350	                                    column: c,
351	                                } => format!("{}.{}", t, c),
352	                                ast::Expr::ColumnRef {
353	                                    table: None,
354	                                    column: c,
355	                                } => c.clone(),
356	                                _ => format!("col_{}", i),
357	                            };
358	                            output_schema.push((name, ColumnType::Text));
359	                        }
360	                    }
361	                    if distinct {
362	                        let key: String = projected
363	                            .iter()
364	                            .map(|v| v.to_string())
365	                            .collect::<Vec<_>>()
366	                            .join("\0");
367	                        if !seen.insert(key) {
368	                            continue;
369	                        }
370	                    }
371	                    rows.push(projected);
372	                }
373	                if output_schema.is_empty() {
374	                    output_schema = child_schema;
375	                }
376	                Ok(ExecutionResult {
377	                    columns: output_schema.iter().map(|(n, _)| n.clone()).collect(),
378	                    column_types: output_schema.iter().map(|(_, t)| t.clone()).collect(),
379	                    rows,
380	                    affected_rows: 0,
381	                    is_query: true,
382	                })
383	            }
384	            PhysicalPlan::Sort { input, order_by } => {
385	                let mut child = self.execute_query(&input)?;
386	                let child_schema: Vec<(String, ColumnType)> = child
387	                    .columns
388	                    .iter()
389	                    .zip(child.column_types.iter())
390	                    .map(|(n, t)| (n.clone(), t.clone()))
391	                    .collect();
392	                child.rows.sort_by(|a, b| {
393	                    for item in &order_by {
394	                        let va = eval_expr(&item.expr, a, &child_schema).unwrap_or(Value::Null);
395	                        let vb = eval_expr(&item.expr, b, &child_schema).unwrap_or(Value::Null);
396	                        match va.partial_cmp(&vb) {
397	                            Some(std::cmp::Ordering::Equal) => {}
398	                            Some(ord) => return if item.desc { ord.reverse() } else { ord },
399	                            None => {}
400	                        }
401	                    }
402	                    std::cmp::Ordering::Equal
403	                });
404	                Ok(child)
405	            }
