408	                limit,
409	                offset,
410	            } => {
411	                let child = self.execute_query(&input)?;
412	                let skipped = offset.min(child.rows.len());
413	                let taken = limit.min(child.rows.len().saturating_sub(skipped));
414	                let rows = child.rows.into_iter().skip(skipped).take(taken).collect();
415	                Ok(ExecutionResult {
416	                    columns: child.columns,
417	                    column_types: child.column_types,
418	                    rows,
419	                    affected_rows: 0,
420	                    is_query: true,
421	                })
422	            }
423	            PhysicalPlan::NestedLoopJoin { left, right, on } => {
424	                let left_r = self.execute_query(&left)?;
425	                let right_r = self.execute_query(&right)?;
