436	                    .map(|(n, t)| (n.clone(), t.clone()))
437	                    .collect();
438	                let combined_s: Vec<(String, ColumnType)> =
439	                    left_s.iter().chain(right_s.iter()).cloned().collect();
440	                let mut rows = Vec::new();
441	                for lrow in &left_r.rows {
