444	                            lrow.iter().chain(rrow.iter()).cloned().collect();
445	                        if let Value::Bool(true) = eval_expr(&on, &combined, &combined_s)? {
446	                            rows.push(combined);
447	                        }
448	                    }
449	                }
450	                Ok(ExecutionResult {
451	                    columns: combined_s.iter().map(|(n, _)| n.clone()).collect(),
452	                    column_types: combined_s.iter().map(|(_, t)| t.clone()).collect(),
453	                    rows,
454	                    affected_rows: 0,
455	                    is_query: true,
456	                })
457	            }
458	            _ => unreachable!(),
