166	    fn try_extract_index_predicate(
167	        expr: &ast::Expr,
168	        table: &str,
169	        catalog: &Catalog,
170	    ) -> Option<(String, String, IndexPredicate)> {
171	        match expr {
172	            ast::Expr::BinaryOp { op, left, right } => match op {
173	                ast::BinaryOp::Eq => {
174	                    if let (Some(col_name), Some(value)) =
175	                        (Self::extract_column(left), Self::extract_literal(right))
176	                    {
177	                        if let Some(idx_name) = catalog.find_index_for_column(table, &col_name) {
178	                            return Some((
179	                                idx_name.to_string(),
180	                                col_name,
181	                                IndexPredicate::Eq(IndexKey::from_value(&value)),
182	                            ));
183	                        }
184	                    }
185	                    if let (Some(value), Some(col_name)) =
186	                        (Self::extract_literal(left), Self::extract_column(right))
187	                    {
188	                        if let Some(idx_name) = catalog.find_index_for_column(table, &col_name) {
189	                            return Some((
190	                                idx_name.to_string(),
191	                                col_name,
192	                                IndexPredicate::Eq(IndexKey::from_value(&value)),
193	                            ));
194	                        }
195	                    }
196	                }
197	                ast::BinaryOp::Gt | ast::BinaryOp::Ge | ast::BinaryOp::Lt | ast::BinaryOp::Le => {
198	                    if let (Some(col_name), Some(value)) =
199	                        (Self::extract_column(left), Self::extract_literal(right))
200	                    {
201	                        if let Some(idx_name) = catalog.find_index_for_column(table, &col_name) {
202	                            let key = IndexKey::from_value(&value);
203	                            let (min, max, min_inc, max_inc) = match op {
204	                                ast::BinaryOp::Gt => (Some(key), None, false, false),
205	                                ast::BinaryOp::Ge => (Some(key), None, true, false),
206	                                ast::BinaryOp::Lt => (None, Some(key), false, false),
207	                                ast::BinaryOp::Le => (None, Some(key), false, true),
208	                                _ => unreachable!(),
209	                            };
210	                            return Some((
211	                                idx_name.to_string(),
212	                                col_name,
213	                                IndexPredicate::Range {
214	                                    min,
215	                                    max,
216	                                    min_inclusive: min_inc,
217	                                    max_inclusive: max_inc,
218	                                },
219	                            ));
220	                        }
221	                    }
222	                }
223	                _ => {}
224	            },
225	            _ => {}
226	        }
