127	    pub fn recover(&self, pm: &mut PageManager) -> Result<()> {
128	        let mut reader = crate::storage::wal::WalReader::open(&self.wal_path)?;
129	        let records = reader.read_all()?;
130	
131	        // Find the last commit record
132	        let mut last_commit_idx = None;
133	        for (i, record) in records.iter().enumerate().rev() {
134	            if record.record_type == crate::storage::wal::WalRecordType::Commit {
135	                last_commit_idx = Some(i);
136	                break;
137	            }
138	        }
139	
140	        if let Some(commit_idx) = last_commit_idx {
141	            // Apply all page writes up to and including the last commit
142	            for record in &records[..=commit_idx] {
143	                if record.record_type == crate::storage::wal::WalRecordType::PageWrite {
144	                    if record.data.len() >= 8 {
145	                        let pid = u64::from_le_bytes(record.data[0..8].try_into().unwrap());
146	                        let page_data = &record.data[8..];
147	                        if page_data.len() == 4096 {
148	                            let mut page = [0u8; 4096];
149	                            page.copy_from_slice(page_data);
150	                            pm.write_page(PageId(pid), &page)?;
151	                        }
152	                    }
153	                }
154	            }
155	            pm.flush()?;
156	            log::info!("WAL recovery: applied committed transactions");
157	        }
158	
159	        // Truncate WAL after recovery
160	        let wal = Wal::create(&self.wal_path)?;
161	        // We can't mutate self here since we only have &self.
162	        // The caller should handle this.
163	        drop(wal);
164	
165	        Ok(())

