56	    pub fn execute(&mut self, stmt: Statement) -> Result<QueryResult> {
57	        match stmt {
58	            Statement::CreateTable(ct) => self.exec_create_table(ct),
59	            Statement::DropTable(dt) => self.exec_drop_table(dt),
60	            Statement::CreateIndex(ci) => self.exec_create_index(ci),
61	            Statement::DropIndex(di) => self.exec_drop_index(di),
62	            Statement::Insert(ins) => self.exec_insert(ins),
63	            Statement::Select(sel) => self.exec_select(sel),
64	            Statement::Update(upd) => self.exec_update(upd),
65	            Statement::Delete(del) => self.exec_delete(del),
66	            Statement::Begin => {
67	                self.txn.begin()?;
68	                Ok(QueryResult {
69	                    columns: vec![],
70	                    rows: vec![],
71	                    affected: 0,
72	                    is_query: false,
73	                })
74	            }
75	            Statement::Commit => {
76	                self.txn.commit(&mut self.pm)?;
77	                self.catalog.save(&mut self.pm)?;
78	                Ok(QueryResult {
79	                    columns: vec![],
80	                    rows: vec![],
81	                    affected: 0,
82	                    is_query: false,
83	                })
84	            }
85	            Statement::Rollback => {
86	                self.txn.rollback()?;
87	                // Reload page manager and catalog from restored DB file
88	                self.pm.reopen(&self.db_path)?;
89	                self.catalog = Catalog::load(&mut self.pm)?;
90	                Ok(QueryResult {
91	                    columns: vec![],
92	                    rows: vec![],
93	                    affected: 0,
94	                    is_query: false,
95	                })
96	            }

362	            let final_row = Row::new(full_row);
363	            let slot_id = heap.insert_row(&mut self.pm, page_id, &final_row, &table_columns)?;
364	
365	            // Update indexes
366	            let indexes = self.catalog.get_indexes_for_table(&table_name);
367	            for (idx_schema, root_page) in indexes {
368	                let col_idx = table_columns
369	                    .iter()
370	                    .position(|c| c.name == idx_schema.column);
371	                if let Some(ci) = col_idx {
372	                    if let Some(val) = final_row.values.get(ci) {
373	                        let btree = BTreeIndex::new(&idx_schema.name, root_page);
374	                        let rid = RowId {
375	                            page_id: page_id.0 as u32,
376	                            slot_id: slot_id as u32,
377	                        };
378	                        btree.insert(&mut self.pm, val, &rid)?;
379	                    }
380	                }
381	            }
382	
383	            affected += 1;
384	        }
385	
386	        self.catalog.save(&mut self.pm)?;
387	        self.pm.flush()?;
388	
389	        Ok(QueryResult {
390	            columns: vec![],
391	            rows: vec![],
392	            affected,
393	            is_query: false,
394	        })

68	    pub fn commit(&mut self, pm: &mut PageManager) -> Result<()> {
69	        let txn = self
70	            .active_txn
71	            .take()
72	            .ok_or_else(|| MiniDbError::Transaction("no active transaction".to_string()))?;
73	
74	        // Write dirty pages to WAL
75	        for (pid, page_data) in &txn.dirty_pages {
76	            self.wal.append(&WalRecord::page_write(pid.0, page_data))?;
77	        }
78	
79	        // Write commit record
80	        self.wal.append(&WalRecord::commit(txn.txn_id))?;
81	        self.wal.flush_and_sync()?;
82	
83	        // Apply dirty pages to main file
84	        for (pid, page_data) in &txn.dirty_pages {
85	            pm.write_page(*pid, page_data)?;
86	        }
87	        pm.flush()?;
88	
89	        // Truncate WAL after successful commit
90	        let wal = Wal::create(&self.wal_path)?;
91	        self.wal = wal;
92	
93	        self.auto_commit = true;
94	        log::debug!("COMMIT transaction");
95	        Ok(())

