398	    fn insert_leaf(
399	        &self,
400	        pm: &mut PageManager,
401	        page_id: PageId,
402	        page: &mut [u8; PAGE_SIZE],
403	        count: u16,
404	        key: &Value,
405	        row_id: &RowId,
406	    ) -> Result<Option<(Value, PageId)>> {
407	        let sk = serialize_key(key);
408	        let entry_size = 1 + sk.len() + 8;
409	
410	        // Calculate current data size
411	        let mut current_size = NODE_HEADER;
412	        let mut pos = NODE_HEADER;
413	        for _ in 0..count {
414	            let klen = page[pos] as usize;
415	            current_size += 1 + klen + 8;
416	            pos += 1 + klen + 8;
417	        }
418	
419	        if current_size + entry_size + 9 > PAGE_SIZE {
420	            // Need to split
421	            return self.split_leaf(pm, page_id, key, row_id);
422	        }
423	
424	        // Find insertion point (sorted)
425	        let mut insert_pos = NODE_HEADER;
426	        for _ in 0..count {
427	            let klen = page[insert_pos] as usize;
428	            if klen > 0 {
429	                let existing = {
430	                    let mut p = 0;
431	                    deserialize_key(&page[insert_pos + 1..insert_pos + 1 + klen], &mut p)?
432	                };
433	                if key.compare_nulls_last(&existing) == std::cmp::Ordering::Less {
434	                    break;
435	                }
436	            }
437	            insert_pos += 1 + klen + 8;
438	        }
439	
440	        // Shift
441	        let shift = entry_size;
442	        let data_end = current_size;
443	        for i in (insert_pos..data_end).rev() {
444	            if i + shift < PAGE_SIZE {
445	                page[i + shift] = page[i];
446	            }
447	        }
448	
449	        // Write entry
450	        let mut p = insert_pos;
451	        page[p] = sk.len() as u8;
452	        p += 1;
453	        page[p..p + sk.len()].copy_from_slice(&sk);
454	        p += sk.len();
455	        let rid = row_id.to_u64();
456	        page[p..p + 8].copy_from_slice(&rid.to_le_bytes());
457	
458	        let new_count = count + 1;
459	        page[1..3].copy_from_slice(&new_count.to_le_bytes());
460	        pm.write_page(page_id, page)?;

464	    fn split_leaf(
465	        &self,
466	        pm: &mut PageManager,
467	        page_id: PageId,
468	        new_key: &Value,
469	        row_id: &RowId,
470	    ) -> Result<Option<(Value, PageId)>> {
471	        let page = pm.read_page(page_id)?;
472	        let count = u16::from_le_bytes(page[1..3].try_into().unwrap());
473	
474	        // Collect all entries
475	        let mut entries: Vec<(Value, u64)> = Vec::new();
476	        let mut pos = NODE_HEADER;
477	        for _ in 0..count {
478	            let klen = page[pos] as usize;
479	            pos += 1;
480	            let mut k = Value::Null;
481	            if klen > 0 {
482	                let mut p = 0;
483	                k = deserialize_key(&page[pos..pos + klen], &mut p)?;
484	                pos += klen;
485	            }
486	            let rid = u64::from_le_bytes(page[pos..pos + 8].try_into().unwrap());
487	            entries.push((k, rid));
488	            pos += 8;
489	        }
490	
491	        // Insert new entry
492	        let new_rid = row_id.to_u64();
493	        let mut insert_idx = entries.len();
494	        for (i, (k, _)) in entries.iter().enumerate() {
495	            if new_key.compare_nulls_last(k) == std::cmp::Ordering::Less {
496	                insert_idx = i;
497	                break;
498	            }
499	        }
500	        entries.insert(insert_idx, (new_key.clone(), new_rid));

