313	    fn parse_select(&mut self) -> Result<Statement> {
314	        self.advance(); // SELECT
315	
316	        let projections = self.parse_projections()?;
317	        let from = if self.peek() == &Token::From {
318	            self.advance();
319	            Some(self.parse_from()?)
320	        } else {
321	            None
322	        };
323	
324	        let where_clause = if self.peek() == &Token::Where {
325	            self.advance();
326	            Some(self.parse_or_expr()?)
327	        } else {
328	            None
329	        };
330	
