338	
339	        let limit = if self.peek() == &Token::Limit {
340	            self.advance();
341	            Some(self.parse_expr()?)
342	        } else {
343	            None
344	        };
345	
346	        let offset = if self.peek() == &Token::Offset {
347	            self.advance();
348	            Some(self.parse_expr()?)
349	        } else {
350	            None
351	        };
352	
