72	    pub fn plan_select(&self, stmt: &SelectStmt) -> Result<LogicalPlan> {
73	        let mut plan = if let Some(from) = &stmt.from {
74	            self.plan_from(from)?
75	        } else {
76	            // SELECT without FROM (e.g., SELECT 1+1)
77	            return Ok(LogicalPlan::Project {
78	                input: Box::new(LogicalPlan::SeqScan {
79	                    table: String::new(),
80	                    filter: None,
81	                }),
82	                projections: self.resolve_projections(&stmt.projections, None)?,
83	            });
84	        };
