156	    fn try_index_scan(&self, plan: &LogicalPlan, predicate: &Expr) -> Result<Option<LogicalPlan>> {
157	        let table_name = match plan {
158	            LogicalPlan::SeqScan { table, .. } => table.clone(),
159	            _ => return Ok(None),
160	        };
161	
162	        // Check for simple equality: col = literal
163	        if let Expr::BinaryOp {
164	            left,
165	            op: BinaryOp::Eq,
166	            right,
167	        } = predicate
168	        {
169	            if let (Expr::ColumnRef { name, .. }, Expr::Literal(val)) =
170	                (left.as_ref(), right.as_ref())
171	            {
172	                let indexes = self.catalog.get_indexes_for_table(&table_name);
173	                for (idx_schema, _root_page) in indexes {
174	                    if idx_schema.column == *name {
175	                        return Ok(Some(LogicalPlan::IndexScan {
176	                            table: table_name,
177	                            index_name: idx_schema.name.clone(),
178	                            key: val.clone(),
179	                            filter: None,
180	                        }));
181	                    }
182	                }
183	            }
184	            // Also check reversed: literal = col
185	            if let (Expr::Literal(val), Expr::ColumnRef { name, .. }) =
186	                (left.as_ref(), right.as_ref())
187	            {
188	                let indexes = self.catalog.get_indexes_for_table(&table_name);
189	                for (idx_schema, _root_page) in indexes {
190	                    if idx_schema.column == *name {
191	                        return Ok(Some(LogicalPlan::IndexScan {
192	                            table: table_name,
193	                            index_name: idx_schema.name.clone(),
194	                            key: val.clone(),
195	                            filter: None,
196	                        }));
197	                    }
198	                }
199	            }
200	        }
201	
202	        // Check for range: col > literal, col < literal, etc.
203	        if let Expr::BinaryOp { left, op: _, right } = predicate {
204	            if let (Expr::ColumnRef { name, .. }, Expr::Literal(val)) =
205	                (left.as_ref(), right.as_ref())
206	            {
207	                let indexes = self.catalog.get_indexes_for_table(&table_name);
208	                for (idx_schema, _root_page) in indexes {
209	                    if idx_schema.column == *name {
210	                        return Ok(Some(LogicalPlan::IndexScan {
211	                            table: table_name,
212	                            index_name: idx_schema.name.clone(),
213	                            key: val.clone(),
214	                            filter: Some(predicate.clone()),
215	                        }));
216	                    }
217	                }
218	            }
219	        }
220	
221	        Ok(None)

