 46	    pub fn run_repl(&self, executor: &mut Executor) -> Result<()> {
 47	        let stdin = io::stdin();
 48	        let stdout = io::stdout();
 49	        let stderr = io::stderr();
 50	        let mut reader = stdin.lock();
 51	        let mut out = stdout.lock();
 52	        let mut err = stderr.lock();
 53	
 54	        let mut buffer = String::new();
 55	        let mut line = String::new();
 56	
 57	        loop {
 58	            if buffer.is_empty() {
 59	                write!(out, "minidb> ")?;
 60	                out.flush()?;
 61	            } else {
 62	                write!(out, "   ...> ")?;
 63	                out.flush()?;
 64	            }
 65	
 66	            line.clear();
 67	            let bytes_read = reader.read_line(&mut line)?;
 68	            if bytes_read == 0 {
 69	                // EOF
 70	                writeln!(out)?;
 71	                break;
 72	            }
 73	
 74	            buffer.push_str(&line);
 75	
 76	            // Check if we have a complete statement (ends with ;)
 77	            if let Some(stmt_end) = buffer.rfind(';') {
 78	                let sql = buffer[..stmt_end].trim().to_string();
 79	                buffer = buffer[stmt_end + 1..].to_string();
 80	
 81	                if sql.is_empty() {
 82	                    continue;
 83	                }
 84	
 85	                match self.execute_sql(executor, &sql) {
 86	                    Ok(result) => {
 87	                        self.print_result(&mut out, &result)?;
 88	                        if !self.quiet && !result.is_query {
 89	                            writeln!(err, "ok")?;
 90	                        } else if !self.quiet && result.is_query {
 91	                            writeln!(err, "ok {} rows", result.rows.len())?;
 92	                        }
 93	                    }
 94	                    Err(MiniDbError::Runtime(msg)) if msg == "exit" => {
 95	                        return Ok(());
 96	                    }
 97	                    Err(e) => {
 98	                        writeln!(err, "Error: {e}")?;
 99	                    }
100	                }
101	            }
102	        }
103	
104	        Ok(())
105	    }

