261	    fn exec_insert(&mut self, stmt: InsertStmt) -> Result<QueryResult> {
262	        let table = self.catalog.get_table(&stmt.table).ok_or_else(|| {
263	            MiniDbError::Catalog(format!("table '{}' does not exist", stmt.table))
264	        })?;
265	        let table_columns = table.columns.clone();
266	        let table_name = stmt.table.clone();
267	
268	        // Determine column mapping
269	        let col_indices: Vec<usize> = if let Some(ref cols) = stmt.columns {
270	            cols.iter()
271	                .map(|c| {
272	                    table_columns
273	                        .iter()
274	                        .position(|tc| tc.name == *c)
275	                        .ok_or_else(|| {
276	                            MiniDbError::Catalog(format!(
277	                                "column '{}' not found in table '{}'",
278	                                c, table_name
279	                            ))
280	                        })
281	                })
282	                .collect::<Result<Vec<_>>>()?
283	        } else {
284	            (0..table_columns.len()).collect()
285	        };
286	
287	        // Ensure we have a page for this table
288	        let pages = self.catalog.get_table_pages(&table_name).to_vec();
289	        let heap = HeapFile::new(&table_name);
290	        let page_id = if pages.is_empty() {
291	            let _pid = self.catalog.alloc_page();
292	            let allocated = heap.alloc_page(&mut self.pm)?;
293	            // Use catalog's page tracking
294	            self.catalog.add_table_page(&table_name, allocated);
295	            allocated
296	        } else {
297	            *pages.last().unwrap()
298	        };
299	
300	        let mut affected = 0;
301	        for value_row in &stmt.values {
302	            // Build full row with defaults
303	            let mut full_row = vec![Value::Null; table_columns.len()];
304	            for (i, col_idx) in col_indices.iter().enumerate() {
305	                let val = if i < value_row.len() {
306	                    // Evaluate literal expression
307	                    match &value_row[i] {
308	                        Expr::Literal(v) => v.clone(),
309	                        _ => {
310	                            return Err(MiniDbError::Runtime(
311	                                "only literal values supported in INSERT".to_string(),
312	                            ));
313	                        }
314	                    }
315	                } else if let Some(ref default) = table_columns[*col_idx].default {
316	                    default.clone()
317	                } else {
318	                    Value::Null
319	                };
320	                full_row[*col_idx] = val;
321	            }
322	
323	            // Check constraints
324	            for (i, col) in table_columns.iter().enumerate() {
325	                if col.not_null && full_row[i].is_null() {
326	                    return Err(MiniDbError::Constraint(format!(
327	                        "NOT NULL constraint violated for column '{}'",
328	                        col.name
329	                    )));
330	                }
331	                if col.primary_key || col.unique {
332	                    // Check uniqueness
333	                    let pages = self.catalog.get_table_pages(&table_name).to_vec();
334	                    for pid in pages {
335	                        let existing = heap.scan_page(&mut self.pm, pid, &table_columns)?;
336	                        for (_, existing_row) in existing {
337	                            if existing_row.values[i] == full_row[i] {
338	                                if col.primary_key {
339	                                    return Err(MiniDbError::Constraint(format!(
340	                                        "PRIMARY KEY constraint violated for column '{}'",
341	                                        col.name
342	                                    )));
343	                                } else {
344	                                    return Err(MiniDbError::Constraint(format!(
345	                                        "UNIQUE constraint violated for column '{}'",
346	                                        col.name
347	                                    )));
348	                                }
349	                            }
350	                        }
351	                    }
352	                }
353	            }
354	
355	            // Type coercion
356	            for (i, col) in table_columns.iter().enumerate() {
357	                if !full_row[i].is_null() {
358	                    full_row[i] = full_row[i].coerce_to(col.col_type)?;
359	                }
360	            }
361	
362	            let final_row = Row::new(full_row);
363	            let slot_id = heap.insert_row(&mut self.pm, page_id, &final_row, &table_columns)?;
364	
365	            // Update indexes
366	            let indexes = self.catalog.get_indexes_for_table(&table_name);
367	            for (idx_schema, root_page) in indexes {
368	                let col_idx = table_columns
369	                    .iter()
370	                    .position(|c| c.name == idx_schema.column);
371	                if let Some(ci) = col_idx {
372	                    if let Some(val) = final_row.values.get(ci) {
373	                        let btree = BTreeIndex::new(&idx_schema.name, root_page);
374	                        let rid = RowId {
375	                            page_id: page_id.0 as u32,
376	                            slot_id: slot_id as u32,
377	                        };
378	                        btree.insert(&mut self.pm, val, &rid)?;
379	                    }
380	                }
381	            }
382	
383	            affected += 1;
384	        }
385	
386	        self.catalog.save(&mut self.pm)?;
387	        self.pm.flush()?;
388	
389	        Ok(QueryResult {
390	            columns: vec![],
391	            rows: vec![],
392	            affected,
393	            is_query: false,
394	        })

