143	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
144	        let mut records = Vec::new();
145	        while self.pos + RECORD_HEADER_SIZE <= self.data.len() {
146	            let len =
147	                u32::from_le_bytes(self.data[self.pos..self.pos + 4].try_into().unwrap()) as usize;
148	            if len < RECORD_HEADER_SIZE || self.pos + len > self.data.len() {
149	                break;
150	            }
151	            let crc_stored =
152	                u32::from_le_bytes(self.data[self.pos + 4..self.pos + 8].try_into().unwrap());
153	            let rtype =
154	                u32::from_le_bytes(self.data[self.pos + 8..self.pos + 12].try_into().unwrap());
155	            let payload = &self.data[self.pos + RECORD_HEADER_SIZE..self.pos + len];
156	
157	            let record_type = WalRecordType::from_u32(rtype)?;
158	            let mut hasher = Hasher::new();
159	            hasher.update(&rtype.to_le_bytes());
160	            hasher.update(payload);
161	            let crc_computed = hasher.finalize();
162	
163	            if crc_stored != crc_computed {
164	                log::warn!(
165	                    "WAL CRC mismatch at offset {}: stored={:#010x} computed={:#010x}, stopping replay",
166	                    self.pos, crc_stored, crc_computed
167	                );
168	                break;

