 81	    /// Commit the current transaction.
 82	    pub fn commit(&mut self) -> Result<()> {
 83	        if self.state != TxnState::Active {
 84	            return Err(MiniDbError::Transaction(
 85	                "no active transaction to commit".into(),
 86	            ));
 87	        }
 88	
 89	        self.wal.append_commit(self.current_txn_id)?;
 90	        self.wal.sync()?;
 91	        self.state = TxnState::Committed;
 92	        self.in_explicit_txn = false;
 93	        self.auto_commit = true;
 94	
 95	        debug!("COMMIT transaction {}", self.current_txn_id);
 96	        Ok(())
 97	    }
 98	
 99	    /// Rollback the current transaction.
100	    pub fn rollback(&mut self) -> Result<()> {
101	        if !self.in_explicit_txn && self.state != TxnState::Active {
102	            return Err(MiniDbError::Transaction(
103	                "no active transaction to rollback".into(),
104	            ));
105	        }
106	
107	        self.state = TxnState::Aborted;
108	        self.in_explicit_txn = false;
109	        self.auto_commit = true;
110	
111	        debug!("ROLLBACK transaction {}", self.current_txn_id);
112	        Ok(())
113	    }
114	
115	    /// Auto-commit if we're in an implicit transaction.
116	    pub fn auto_commit_if_needed(&mut self) -> Result<()> {
117	        if self.auto_commit && self.state == TxnState::Active {
118	            self.commit()?;
119	        }
120	        Ok(())
121	    }
