49	impl WalRecord {
50	    pub fn encode(&self) -> Vec<u8> {
51	        let mut body = Vec::new();
52	        body.push(self.op as u8);
53	        body.extend_from_slice(&self.txn_id.to_le_bytes());
54	        body.extend_from_slice(&(self.data.len() as u32).to_le_bytes());
55	        body.extend_from_slice(&self.data);
56	
57	        let crc = crc32fast::hash(&body);
58	        let mut record = Vec::with_capacity(4 + body.len());
59	        record.extend_from_slice(&crc.to_le_bytes());
60	        record.extend_from_slice(&body);
61	        record
62	    }

 64	    pub fn decode(data: &[u8]) -> Result<(Self, usize)> {
 65	        if data.len() < 17 {
 66	            return Err(MiniDbError::Wal("WAL record too short".into()));
 67	        }
 68	
 69	        let crc = u32::from_le_bytes(data[0..4].try_into().unwrap());
 70	        let body = &data[4..];
 71	
 72	        // Read data_len first to know the actual record body size
 73	        let op = WalOp::from_u8(body[0])
 74	            .ok_or_else(|| MiniDbError::Wal(format!("unknown WAL op: {}", body[0])))?;
 75	        let txn_id = u64::from_le_bytes(body[1..9].try_into().unwrap());
 76	        let data_len = u32::from_le_bytes(body[9..13].try_into().unwrap()) as usize;
 77	
 78	        if body.len() < 13 + data_len {
 79	            return Err(MiniDbError::Wal("WAL record data truncated".into()));
 80	        }
 81	
 82	        // CRC is computed only over the record body (not the rest of the file)
 83	        let record_body = &body[..13 + data_len];
 84	        let computed_crc = crc32fast::hash(record_body);
 85	        if crc != computed_crc {
 86	            return Err(MiniDbError::Wal(
 87	                "WAL record CRC mismatch (torn write)".into(),
 88	            ));
 89	        }
 90	
 91	        let record_data = body[13..13 + data_len].to_vec();
 92	        let total_len = 4 + 13 + data_len;
 93	
 94	        Ok((
 95	            WalRecord {
 96	                op,
 97	                txn_id,
 98	                data: record_data,
 99	            },
100	            total_len,
101	        ))
102	    }

212	    fn decode_records(buf: &[u8]) -> Result<Vec<WalRecord>> {
213	        let mut records = Vec::new();
214	        let mut pos = 0;
215	
216	        while pos < buf.len() {
217	            if pos + 17 > buf.len() {
218	                break; // incomplete record
219	            }
220	            match WalRecord::decode(&buf[pos..]) {
221	                Ok((record, len)) => {
222	                    records.push(record);
223	                    pos += len;
224	                }
225	                Err(e) => {
226	                    log::warn!("WAL record decode error at offset {}: {}", pos, e);
227	                    break; // corrupted record, stop replay
228	                }
229	            }
230	        }
231	
232	        Ok(records)

