 56	    /// Insert a (key, row_id) pair into the B-tree.
 57	    /// This is a simplified in-place insert for leaf nodes only.
 58	    pub fn insert(&self, page: &mut Page, key: &Value, row_id: u64) -> Result<()> {
 59	        if !Self::is_leaf(page) {
 60	            return Err(MiniDbError::Index(
 61	                "cannot insert directly into internal node".into(),
 62	            ));
 63	        }
 64	
 65	        let count = Self::key_count(page) as usize;
 66	        let mut pos = BTREE_HEADER_SIZE;
 67	
 68	        // Find insertion position (sorted by key)
 69	        let mut insert_idx = count;
 70	        for i in 0..count {
 71	            let (existing_key, _) = Self::read_leaf_entry(page, pos)?;
 72	            if Self::value_cmp(key, &existing_key) == std::cmp::Ordering::Less {
 73	                insert_idx = i;
 74	                break;
 75	            }
 76	            pos += Self::leaf_entry_size(&existing_key);
 77	        }
 78	
 79	        // Shift entries after insert position
 80	        let serialized = Self::serialize_leaf_entry(key, row_id);
 81	        let entry_size = serialized.len();
 82	
 83	        // Find the byte offset for insert_idx
 84	        let mut byte_offset = BTREE_HEADER_SIZE;
 85	        for _i in 0..insert_idx {
 86	            let (k, _) = Self::read_leaf_entry(page, byte_offset)?;
 87	            byte_offset += Self::leaf_entry_size(&k);
 88	        }
 89	
 90	        // Shift existing data right
 91	        let _total_data_start = BTREE_HEADER_SIZE;
 92	        let shift_start = byte_offset;
 93	        let data_end = {
 94	            let mut p = BTREE_HEADER_SIZE;
 95	            for _ in 0..count {
 96	                let (k, _) = Self::read_leaf_entry(page, p)?;
 97	                p += Self::leaf_entry_size(&k);
 98	            }
 99	            p
100	        };
101	
102	        // Make room
103	        if data_end + entry_size > PAGE_SIZE {
104	            return Err(MiniDbError::Index("B-tree leaf page is full".into()));
105	        }
106	
107	        // Shift bytes right
108	        let page_data = page.as_mut_slice();
109	        for i in (shift_start..data_end).rev() {
110	            page_data[i + entry_size] = page_data[i];
111	        }
112	
113	        // Write new entry
114	        let mut write_pos = shift_start;
115	        for &byte in &serialized {
116	            page.as_mut_slice()[write_pos] = byte;
117	            write_pos += 1;
118	        }
119	
120	        Self::set_key_count(page, count as u16 + 1);
121	        Ok(())
122	    }
