127	            return Err(MiniDbError::Index("search_eq on internal node".into()));
128	        }
129	
130	        let count = Self::key_count(page) as usize;
131	        let mut pos = BTREE_HEADER_SIZE;
132	        let mut results = Vec::new();
133	
134	        for _ in 0..count {
135	            let (k, rid) = Self::read_leaf_entry(page, pos)?;
136	            let cmp = Self::value_cmp(&k, key);
137	            match cmp {
138	                std::cmp::Ordering::Equal => results.push(rid),
139	                std::cmp::Ordering::Greater => break, // past the range
140	                _ => {}
141	            }
142	            pos += Self::leaf_entry_size(&k);
143	        }
