50	            crate::parser::ast::Statement::Delete(del) => self.execute_delete(del),
51	            crate::parser::ast::Statement::CreateTable(ct) => self.execute_create_table(ct),
52	            crate::parser::ast::Statement::DropTable { name } => self.execute_drop_table(name),
53	            crate::parser::ast::Statement::CreateIndex(ci) => self.execute_create_index(ci),
54	            crate::parser::ast::Statement::DropIndex { name } => self.execute_drop_index(name),
55	            crate::parser::ast::Statement::Begin => {
56	                self.txn.begin()?;
57	                Ok(QueryResult::Success)
58	            }
