 90	    fn execute_select(&mut self, sel: &crate::parser::ast::SelectStmt) -> Result<QueryResult> {
 91	        // Check for aggregates before creating planner (to avoid borrow conflicts)
 92	        let has_agg = sel.projection.iter().any(|item| {
 93	            if let crate::parser::ast::SelectItem::Expr { expr, .. } = item {
 94	                is_aggregate_expr(expr)
 95	            } else {
 96	                false
 97	            }
 98	        });
 99	
100	        if has_agg && sel.group_by.is_none() {
101	            // For aggregate queries without GROUP BY, bypass the Project
102	            // and compute aggregates directly from raw input rows
103	            let planner = Planner::new(&self.catalog);
104	            let logical = planner.plan(&crate::parser::ast::Statement::Select(sel.clone()))?;
105	            let logical = planner.optimize(logical)?;
106	
107	            // Build the input plan (strip the final Project if present)
108	            let input_logical = match &logical {
109	                LogicalPlan::Project { input, .. } => input.as_ref().clone(),
110	                other => other.clone(),
111	            };
112	
113	            let physical = self.create_physical_plan(&input_logical)?;
114	            let mut op = self.build_operator(physical)?;
115	
116	            op.open()?;
117	            let mut rows = Vec::new();
118	            loop {
119	                match op.next()? {
120	                    None => break,
121	                    Some(row) => rows.push(row),
122	                }
123	            }
124	            op.close()?;
125	
126	            let input_schema = op.schema().clone();
127	
128	            // Build output schema from projection aliases
129	            let mut out_cols = Vec::new();
130	            for item in &sel.projection {
131	                match item {
132	                    crate::parser::ast::SelectItem::Expr { alias, .. } => {
133	                        let name = alias.clone().unwrap_or_else(|| "expr".to_string());
134	                        out_cols.push(crate::types::ColumnDef {
135	                            name,
136	                            col_type: crate::types::ColumnType::Text,
137	                            constraints: vec![],
138	                        });
139	                    }
140	                    _ => out_cols.push(crate::types::ColumnDef {
141	                        name: "expr".into(),
142	                        col_type: crate::types::ColumnType::Text,
143	                        constraints: vec![],
144	                    }),
145	                }
146	            }
147	            let schema = Schema::new(out_cols);
148	
149	            // Evaluate aggregates
150	            let mut agg_row = Vec::new();
151	            for item in &sel.projection {
152	                match item {
153	                    crate::parser::ast::SelectItem::Expr { expr, .. } => {
154	                        let val = self.eval_aggregate(expr, &rows, &input_schema)?;
155	                        agg_row.push(val);
156	                    }
157	                    _ => agg_row.push(Value::Null),
158	                }
159	            }
160	            Ok(QueryResult::Rows {
161	                schema,
162	                rows: vec![agg_row],
163	            })
164	        } else {
165	            let planner = Planner::new(&self.catalog);
166	            let logical = planner.plan(&crate::parser::ast::Statement::Select(sel.clone()))?;
167	            let logical = planner.optimize(logical)?;
168	            let physical = self.create_physical_plan(&logical)?;
169	            let mut op = self.build_operator(physical)?;
170	
171	            op.open()?;
172	            let mut rows = Vec::new();
173	            loop {
174	                match op.next()? {
175	                    None => break,
176	                    Some(row) => rows.push(row),
177	                }
178	            }
179	            op.close()?;
180	
181	            let schema = op.schema().clone();
182	            Ok(QueryResult::Rows { schema, rows })
183	        }

