64	    /// Insert a row into the heap, returns (page_id, slot_index, row_id)
65	    pub fn insert_row(page: &mut Page, row: &[Value], row_id: u64) -> Result<(PageId, u32, u64)> {
66	        let serialized = Self::serialize_row(row);
67	        let row_len = serialized.len();
68	
69	        let row_count = page.read_u32(8);
70	        let data_end = page.read_u32(12) as usize; // bytes used from end of page
71	        let slot_count = page.read_u32(16);
72	
73	        // Check slot directory won't overlap with data area
74	        let new_slot_count = slot_count + 1;
75	        let slot_dir_end = HEADER_SIZE + new_slot_count as usize * SLOT_ENTRY_SIZE;
76	
77	        // Row data is stored from PAGE_SIZE backwards
78	        let row_data_start = PAGE_SIZE - data_end - row_len;
79	
80	        if row_data_start < slot_dir_end {
81	            return Err(MiniDbError::Storage("page is full".into()));
82	        }
83	
84	        // Write row data from end of page
85	        page.write_bytes(row_data_start, &serialized);
86	
87	        // Write slot entry (store absolute offset)
88	        let slot_offset = HEADER_SIZE + slot_count as usize * SLOT_ENTRY_SIZE;
89	        page.write_u32(slot_offset, row_data_start as u32);
90	        page.write_u16(slot_offset + 4, row_len as u16);
91	
92	        // Update header
93	        page.write_u32(8, row_count + 1);
94	        page.write_u32(12, (data_end + row_len) as u32);
95	        page.write_u32(16, new_slot_count);
96	
97	        Ok((page.id, slot_count, row_id))
98	    }

