356	    fn execute_insert(&mut self, ins: &crate::parser::ast::InsertStmt) -> Result<QueryResult> {
357	        self.txn.begin_auto()?;
358	
359	        let table = self.catalog.get_table(&ins.table)?.clone();
360	        let schema = table.schema();
361	        let columns = if let Some(cols) = &ins.columns {
362	            cols.clone()
363	        } else {
364	            schema
365	                .column_names()
366	                .iter()
367	                .map(|s| s.to_string())
368	                .collect()
369	        };
370	
371	        let root_page = self.catalog.table_root_page(&ins.table).ok_or_else(|| {
372	            MiniDbError::Catalog(format!("no root page for table '{}'", ins.table))
373	        })?;
374	
375	        let mut count = 0u64;
376	        for value_row in &ins.values {
377	            // Build full row with defaults
378	            let mut row = schema.default_row();
379	
380	            for (i, expr) in value_row.iter().enumerate() {
381	                let col_name = columns
382	                    .get(i)
383	                    .ok_or_else(|| MiniDbError::Runtime("too many values for columns".into()))?;
384	
385	                let col_idx = schema.column_index(col_name).ok_or_else(|| {
386	                    MiniDbError::Catalog(format!("column '{}' not found", col_name))
387	                })?;
388	
389	                let val = self.eval_const_or_default(expr, &schema)?;
390	                let coerced = val.coerce_to(schema.columns[col_idx].col_type)?;
391	                row[col_idx] = coerced;
392	            }
393	
394	            // Validate constraints
395	            self.validate_constraints(&table, &row)?;
396	
397	            // Insert into heap
398	            let row_id = self.catalog.next_row_id(&ins.table);
399	            let page = self.pager.read_page_mut(PageId(root_page))?;
400	            let (_page_id, slot_idx, _row_id) = HeapFile::insert_row(page, &row, row_id)?;
401	
402	            // Update indexes using slot_idx as the row identifier
403	            let indexes = self.catalog.indexes_for_table(&ins.table).to_vec();
404	            for idx in &indexes {
405	                if let Some(idx_root) = self.catalog.index_root_page(&idx.name) {
406	                    let col_idx = schema.column_index(&idx.column_name).ok_or_else(|| {
407	                        MiniDbError::Index(format!("column '{}' not found", idx.column_name))
408	                    })?;
409	                    let key = row[col_idx].clone();
410	                    let idx_page = self.pager.read_page_mut(PageId(idx_root))?;
411	                    BTree::new(PageId(idx_root)).insert(idx_page, &key, slot_idx as u64)?;
412	                }
413	            }
414	
415	            count += 1;
416	        }
417	
418	        if !self.txn.in_transaction() {
419	            self.flush_dirty_pages()?;
420	        }
421	        self.txn.auto_commit_if_needed()?;
422	
423	        Ok(QueryResult::RowsAffected(count))

235	    /// Replay the WAL: returns committed page writes and catalog data.
236	    pub fn replay(&mut self) -> Result<WalReplayResult> {
237	        let records = self.read_all()?;
238	        let mut result = WalReplayResult::default();
239	        let mut committed_txns = std::collections::HashSet::new();
240	        let mut pending_writes: Vec<(u64, u64, Vec<u8>)> = Vec::new();
241	        let mut pending_catalog: Option<Vec<u8>> = None;
242	        let _last_checkpoint_pos = 0;
243	
244	        // First pass: find committed transactions
245	        for record in &records {
246	            match record.op {
247	                WalOp::Commit => {
248	                    committed_txns.insert(record.txn_id);
249	                }
250	                WalOp::Checkpoint => {
251	                    // Everything before checkpoint is already flushed
252	                    committed_txns.clear();
253	                    pending_writes.clear();
254	                    pending_catalog = None;
255	                }
256	                _ => {}
257	            }
258	        }
259	
260	        // Second pass: collect writes from committed transactions
261	        for record in &records {
262	            match record.op {
263	                WalOp::PageWrite => {
264	                    if committed_txns.contains(&record.txn_id) {
265	                        let page_id = u64::from_le_bytes(record.data[0..8].try_into().unwrap());
266	                        let page_data = record.data[8..].to_vec();
267	                        pending_writes.push((record.txn_id, page_id, page_data));
268	                    }
269	                }
270	                WalOp::CatalogUpdate => {
271	                    if committed_txns.contains(&record.txn_id) {
272	                        pending_catalog = Some(record.data.clone());
273	                    }
274	                }
275	                WalOp::Checkpoint => {
276	                    pending_writes.clear();
277	                    pending_catalog = None;
278	                }
279	                _ => {}
280	            }
281	        }
282	
283	        result.page_writes = pending_writes;
284	        result.catalog_data = pending_catalog;
285	        result.has_uncommitted = !committed_txns.is_empty()
286	            && records.last().map_or(false, |r| {
287	                r.op != WalOp::Commit && r.op != WalOp::Checkpoint
288	            });
289	
290	        Ok(result)

1254	    pub fn recover_from_wal(&mut self) -> Result<()> {
1255	        let replay = self.txn.replay_wal()?;
1256	
1257	        for (_txn_id, page_id, data) in &replay.page_writes {
1258	            let page = self.pager.read_page_mut(PageId(*page_id))?;
1259	            let copy_len = data.len().min(PAGE_SIZE);
1260	            page.write_bytes(0, &data[..copy_len]);
1261	        }
1262	
1263	        if let Some(catalog_data) = &replay.catalog_data {
1264	            if let Ok(catalog) = Catalog::deserialize(catalog_data) {
1265	                self.catalog = catalog;
1266	            }
1267	        }
1268	
1269	        self.pager.flush()?;
1270	        self.txn.checkpoint()?;
1271	
1272	        Ok(())
1273	    }

102	    fn evict_one(&mut self) -> Result<()> {
103	        // Find a non-dirty page to evict (LRU-like: just pick the first non-dirty)
104	        let victim = self
105	            .cache
106	            .iter()
107	            .find(|(_, page)| !page.dirty)
108	            .map(|(id, _)| *id);
109	
110	        if let Some(id) = victim {
111	            self.cache.remove(&id);
112	        } else {
113	            // All pages dirty - flush first one
114	            if let Some((&id, _)) = self.cache.iter().next() {
115	                let page = self.cache.remove(&id).unwrap();
116	                self.write_page_to_disk(&page)?;
