485	    fn do_commit_internal(&mut self) -> Result<()> {
486	        let id = self.txn.current().expect("active");
487	        // Collect dirty page images and append redo records.
488	        let dirty = self.pager.dirty_snapshot();
489	        for (pid, buf) in &dirty {
490	            self.wal.append(&WalRecord::PageImage {
491	                txn_id: id.0,
492	                page_id: *pid,
493	                bytes: buf.to_vec(),
494	            })?;
495	        }
496	        // Catalog snapshot if anything changed.
497	        if self.catalog_dirty {
498	            let bytes = self.catalog.to_json()?;
499	            self.wal.append(&WalRecord::CatalogSnapshot {
500	                txn_id: id.0,
501	                bytes,
502	            })?;
503	        }
504	        self.wal.append(&WalRecord::Commit { txn_id: id.0 })?;
505	        self.wal.fsync()?;
506	        // Now flush data pages.
507	        self.pager.flush()?;
508	        if self.catalog_dirty {
509	            self.save_catalog()?;
510	        }
511	        // Persist dirty indexes.
512	        for name in std::mem::take(&mut self.indexes_dirty) {
513	            if let Some(idx) = self.indexes.get(&name) {
514	                idx.persist()?;
515	            }
516	        }
517	        // Truncate WAL on successful checkpoint.
518	        self.wal.truncate()?;
519	        self.catalog_dirty = false;
520	        self.catalog_snapshot_for_txn = None;
521	        self.txn.finish()?;
522	        debug!("committed txn {:?}", id);
523	        Ok(())

80	        // Recover from WAL before opening the pager so that pages are correct.
