153	    fn recover(root: &Path) -> Result<()> {
154	        let wal_path = root.join(WAL_FILE);
155	        if !wal_path.exists() {
156	            return Ok(());
157	        }
158	        let mut wal = Wal::open(&wal_path)?;
159	        let recs = wal.read_all()?;
160	        if recs.is_empty() {
161	            return Ok(());
162	        }
163	        let mut data = OpenOptions::new()
164	            .read(true)
165	            .write(true)
166	            .create(true)
167	            .open(root.join(DATA_FILE))?;
168	        if let Some(cat_bytes) = replay(recs, &mut data)? {
169	            let cat_path = root.join(CATALOG_FILE);
170	            let tmp = cat_path.with_extension("tmp");
171	            std::fs::write(&tmp, &cat_bytes)?;
172	            std::fs::rename(&tmp, &cat_path)?;
173	            info!("WAL replay applied catalog snapshot");
174	        }
175	        wal.truncate()?;
176	        Ok(())

