 93	    pub fn append(&mut self, rec: &WalRecord) -> Result<()> {
 94	        let payload = encode_payload(rec);
 95	        let crc = crc32fast::hash(&payload);
 96	        let mut header = Vec::with_capacity(8);
 97	        header.extend_from_slice(&(payload.len() as u32 + 4).to_le_bytes());
 98	        header.extend_from_slice(&crc.to_le_bytes());
 99	        self.file.seek(SeekFrom::End(0))?;
100	        self.file.write_all(&header)?;
101	        self.file.write_all(&payload)?;
102	        Ok(())
103	    }
