110	    /// Read every record from the start of the file. Stops cleanly on
111	    /// torn-tail records (truncated header or CRC mismatch).
112	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
113	        self.file.seek(SeekFrom::Start(0))?;
114	        let mut out = Vec::new();
115	        loop {
116	            let mut hdr = [0u8; 8];
117	            match self.file.read_exact(&mut hdr) {
118	                Ok(()) => {}
119	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
120	                Err(e) => return Err(e.into()),
121	            }
122	            let rec_len = u32::from_le_bytes(hdr[0..4].try_into().unwrap()) as usize;
123	            let crc = u32::from_le_bytes(hdr[4..8].try_into().unwrap());
124	            // rec_len includes the crc (4 bytes already in header), payload follows.
125	            let payload_len = rec_len.saturating_sub(4);
126	            let mut payload = vec![0u8; payload_len];
127	            match self.file.read_exact(&mut payload) {
128	                Ok(()) => {}
129	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
130	                    warn!("truncated WAL tail: dropping last record");
131	                    break;
132	                }
133	                Err(e) => return Err(e.into()),
134	            }
135	            let actual = crc32fast::hash(&payload);
136	            if actual != crc {
137	                warn!("WAL CRC mismatch: dropping last record");
138	                break;
139	            }
140	            match decode_payload(&payload) {
141	                Ok(r) => out.push(r),
142	                Err(e) => {
143	                    warn!("WAL decode failure: {}", e);
144	                    break;
145	                }
146	            }
147	        }
148	        Ok(out)

238	/// Apply WAL records: replays committed transactions onto `data_file`. Returns
239	/// the catalog bytes from the most-recent committed catalog snapshot, if any.
240	pub fn replay(records: Vec<WalRecord>, data_file: &mut File) -> Result<Option<Vec<u8>>> {
241	    // First: bucket by txn_id and find committed/rolled-back transactions.
242	    let mut by_txn: HashMap<u64, Vec<WalRecord>> = HashMap::new();
243	    let mut committed: Vec<u64> = Vec::new();
244	    let mut rolled: std::collections::HashSet<u64> = std::collections::HashSet::new();
245	    for r in &records {
246	        by_txn.entry(r.txn_id()).or_default().push(r.clone());
247	    }
248	    // Iterate in original order to preserve commit ordering.
249	    let mut seen = std::collections::HashSet::new();
250	    for r in &records {
251	        match r {
252	            WalRecord::Commit { txn_id } => {
253	                if seen.insert(*txn_id) {
254	                    committed.push(*txn_id);
255	                }
256	            }
257	            WalRecord::Rollback { txn_id } => {
258	                rolled.insert(*txn_id);
