110	    /// Read every record from the start of the file. Stops cleanly on
111	    /// torn-tail records (truncated header or CRC mismatch).
112	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
113	        self.file.seek(SeekFrom::Start(0))?;
114	        let mut out = Vec::new();
115	        loop {
116	            let mut hdr = [0u8; 8];
117	            match self.file.read_exact(&mut hdr) {
118	                Ok(()) => {}
119	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
120	                Err(e) => return Err(e.into()),
121	            }
122	            let rec_len = u32::from_le_bytes(hdr[0..4].try_into().unwrap()) as usize;
123	            let crc = u32::from_le_bytes(hdr[4..8].try_into().unwrap());
124	            // rec_len includes the crc (4 bytes already in header), payload follows.
125	            let payload_len = rec_len.saturating_sub(4);
126	            let mut payload = vec![0u8; payload_len];
127	            match self.file.read_exact(&mut payload) {
128	                Ok(()) => {}
129	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
130	                    warn!("truncated WAL tail: dropping last record");
131	                    break;
132	                }
133	                Err(e) => return Err(e.into()),
134	            }
135	            let actual = crc32fast::hash(&payload);
136	            if actual != crc {
137	                warn!("WAL CRC mismatch: dropping last record");
138	                break;
139	            }
140	            match decode_payload(&payload) {
141	                Ok(r) => out.push(r),
142	                Err(e) => {
143	                    warn!("WAL decode failure: {}", e);
144	                    break;
145	                }
146	            }
147	        }
148	        Ok(out)

30	pub fn run_with_io<R: BufRead, O: Write, E: Write>(
31	    args: CliArgs,
32	    input: &mut R,
33	    out: &mut O,
34	    err: &mut E,
35	) -> Result<i32> {
36	    if args.print_help {
37	        write!(out, "{}", HELP_TEXT)?;
38	        return Ok(0);
39	    }
40	    if args.print_version {
41	        writeln!(out, "minidb {}", VERSION)?;
42	        return Ok(0);
43	    }
44	    if args.init {
45	        Engine::create_empty(&args.db)?;
46	        writeln!(err, "initialized empty database at {:?}", args.db)?;
47	        return Ok(0);
48	    }
49	
50	    let mut engine = Engine::open(&args.db)?;
51	    let mut state = SessionState::new(args.format, args.quiet);
52	
53	    match &args.mode {
54	        Some(RunMode::Eval(sql)) => run_eval(&mut engine, &mut state, sql, out, err),
55	        Some(RunMode::File(path)) => {
56	            let bytes = std::fs::read_to_string(path)
57	                .map_err(|e| MiniDbError::cli(format!("could not read {:?}: {}", path, e)))?;
58	            run_script(
59	                &mut engine,
60	                &mut state,
61	                &bytes,
62	                args.continue_on_error,
63	                out,
64	                err,
65	            )
66	        }
67	        Some(RunMode::Repl) => run_repl(&mut engine, &mut state, input, out, err),
68	        None => {
69	            // Decide based on stdin TTY.
70	            if atty::is(atty::Stream::Stdin) {
71	                run_repl(&mut engine, &mut state, input, out, err)
72	            } else {
73	                let mut buf = String::new();
74	                input.read_to_string(&mut buf)?;
75	                run_script(
76	                    &mut engine,
77	                    &mut state,
78	                    &buf,
79	                    args.continue_on_error,
80	                    out,
81	                    err,
82	                )
83	            }
84	        }
85	    }

 69	    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
 70	        let root = path.as_ref().to_path_buf();
 71	        if root.exists() && root.is_file() {
 72	            return Err(MiniDbError::storage(format!(
 73	                "database path {:?} is a regular file; expected a directory",
 74	                root
 75	            )));
 76	        }
 77	        std::fs::create_dir_all(&root)?;
 78	        std::fs::create_dir_all(root.join(INDEX_DIR))?;
 79	
