189	        // Meta commands handled outside of plan/exec.
190	        if let ast::Statement::Meta(m) = &stmt {
191	            return self.exec_meta(m);
192	        }
193	        // Transaction control.
194	        match &stmt {
195	            ast::Statement::Begin => return self.do_begin(),
196	            ast::Statement::Commit => return self.do_commit(),
197	            ast::Statement::Rollback => return self.do_rollback(),
198	            _ => {}
199	        }
200	        // For all other statements: ensure a transaction is active (auto-commit).
201	        let auto = !self.txn.is_active();
202	        if auto {
203	            self.do_begin_implicit()?;
204	        }
205	        let result = self.execute_in_txn(stmt);
206	        match result {
207	            Ok(r) => {
208	                if auto {
209	                    self.do_commit_internal()?;
210	                }
211	                Ok(r)
212	            }
213	            Err(e) => {
214	                if auto {
215	                    let _ = self.do_rollback_internal();
216	                }
217	                Err(e)
218	            }
219	        }
220	    }
