350	    fn exec_create_index(&mut self, ci: ast::CreateIndex) -> Result<ExecResult> {
351	        let table = self.catalog.get_table(&ci.table)?.clone();
352	        let col_idx = table.column_index(&ci.column).ok_or_else(|| {
353	            MiniDbError::catalog(format!(
354	                "column '{}' not found on table '{}'",
355	                ci.column, ci.table
356	            ))
357	        })?;
358	        let idx_schema = IndexSchema {
359	            name: ci.name.clone(),
360	            table: ci.table.clone(),
361	            column: ci.column.clone(),
362	        };
363	        self.catalog.add_index(idx_schema)?;
364	        self.catalog_dirty = true;
365	        // Build the index.
366	        let idx_path = self.root.join(INDEX_DIR).join(format!("{}.bin", ci.name));
367	        let mut tree = PersistentBTree::open(&idx_path)?;
368	        let rows = crate::storage::heap::Heap::new(&mut self.pager).scan(table.heap_head)?;
369	        for (rid, t) in rows {
370	            tree.tree.insert(t.values[col_idx].clone(), rid)?;
371	        }
372	        let key = ci.name.to_ascii_lowercase();
373	        self.indexes.insert(key.clone(), tree);
374	        self.indexes_dirty.insert(key);
