145	        // Evaluate bound expressions against an empty row (they must be const).
146	        let empty_schema = OperatorSchema::default();
147	        let empty_row: Row = Vec::new();
148	        let row_ids = {
149	            let idx = ctx
150	                .indexes
151	                .get(&self.index_name.to_ascii_lowercase())
152	                .ok_or_else(|| MiniDbError::ty(format!("index '{}' missing", self.index_name)))?;
153	            if let Some(eq) = &self.bounds.eq {
154	                let v = expr_eval::eval(eq, &empty_schema, &empty_row)?;
155	                let v = expr_eval::coerce(v, dtype)?;
156	                idx.tree.lookup_eq(&v)
157	            } else {
158	                let lower_v = match &self.bounds.lower {
159	                    Some((e, inc)) => {
160	                        let v = expr_eval::eval(e, &empty_schema, &empty_row)?;
161	                        Some((expr_eval::coerce(v, dtype)?, *inc))
162	                    }
163	                    None => None,
164	                };
165	                let upper_v = match &self.bounds.upper {
166	                    Some((e, inc)) => {
167	                        let v = expr_eval::eval(e, &empty_schema, &empty_row)?;
168	                        Some((expr_eval::coerce(v, dtype)?, *inc))
169	                    }
170	                    None => None,
171	                };
172	                let lower_ref = lower_v.as_ref().map(|(v, b)| (v, *b));
173	                let upper_ref = upper_v.as_ref().map(|(v, b)| (v, *b));
174	                idx.tree.lookup_range(lower_ref, upper_ref)
175	            }
176	        };
177	
178	        let mut rows = Vec::new();
179	        for rid in row_ids {
180	            if let Some(t) = read_row_by_id(ctx, rid)? {
181	                let row = t.values;
182	                if let Some(pred) = &self.residual {
183	                    let ok = predicate_passes(expr_eval::eval(pred, &self.schema, &row)?)?;
184	                    if !ok {
185	                        continue;
186	                    }
187	                }
188	                rows.push(row);
189	            }
190	        }

