158	/// Detect a top-level conjunction containing exactly one supported predicate
159	/// against an indexed column. Returns the index, column, bounds, and any
160	/// residual predicate that should still be applied above the scan.
161	fn try_match_index(
162	    table: &str,
163	    alias: &Option<String>,
164	    pred: &Expr,
165	    catalog: &Catalog,
166	) -> Option<(String, String, IndexBounds, Option<Expr>)> {
167	    let conjuncts = split_and(pred);
168	    let mut chosen: Option<(usize, String, String, IndexBounds)> = None;
169	    for (idx, conj) in conjuncts.iter().enumerate() {
170	        if let Some((column, bounds)) = match_indexable(conj, table, alias) {
171	            // Check that an index exists on this column.
172	            let idxs = catalog.indexes_for_column(table, &column);
173	            if let Some(i) = idxs.first() {
174	                chosen = Some((idx, i.name.clone(), column, bounds));
175	                break;
176	            }
177	        }
178	    }
179	    let (consumed_idx, index_name, column, bounds) = chosen?;
180	    let residual: Vec<&Expr> = conjuncts
181	        .iter()
182	        .enumerate()
183	        .filter_map(|(i, e)| if i == consumed_idx { None } else { Some(*e) })
184	        .collect();
185	    let residual_expr = if residual.is_empty() {
186	        None
187	    } else {
188	        let mut out = residual[0].clone();
189	        for r in &residual[1..] {
190	            out = Expr::And(Box::new(out), Box::new((*r).clone()));
191	        }
192	        Some(out)
193	    };
194	    Some((index_name, column, bounds, residual_expr))
195	}

