47	        return Ok(0);
48	    }
49	
50	    let mut engine = Engine::open(&args.db)?;
51	    let mut state = SessionState::new(args.format, args.quiet);
52	
53	    match &args.mode {
54	        Some(RunMode::Eval(sql)) => run_eval(&mut engine, &mut state, sql, out, err),
55	        Some(RunMode::File(path)) => {
56	            let bytes = std::fs::read_to_string(path)
57	                .map_err(|e| MiniDbError::cli(format!("could not read {:?}: {}", path, e)))?;
58	            run_script(
59	                &mut engine,
60	                &mut state,
61	                &bytes,
62	                args.continue_on_error,
63	                out,
64	                err,
65	            )
66	        }
67	        Some(RunMode::Repl) => run_repl(&mut engine, &mut state, input, out, err),
68	        None => {
69	            // Decide based on stdin TTY.
70	            if atty::is(atty::Stream::Stdin) {
71	                run_repl(&mut engine, &mut state, input, out, err)
72	            } else {
73	                let mut buf = String::new();
74	                input.read_to_string(&mut buf)?;
75	                run_script(
76	                    &mut engine,
77	                    &mut state,
78	                    &buf,
79	                    args.continue_on_error,
80	                    out,
81	                    err,
82	                )
83	            }
84	        }
85	    }

