63	    /// Allocate a new page, returning its id and a zeroed buffer marked dirty.
64	    pub fn allocate(&mut self) -> PageId {
65	        self.num_pages += 1;
66	        let id = PageId(self.num_pages);
67	        let buf = Box::new([0u8; PAGE_SIZE]);
68	        self.dirty.insert(id, buf);
69	        debug!("allocated page {}", id);
70	        id
71	    }
72	
73	    /// Read a page into a freshly-allocated buffer.
74	    pub fn read(&mut self, id: PageId) -> Result<Box<PageBuf>> {
75	        if id.is_null() || id.0 > self.num_pages {
76	            return Err(MiniDbError::storage(format!("page id {} out of range", id)));
77	        }
78	        if let Some(b) = self.dirty.get(&id) {
79	            return Ok(b.clone());
80	        }
81	        if let Some(b) = self.cache.get(&id) {
82	            return Ok(b.clone());
83	        }
84	        let mut buf = Box::new([0u8; PAGE_SIZE]);
85	        self.file
86	            .seek(SeekFrom::Start((id.0 - 1) * PAGE_SIZE as u64))?;
87	        self.file.read_exact(buf.as_mut_slice())?;
88	        self.cache.insert(id, buf.clone());
89	        Ok(buf)
90	    }

