640	                .collect();
641	            let evald = evald?;
642	            let row = build_full_row(&table_def, self.columns.as_deref(), evald)?;
643	            // Constraint checks.
644	            for (i, c) in table_def.columns.iter().enumerate() {
645	                let v = &row[i];
646	                if c.not_null && matches!(v, Value::Null) {
647	                    return Err(MiniDbError::constraint(format!(
648	                        "NOT NULL violated for column {}",
649	                        c.name
650	                    )));
651	                }
652	                if !matches!(v, Value::Null) && c.unique {
653	                    if let Some(idx) = ctx.engine.catalog().find_index_for(&self.table, &c.name) {
654	                        if idx.unique {
655	                            // Look up existing rows with this key. Reads also
656	                            // see buffered txn state.
657	                            let existing = ctx.engine.index_lookup_eq(&self.table, &c.name, v)?;
658	                            if !existing.is_empty() {
659	                                return Err(MiniDbError::constraint(format!(
660	                                    "UNIQUE violated for column {}",
661	                                    c.name
662	                                )));
663	                            }
664	                        }
665	                    } else {
666	                        // Fall back to a scan.
667	                        let scan = ctx.engine.scan_table(&self.table)?;
668	                        for vr in scan {
669	                            if Value::cmp_sql(&vr.values[i], v)
670	                                .map(|o| o == Ordering::Equal)
671	                                .unwrap_or(false)
672	                            {
673	                                return Err(MiniDbError::constraint(format!(
674	                                    "UNIQUE violated for column {}",
675	                                    c.name
676	                                )));
677	                            }
678	                        }
679	                    }
680	                }
681	            }
682	            ctx.engine.dml_insert(&self.table, row)?;
683	            self.affected += 1;
684	        }
685	        self.done = true;
686	        Ok(Some(ExecRow::from_values(vec![Value::Int(self.affected)])))

