249	    fn execute_one(&mut self, stmt: &Statement) -> Option<i32> {
250	        match execute_statement(stmt, self.engine) {
251	            Ok(StatementOutcome::Select(rs)) => {
252	                if let Err(e) = self.print_result_set(&rs) {
253	                    self.report_error(&e);
254	                    return Some(io_or_storage_exit_code(&e));
255	                }
256	                None
257	            }
258	            Ok(StatementOutcome::Write(wr)) => {
259	                self.print_write_result(&wr);
260	                None
261	            }
262	            Err(e) => {
263	                self.report_error(&e);
264	                if self.continue_on_error {
265	                    None
266	                } else {
267	                    Some(error_exit_code(&e))
268	                }
269	            }
270	        }

394	        self.expect(Token::Values, "VALUES")?;
395	        let mut rows = Vec::new();
396	        loop {
397	            self.expect(Token::LParen, "(")?;
398	            let mut row = Vec::new();
399	            loop {
400	                row.push(self.parse_expr()?);
401	                match self.peek().token {
402	                    Token::Comma => {
403	                        self.bump();
404	                    }
405	                    Token::RParen => {
406	                        self.bump();
407	                        break;
408	                    }
409	                    _ => {
410	                        let cur = self.peek().clone();
411	                        return Err(MiniDbError::parse(
412	                            format!("expected ',' or ')', got {:?}", cur.token),
413	                            cur.line,
414	                            cur.column,
415	                        ));
416	                    }
417	                }
418	            }
419	            rows.push(row);
420	            if self.peek().token == Token::Comma {
421	                self.bump();
422	            } else {
423	                break;
424	            }
425	        }
426	        Ok(Statement::Insert(Insert {
427	            table,
428	            columns,
429	            rows,
430	        }))

105	        Statement::Insert(ins) => {
106	            let plan = planner::plan_insert(ins);
107	            let WritePlan::Insert {
108	                table,
109	                rows,
110	                columns,
111	            } = plan
112	            else {
113	                unreachable!()
114	            };
115	            // Verify table exists, applying table-level CHECKs after insert.
116	            // (Simplified: CHECKs are pre-validated against each candidate row.)
117	            let mut op = Insert::new(table.clone(), columns, rows);
118	            let count = run_dml(&mut op, engine)?;
119	            Ok(StatementOutcome::Write(WriteResult {
120	                affected: count,
121	                summary: format!(
122	                    "ok {} row{} inserted",
123	                    count,
124	                    if count == 1 { "" } else { "s" }
125	                ),
126	            }))

627	    fn next(&mut self, ctx: &mut ExecCtx) -> Result<Option<ExecRow>> {
628	        if self.done {
629	            return Ok(None);
630	        }
631	        let table_def = ctx.engine.catalog().get_table(&self.table)?.clone();
632	        for raw_row in &self.rows {
633	            // Evaluate each expression with no row context (literal-only).
634	            let evald: Result<Vec<Value>> = raw_row
635	                .iter()
636	                .map(|e| {
637	                    let bound = bind(e, &Schema::empty())?;
638	                    eval(&bound, &[])
639	                })
640	                .collect();
641	            let evald = evald?;
642	            let row = build_full_row(&table_def, self.columns.as_deref(), evald)?;
643	            // Constraint checks.
644	            for (i, c) in table_def.columns.iter().enumerate() {
645	                let v = &row[i];
646	                if c.not_null && matches!(v, Value::Null) {
647	                    return Err(MiniDbError::constraint(format!(
648	                        "NOT NULL violated for column {}",
649	                        c.name
650	                    )));
651	                }
652	                if !matches!(v, Value::Null) && c.unique {
653	                    if let Some(idx) = ctx.engine.catalog().find_index_for(&self.table, &c.name) {
654	                        if idx.unique {
655	                            // Look up existing rows with this key. Reads also
656	                            // see buffered txn state.
657	                            let existing = ctx.engine.index_lookup_eq(&self.table, &c.name, v)?;
658	                            if !existing.is_empty() {
659	                                return Err(MiniDbError::constraint(format!(
660	                                    "UNIQUE violated for column {}",
661	                                    c.name
662	                                )));
663	                            }
664	                        }
665	                    } else {
666	                        // Fall back to a scan.
667	                        let scan = ctx.engine.scan_table(&self.table)?;
668	                        for vr in scan {
669	                            if Value::cmp_sql(&vr.values[i], v)
670	                                .map(|o| o == Ordering::Equal)
671	                                .unwrap_or(false)
672	                            {
673	                                return Err(MiniDbError::constraint(format!(
674	                                    "UNIQUE violated for column {}",
675	                                    c.name
676	                                )));
677	                            }
678	                        }
679	                    }
680	                }
681	            }
682	            ctx.engine.dml_insert(&self.table, row)?;
683	            self.affected += 1;
684	        }
685	        self.done = true;
686	        Ok(Some(ExecRow::from_values(vec![Value::Int(self.affected)])))

518	    pub fn dml_insert(&mut self, table: &str, values: Vec<Value>) -> Result<()> {
519	        if self.txn.in_transaction() {
520	            let txn_id = self.txn.current_txn_id().unwrap();
521	            self.buffer.record_insert(
522	                table,
523	                values.clone(),
524	                WalRecord::Insert {
525	                    txn_id,
526	                    table: table.to_string(),
527	                    values,
528	                },
529	            );
530	            return Ok(());
531	        }
532	        // Auto-commit.
533	        let txn_id = self.txn.allocate_id();
534	        self.wal.append(&WalRecord::Begin { txn_id })?;
535	        self.wal.append(&WalRecord::Insert {
536	            txn_id,
537	            table: table.to_string(),
538	            values: values.clone(),
539	        })?;
540	        self.wal.append(&WalRecord::Commit { txn_id })?;
541	        self.wal.fsync()?;
542	        self.apply_insert(table, &values)?;
543	        self.pager.flush()?;
544	        self.wal.truncate()?;
545	        Ok(())

