229	pub fn build_plan(plan: &PhysicalPlan, engine: &Engine) -> Result<Box<dyn PhysicalOperator>> {
230	    Ok(match plan {
231	        PhysicalPlan::SeqScan { table, alias } => {
232	            Box::new(SeqScan::new(table.clone(), alias.clone(), engine)?)
233	        }
234	        PhysicalPlan::IndexScan {
235	            table,
236	            alias,
237	            column,
238	            bound,
239	            ..
240	        } => Box::new(IndexScan::new(
241	            table.clone(),
242	            alias.clone(),
243	            column.clone(),
244	            bound.clone(),
245	            engine,
246	        )?),
247	        PhysicalPlan::Filter { input, predicate } => {
248	            let child = build_plan(input, engine)?;
249	            Box::new(Filter::new(predicate.clone(), child))
250	        }
251	        PhysicalPlan::Project { input, projections } => {
252	            let child = build_plan(input, engine)?;
253	            Box::new(Project::new(projections.clone(), child))
254	        }
255	        PhysicalPlan::NestedLoopJoin { left, right, on } => {
256	            let l = build_plan(left, engine)?;
257	            let r = build_plan(right, engine)?;
258	            Box::new(NestedLoopJoin::new(l, r, on.clone()))
259	        }
260	        PhysicalPlan::Sort { input, items } => {
261	            let child = build_plan(input, engine)?;
262	            Box::new(Sort::new(items.clone(), child))
263	        }
264	        PhysicalPlan::Limit {
265	            input,
266	            limit,
267	            offset,
268	        } => {
269	            let child = build_plan(input, engine)?;
270	            Box::new(Limit::new(*limit, *offset, child))
271	        }
272	    })

