35	fn cmp_key(a: &Value, b: &Value) -> Ordering {
36	    // Indexes order non-NULL ascending; NULLs sort first.
37	    match (a, b) {
38	        (Value::Null, Value::Null) => Ordering::Equal,
39	        (Value::Null, _) => Ordering::Less,
40	        (_, Value::Null) => Ordering::Greater,
41	        _ => crate::types::Value::cmp_sql(a, b).unwrap_or(Ordering::Equal),
42	    }
43	}
44	
45	fn cmp_entry(a: &IndexEntry, b: &IndexEntry) -> Ordering {
46	    cmp_key(&a.key, &b.key).then_with(|| {
47	        a.row_id
48	            .page
49	            .0
50	            .cmp(&b.row_id.page.0)
51	            .then(a.row_id.slot.cmp(&b.row_id.slot))
52	    })
53	}

196	    /// Insert a single entry, splitting leaf pages as needed.
197	    pub fn insert(pager: &mut Pager, root: PageId, entry: IndexEntry) -> Result<()> {
198	        // Find target leaf: walk the chain until we find a leaf whose last key >= entry.key,
199	        // or reach the tail.
200	        let mut cur = root;
201	        loop {
202	            let buf = pager.read_page(cur)?;
203	            let h = LeafHeader::read(&buf);
204	            if h.next_page == 0 {
205	                break;
206	            }
207	            let entries = read_leaf_entries(&buf)?;
208	            if let Some(last) = entries.last() {
209	                if cmp_entry(&entry, last) == Ordering::Greater {
210	                    cur = PageId(h.next_page);
211	                    continue;
212	                }
213	            }
214	            break;
215	        }
216	
217	        let buf = pager.read_page(cur)?;
218	        let mut entries = read_leaf_entries(&buf)?;
219	        let pos = entries
220	            .binary_search_by(|e| cmp_entry(e, &entry))
221	            .unwrap_or_else(|i| i);
222	        entries.insert(pos, entry);
223	
224	        // Try to write back. If it overflows, split.
225	        let mut probe = vec![0u8; PAGE_SIZE];
226	        let next = LeafHeader::read(&buf).next_page;
227	        match write_leaf_entries(&mut probe, next, &entries) {
228	            Ok(()) => {
229	                pager.write_page(cur, &probe)?;
230	                Ok(())
231	            }
232	            Err(_) => {
233	                // Split. Allocate a sibling and move the upper half.
234	                let mid = entries.len() / 2;
235	                let right_entries: Vec<_> = entries.split_off(mid);
236	                let new_id = pager.allocate_page()?;
237	                let mut left = vec![0u8; PAGE_SIZE];
238	                let mut right = vec![0u8; PAGE_SIZE];
239	                write_leaf_entries(&mut right, next, &right_entries)?;
240	                write_leaf_entries(&mut left, new_id.0, &entries)?;
241	                pager.write_page(new_id, &right)?;
242	                pager.write_page(cur, &left)?;
243	                let _ = buf; // silence unused
244	                Ok(())
245	            }

281	    /// Range scan (inclusive on both ends as configured).
282	    pub fn range_scan(
283	        pager: &mut Pager,
284	        root: PageId,
285	        lo: Option<Value>,
286	        hi: Option<Value>,
287	        lo_inclusive: bool,
288	        hi_inclusive: bool,
289	    ) -> Result<Vec<RowId>> {
290	        let mut out = Vec::new();
291	        let mut cur = root;
292	        loop {
293	            let buf = pager.read_page(cur)?;
294	            let entries = read_leaf_entries(&buf)?;
295	            let h = LeafHeader::read(&buf);
296	            for e in &entries {
297	                if let Some(l) = &lo {
298	                    let c = cmp_key(&e.key, l);
299	                    if c == Ordering::Less {
300	                        continue;
301	                    }
302	                    if c == Ordering::Equal && !lo_inclusive {
303	                        continue;
304	                    }
305	                }
306	                if let Some(h2) = &hi {
307	                    let c = cmp_key(&e.key, h2);
308	                    if c == Ordering::Greater {
309	                        continue;
310	                    }
311	                    if c == Ordering::Equal && !hi_inclusive {
312	                        continue;
313	                    }
314	                }
315	                out.push(e.row_id);
316	            }
317	            if h.next_page == 0 {
318	                break;
319	            }
320	            cur = PageId(h.next_page);
321	        }
322	        Ok(out)
323	    }

