473	        self.implicit_commit_if_open()?;
474	        let txn_id = self.txn.allocate_id();
475	        self.wal.append(&WalRecord::Begin { txn_id })?;
476	        self.wal.append(&WalRecord::CreateIndex {
477	            txn_id,
478	            name: name.to_string(),
479	            table: table.to_string(),
480	            column: column.to_string(),
481	        })?;
482	        self.wal.append(&WalRecord::Commit { txn_id })?;
