409	
410	impl PhysicalOperator for NestedLoopJoin {
411	    fn open(&mut self, ctx: &mut ExecCtx) -> Result<()> {
412	        self.left.open(ctx)?;
413	        self.right.open(ctx)?;
414	        // Materialise right side so we can replay it for every left row.
415	        self.right_rows.clear();
416	        while let Some(r) = self.right.next(ctx)? {
417	            self.right_rows.push(r);
418	        }
419	        self.right.close(ctx)?;
420	        self.schema = Schema::concat(self.left.schema(), self.right.schema());
421	        self.bound = Some(bind(&self.on, &self.schema)?);
422	        self.left_current = self.left.next(ctx)?;
423	        self.right_pos = 0;
424	        Ok(())
425	    }
426	    fn next(&mut self, ctx: &mut ExecCtx) -> Result<Option<ExecRow>> {
427	        let bound = self.bound.as_ref().expect("join not opened");
428	        loop {
429	            let l = match &self.left_current {
430	                Some(r) => r.clone(),
431	                None => return Ok(None),
432	            };
433	            while self.right_pos < self.right_rows.len() {
434	                let r = &self.right_rows[self.right_pos];
435	                self.right_pos += 1;
436	                let mut values = Vec::with_capacity(l.values.len() + r.values.len());
437	                values.extend_from_slice(&l.values);
438	                values.extend_from_slice(&r.values);
439	                let tri = eval_predicate(bound, &values)?;
440	                if tri.is_true() {
441	                    return Ok(Some(ExecRow {
442	                        rref: None,
443	                        source_table: None,
444	                        values,
445	                    }));
446	                }
447	            }
448	            self.left_current = self.left.next(ctx)?;
449	            self.right_pos = 0;
450	        }
451	    }
452	    fn close(&mut self, ctx: &mut ExecCtx) -> Result<()> {
453	        self.left.close(ctx)?;
454	        self.right_rows.clear();
455	        self.left_current = None;
456	        Ok(())
457	    }
458	    fn schema(&self) -> &Schema {
459	        &self.schema
460	    }
461	}
