822	                        table_def.columns[*idx].name
823	                    )));
824	                }
825	                new_values[*idx] = v;
826	            }
827	            match r.rref {
828	                Some(RowRef::Persistent(rid)) => {
829	                    ctx.engine
830	                        .dml_update_persistent(&self.table, rid, new_values)?;
831	                }
832	                Some(RowRef::Pending(i)) => {
