32	    // Try to push a filter down into an IndexScan when applicable.
33	    if let Some(pred) = &sel.r#where {
34	        plan = maybe_index_scan(plan, pred, catalog).unwrap_or_else(|| PhysicalPlan::Filter {
35	            input: Box::new(
36	                maybe_index_scan_inner(&sel.from, pred, catalog).unwrap_or_else(|| {
37	                    match &sel.from {
38	                        Some(f) => {
39	                            from_clause_to_plan(f, catalog).unwrap_or(PhysicalPlan::SeqScan {
40	                                table: "__no_table__".into(),
41	                                alias: None,
42	                            })
43	                        }
44	                        None => PhysicalPlan::SeqScan {
45	                            table: "__no_table__".into(),
46	                            alias: None,
47	                        },
48	                    }
49	                }),
50	            ),
51	            predicate: pred.clone(),
52	        });

149	fn maybe_index_scan(plan: PhysicalPlan, pred: &Expr, catalog: &Catalog) -> Option<PhysicalPlan> {
150	    // Only attempt an index scan when the source is a single SeqScan.
151	    if let PhysicalPlan::SeqScan { table, alias } = &plan {
152	        if let Some(scan) = single_table_index_scan(table, pred, catalog) {
153	            return Some(remap_alias(scan, alias.clone()));
154	        }
155	    }
156	    None
157	}
158	
159	fn remap_alias(plan: PhysicalPlan, alias: Option<String>) -> PhysicalPlan {
160	    match plan {
161	        PhysicalPlan::IndexScan {
162	            table,
163	            column,
164	            index_name,
165	            bound,
166	            ..
167	        } => PhysicalPlan::IndexScan {
168	            table,
169	            alias,
170	            column,
171	            index_name,
172	            bound,
173	        },
174	        other => other,
175	    }
176	}
177	
178	fn maybe_index_scan_inner(
179	    from: &Option<FromClause>,
180	    pred: &Expr,
181	    catalog: &Catalog,
182	) -> Option<PhysicalPlan> {
183	    match from {
184	        Some(FromClause::Table { name, alias }) => {
185	            if let Some(scan) = single_table_index_scan(name, pred, catalog) {
186	                return Some(remap_alias(scan, alias.clone()));
187	            }
188	            None
189	        }
190	        _ => None,
191	    }
192	}
193	
194	fn single_table_index_scan(table: &str, pred: &Expr, catalog: &Catalog) -> Option<PhysicalPlan> {
195	    let table_def = catalog.get_table(table).ok()?;
196	    let (col_qual, col, op, lit) = extract_simple_predicate(pred)?;
197	    if let Some(q) = col_qual {
198	        if !q.eq_ignore_ascii_case(table) {
199	            return None;
200	        }
201	    }
202	    if !table_def
203	        .columns
204	        .iter()
205	        .any(|c| c.name.eq_ignore_ascii_case(&col))
206	    {
207	        return None;
208	    }
209	    let idx = catalog.find_index_for(table, &col)?;
210	    let bound = match op {
211	        BinaryOp::Eq => IndexBound::Equal(lit),
212	        BinaryOp::Lt => IndexBound::Range {
213	            lo: None,
214	            hi: Some(lit),
215	            lo_inclusive: false,
216	            hi_inclusive: false,
217	        },
218	        BinaryOp::LtEq => IndexBound::Range {
219	            lo: None,
220	            hi: Some(lit),
221	            lo_inclusive: false,
222	            hi_inclusive: true,
223	        },
224	        BinaryOp::Gt => IndexBound::Range {
225	            lo: Some(lit),
226	            hi: None,
227	            lo_inclusive: false,
228	            hi_inclusive: false,
229	        },
230	        BinaryOp::GtEq => IndexBound::Range {
231	            lo: Some(lit),
232	            hi: None,
233	            lo_inclusive: true,
234	            hi_inclusive: false,
235	        },
236	        _ => return None,
237	    };
238	    Some(PhysicalPlan::IndexScan {
239	        table: table.to_string(),
240	        alias: None,
241	        column: col,
242	        index_name: idx.name.clone(),
243	        bound,
244	    })
245	}

