643	fn print_table<W: Write>(w: &mut W, rs: &ResultSet) -> Result<()> {
644	    let headers: Vec<String> = rs.schema.columns.iter().map(|c| c.name.clone()).collect();
645	    let body: Vec<Vec<String>> = rs
646	        .rows
647	        .iter()
648	        .map(|r| r.iter().map(value_display).collect())
649	        .collect();
650	    let cols = headers.len();
651	    let mut widths: Vec<usize> = headers.iter().map(|h| display_width(h)).collect();
652	    for row in &body {
653	        for (i, cell) in row.iter().enumerate() {
654	            if i >= widths.len() {
655	                widths.push(display_width(cell));
656	            } else if display_width(cell) > widths[i] {
657	                widths[i] = display_width(cell);
658	            }
659	        }
660	    }
661	    if cols == 0 {
662	        return Ok(());
663	    }
664	    write_separator(w, &widths)?;
665	    write_row(w, &headers, &widths)?;
666	    write_separator(w, &widths)?;
667	    for row in &body {
668	        write_row(w, row, &widths)?;
669	    }
670	    write_separator(w, &widths)?;
671	    Ok(())
672	}

