42	        let path: PathBuf = path.as_ref().into();
43	        let exists = path.exists();
44	        let file = OpenOptions::new()
45	            .read(true)
46	            .write(true)
47	            .create(true)
48	            .truncate(false)
49	            .open(&path)?;
50	        let mut p = Pager {
51	            path,
52	            file,
53	            header: Header::default(),
54	        };
55	        if exists && p.file_len()? >= PAGE_SIZE as u64 {
56	            p.read_header()?;
57	        } else {
58	            p.write_header()?;
59	            p.flush()?;
60	        }
61	        Ok(p)

108	    /// Read a page into a fresh 4096-byte buffer.
109	    pub fn read_page(&mut self, id: PageId) -> Result<Vec<u8>> {
110	        if id.0 == 0 || id.0 >= self.header.num_pages {
111	            return Err(MiniDbError::storage(format!("invalid page id: {}", id.0)));
112	        }
113	        let mut buf = vec![0u8; PAGE_SIZE];
114	        self.file.seek(SeekFrom::Start(id.0 * PAGE_SIZE as u64))?;
115	        self.file.read_exact(&mut buf)?;
116	        Ok(buf)
117	    }
118	
119	    pub fn write_page(&mut self, id: PageId, data: &[u8]) -> Result<()> {
120	        if data.len() != PAGE_SIZE {
121	            return Err(MiniDbError::storage(format!(
122	                "page data must be {} bytes, got {}",
123	                PAGE_SIZE,
124	                data.len()
125	            )));
126	        }
127	        if id.0 == 0 || id.0 >= self.header.num_pages {
128	            return Err(MiniDbError::storage(format!(
129	                "invalid page id for write: {}",
130	                id.0
131	            )));
132	        }
133	        self.file.seek(SeekFrom::Start(id.0 * PAGE_SIZE as u64))?;
134	        self.file.write_all(data)?;
135	        Ok(())

150	/// A heap is an append-friendly chain of slotted pages associated with a single table.
151	pub struct Heap;
152	
153	impl Heap {
154	    /// Create a new empty heap and return its first page id.
155	    pub fn create(pager: &mut Pager) -> Result<PageId> {
156	        let id = pager.allocate_page()?;
157	        let mut buf = vec![0u8; PAGE_SIZE];
158	        init_page(&mut buf);
159	        pager.write_page(id, &buf)?;
160	        Ok(id)
161	    }
162	
163	    /// Insert a row into the heap rooted at `root`. Returns the assigned RowId.
164	    pub fn insert(pager: &mut Pager, root: PageId, values: &[Value]) -> Result<RowId> {
165	        let mut record = Vec::with_capacity(64);
166	        codec::encode_row(values, &mut record)?;
167	        if record.len() + SLOT_LEN > PAGE_SIZE - HEADER_LEN {
168	            return Err(MiniDbError::storage("row too large for a single page"));
169	        }
170	        // Walk the chain until we find a page with room or reach the tail.
171	        let mut current = root;
172	        loop {
173	            let mut buf = pager.read_page(current)?;
174	            if let Some(slot) = try_insert_into_page(&mut buf, &record) {
175	                pager.write_page(current, &buf)?;
176	                return Ok(RowId::new(current, slot));
177	            }
178	            let h = PageHeader::read(&buf);
179	            if h.next_page == 0 {
180	                let new_page = pager.allocate_page()?;
181	                let mut nbuf = vec![0u8; PAGE_SIZE];
182	                init_page(&mut nbuf);
183	                let slot = try_insert_into_page(&mut nbuf, &record)
184	                    .ok_or_else(|| MiniDbError::storage("row will not fit in fresh page"))?;
185	                pager.write_page(new_page, &nbuf)?;
186	                let mut h2 = PageHeader::read(&buf);
187	                h2.next_page = new_page.0;
188	                h2.write(&mut buf);
189	                pager.write_page(current, &buf)?;
190	                return Ok(RowId::new(new_page, slot));
191	            }
192	            current = PageId(h.next_page);
193	        }
194	    }

