112	    fn recover(&mut self) -> Result<()> {
113	        let records = wal::read_all(&self.wal_path)?;
114	        if records.is_empty() {
115	            return Ok(());
116	        }
117	        let committed = wal::committed_records(records);
118	        for rec in committed {
119	            self.apply_record(&rec)?;
120	        }
121	        self.pager.flush()?;
122	        self.persist_catalog()?;
123	        self.wal.truncate()?;
124	        Ok(())

392	/// Read all valid records from the WAL on disk, stopping at the first framing
393	/// or CRC failure (which is treated as a torn write at the tail).
394	pub fn read_all<P: AsRef<Path>>(path: P) -> Result<Vec<WalRecord>> {
395	    let mut out = Vec::new();
396	    let path = path.as_ref();
397	    if !path.exists() {
398	        return Ok(out);
399	    }
400	    let mut file = OpenOptions::new().read(true).open(path)?;
401	    let len = file.metadata()?.len();
402	    let mut pos = 0u64;
403	    while pos < len {
404	        let mut hdr = [0u8; 8];
405	        if let Err(_) = file.read_exact(&mut hdr) {
406	            break;
407	        }
408	        let mut a = [0u8; 4];
409	        a.copy_from_slice(&hdr[0..4]);
410	        let plen = u32::from_le_bytes(a) as u64;
411	        a.copy_from_slice(&hdr[4..8]);
412	        let crc_expected = u32::from_le_bytes(a);
413	        if pos + 8 + plen > len {
414	            break;
415	        }
416	        let mut payload = vec![0u8; plen as usize];
417	        if let Err(_) = file.read_exact(&mut payload) {
418	            break;
419	        }
420	        let mut h = crc32fast::Hasher::new();
421	        h.update(&payload);
422	        if h.finalize() != crc_expected {
423	            break;
424	        }
425	        match WalRecord::decode(&payload) {
426	            Ok(r) => out.push(r),
427	            Err(_) => break,
428	        }
429	        pos += 8 + plen;
430	    }
431	    Ok(out)
432	}
