434	/// Returns only the records belonging to transactions that fully committed.
435	/// Records of in-flight / aborted transactions are dropped.
436	pub fn committed_records(records: Vec<WalRecord>) -> Vec<WalRecord> {
437	    use std::collections::{HashMap, HashSet};
438	    let mut by_txn: HashMap<u64, Vec<WalRecord>> = HashMap::new();
439	    let mut committed: HashSet<u64> = HashSet::new();
440	    let mut order: Vec<u64> = Vec::new();
441	    for r in records {
442	        let id = r.txn_id();
443	        if r.is_commit() {
444	            committed.insert(id);
445	            continue;
446	        }
447	        let entry = by_txn.entry(id).or_default();
448	        if entry.is_empty() {
449	            order.push(id);
450	        }
451	        entry.push(r);
452	    }
453	    let mut out = Vec::new();
454	    for id in order {
455	        if committed.contains(&id) {
456	            if let Some(rs) = by_txn.remove(&id) {
457	                for r in rs {
458	                    if !matches!(r, WalRecord::Begin { .. }) {
459	                        out.push(r);
460	                    }
461	                }
462	            }
463	        }
464	    }
465	    out
466	}

