509	fn parse_args(argv: &[String]) -> Result<Args> {
510	    let mut db_path: Option<PathBuf> = None;
511	    let mut mode: Option<Mode> = None;
512	    let mut format = OutputFormat::Table;
513	    let mut quiet = false;
514	    let mut continue_on_error = false;
515	    let mut init: Option<PathBuf> = None;
516	
517	    let mut i = 1;
518	    while i < argv.len() {
519	        let arg = &argv[i];
520	        match arg.as_str() {
521	            "--help" | "-h" => mode = Some(Mode::Help),
522	            "--version" | "-V" => mode = Some(Mode::Version),
523	            "--repl" => mode = Some(Mode::Repl),
524	            "--quiet" => quiet = true,
525	            "--continue-on-error" => continue_on_error = true,
526	            "--eval" => {
527	                i += 1;
528	                let s = argv
529	                    .get(i)
530	                    .ok_or_else(|| MiniDbError::cli("--eval requires an argument"))?;
531	                mode = Some(Mode::Eval(s.clone()));
532	            }
533	            s if s.starts_with("--eval=") => {
534	                mode = Some(Mode::Eval(s["--eval=".len()..].to_string()));
535	            }
536	            "--file" => {
537	                i += 1;
538	                let p = argv
539	                    .get(i)
540	                    .ok_or_else(|| MiniDbError::cli("--file requires a path"))?;
541	                mode = Some(Mode::File(PathBuf::from(p)));
542	            }
543	            s if s.starts_with("--file=") => {
544	                mode = Some(Mode::File(PathBuf::from(&s["--file=".len()..])));
545	            }
546	            "--init" => {
547	                i += 1;
548	                let p = argv
549	                    .get(i)
550	                    .ok_or_else(|| MiniDbError::cli("--init requires a path"))?;
551	                init = Some(PathBuf::from(p));
552	            }
553	            s if s.starts_with("--init=") => {
554	                init = Some(PathBuf::from(&s["--init=".len()..]));
555	            }
556	            "--format" => {
557	                i += 1;
558	                let f = argv
559	                    .get(i)
560	                    .ok_or_else(|| MiniDbError::cli("--format requires a value"))?;
561	                format = OutputFormat::parse(f)?;
562	            }
563	            s if s.starts_with("--format=") => {
564	                format = OutputFormat::parse(&s["--format=".len()..])?;
565	            }

 8	    let parsed = match parse_args(&args) {
 9	        Ok(p) => p,
10	        Err(e) => {
11	            eprintln!("error: {}", e);
12	            std::process::exit(exit_code_for(&e));
13	        }
14	    };
15	    match run(parsed) {
16	        Ok(code) => std::process::exit(code),
17	        Err(e) => {
18	            eprintln!("error: {}", e);
19	            std::process::exit(exit_code_for(&e));
20	        }

205	pub fn run_sql<W: Write>(
206	    db: &mut Database,
207	    sql: &str,
208	    session: &mut Session,
209	    out: &mut W,
210	    continue_on_error: bool,
211	) -> Result<i32> {
212	    // Split out meta-commands (lines starting with `.`) from real SQL.
213	    let mut last_err: Option<MiniDbError> = None;
214	    for chunk in split_for_meta(sql) {
215	        match chunk {
216	            Chunk::Meta(m) => {
217	                if let Err(e) = run_meta(&m, db, session, out) {
218	                    eprintln!("error: {}", e);
219	                    if !continue_on_error {
220	                        return Ok(exit_code_for(&e));
221	                    }
222	                    last_err = Some(e);
223	                }
224	            }
225	            Chunk::Sql(text) => match parse_sql(&text) {
226	                Ok(stmts) => {
227	                    for s in stmts {
228	                        match db.execute(&s) {
229	                            Ok(r) => emit_result(&r, session, out)?,
230	                            Err(e) => {
231	                                eprintln!("error: {}", e);
232	                                if !continue_on_error {
233	                                    return Ok(exit_code_for(&e));
234	                                }
235	                                last_err = Some(e);
236	                            }
237	                        }
238	                    }
239	                }
240	                Err(e) => {
241	                    eprintln!("error: {}", e);
242	                    if !continue_on_error {
243	                        return Ok(exit_code_for(&e));
244	                    }
245	                    last_err = Some(e);
246	                }
247	            },
248	        }
249	    }
250	    if let Some(e) = last_err {
251	        Ok(exit_code_for(&e))
252	    } else {
253	        Ok(0)
254	    }
255	}

