282	    /// Execute a single statement; auto-commit if no explicit transaction.
283	    pub fn execute(&mut self, stmt: &Statement) -> Result<StmtResult> {
284	        match stmt {
285	            Statement::Begin => {
286	                if self.txns.is_explicit() {
287	                    return Err(MiniDbError::Runtime("transaction already active".into()));
288	                }
289	                let id = self.catalog.allocate_txn();
290	                self.txns.begin(id, true)?;
291	                self.wal.append(&WalRecord::Begin { txn_id: id })?;
292	                Ok(StmtResult::Ack("BEGIN".into()))
293	            }
294	            Statement::Commit => {
295	                if !self.txns.is_explicit() {
296	                    return Err(MiniDbError::Runtime("no active transaction".into()));
297	                }
298	                let txn = self.txns.take().unwrap();
299	                self.wal.append(&WalRecord::Commit { txn_id: txn.id })?;
300	                self.wal.sync()?;
301	                self.flush_snapshot()?;
302	                Ok(StmtResult::Ack("COMMIT".into()))
303	            }
304	            Statement::Rollback => {
305	                if !self.txns.is_explicit() {
306	                    return Err(MiniDbError::Runtime("no active transaction".into()));
307	                }
308	                let txn = self.txns.take().unwrap();
309	                // Revert in-memory mutations by re-loading the snapshot.
310	                self.wal.append(&WalRecord::Rollback { txn_id: txn.id })?;
311	                self.wal.sync()?;
312	                let snapshot = self.pages.read_snapshot()?;
313	                self.catalog = if snapshot.is_empty() {
314	                    Catalog::new()
315	                } else {
316	                    bincode::deserialize(&snapshot)?
317	                };
318	                self.wal.truncate()?;
319	                Ok(StmtResult::Ack("ROLLBACK".into()))
320	            }
321	            other => self.execute_in_txn(other),
322	        }
323	    }
324	
325	    fn execute_in_txn(&mut self, stmt: &Statement) -> Result<StmtResult> {
326	        let started_implicit = !self.txns.is_active();
327	        if started_implicit {
328	            let id = self.catalog.allocate_txn();
329	            self.txns.begin(id, false)?;
330	        }
331	        let res = self.execute_inner(stmt);
332	        match res {
333	            Ok(r) => {
334	                if started_implicit {
335	                    let txn = self.txns.take().unwrap();
336	                    self.wal.append(&WalRecord::Commit { txn_id: txn.id })?;
337	                    self.wal.sync()?;
338	                    self.flush_snapshot()?;
339	                }
340	                Ok(r)
341	            }
342	            Err(e) => {
343	                if started_implicit {
344	                    // Roll back the implicit transaction by reverting to snapshot.
345	                    let _ = self.txns.take();
346	                    let snapshot = self.pages.read_snapshot()?;
347	                    self.catalog = if snapshot.is_empty() {
348	                        Catalog::new()
349	                    } else {
350	                        bincode::deserialize(&snapshot)?
351	                    };
352	                    self.wal.truncate()?;
353	                }
354	                Err(e)
355	            }
356	        }
357	    }

57	    pub fn begin(&mut self, id: u64, explicit: bool) -> Result<()> {
