 89	    fn recover(&mut self) -> Result<()> {
 90	        let recs = self.wal.replay()?;
 91	        if recs.is_empty() {
 92	            return Ok(());
 93	        }
 94	        info!("WAL replay: {} records", recs.len());
 95	
 96	        // Determine which transactions committed.
 97	        use std::collections::HashSet;
 98	        let mut committed: HashSet<u64> = HashSet::new();
 99	        for r in &recs {
100	            if let WalRecord::Commit { txn_id } = r {
101	                committed.insert(*txn_id);
102	            }
103	        }
104	        // Apply only committed records (excluding Begin/Commit/Rollback themselves).
105	        for r in &recs {
106	            let Some(tid) = r.txn_id() else { continue };
107	            if !committed.contains(&tid) {
108	                continue;
109	            }
110	            self.apply_record(r)?;
111	        }
112	        // After replay, persist the snapshot and truncate WAL.
113	        self.flush_snapshot()?;
114	        warn!("recovery complete; WAL truncated");
115	        Ok(())

