55	/// Volcano-style iterator. Operators must implement `open`/`next`/`close` and
56	/// expose their output schema. `next` returns `Ok(None)` when exhausted.
57	pub trait PhysicalOperator {
58	    fn open(&mut self) -> Result<()>;
59	    fn next(&mut self) -> Result<Option<Tuple>>;
60	    fn close(&mut self) -> Result<()>;
61	    fn schema(&self) -> &ExecSchema;
