18	impl PhysicalOperator for Filter {
19	    fn open(&mut self) -> Result<()> {
20	        self.child.open()
21	    }
22	
23	    fn next(&mut self) -> Result<Option<Tuple>> {
24	        let schema = self.child.schema().clone();
25	        loop {
26	            let Some(row) = self.child.next()? else {
27	                return Ok(None);
28	            };
29	            let v = eval(&self.predicate, &schema, &row)?;
30	            // SQL semantics: NULL is treated as not-matching for WHERE.
31	            let pass = match v {
32	                Value::Bool(b) => b,
33	                Value::Null => false,
34	                other => other.truthy().unwrap_or(false),
35	            };
36	            if pass {
37	                return Ok(Some(row));
38	            }
39	        }
40	    }
41	
42	    fn close(&mut self) -> Result<()> {
43	        self.child.close()
44	    }
45	
46	    fn schema(&self) -> &ExecSchema {
47	        self.child.schema()
48	    }

