404	    fn build_executor(&self, plan: &PhysicalPlan) -> Result<Box<dyn PhysicalOperator>> {
405	        Ok(match plan {
406	            PhysicalPlan::SeqScan { table, alias } => {
407	                let meta = self.catalog.ensure_table_exists(table)?;
408	                Box::new(SeqScan::new(meta, alias.as_deref()))
409	            }
410	            PhysicalPlan::IndexScan {
411	                table,
412	                alias,
413	                index_name,
414	                bound,
415	                ..
416	            } => {
417	                let meta = self.catalog.ensure_table_exists(table)?;
418	                let idx = self
419	                    .catalog
420	                    .indexes
421	                    .get(&index_name.to_ascii_lowercase())
422	                    .ok_or_else(|| {
423	                        MiniDbError::Catalog(format!("no such index: {}", index_name))
424	                    })?;
425	                let (lo, hi) = match bound {
426	                    IndexBound::Eq(e) => {
427	                        let v = const_eval(e)?;
428	                        (Some(v.clone()), Some(v))
429	                    }
430	                    IndexBound::Range { lo, hi } => (
431	                        match lo {
432	                            Some((e, _)) => Some(const_eval(e)?),
433	                            None => None,
434	                        },
435	                        match hi {
436	                            Some((e, _)) => Some(const_eval(e)?),
437	                            None => None,
438	                        },
439	                    ),
440	                };
441	                Box::new(IndexScan::new(meta, idx, alias.as_deref(), bound, lo, hi))
442	            }
443	            PhysicalPlan::Filter { input, predicate } => {
444	                Box::new(Filter::new(self.build_executor(input)?, predicate.clone()))
445	            }
446	            PhysicalPlan::Project { input, projections } => Box::new(Project::new(
447	                self.build_executor(input)?,
448	                projections.clone(),
449	            )),
450	            PhysicalPlan::NestedLoopJoin { left, right, on } => Box::new(NestedLoopJoin::new(
451	                self.build_executor(left)?,
452	                self.build_executor(right)?,
453	                on.clone(),
454	            )),
455	            PhysicalPlan::Sort { input, keys } => {
456	                Box::new(Sort::new(self.build_executor(input)?, keys.clone()))
457	            }
458	            PhysicalPlan::Limit {
459	                input,
460	                limit,
461	                offset,
462	            } => Box::new(Limit::new(self.build_executor(input)?, *limit, *offset)),
463	        })

