205	pub fn run_sql<W: Write>(
206	    db: &mut Database,
207	    sql: &str,
208	    session: &mut Session,
209	    out: &mut W,
210	    continue_on_error: bool,
211	) -> Result<i32> {
212	    // Split out meta-commands (lines starting with `.`) from real SQL.
213	    let mut last_err: Option<MiniDbError> = None;
214	    for chunk in split_for_meta(sql) {
215	        match chunk {
216	            Chunk::Meta(m) => {
217	                if let Err(e) = run_meta(&m, db, session, out) {
218	                    eprintln!("error: {}", e);
219	                    if !continue_on_error {
220	                        return Ok(exit_code_for(&e));
221	                    }
222	                    last_err = Some(e);
223	                }
224	            }
225	            Chunk::Sql(text) => match parse_sql(&text) {
226	                Ok(stmts) => {
227	                    for s in stmts {
228	                        match db.execute(&s) {
229	                            Ok(r) => emit_result(&r, session, out)?,
230	                            Err(e) => {
231	                                eprintln!("error: {}", e);
232	                                if !continue_on_error {
233	                                    return Ok(exit_code_for(&e));
234	                                }
235	                                last_err = Some(e);
236	                            }
237	                        }
238	                    }
239	                }
240	                Err(e) => {
241	                    eprintln!("error: {}", e);
242	                    if !continue_on_error {
243	                        return Ok(exit_code_for(&e));
244	                    }
245	                    last_err = Some(e);
246	                }
247	            },
248	        }
249	    }
250	    if let Some(e) = last_err {
251	        Ok(exit_code_for(&e))
252	    } else {
253	        Ok(0)
254	    }
255	}

