111	    /// Persist the in-memory snapshot to pages 1..K and update header.
112	    pub fn write_snapshot(&mut self, bytes: &[u8]) -> Result<()> {
113	        let n_pages = ((bytes.len() + PAGE_SIZE - 1) / PAGE_SIZE).max(0);
114	        debug!(
115	            "writing snapshot: {} bytes across {} pages",
116	            bytes.len(),
117	            n_pages
118	        );
119	        for i in 0..n_pages {
120	            let start = i * PAGE_SIZE;
121	            let end = ((i + 1) * PAGE_SIZE).min(bytes.len());
122	            let mut page = Page::empty(PageId(1 + i as u64));
123	            page.data[..end - start].copy_from_slice(&bytes[start..end]);
124	            self.write_page(&page)?;
125	        }
126	        self.snapshot_len = bytes.len() as u64;
127	        self.num_pages = 1 + n_pages as u64;
128	        // truncate file to current pages
129	        self.file.set_len(self.num_pages * PAGE_SIZE as u64)?;
130	        self.write_header()?;
131	        self.file.sync_data()?;
132	        Ok(())
133	    }
