133	    pub fn replay(&mut self) -> Result<Vec<WalRecord>> {
134	        self.file.seek(SeekFrom::Start(0))?;
135	        let mut buf = Vec::new();
136	        self.file.read_to_end(&mut buf)?;
137	        let mut out = Vec::new();
138	        let mut i = 0usize;
139	        while i + 8 <= buf.len() {
140	            let len = u32::from_le_bytes(buf[i..i + 4].try_into().unwrap()) as usize;
141	            let crc = u32::from_le_bytes(buf[i + 4..i + 8].try_into().unwrap());
142	            if i + 8 + len > buf.len() {
143	                break; // torn write; truncate
144	            }
145	            let payload = &buf[i + 8..i + 8 + len];
146	            let mut h = Hasher::new();
147	            h.update(payload);
148	            if h.finalize() != crc {
149	                break;
150	            }
151	            let rec: WalRecord = match bincode::deserialize(payload) {
152	                Ok(r) => r,
153	                Err(_) => break,
154	            };
155	            out.push(rec);
156	            i += 8 + len;
157	        }
158	        Ok(out)
159	    }

