205	pub fn run_sql<W: Write>(
206	    db: &mut Database,
207	    sql: &str,
208	    session: &mut Session,
209	    out: &mut W,
210	    continue_on_error: bool,
211	) -> Result<i32> {
212	    // Split out meta-commands (lines starting with `.`) from real SQL.
213	    let mut last_err: Option<MiniDbError> = None;
214	    for chunk in split_for_meta(sql) {
215	        match chunk {
216	            Chunk::Meta(m) => {
217	                if let Err(e) = run_meta(&m, db, session, out) {
218	                    eprintln!("error: {}", e);
219	                    if !continue_on_error {
220	                        return Ok(exit_code_for(&e));
221	                    }
222	                    last_err = Some(e);
223	                }
224	            }
225	            Chunk::Sql(text) => match parse_sql(&text) {
226	                Ok(stmts) => {
227	                    for s in stmts {
228	                        match db.execute(&s) {
229	                            Ok(r) => emit_result(&r, session, out)?,
230	                            Err(e) => {
231	                                eprintln!("error: {}", e);
232	                                if !continue_on_error {
233	                                    return Ok(exit_code_for(&e));
234	                                }
235	                                last_err = Some(e);
236	                            }
237	                        }
238	                    }
239	                }
240	                Err(e) => {
241	                    eprintln!("error: {}", e);
242	                    if !continue_on_error {
243	                        return Ok(exit_code_for(&e));
244	                    }
245	                    last_err = Some(e);
246	                }
247	            },
248	        }
249	    }
250	    if let Some(e) = last_err {
251	        Ok(exit_code_for(&e))
252	    } else {
253	        Ok(0)
254	    }
255	}

257	fn run_repl(db: &mut Database, session: &mut Session) -> Result<i32> {
258	    let stdin = io::stdin();
259	    let stdout = io::stdout();
260	    let mut out = stdout.lock();
261	    let mut buf = String::new();
262	    let mut interactive = atty_stdin();
263	    if interactive {
264	        eprintln!(
265	            "minidb {} — type SQL ending with ';', or .exit to quit",
266	            env!("CARGO_PKG_VERSION")
267	        );
268	    }
269	    loop {
270	        if interactive {
271	            eprint!("minidb> ");
272	            let _ = io::stderr().flush();
273	        }
274	        let mut line = String::new();
275	        let n = stdin.lock().read_line(&mut line)?;
276	        if n == 0 {
277	            break;
278	        }
279	        buf.push_str(&line);
280	        // A leading `.` at the head of `buf` is a meta-command; it terminates
281	        // at the newline rather than at `;`.
282	        while let Some(rest) = buf.strip_prefix('.') {
283	            // find newline
284	            if let Some(nl) = rest.find('\n') {
285	                let cmd: String = format!(".{}", &rest[..nl]).trim().to_string();
286	                let consumed = 1 + nl + 1;
287	                buf = buf[consumed..].to_string();
288	                if let Err(e) = run_meta(&cmd, db, session, &mut out) {
289	                    eprintln!("error: {}", e);
290	                }
291	                if cmd.eq_ignore_ascii_case(".exit") {
292	                    return Ok(0);
293	                }
294	            } else {
295	                break;
296	            }
297	        }
298	        // Process complete statements terminated by `;` (outside string literals).
299	        loop {
300	            match find_terminator(&buf) {
301	                Some(pos) => {
302	                    let stmt: String = buf.drain(..=pos).collect();
303	                    let trimmed = stmt.trim().trim_end_matches(';').trim().to_string();
304	                    if trimmed.is_empty() {
305	                        continue;
306	                    }
307	                    if trimmed.starts_with('.') {
308	                        if let Err(e) = run_meta(&trimmed, db, session, &mut out) {
309	                            eprintln!("error: {}", e);
310	                        }
311	                        if trimmed.eq_ignore_ascii_case(".exit") {
312	                            return Ok(0);
313	                        }
314	                    } else {
315	                        match parse_sql(&format!("{};", trimmed)) {
316	                            Ok(stmts) => {
317	                                for s in stmts {
318	                                    match db.execute(&s) {
319	                                        Ok(r) => {
320	                                            if let Err(e) = emit_result(&r, session, &mut out) {
321	                                                eprintln!("error: {}", e);
322	                                            }
323	                                        }
324	                                        Err(e) => eprintln!("error: {}", e),
325	                                    }
326	                                }
327	                            }
328	                            Err(e) => eprintln!("error: {}", e),
329	                        }
330	                    }
331	                }
332	                None => break,
333	            }
334	        }
335	        let _ = interactive; // avoid warning
336	        interactive = atty_stdin();
337	    }
338	    Ok(0)
339	}

468	fn emit_result<W: Write>(r: &StmtResult, session: &Session, out: &mut W) -> Result<()> {
469	    match r {
470	        StmtResult::Rows { schema, rows } => {
471	            match session.format {
472	                OutputFormat::Table => write_table(out, schema, rows)?,
473	                OutputFormat::Csv => write_csv(out, schema, rows)?,
474	                OutputFormat::Json => write_json(out, schema, rows)?,
475	            }
476	            if !session.quiet {
477	                let n = rows.len();
478	                let label = if n == 1 { "row" } else { "rows" };
479	                eprintln!("ok {} {}", n, label);
480	            }
481	        }
482	        StmtResult::Mutation { affected, kind } => {
483	            if !session.quiet {
484	                let label = match kind {
485	                    MutationKind::Insert | MutationKind::Update | MutationKind::Delete => {
486	                        if *affected == 1 {
487	                            "row affected"
488	                        } else {
489	                            "rows affected"
490	                        }
491	                    }
492	                    MutationKind::Ddl => "ok",
493	                };
494	                if matches!(kind, MutationKind::Ddl) {
495	                    eprintln!("ok");
496	                } else {
497	                    eprintln!("ok {} {}", affected, label);
498	                }
499	            }
500	        }
501	        StmtResult::Ack(s) => {
502	            if !session.quiet {
503	                eprintln!("ok {}", s);
504	            }
505	        }
506	    }
507	    Ok(())

