155	/// Run the CLI; return the process exit code.
156	pub fn run<R: Read, W: Write, E: Write>(
157	    argv: Vec<String>,
158	    stdin: R,
159	    stdout: &mut W,
160	    stderr: &mut E,
161	    is_tty: bool,
162	) -> i32 {
163	    let opt = match parse_args(&argv) {
164	        Ok(o) => o,
165	        Err(e) => {
166	            let _ = writeln!(stderr, "minidb: {}", e);
167	            let _ = writeln!(stderr, "{}", HELP_TEXT);
168	            return 2;
169	        }

204	    // Open database
205	    let mut db = match Database::open(&opt.db) {
206	        Ok(d) => d,
207	        Err(e) => {
208	            let _ = writeln!(stderr, "minidb: {}", e);
209	            return classify_exit(&e);
210	        }
211	    };
212	
213	    if let Some(sql) = &opt.eval {
214	        return execute_string(&mut db, sql, &opt, stdout, stderr);
215	    }
216	    if let Some(path) = &opt.file {
217	        let sql = match std::fs::read_to_string(path) {
218	            Ok(s) => s,
219	            Err(e) => {
220	                let _ = writeln!(stderr, "minidb: cannot read {}: {}", path.display(), e);
221	                return 3;
222	            }
223	        };
224	        return execute_script(&mut db, &sql, &opt, stdout, stderr);
225	    }
226	
227	    if opt.repl || is_tty {
228	        return repl(&mut db, opt, stdin, stdout, stderr);
229	    }
230	    // Non-interactive stdin: read all and execute as a script.
231	    let mut buf = String::new();
232	    let mut reader = BufReader::new(stdin);
233	    if let Err(e) = reader.read_to_string(&mut buf) {
234	        let _ = writeln!(stderr, "minidb: {}", e);
235	        return 3;
236	    }
237	    execute_script(&mut db, &buf, &opt, stdout, stderr)
238	}
