316	    pub fn execute_statement(&mut self, stmt: Statement) -> Result<StatementResult> {
317	        // Auto-begin a transaction for DML/DDL when none is active.
318	        let needs_txn = match &stmt {
319	            Statement::Begin | Statement::Commit | Statement::Rollback | Statement::Select(_) => {
320	                false
321	            }
322	            _ => true,
323	        };
324	        let auto = needs_txn && !self.txn.in_transaction();
325	        if auto {
326	            self.txn.begin(
327	                false,
328	                &self.catalog,
329	                &self.indexes,
330	                self.pager.next_page_id(),
331	            )?;
332	        }
333	        let res = self.exec_inner(stmt);
334	        match (auto, res) {
335	            (true, Ok(r)) => {
336	                self.commit_internal()?;
337	                Ok(r)
338	            }
339	            (true, Err(e)) => {
340	                self.rollback_internal()?;
341	                Err(e)
342	            }
343	            (false, r) => r,
344	        }
345	    }

 71	    pub fn begin(
 72	        &mut self,
 73	        explicit: bool,
 74	        catalog: &Catalog,
 75	        indexes: &std::collections::HashMap<String, BTreeIndex>,
 76	        next_page: u64,
 77	    ) -> Result<u64> {
 78	        if self.current.is_some() {
 79	            return Err(crate::error::MiniDbError::Runtime(
 80	                "a transaction is already active".into(),
 81	            ));
 82	        }
 83	        let id = self.next_id;
 84	        self.next_id += 1;
 85	        self.current = Some(Transaction {
 86	            id,
 87	            explicit,
 88	            state: TxnState::Active,
 89	            records: vec![WalRecord::Begin { txn_id: id }],
 90	            before_pages: HashMap::new(),
 91	            before_catalog: Some(catalog.clone()),
 92	            before_indexes: indexes.clone(),
 93	            before_next_page: next_page,
 94	        });
 95	        Ok(id)
 96	    }
