880	    fn commit_internal(&mut self) -> Result<()> {
881	        let txn = self.txn.take().expect("txn active");
882	        // Skip empty txns (no records beyond Begin) — still treat as committed.
883	        for r in &txn.records {
884	            self.wal.append(r)?;
885	        }
886	        self.wal.append(&WalRecord::Commit { txn_id: txn.id })?;
887	        self.wal.fsync()?;
888	        // Flush pager + catalog + indexes
889	        self.pager.flush()?;
890	        save_catalog(&catalog_path(&self.path), &self.catalog)?;
891	        for (name, idx) in &self.indexes {
892	            save_index(&index_path(&self.path, name), idx)?;
893	        }
894	        // Truncate WAL after successful checkpoint
895	        self.wal.truncate()?;
896	        Ok(())
897	    }
