899	    fn rollback_internal(&mut self) -> Result<()> {
900	        let txn = self.txn.take().expect("txn active");
901	        if let Some(cat) = txn.before_catalog {
902	            self.catalog = cat;
903	        }
904	        self.indexes = txn.before_indexes;
905	        // Discard cached pager state — uncommitted pages are not on disk, so
906	        // future reads will pull the pre-transaction state from the file.
907	        self.pager.discard_cache();
908	        self.pager.reset_next_page(txn.before_next_page);
909	        Ok(())

