296	    pub fn append(&mut self, rec: &WalRecord) -> Result<()> {
297	        let payload = rec.encode();
298	        let crc = crc32fast::hash(&payload);
299	        self.file.seek(SeekFrom::End(0))?;
300	        self.file.write_all(&(payload.len() as u32).to_le_bytes())?;
301	        self.file.write_all(&crc.to_le_bytes())?;
302	        self.file.write_all(&payload)?;
303	        Ok(())
304	    }
305	
306	    pub fn fsync(&mut self) -> Result<()> {
307	        self.file.sync_all()?;
308	        Ok(())
309	    }
310	
311	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
312	        let mut out = Vec::new();
313	        self.file.seek(SeekFrom::Start(0))?;
314	        let mut hdr = [0u8; 8];
315	        loop {
316	            match self.file.read_exact(&mut hdr) {
317	                Ok(()) => {}
318	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
319	                Err(e) => return Err(e.into()),
320	            }
321	            let len = u32::from_le_bytes([hdr[0], hdr[1], hdr[2], hdr[3]]) as usize;
322	            let crc = u32::from_le_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
323	            let mut payload = vec![0u8; len];
324	            match self.file.read_exact(&mut payload) {
325	                Ok(()) => {}
326	                Err(_) => break, // torn write at end
327	            }
328	            let actual_crc = crc32fast::hash(&payload);
329	            if actual_crc != crc {
330	                log::warn!("WAL crc mismatch — stopping replay at this record");
331	                break;
332	            }
333	            match WalRecord::decode(&payload) {
334	                Ok(r) => out.push(r),
335	                Err(e) => {
336	                    log::warn!("WAL decode error: {} — stopping replay", e);
337	                    break;
338	                }
339	            }
340	        }
341	        Ok(out)
342	    }
343	
344	    pub fn truncate(&mut self) -> Result<()> {
345	        self.file.set_len(0)?;
346	        self.file.sync_all()?;
347	        self.file.seek(SeekFrom::Start(0))?;
348	        Ok(())
349	    }
350	
351	    pub fn path(&self) -> &Path {
352	        &self.path
353	    }
354	}
