356	/// Replay records, return only those belonging to fully-committed transactions
357	/// (i.e. ones with a Commit record present).
358	pub fn committed_records(records: Vec<WalRecord>) -> Vec<WalRecord> {
359	    use std::collections::HashSet;
360	    let mut committed: HashSet<u64> = HashSet::new();
361	    for r in &records {
362	        if let WalRecord::Commit { txn_id } = r {
363	            committed.insert(*txn_id);
364	        }
365	    }
366	    records
367	        .into_iter()
368	        .filter(|r| committed.contains(&r.txn_id()))
369	        .collect()
370	}

