517	    fn create_index_internal(
518	        &mut self,
519	        name: String,
520	        table: String,
521	        column: String,
522	        check_dup: bool,
523	    ) -> Result<()> {
524	        if self.catalog.indexes.contains_key(&name) {
525	            if check_dup {
526	                return Err(MiniDbError::AlreadyExists(format!("index {}", name)));
527	            }
528	            return Ok(());
529	        }
530	        self.catalog.add_index(IndexSchema {
531	            name: name.clone(),
532	            table: table.clone(),
533	            column: column.clone(),
534	        })?;
535	        self.indexes.insert(name.clone(), BTreeIndex::new());
536	        // Populate from existing data
537	        let t = self.catalog.get_table(&table)?.clone();
538	        let col_idx = t
539	            .column_index(&column)
540	            .ok_or_else(|| MiniDbError::NoSuchColumn(column.clone()))?;
541	        let types = t.data_types();
542	        let first = t.first_page;
543	        let mut entries: Vec<(Value, RowId)> = Vec::new();
544	        {
545	            let mut iter = HeapIter::new(&mut self.pager, first);
546	            while let Some((rid, bytes)) = iter.next() {
547	                let vals = decode_tuple(&bytes)?;
548	                let coerced: Result<Vec<Value>> = vals
549	                    .into_iter()
550	                    .zip(types.iter())
551	                    .map(|(v, t)| v.coerce(*t))
552	                    .collect();
553	                let row = coerced?;
554	                entries.push((row[col_idx].clone(), rid));
555	            }
556	        }
557	        let idx_ref = self.indexes.get_mut(&name).unwrap();
558	        for (k, rid) in entries {
559	            idx_ref.insert(k, rid);
560	        }

656	        // Encode and insert
657	        let bytes = encode_tuple(&values);
658	        let first = self.catalog.get_table(table)?.first_page;
659	        let (rid, new_first) = heap_insert(&mut self.pager, first, &bytes)?;
660	        if first.is_none() {
661	            self.catalog.get_table_mut(table).unwrap().first_page = Some(new_first);
662	        }
663	        // Update indexes
664	        let indexes_for: Vec<IndexSchema> = self
665	            .catalog
666	            .indexes_for(table)
667	            .into_iter()
668	            .cloned()
669	            .collect();
670	        for idx_meta in indexes_for {
671	            let col_i = t.column_index(&idx_meta.column).unwrap();
672	            let idx = self.indexes.get_mut(&idx_meta.name).unwrap();
673	            idx.insert(values[col_i].clone(), rid);
674	        }
675	        let txn_id = self.txn.current().map(|t| t.id).unwrap_or(0);
676	        self.txn.record(WalRecord::Insert {
677	            txn_id,
678	            table: table.to_string(),
679	            page: rid.page.raw(),
680	            slot: rid.slot,
681	            tuple: bytes,
682	        });

