134	            .get(&self.index_name)
135	            .ok_or_else(|| crate::error::MiniDbError::NoSuchIndex(self.index_name.clone()))?;
136	        let row_ids = if let Some(eq) = &self.eq {
137	            idx.equal_range(eq)
138	        } else {
139	            idx.range_scan(self.lo.as_ref(), self.lo_inc, self.hi.as_ref(), self.hi_inc)
140	        };
141	        let t = ctx.catalog.get_table(&self.table)?;
142	        let types = t.data_types();
143	        for rid in row_ids {
144	            let pg = ctx.pager.read_page(rid.page)?;
145	            if let Some(buf) = crate::storage::heap::read_tuple(pg, rid.slot) {
146	                let vals = decode_tuple(buf)?;
147	                let coerced: Result<Vec<Value>> = vals
148	                    .into_iter()
149	                    .zip(types.iter())
150	                    .map(|(v, t)| v.coerce(*t))
151	                    .collect();
152	                self.rows.push(Row::new(coerced?));
153	            }
154	        }
155	        Ok(())
156	    }
