 89	    pub fn equal_range(&self, key: &Value) -> Vec<RowId> {
 90	        let from = (IndexKey(key.clone()), 0u64, 0u16);
 91	        let to = (IndexKey(key.clone()), u64::MAX, u16::MAX);
 92	        self.map
 93	            .range(from..=to)
 94	            .map(|((_, p, s), _)| RowId {
 95	                page: PageId(*p),
 96	                slot: *s,
 97	            })
 98	            .collect()
 99	    }
100	
101	    pub fn range_scan(
102	        &self,
103	        lo: Option<&Value>,
104	        lo_inclusive: bool,
105	        hi: Option<&Value>,
106	        hi_inclusive: bool,
107	    ) -> Vec<RowId> {
108	        let mut out = Vec::new();
109	        for ((k, p, s), _) in self.map.iter() {
110	            if let Some(l) = lo {
111	                let cmp = k.cmp(&IndexKey(l.clone()));
112	                if cmp == Ordering::Less || (cmp == Ordering::Equal && !lo_inclusive) {
113	                    continue;
114	                }
115	            }
116	            if let Some(h) = hi {
117	                let cmp = k.cmp(&IndexKey(h.clone()));
118	                if cmp == Ordering::Greater || (cmp == Ordering::Equal && !hi_inclusive) {
119	                    continue;
120	                }
121	            }
122	            out.push(RowId {
123	                page: PageId(*p),
124	                slot: *s,
125	            });
126	        }
127	        out
128	    }

316	    pub fn execute_statement(&mut self, stmt: Statement) -> Result<StatementResult> {
317	        // Auto-begin a transaction for DML/DDL when none is active.
318	        let needs_txn = match &stmt {
319	            Statement::Begin | Statement::Commit | Statement::Rollback | Statement::Select(_) => {
320	                false
321	            }
322	            _ => true,
323	        };
324	        let auto = needs_txn && !self.txn.in_transaction();
325	        if auto {
326	            self.txn.begin(
327	                false,
328	                &self.catalog,
329	                &self.indexes,
330	                self.pager.next_page_id(),
331	            )?;
332	        }
333	        let res = self.exec_inner(stmt);
334	        match (auto, res) {
335	            (true, Ok(r)) => {
336	                self.commit_internal()?;
337	                Ok(r)
338	            }
339	            (true, Err(e)) => {
340	                self.rollback_internal()?;
341	                Err(e)
342	            }
343	            (false, r) => r,
344	        }
345	    }
