13	impl Parser {
14	    pub fn parse_sql(src: &str) -> Result<Vec<Statement>> {
15	        let tokens = Lexer::new(src).tokenize()?;
16	        let mut p = Parser { tokens, pos: 0 };
17	        let mut stmts = Vec::new();
18	        loop {
19	            // skip leading semicolons
20	            while matches!(p.peek().token, Token::Semicolon) {
21	                p.bump();
22	            }
23	            if matches!(p.peek().token, Token::Eof) {
24	                break;
25	            }
26	            let s = p.parse_statement()?;
27	            stmts.push(s);
28	            match &p.peek().token {
29	                Token::Semicolon => {
30	                    p.bump();
31	                }
32	                Token::Eof => break,
33	                _ => {
34	                    let t = p.peek().clone();
35	                    return Err(MiniDbError::Parse {
36	                        line: t.line,
37	                        col: t.col,
38	                        msg: format!("expected ';' or EOF, got {:?}", t.token),
39	                    });
40	                }
41	            }
42	        }
43	        Ok(stmts)
44	    }

