36	pub fn plan_select(s: &Select) -> Result<LogicalPlan> {
37	    let mut plan = LogicalPlan::Scan {
38	        table: s.from.name.clone(),
39	        alias: s.from.alias.clone(),
40	    };
41	    if let Some(j) = &s.join {
42	        let right = LogicalPlan::Scan {
43	            table: j.right.name.clone(),
44	            alias: j.right.alias.clone(),
45	        };
46	        plan = LogicalPlan::Join {
47	            left: Box::new(plan),
48	            right: Box::new(right),
49	            on: j.on.clone(),
50	        };
51	    }
52	    if let Some(w) = &s.where_clause {
53	        plan = LogicalPlan::Filter {
54	            input: Box::new(plan),
55	            predicate: w.clone(),
56	        };
57	    }
58	    plan = LogicalPlan::Project {
59	        input: Box::new(plan),
60	        projections: s.projections.clone(),
61	    };
62	    if !s.order_by.is_empty() {
63	        plan = LogicalPlan::Sort {
64	            input: Box::new(plan),
65	            keys: s.order_by.clone(),
66	        };
67	    }
68	    if s.limit.is_some() || s.offset.is_some() {
69	        let limit = s.limit.as_ref().map(|e| eval_const_int(e)).transpose()?;
70	        let offset = s.offset.as_ref().map(|e| eval_const_int(e)).transpose()?;
71	        plan = LogicalPlan::Limit {
72	            input: Box::new(plan),
73	            limit,
74	            offset,
75	        };
76	    }
77	    Ok(plan)

 94	/// Try to extract `(column, op, literal)` triples ANDed together at the top of
 95	/// a predicate. Used for index selection.
 96	pub fn extract_simple_filters(e: &Expr) -> Vec<(String, BinaryOp, crate::types::Value)> {
 97	    use crate::types::Value;
 98	    let mut out = Vec::new();
 99	    walk(e, &mut out);
100	    fn walk(e: &Expr, out: &mut Vec<(String, BinaryOp, Value)>) {
101	        match e {
102	            Expr::BinaryOp {
103	                op: BinaryOp::And,
104	                left,
105	                right,
106	            } => {
107	                walk(left, out);
108	                walk(right, out);
109	            }
110	            Expr::BinaryOp { op, left, right } => {
111	                let interesting = matches!(
112	                    op,
113	                    BinaryOp::Eq
114	                        | BinaryOp::Neq
115	                        | BinaryOp::Lt
116	                        | BinaryOp::Lte
117	                        | BinaryOp::Gt
118	                        | BinaryOp::Gte
119	                );
120	                if !interesting {
121	                    return;
122	                }
123	                if let (Expr::Column { name, .. }, Expr::Literal(v)) =
124	                    (left.as_ref(), right.as_ref())
125	                {
126	                    out.push((name.clone(), *op, v.clone()));
127	                } else if let (Expr::Literal(v), Expr::Column { name, .. }) =
128	                    (left.as_ref(), right.as_ref())
129	                {
130	                    let flipped = match op {
131	                        BinaryOp::Lt => BinaryOp::Gt,
132	                        BinaryOp::Lte => BinaryOp::Gte,
133	                        BinaryOp::Gt => BinaryOp::Lt,
134	                        BinaryOp::Gte => BinaryOp::Lte,
135	                        other => *other,
136	                    };
137	                    out.push((name.clone(), flipped, v.clone()));
138	                }
139	            }
140	            _ => {}
141	        }
142	    }
143	    out
144	}

111	pub fn build_physical(cat: &Catalog, plan: LogicalPlan) -> Result<PhysicalPlan> {
112	    match plan {
113	        LogicalPlan::Scan { table, alias } => {
114	            let t = cat.get_table(&table)?;
115	            let cols = t
116	                .columns
117	                .iter()
118	                .map(|c| ColumnRef {
119	                    table: Some(alias.clone().unwrap_or_else(|| table.clone())),
120	                    name: c.name.clone(),
121	                    data_type: c.data_type,
122	                })
123	                .collect();
124	            Ok(PhysicalPlan::SeqScan {
125	                table,
126	                alias,
127	                schema: Schema { columns: cols },
128	            })
129	        }
130	        LogicalPlan::Join { left, right, on } => {
131	            let l = build_physical(cat, *left)?;
132	            let r = build_physical(cat, *right)?;
133	            let mut cols = l.schema().columns.clone();
134	            cols.extend_from_slice(&r.schema().columns);
135	            Ok(PhysicalPlan::NestedLoopJoin {
136	                left: Box::new(l),
137	                right: Box::new(r),
138	                on,
139	                schema: Schema { columns: cols },
140	            })
141	        }
142	        LogicalPlan::Filter { input, predicate } => {
143	            let phys = build_physical(cat, *input)?;
144	            // Try to push down to IndexScan when predicate is a single eq/range on an indexed column.
145	            if let PhysicalPlan::SeqScan {
146	                table,
147	                alias,
148	                schema,
149	            } = &phys
150	            {
151	                let simples = extract_simple_filters(&predicate);
152	                if simples.len() == 1 {
153	                    let (col, op, val) = &simples[0];
154	                    let idx_opt = cat
155	                        .indexes_for(table)
156	                        .into_iter()
157	                        .find(|i| i.column == *col);
158	                    if let Some(idx) = idx_opt {
159	                        use crate::parser::ast::BinaryOp;
160	                        let mut eq = None;
161	                        let (mut lo, mut lo_inc, mut hi, mut hi_inc) = (None, false, None, false);
162	                        match op {
163	                            BinaryOp::Eq => eq = Some(val.clone()),
164	                            BinaryOp::Lt => {
165	                                hi = Some(val.clone());
166	                                hi_inc = false;
167	                            }
168	                            BinaryOp::Lte => {
169	                                hi = Some(val.clone());
170	                                hi_inc = true;
171	                            }
172	                            BinaryOp::Gt => {
173	                                lo = Some(val.clone());
174	                                lo_inc = false;
175	                            }
176	                            BinaryOp::Gte => {
177	                                lo = Some(val.clone());
178	                                lo_inc = true;
179	                            }
180	                            _ => {}
181	                        }
182	                        if eq.is_some() || lo.is_some() || hi.is_some() {
183	                            let new = PhysicalPlan::IndexScan {
184	                                table: table.clone(),
185	                                alias: alias.clone(),
186	                                index_name: idx.name.clone(),
187	                                column: col.clone(),
188	                                lo,
189	                                lo_inclusive: lo_inc,
190	                                hi,
191	                                hi_inclusive: hi_inc,
192	                                eq,
193	                                schema: schema.clone(),
194	                            };
195	                            return Ok(PhysicalPlan::Filter {
196	                                schema: new.schema().clone(),
197	                                input: Box::new(new),
198	                                predicate,
199	                            });
200	                        }
201	                    }
202	                }
203	            }
204	            let schema = phys.schema().clone();
205	            Ok(PhysicalPlan::Filter {
206	                input: Box::new(phys),
207	                predicate,
208	                schema,
209	            })

31	impl fmt::Display for MiniDbError {
32	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
33	        match self {
34	            MiniDbError::Io(e) => write!(f, "io error: {}", e),
35	            MiniDbError::Lex { line, col, msg } => {
36	                write!(f, "lex error at line {} col {}: {}", line, col, msg)
37	            }
38	            MiniDbError::Parse { line, col, msg } => {
