 9	pub fn eval(expr: &Expr, row: &Row, schema: &Schema) -> Result<Value> {
10	    match expr {
11	        Expr::Literal(v) => Ok(v.clone()),
12	        Expr::Column { table, name } => {
13	            let idx = schema.find(table.as_deref(), name).ok_or_else(|| {
14	                MiniDbError::NoSuchColumn(match table {
15	                    Some(t) => format!("{}.{}", t, name),
16	                    None => name.clone(),
17	                })
18	            })?;
19	            Ok(row.0[idx].clone())
20	        }
21	        Expr::UnaryOp { op, expr } => {
22	            let v = eval(expr, row, schema)?;
23	            match op {
24	                UnaryOp::Neg => match v {
25	                    Value::Null => Ok(Value::Null),
26	                    Value::Int(i) => Ok(Value::Int(-i)),
27	                    Value::Real(r) => Ok(Value::Real(-r)),
28	                    other => Err(MiniDbError::Type(format!("cannot negate {:?}", other))),
29	                },
30	                UnaryOp::Not => Ok(tribool_to_value(TriBool::from_value(&v).not())),
31	            }
32	        }
33	        Expr::BinaryOp { op, left, right } => {
34	            let l = eval(left, row, schema)?;
35	            let r = eval(right, row, schema)?;
36	            apply_binary(*op, l, r)
37	        }
38	        Expr::IsNull(e) => {
39	            let v = eval(e, row, schema)?;
40	            Ok(Value::Bool(v.is_null()))
41	        }
42	        Expr::IsNotNull(e) => {
43	            let v = eval(e, row, schema)?;
44	            Ok(Value::Bool(!v.is_null()))
45	        }
46	        Expr::Function { name, args } => {
47	            let vals: Result<Vec<Value>> = args.iter().map(|a| eval(a, row, schema)).collect();
48	            let vals = vals?;
49	            apply_function(name, &vals)
50	        }

