 87	pub fn parse_args(argv: &[String]) -> std::result::Result<CliOptions, String> {
 88	    let mut opt = CliOptions::default();
 89	    let mut i = 1;
 90	    while i < argv.len() {
 91	        let a = &argv[i];
 92	        match a.as_str() {
 93	            "--help" | "-h" => {
 94	                opt.show_help = true;
 95	                i += 1;
 96	            }
 97	            "--version" | "-V" => {
 98	                opt.show_version = true;
 99	                i += 1;
100	            }
101	            "--repl" => {
102	                opt.repl = true;
103	                i += 1;
104	            }
105	            "--quiet" => {
106	                opt.quiet = true;
107	                i += 1;
108	            }
109	            "--continue-on-error" => {
110	                opt.continue_on_error = true;
111	                i += 1;
112	            }
113	            "--init" => {
114	                opt.init = true;
115	                i += 1;
116	            }
117	            "--db" => {
118	                i += 1;
119	                if i >= argv.len() {
120	                    return Err("--db expects a path".into());
121	                }
122	                opt.db = PathBuf::from(&argv[i]);
123	                i += 1;
124	            }
125	            "--eval" => {
126	                i += 1;
127	                if i >= argv.len() {
128	                    return Err("--eval expects a SQL string".into());
129	                }
130	                opt.eval = Some(argv[i].clone());
131	                i += 1;
132	            }
133	            "--file" => {
134	                i += 1;
135	                if i >= argv.len() {
136	                    return Err("--file expects a path".into());
137	                }
138	                opt.file = Some(PathBuf::from(&argv[i]));
139	                i += 1;
140	            }
141	            "--format" => {
142	                i += 1;
143	                if i >= argv.len() {
144	                    return Err("--format expects a value".into());
145	                }
146	                opt.format = OutputFormat::parse(&argv[i])?;
147	                i += 1;
148	            }
149	            other => return Err(format!("unknown argument: {}", other)),
150	        }
151	    }
152	    Ok(opt)
153	}

313	fn repl<R: Read, W: Write, E: Write>(
314	    db: &mut Database,
315	    mut opt: CliOptions,
316	    stdin: R,
317	    stdout: &mut W,
318	    stderr: &mut E,
319	) -> i32 {
320	    let mut reader = BufReader::new(stdin);
321	    let mut buffer = String::new();
322	    let _ = writeln!(stderr, "minidb {} — type .exit to quit", VERSION);
323	    loop {
324	        if buffer.is_empty() {
325	            let _ = write!(stderr, "minidb> ");
326	        } else {
327	            let _ = write!(stderr, "    ... ");
328	        }
329	        let _ = stderr.flush();
330	        let mut line = String::new();
331	        match reader.read_line(&mut line) {
332	            Ok(0) => break,
333	            Ok(_) => {}
334	            Err(e) => {
335	                let _ = writeln!(stderr, "minidb: {}", e);
336	                return 3;
337	            }
338	        }
339	        buffer.push_str(&line);
340	
341	        // Meta-commands at the start of a fresh buffer
342	        let trimmed = buffer.trim();
343	        if trimmed.starts_with('.') && (line.ends_with('\n') || line.ends_with(';')) {
344	            let cmd = trimmed
345	                .trim_end_matches(';')
346	                .trim_start_matches('.')
347	                .to_string();
348	            buffer.clear();
349	            match handle_meta(db, &cmd, &opt, stdout, stderr) {
350	                Some(_code) => {
351	                    if cmd == "exit" {
352	                        return 0;
353	                    }
354	                    // continue
355	                }
356	                None => {
357	                    let _ = writeln!(stderr, "unknown meta-command: .{}", cmd);
358	                }
359	            }
360	            // .format may have changed the format
361	            opt.format = current_format();
362	            continue;
363	        }

405	fn handle_meta<W: Write, E: Write>(
406	    db: &mut Database,
407	    cmd: &str,
408	    _opt: &CliOptions,
409	    stdout: &mut W,
410	    stderr: &mut E,
411	) -> Option<i32> {
412	    let parts: Vec<&str> = cmd.split_whitespace().collect();
413	    let head = parts.first().map(|s| *s).unwrap_or("");
414	    match head {
415	        "exit" | "quit" => {
416	            // signal exit; in REPL we return immediately
417	            std::process::exit(0);
418	        }
419	        "tables" => {
420	            let mut names: Vec<&String> = db.catalog.tables.keys().collect();
421	            names.sort();
422	            for n in names {
423	                let _ = writeln!(stdout, "{}", n);
424	            }
425	            Some(0)
426	        }
427	        "indexes" => {
428	            let mut idx: Vec<&crate::catalog::IndexSchema> = db
429	                .catalog
430	                .indexes
431	                .values()
432	                .filter(|i| !i.name.starts_with("__"))
433	                .collect();
434	            idx.sort_by(|a, b| a.name.cmp(&b.name));
435	            for i in idx {
436	                let _ = writeln!(stdout, "{}\t{}\t{}", i.name, i.table, i.column);
437	            }
438	            Some(0)
439	        }
440	        "schema" => {
441	            let target = parts.get(1);
442	            let mut names: Vec<String> = db.catalog.tables.keys().cloned().collect();
443	            names.sort();
444	            for n in names {
445	                if let Some(t) = target {
446	                    if &n != t {
447	                        continue;
448	                    }
449	                }
450	                let ts = db.catalog.tables.get(&n).unwrap();
451	                let _ = writeln!(stdout, "{}", schema_to_sql(ts));
452	            }
453	            Some(0)
454	        }
455	        "format" => {
456	            if let Some(kind) = parts.get(1) {
457	                match OutputFormat::parse(kind) {
458	                    Ok(f) => {
459	                        set_format(f);
460	                        Some(0)
461	                    }
462	                    Err(e) => {
463	                        let _ = writeln!(stderr, "{}", e);
464	                        Some(2)
465	                    }
466	                }
467	            } else {
468	                let _ = writeln!(stderr, ".format expects a kind");
469	                Some(2)
470	            }
471	        }

549	fn emit_result<W: Write, E: Write>(
550	    r: &StatementResult,
551	    opt: &CliOptions,
552	    stdout: &mut W,
553	    stderr: &mut E,
554	) {
555	    let fmt =
556	        if matches!(opt.format, OutputFormat::Table) && current_format() != OutputFormat::Table {
557	            current_format()
558	        } else {
559	            opt.format
560	        };
561	    match r {
562	        StatementResult::Rows { columns, rows } => {
563	            match fmt {
564	                OutputFormat::Table => print_table(columns, rows, stdout),
565	                OutputFormat::Csv => print_csv(columns, rows, stdout),
566	                OutputFormat::Json => print_json(columns, rows, stdout),
567	            }

204	    // Open database
205	    let mut db = match Database::open(&opt.db) {
206	        Ok(d) => d,
207	        Err(e) => {
208	            let _ = writeln!(stderr, "minidb: {}", e);
209	            return classify_exit(&e);
210	        }
211	    };
212	
213	    if let Some(sql) = &opt.eval {
214	        return execute_string(&mut db, sql, &opt, stdout, stderr);
215	    }
216	    if let Some(path) = &opt.file {
217	        let sql = match std::fs::read_to_string(path) {
218	            Ok(s) => s,
219	            Err(e) => {
220	                let _ = writeln!(stderr, "minidb: cannot read {}: {}", path.display(), e);
221	                return 3;
222	            }
223	        };
224	        return execute_script(&mut db, &sql, &opt, stdout, stderr);

