674	fn print_json<W: Write>(cols: &[String], rows: &[Vec<Value>], out: &mut W) {
675	    let _ = write!(out, "[");
676	    for (ri, r) in rows.iter().enumerate() {
677	        if ri > 0 {
678	            let _ = write!(out, ",");
679	        }
680	        let _ = write!(out, "{{");
681	        for (ci, v) in r.iter().enumerate() {
682	            if ci > 0 {
683	                let _ = write!(out, ",");
684	            }
685	            let _ = write!(out, "{}:{}", json_string(&cols[ci]), v.to_json());
