11	/// Pager: a thin abstraction over a file of fixed-size pages.
12	/// Pages are cached in memory; `flush` writes dirty pages and fsyncs.
13	pub struct Pager {
14	    file: File,
15	    path: PathBuf,
16	    cache: HashMap<PageId, Page>,
17	    dirty: HashMap<PageId, bool>,
18	    next_page: u64,
19	}
