21	impl Pager {
22	    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self> {
23	        let path = path.as_ref().to_path_buf();
24	        let mut file = OpenOptions::new()
25	            .read(true)
26	            .write(true)
27	            .create(true)
28	            .open(&path)?;
29	        let len = file.metadata()?.len();
30	        let next_page = if len == 0 {
31	            1 // page 0 is meta
32	        } else {
33	            len / PAGE_SIZE as u64
34	        };
35	        if len == 0 {
36	            // Initialize meta page
37	            let mut meta = Page::empty(PageId::META);
38	            meta.data[..MAGIC.len()].copy_from_slice(MAGIC);
39	            meta.data[MAGIC.len()..MAGIC.len() + 8].copy_from_slice(&1u64.to_le_bytes());
40	            file.write_all(&meta.data)?;

 67	    pub fn allocate_page(&mut self) -> Result<PageId> {
 68	        let id = PageId(self.next_page);
 69	        self.next_page += 1;
 70	        let page = Page::empty(id);
 71	        self.cache.insert(id, page);
 72	        self.dirty.insert(id, true);
 73	        Ok(id)
 74	    }
 75	
 76	    pub fn read_page(&mut self, id: PageId) -> Result<&Page> {
 77	        if !self.cache.contains_key(&id) {
 78	            let mut buf = vec![0u8; PAGE_SIZE];
 79	            let offset = id.raw() * PAGE_SIZE as u64;
 80	            self.file.seek(SeekFrom::Start(offset))?;
 81	            self.file.read_exact(&mut buf).map_err(|e| {
 82	                MiniDbError::Storage(format!("failed to read page {}: {}", id.raw(), e))
 83	            })?;
 84	            self.cache.insert(id, Page { id, data: buf });
 85	        }
 86	        Ok(self.cache.get(&id).unwrap())
 87	    }
 88	
 89	    pub fn write_page(&mut self, page: Page) -> Result<()> {
 90	        let id = page.id;
 91	        self.cache.insert(id, page);
 92	        self.dirty.insert(id, true);
 93	        if id.raw() + 1 > self.next_page {
 94	            self.next_page = id.raw() + 1;
 95	        }
 96	        Ok(())
 97	    }
 98	
 99	    pub fn page_mut(&mut self, id: PageId) -> Result<&mut Page> {
100	        // Ensure loaded
101	        let _ = self.read_page(id)?;
102	        self.dirty.insert(id, true);
103	        Ok(self.cache.get_mut(&id).unwrap())
104	    }
105	
106	    pub fn flush(&mut self) -> Result<()> {
107	        // Pre-extend file if needed
108	        let needed_len = self.next_page * PAGE_SIZE as u64;
109	        let cur_len = self.file.metadata()?.len();
110	        if cur_len < needed_len {
111	            self.file.set_len(needed_len)?;
112	        }
113	        let dirty: Vec<PageId> = self
114	            .dirty
115	            .iter()
116	            .filter_map(|(k, v)| if *v { Some(*k) } else { None })
117	            .collect();
118	        for id in dirty {
119	            if let Some(page) = self.cache.get(&id) {
120	                let off = id.raw() * PAGE_SIZE as u64;
121	                self.file.seek(SeekFrom::Start(off))?;
122	                self.file.write_all(&page.data)?;
123	                self.dirty.insert(id, false);
124	            }
125	        }
126	        self.file.sync_all()?;
127	        Ok(())

 1	//! Slotted-page heap for storing tuples.
 2	//!
 3	//! Each heap page has a small fixed header followed by a forward-growing
 4	//! tuple area and a backward-growing slot directory.
 5	//!
 6	//! Layout (offsets in bytes):
 7	//!   0..8   next_page_id (u64)  -- next page in this table's chain, 0 = none
 8	//!   8..10  num_slots    (u16)
 9	//!   10..12 free_start   (u16)  -- next byte to write a tuple to
10	//!   12..14 free_end     (u16)  -- byte just past the last slot entry
11	//!   14..16 reserved
12	//!   slot directory grows downward from PAGE_SIZE; each slot = (offset:u16, len:u16)
13	
14	use crate::error::{MiniDbError, Result};
15	use crate::storage::page::{Page, PageId, PAGE_SIZE};
16	use crate::storage::pager::Pager;
17	
18	const HDR_LEN: usize = 16;
19	const SLOT_LEN: usize = 4;
20	
21	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
22	pub struct RowId {
23	    pub page: PageId,
24	    pub slot: u16,
25	}
26	
27	pub fn init_heap_page(page: &mut Page) {
28	    page.data[0..8].copy_from_slice(&0u64.to_le_bytes());
29	    page.data[8..10].copy_from_slice(&0u16.to_le_bytes());
30	    page.data[10..12].copy_from_slice(&(HDR_LEN as u16).to_le_bytes());
31	    page.data[12..14].copy_from_slice(&(PAGE_SIZE as u16).to_le_bytes());
32	    for b in &mut page.data[14..16] {
33	        *b = 0;
34	    }
35	}

175	/// Insert a tuple into the chain starting at `first_page`. If first_page is None, allocate
176	/// a new page. Returns RowId, plus possibly the (new) first page id of the chain.
177	pub fn heap_insert(
178	    pager: &mut Pager,
179	    first_page: Option<PageId>,
180	    tuple: &[u8],
181	) -> Result<(RowId, PageId)> {
182	    if tuple.len() + SLOT_LEN + HDR_LEN > PAGE_SIZE {
183	        return Err(MiniDbError::Storage(format!(
184	            "tuple too large for a page: {} bytes",
185	            tuple.len()
186	        )));
187	    }
188	    // Walk chain to find page with room
189	    let mut cur = first_page;
190	    let mut last = None;
191	    while let Some(pid) = cur {
192	        last = Some(pid);
193	        let pg = pager.read_page(pid)?.clone();
194	        let needed = tuple.len() + SLOT_LEN;
195	        if (free_start(&pg) as usize) + needed <= (free_end(&pg) as usize) {
196	            let pg_mut = pager.page_mut(pid)?;
197	            let s = try_insert_tuple(pg_mut, tuple).expect("space pre-checked");
198	            return Ok((RowId { page: pid, slot: s }, first_page.unwrap()));
199	        }
200	        cur = if page_next(&pg).raw() == 0 {
201	            None
202	        } else {
203	            Some(page_next(&pg))
204	        };
205	    }
206	    // Allocate new page, link from last (or set as new first).
207	    let new_id = pager.allocate_page()?;
208	    {
209	        let pg = pager.page_mut(new_id)?;
210	        init_heap_page(pg);
211	        let s = try_insert_tuple(pg, tuple)
212	            .ok_or_else(|| MiniDbError::Storage("tuple did not fit in fresh page".into()))?;
213	        let row = RowId {
214	            page: new_id,
215	            slot: s,
216	        };
217	        // Drop borrow of pg before mutating last
218	        let new_first = match (first_page, last) {
219	            (None, _) => new_id,
220	            (Some(first), Some(last_id)) => {
221	                let last_pg = pager.page_mut(last_id)?;
222	                set_page_next(last_pg, new_id);
223	                first
224	            }
225	            (Some(first), None) => first,
226	        };
227	        return Ok((row, new_first));
228	    }

