 76	    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self> {
 77	        let path = path.as_ref().to_path_buf();
 78	        let pager = Pager::open(&path)?;
 79	        let wal = Wal::open(wal_path(&path))?;
 80	        let mut catalog = load_catalog(&catalog_path(&path))?;
 81	        // re-parse stored expressions
 82	        for t in catalog.tables.values_mut() {
 83	            t.checks.clear();
 84	            for blob in &t.checks_blob {
 85	                let s = std::str::from_utf8(blob)
 86	                    .map_err(|_| MiniDbError::Catalog("non-utf8 check".into()))?;
 87	                t.checks.push(parse_expr_string(s)?);
 88	            }
 89	            for c in t.columns.iter_mut() {
 90	                if let Some(blob) = &c.default_blob {
 91	                    let s = std::str::from_utf8(blob)
 92	                        .map_err(|_| MiniDbError::Catalog("non-utf8 default".into()))?;
 93	                    c.default_expr = Some(parse_expr_string(s)?);
 94	                }
 95	            }
 96	        }
 97	
 98	        // Load indexes
 99	        let mut indexes = HashMap::new();
100	        for idx in catalog.indexes.values() {
101	            let p = index_path(&path, &idx.name);
102	            indexes.insert(idx.name.clone(), load_index(&p)?);
103	        }
104	
105	        let mut db = Database {
106	            path,
107	            pager,
108	            wal,
109	            catalog,
110	            indexes,
111	            txn: TransactionManager::new(),
112	        };
113	
114	        db.replay_wal()?;
115	        Ok(db)
116	    }
