118	    fn replay_wal(&mut self) -> Result<()> {
119	        let recs = self.wal.read_all()?;
120	        if recs.is_empty() {
121	            return Ok(());
122	        }
123	        let committed = committed_records(recs);
124	        if committed.is_empty() {
125	            self.wal.truncate()?;

128	        log::info!("replaying {} WAL record(s)", committed.len());
129	        for r in committed {
130	            match r {
131	                WalRecord::Insert {
132	                    table,
133	                    page,
134	                    slot,
135	                    tuple,
136	                    ..
137	                } => {
138	                    self.replay_write(&table, page, slot, &tuple)?;
139	                }
140	                WalRecord::Delete {
141	                    table, page, slot, ..
142	                } => {
143	                    self.replay_delete(&table, page, slot)?;
144	                }
145	                WalRecord::Update {
146	                    table,
147	                    page,
148	                    slot,
149	                    new,
150	                    ..
151	                } => {
152	                    self.replay_write(&table, page, slot, &new)?;
153	                }
154	                WalRecord::CreateTable { schema_blob, .. } => {
155	                    let s = std::str::from_utf8(&schema_blob)
156	                        .map_err(|_| MiniDbError::Wal("invalid utf8".into()))?
157	                        .to_string();
158	                    let stmts = Parser::parse_sql(&s)?;
159	                    for st in stmts {
160	                        if let Statement::CreateTable(ct) = st {
161	                            if !self.catalog.tables.contains_key(&ct.name) {
162	                                self.create_table_internal(ct, false)?;
163	                            }
164	                        }
165	                    }
166	                }
167	                WalRecord::DropTable { table, .. } => {
168	                    let _ = self.catalog.drop_table(&table);
169	                }
170	                WalRecord::CreateIndex { blob, .. } => {
171	                    let s = std::str::from_utf8(&blob)
172	                        .map_err(|_| MiniDbError::Wal("invalid utf8".into()))?
173	                        .to_string();
174	                    let stmts = Parser::parse_sql(&s)?;
175	                    for st in stmts {
176	                        if let Statement::CreateIndex {
177	                            name,
178	                            table,
179	                            column,
180	                        } = st
181	                        {
182	                            if !self.catalog.indexes.contains_key(&name) {
183	                                self.create_index_internal(name, table, column, false)?;
184	                            }
185	                        }
186	                    }
187	                }
188	                WalRecord::DropIndex { name, .. } => {
189	                    let _ = self.catalog.drop_index(&name);
190	                    self.indexes.remove(&name);
191	                }
192	                _ => {}
193	            }
194	        }
195	        // Persist replayed state
196	        self.checkpoint()?;
197	        Ok(())

311	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
312	        let mut out = Vec::new();
313	        self.file.seek(SeekFrom::Start(0))?;
314	        let mut hdr = [0u8; 8];
315	        loop {
316	            match self.file.read_exact(&mut hdr) {
317	                Ok(()) => {}
318	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
319	                Err(e) => return Err(e.into()),
320	            }
321	            let len = u32::from_le_bytes([hdr[0], hdr[1], hdr[2], hdr[3]]) as usize;
322	            let crc = u32::from_le_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
323	            let mut payload = vec![0u8; len];
324	            match self.file.read_exact(&mut payload) {
325	                Ok(()) => {}
326	                Err(_) => break, // torn write at end
327	            }
328	            let actual_crc = crc32fast::hash(&payload);
329	            if actual_crc != crc {
330	                log::warn!("WAL crc mismatch — stopping replay at this record");
331	                break;
332	            }
333	            match WalRecord::decode(&payload) {
334	                Ok(r) => out.push(r),
335	                Err(e) => {
336	                    log::warn!("WAL decode error: {} — stopping replay", e);
337	                    break;
338	                }
339	            }
340	        }
341	        Ok(out)
342	    }
