356	/// Replay records, return only those belonging to fully-committed transactions
357	/// (i.e. ones with a Commit record present).
358	pub fn committed_records(records: Vec<WalRecord>) -> Vec<WalRecord> {
359	    use std::collections::HashSet;
360	    let mut committed: HashSet<u64> = HashSet::new();
361	    for r in &records {
362	        if let WalRecord::Commit { txn_id } = r {
363	            committed.insert(*txn_id);
364	        }
365	    }
366	    records
367	        .into_iter()
368	        .filter(|r| committed.contains(&r.txn_id()))
369	        .collect()
370	}

861	    fn exec_select(&mut self, s: ast::Select) -> Result<StatementResult> {
862	        let logical = plan_select(&s)?;
863	        let physical = build_physical(&self.catalog, logical)?;
864	        let columns: Vec<String> = physical.schema().names();
865	        let mut tree = operators::build(physical);
866	        let mut ctx = ExecCtx {
867	            pager: &mut self.pager,
868	            catalog: &self.catalog,
869	            indexes: &self.indexes,
870	        };
871	        tree.open(&mut ctx)?;
872	        let mut rows = Vec::new();
873	        while let Some(r) = tree.next(&mut ctx)? {
874	            rows.push(r.0);
875	        }
876	        tree.close(&mut ctx)?;
877	        Ok(StatementResult::Rows { columns, rows })

