126	    pub fn read_record(&mut self) -> Result<Option<WalRecord>> {
127	        let len = match self.reader.read_u32::<LittleEndian>() {
128	            Ok(l) => l,
129	            Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
130	            Err(e) => return Err(e.into()),
131	        };
132	
133	        let crc = self.reader.read_u32::<LittleEndian>()?;
134	
135	        let mut payload = vec![0u8; len as usize];
136	        self.reader.read_exact(&mut payload)?;
137	
138	        let computed_crc = compute_crc32(&payload);
139	        if computed_crc != crc {
140	            return Err(MiniDbError::CrcMismatch);
141	        }
142	
143	        let record: WalRecord = serde_json::from_slice(&payload)
144	            .map_err(|e| MiniDbError::Wal(format!("deserialization error: {}", e)))?;
145	
146	        Ok(Some(record))
147	    }
148	
149	    pub fn read_all(&mut self) -> Result<Vec<WalRecord>> {
150	        let mut records = Vec::new();
151	        loop {
152	            match self.read_record() {
153	                Ok(Some(r)) => records.push(r),
154	                Ok(None) => break,
155	                Err(MiniDbError::CrcMismatch) => {
156	                    // Torn write at the tail — stop here (partial record)
157	                    log::warn!("WAL: CRC mismatch at tail, treating as torn write");
158	                    break;
159	                }
160	                Err(e) => return Err(e),
161	            }
162	        }
163	        Ok(records)
164	    }

