830	    let idx_meta = IndexMeta {
831	        name: stmt.name.clone(),
832	        table: stmt.table.clone(),
833	        columns: stmt.columns.clone(),
834	        unique: stmt.unique,
835	        btree_root: tree.root.as_u64(),
836	    };
837	
838	    ctx.catalog.create_index(idx_meta)?;
839	
840	    // Build the index from existing table rows
841	    let table_meta = ctx.catalog.get_table(&stmt.table)?.clone();
842	    let heap_root = PageId(table_meta.heap_root);
843	    let schema = table_meta.schema.clone();
844	    let col_idx = schema
845	        .find_column(&stmt.columns[0])
846	        .ok_or_else(|| MiniDbError::Schema(format!("column '{}' not found", stmt.columns[0])))?;
847	
848	    let heap = Heap::open(heap_root);
849	    let idx_root = PageId(ctx.catalog.get_index(&stmt.name)?.btree_root);
850	    let mut btree = BTree::open(idx_root);
