854	        if data.len() < 8 {
855	            return Ok(true);
856	        }
857	        let row_id = u64::from_le_bytes(data[..8].try_into().unwrap());
858	        let row = schema.deserialize_row(&data[8..])?;
859	        let key_val = &row[col_idx];
