 68	/// Convert a logical plan to a physical plan, choosing index scans where applicable.
 69	pub fn build_physical_plan(logical: &LogicalPlan, catalog: &Catalog) -> Result<PhysicalPlan> {
 70	    match logical {
 71	        LogicalPlan::Scan {
 72	            table,
 73	            alias,
 74	            predicate,
 75	        } => {
 76	            // Check if we can use an index
 77	            if let Some(pred) = predicate {
 78	                if let Some((index_name, col, eq_val, lo, hi)) =
 79	                    find_index_predicate(pred, table, catalog)
 80	                {
 81	                    return Ok(PhysicalPlan::IndexScan {
 82	                        table: table.clone(),
 83	                        alias: alias.clone(),
 84	                        index_name,
 85	                        index_col: col,
 86	                        eq_val,
 87	                        range_lo: lo,
 88	                        range_hi: hi,
 89	                        predicate: Some(pred.clone()),
 90	                    });
 91	                }
 92	            }
 93	            Ok(PhysicalPlan::SeqScan {
 94	                table: table.clone(),
 95	                alias: alias.clone(),
 96	                predicate: predicate.clone(),
 97	            })
 98	        }
 99	        LogicalPlan::Filter { input, predicate } => {
100	            // Try to push filter into scan
101	            if let LogicalPlan::Scan {
102	                table,
103	                alias,
104	                predicate: scan_pred,
105	            } = input.as_ref()
106	            {
107	                let merged_pred = match scan_pred {
108	                    None => predicate.clone(),
109	                    Some(sp) => Expr::BinOp {
110	                        op: BinOp::And,
111	                        left: Box::new(sp.clone()),
112	                        right: Box::new(predicate.clone()),
113	                    },
114	                };
115	                let new_scan = LogicalPlan::Scan {
116	                    table: table.clone(),
117	                    alias: alias.clone(),
118	                    predicate: Some(merged_pred),
119	                };
120	                return build_physical_plan(&new_scan, catalog);
121	            }
122	            let phys_input = build_physical_plan(input, catalog)?;
123	            Ok(PhysicalPlan::Filter {
124	                input: Box::new(phys_input),
125	                predicate: predicate.clone(),
126	            })
127	        }
128	        LogicalPlan::Project { input, items } => {
129	            let phys_input = build_physical_plan(input, catalog)?;
130	            Ok(PhysicalPlan::Project {
131	                input: Box::new(phys_input),
132	                items: items.clone(),
133	            })
134	        }
135	        LogicalPlan::Join {
136	            left,
137	            right,
138	            join_type,
139	            condition,
140	        } => {
141	            let phys_left = build_physical_plan(left, catalog)?;
142	            let phys_right = build_physical_plan(right, catalog)?;
143	            Ok(PhysicalPlan::NestedLoopJoin {
144	                left: Box::new(phys_left),
145	                right: Box::new(phys_right),
146	                join_type: join_type.clone(),
147	                condition: condition.clone(),
