196	impl PhysicalOperator for IndexScan {
197	    fn schema(&self) -> &Schema {
198	        &self.schema
199	    }
200	
201	    fn open(&mut self, ctx: &mut ExecutionContext) -> Result<()> {
202	        // Evaluate key expressions
203	        let empty_row: Vec<Value> = vec![];
204	        let empty_schema = Schema::default();
205	
206	        let idx_meta = ctx.catalog.get_index(&self.index_name)?.clone();
207	        let table_meta = ctx.catalog.get_table(&self.table)?.clone();
208	        let heap_root = PageId(table_meta.heap_root);
209	        let btree_root = PageId(idx_meta.btree_root);
210	        let schema = table_meta.schema.clone();
211	        let predicate = self.predicate.clone();
212	
213	        let row_ids: Vec<u64> = if let Some(eq_expr) = &self.eq_val {
214	            let eq_val = eval_expr(eq_expr, &empty_row, &empty_schema)?;
215	            let key_bytes = eq_val.to_bytes();
216	            let tree = BTree::open(btree_root);
217	            tree.search_exact(&mut ctx.pager, &key_bytes)?
218	        } else {
219	            let lo_bytes = if let Some(lo_expr) = &self.range_lo {
220	                let lo_val = eval_expr(lo_expr, &empty_row, &empty_schema)?;
221	                Some(lo_val.to_bytes())
222	            } else {
223	                None
224	            };
225	            let hi_bytes = if let Some(hi_expr) = &self.range_hi {
226	                let hi_val = eval_expr(hi_expr, &empty_row, &empty_schema)?;
227	                Some(hi_val.to_bytes())
228	            } else {
229	                None
230	            };
231	            let tree = BTree::open(btree_root);
232	            let results =
233	                tree.range_scan(&mut ctx.pager, lo_bytes.as_deref(), hi_bytes.as_deref())?;
234	            results.into_iter().map(|(_, rid)| rid).collect()
235	        };
236	
237	        // Fetch rows by row_id
238	        let heap = Heap::open(heap_root);
239	        let mut rows = Vec::new();
240	        let row_id_set: std::collections::HashSet<u64> = row_ids.into_iter().collect();
241	
242	        heap.scan(&mut ctx.pager, |_pid, _slot, data| {
243	            if data.len() < 8 {
244	                return Ok(true);
245	            }
246	            let row_id = u64::from_le_bytes(data[..8].try_into().unwrap());
247	            if !row_id_set.contains(&row_id) {
248	                return Ok(true);
249	            }
250	
251	            let row = schema.deserialize_row(&data[8..])?;
252	            if let Some(pred) = &predicate {
253	                if eval_predicate(pred, &row, &schema)? != Some(true) {
254	                    return Ok(true);
255	                }
256	            }
257	            rows.push(row);
258	            Ok(true)
259	        })?;
260	
261	        self.rows = rows;
262	        self.pos = 0;
263	        Ok(())
264	    }
265	
266	    fn next(&mut self, _: &mut ExecutionContext) -> Result<Option<Row>> {
267	        if self.pos < self.rows.len() {
268	            let row = self.rows[self.pos].clone();
269	            self.pos += 1;
270	            Ok(Some(row))
271	        } else {
272	            Ok(None)
273	        }
274	    }
275	
276	    fn close(&mut self, _: &mut ExecutionContext) -> Result<()> {
277	        self.rows.clear();
278	        Ok(())
279	    }
280	}
