332	
333	impl Project {
334	    pub fn new(
335	        input: Box<dyn PhysicalOperator>,
336	        items: Vec<SelectItem>,
337	        ctx: &ExecutionContext,
338	    ) -> Result<Self> {
339	        let input_schema = input.schema().clone();
340	        let output_schema = compute_output_schema(&items, &input_schema)?;
341	        Ok(Project {
342	            input,
343	            items,
344	            input_schema,
345	            output_schema,
346	        })
347	    }
