349	
350	fn compute_output_schema(items: &[SelectItem], input: &Schema) -> Result<Schema> {
351	    let mut cols = Vec::new();
352	    for item in items {
353	        match item {
354	            SelectItem::Wildcard => {
355	                cols.extend(input.columns.clone());
356	            }
357	            SelectItem::QualifiedWildcard(tbl) => {
358	                // Include all columns (simplified: we don't track table aliases at schema level)
359	                cols.extend(input.columns.clone());
360	            }
361	            SelectItem::Expr { expr, alias } => {
362	                let name = alias.clone().unwrap_or_else(|| expr_name(expr));
363	                let dt = infer_expr_type(expr, input).unwrap_or(DataType::Text);
364	                cols.push(Column::new(name, dt));
365	            }
366	        }
367	    }
368	    Ok(Schema::new(cols))
369	}
370	
371	fn expr_name(expr: &Expr) -> String {
372	    match expr {
373	        Expr::Column(c) => c.column.clone(),
374	        Expr::Literal(v) => v.to_string(),
375	        Expr::FunctionCall { name, .. } => name.clone(),
376	        Expr::BinOp { op, left, right } => format!("expr"),
377	        _ => "col".to_string(),
378	    }
379	}
380	
381	fn infer_expr_type(expr: &Expr, schema: &Schema) -> Option<DataType> {
382	    match expr {
383	        Expr::Literal(v) => Some(v.data_type()),
384	        Expr::Column(c) => {
385	            let idx = schema.find_column(&c.column)?;
386	            Some(schema.columns[idx].data_type.clone())
387	        }
388	        Expr::BinOp { op, left, right } => match op {
389	            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div => infer_expr_type(left, schema),
390	            _ => Some(DataType::Bool),
391	        },
392	        Expr::FunctionCall { name, .. } => match name.as_str() {
393	            "LENGTH" | "ABS" => Some(DataType::Int),
394	            "LOWER" | "UPPER" | "SUBSTR" | "COALESCE" => Some(DataType::Text),
395	            _ => None,
396	        },
397	        _ => None,
398	    }
399	}
