401	impl PhysicalOperator for Project {
402	    fn schema(&self) -> &Schema {
403	        &self.output_schema
404	    }
405	
406	    fn open(&mut self, ctx: &mut ExecutionContext) -> Result<()> {
407	        self.input.open(ctx)
408	    }
409	
410	    fn next(&mut self, ctx: &mut ExecutionContext) -> Result<Option<Row>> {
411	        match self.input.next(ctx)? {
412	            None => Ok(None),
413	            Some(row) => {
414	                let projected = project_row(&self.items, &row, &self.input_schema)?;
415	                Ok(Some(projected))
416	            }
417	        }
418	    }
419	
420	    fn close(&mut self, ctx: &mut ExecutionContext) -> Result<()> {
421	        self.input.close(ctx)
422	    }
423	}

1018	pub fn do_update(
1019	    table: &str,
1020	    scan_plan: &PhysicalPlan,
1021	    assignments: &[(String, Expr)],
1022	    ctx: &mut ExecutionContext,
1023	) -> Result<usize> {
1024	    // Collect rows to update
1025	    let table_meta = ctx.catalog.get_table(table)?.clone();
1026	    let schema = table_meta.schema.clone();
1027	    let heap_root = PageId(table_meta.heap_root);
1028	    let heap = Heap::open(heap_root);
1029	    let idx_names = ctx.catalog.index_names_for_table(table);
1030	
1031	    // Scan to find rows
1032	    let mut to_update: Vec<(PageId, u16, u64, Row)> = Vec::new();
1033	    let predicate = extract_predicate(scan_plan);
1034	
1035	    heap.scan(&mut ctx.pager, |pid, slot, data| {
1036	        if data.len() < 8 {
1037	            return Ok(true);
1038	        }
1039	        let row_id = u64::from_le_bytes(data[..8].try_into().unwrap());
1040	        let row = schema.deserialize_row(&data[8..])?;
1041	        if let Some(pred) = &predicate {
1042	            if eval_predicate(pred, &row, &schema)? != Some(true) {
1043	                return Ok(true);
1044	            }
1045	        }
1046	        to_update.push((pid, slot, row_id, row));
1047	        Ok(true)
1048	    })?;
1049	
1050	    let count = to_update.len();
1051	    let empty_row: Vec<Value> = vec![];
1052	    let empty_schema = Schema::default();
1053	
1054	    for (pid, slot, row_id, old_row) in &to_update {
1055	        let mut new_row = old_row.clone();
1056	
1057	        for (col_name, expr) in assignments {
1058	            if let Some(idx) = schema.find_column(col_name) {
1059	                new_row[idx] = eval_expr(expr, old_row, &schema)?;
1060	            } else {
1061	                return Err(MiniDbError::Schema(format!(
1062	                    "column '{}' not found in table '{}'",
1063	                    col_name, table
1064	                )));
1065	            }
1066	        }
1067	
1068	        // NOT NULL checks
1069	        for (i, col) in schema.columns.iter().enumerate() {
1070	            if !col.nullable && new_row[i].is_null() {
1071	                return Err(MiniDbError::Constraint(format!(
1072	                    "NOT NULL constraint violated for column '{}'",
1073	                    col.name
1074	                )));
1075	            }
1076	        }
1077	
1078	        let old_serialized = {
1079	            let mut d = row_id.to_le_bytes().to_vec();
1080	            d.extend(schema.serialize_row(old_row)?);
1081	            d
1082	        };
1083	        let new_serialized = {
1084	            let mut d = row_id.to_le_bytes().to_vec();
1085	            d.extend(schema.serialize_row(&new_row)?);
1086	            d
1087	        };
1088	
1089	        // Update the heap
1090	        let new_loc = heap.update_row(&mut ctx.pager, *pid, *slot, &new_serialized)?;
1091	
1092	        // Update indexes
1093	        for idx_name in &idx_names {
1094	            if let Ok(idx_meta) = ctx.catalog.get_index(idx_name) {
1095	                let col_name_idx = idx_meta.columns[0].clone();
1096	                let btree_root = PageId(idx_meta.btree_root);
1097	                if let Some(col_idx) = schema.find_column(&col_name_idx) {
1098	                    let old_key = BTreeKey::new(&old_row[col_idx], *row_id);
1099	                    let new_key = BTreeKey::new(&new_row[col_idx], *row_id);
1100	                    let mut tree = BTree::open(btree_root);
1101	                    tree.delete(&mut ctx.pager, &old_key)?;
1102	                    tree.insert(&mut ctx.pager, new_key)?;
1103	                    if let Some(idx) = ctx.catalog.indexes.get_mut(&idx_name.to_lowercase()) {
1104	                        idx.btree_root = tree.root.as_u64();
1105	                    }
1106	                }
1107	            }
1108	        }
1109	
1110	        // WAL
1111	        let tid = ctx.txn.current_txn_id();
1112	        ctx.txn.log_record(WalRecord::UpdateRow {
1113	            txn_id: tid,
1114	            table: table.to_string(),
1115	            row_id: *row_id,
1116	            old_data: old_serialized,
1117	            new_data: new_serialized,
1118	        })?;
1119	    }
1120	
1121	    Ok(count)
1122	}
