126	    fn parse_statement(&mut self) -> Result<Statement> {
127	        let (line, col) = self.peek_pos();
128	        match self.peek().clone() {
129	            Token::Select | Token::Distinct => Ok(Statement::Select(self.parse_select()?)),
130	            Token::Insert => Ok(Statement::Insert(self.parse_insert()?)),
131	            Token::Update => Ok(Statement::Update(self.parse_update()?)),
132	            Token::Delete => Ok(Statement::Delete(self.parse_delete()?)),
133	            Token::Create => self.parse_create(),
134	            Token::Drop => self.parse_drop(),
135	            Token::Begin => {
136	                self.advance();
137	                Ok(Statement::Begin)
138	            }
139	            Token::Commit => {
140	                self.advance();
141	                Ok(Statement::Commit)
142	            }
143	            Token::Rollback => {
144	                self.advance();
145	                Ok(Statement::Rollback)
146	            }
147	            Token::MetaSchema => {
148	                self.advance();
149	                Ok(Statement::MetaSchema)
150	            }
151	            Token::MetaTables => {
152	                self.advance();
153	                Ok(Statement::MetaTables)
154	            }
155	            Token::MetaIndexes => {
156	                self.advance();
