68	/// Convert a logical plan to a physical plan, choosing index scans where applicable.
69	pub fn build_physical_plan(logical: &LogicalPlan, catalog: &Catalog) -> Result<PhysicalPlan> {
70	    match logical {
71	        LogicalPlan::Scan {
72	            table,
73	            alias,
74	            predicate,
75	        } => {
76	            // Check if we can use an index
77	            if let Some(pred) = predicate {
78	                if let Some((index_name, col, eq_val, lo, hi)) =
79	                    find_index_predicate(pred, table, catalog)
80	                {
81	                    return Ok(PhysicalPlan::IndexScan {
82	                        table: table.clone(),
83	                        alias: alias.clone(),
84	                        index_name,
85	                        index_col: col,
86	                        eq_val,
87	                        range_lo: lo,
88	                        range_hi: hi,
89	                        predicate: Some(pred.clone()),
90	                    });
91	                }
92	            }
93	            Ok(PhysicalPlan::SeqScan {
94	                table: table.clone(),
95	                alias: alias.clone(),
96	                predicate: predicate.clone(),
97	            })
98	        }

215	/// Try to find an index that matches a predicate for the given table.
216	/// Returns (index_name, col, eq_val, range_lo, range_hi) if found.
217	fn find_index_predicate(
218	    expr: &Expr,
219	    table: &str,
220	    catalog: &Catalog,
221	) -> Option<(String, String, Option<Expr>, Option<Expr>, Option<Expr>)> {
222	    match expr {
223	        Expr::BinOp { op, left, right } => {
224	            if let Expr::Column(col_ref) = left.as_ref() {
225	                let col_name = &col_ref.column;
226	                if let Some(idx) = catalog.find_index_for_column(table, col_name) {
227	                    let idx_name = idx.name.clone();
228	                    let col = col_name.clone();
229	                    match op {
230	                        BinOp::Eq => {
231	                            return Some((idx_name, col, Some(*right.clone()), None, None));
232	                        }
233	                        BinOp::Lt | BinOp::Le => {
234	                            return Some((idx_name, col, None, None, Some(*right.clone())));
235	                        }
236	                        BinOp::Gt | BinOp::Ge => {
237	                            return Some((idx_name, col, None, Some(*right.clone()), None));
238	                        }
239	                        _ => {}
240	                    }
241	                }
242	            }
243	            if let Expr::Column(col_ref) = right.as_ref() {
244	                let col_name = &col_ref.column;
245	                if let Some(idx) = catalog.find_index_for_column(table, col_name) {
246	                    let idx_name = idx.name.clone();
247	                    let col = col_name.clone();
248	                    match op {
249	                        BinOp::Eq => {
250	                            return Some((idx_name, col, Some(*left.clone()), None, None));
251	                        }
252	                        _ => {}
253	                    }
254	                }
255	            }
256	            None
257	        }
258	        _ => None,
259	    }
260	}

