704	pub fn do_create_table(stmt: &CreateTableStmt, ctx: &mut ExecutionContext) -> Result<()> {
705	    use crate::catalog::TableMeta;
706	    use crate::parser::ast::TableConstraint;
707	    use crate::types::Column;
708	
709	    if ctx.catalog.get_table(&stmt.name).is_ok() {
710	        if stmt.if_not_exists {
711	            return Ok(());
712	        }
713	        return Err(MiniDbError::AlreadyExists(format!(
714	            "table '{}' already exists",
715	            stmt.name
716	        )));
717	    }
718	
719	    // Build columns from column defs
720	    let mut columns = Vec::new();
721	    for col_def in &stmt.columns {
722	        let mut col = Column::new(col_def.name.clone(), col_def.data_type.clone());
723	        col.nullable = !col_def.not_null && !col_def.primary_key;
724	        col.primary_key = col_def.primary_key;
725	        col.unique = col_def.unique || col_def.primary_key;
726	        if let Some(default_expr) = &col_def.default {
727	            let empty: Vec<Value> = vec![];
728	            let v = eval_expr(default_expr, &empty, &Schema::default())?;
729	            col.default = Some(v);
730	        }
731	        columns.push(col);
732	    }
733	
734	    // Apply table-level constraints
735	    for constraint in &stmt.constraints {
736	        match constraint {
737	            TableConstraint::PrimaryKey(cols) => {
738	                for col_name in cols {
