180	/// Heap manager: manages the set of pages for a table
181	pub struct Heap {
182	    pub root_page: PageId,
183	}
184	
185	impl Heap {
186	    /// Create a new heap with a root page
187	    pub fn create(pager: &mut Pager) -> Result<Self> {
188	        let id = pager.allocate_page()?;
189	        let page = pager.read_page_mut(id)?;
190	        // Initialize root page
191	        page.data[0..2].copy_from_slice(&0u16.to_le_bytes()); // num_slots = 0
192	        page.data[2..6].copy_from_slice(&0u32.to_le_bytes()); // next_page = 0 (none)
193	        page.mark_dirty();
194	        Ok(Heap { root_page: id })
195	    }
196	
197	    pub fn open(root_page: PageId) -> Self {
198	        Heap { root_page }
199	    }
200	
201	    /// Insert a row, returning its (page_id, slot) location
202	    pub fn insert_row(&self, pager: &mut Pager, row_data: &[u8]) -> Result<(PageId, u16)> {
203	        // Walk pages to find one with space
204	        let mut current_id = self.root_page;
205	        loop {
206	            let next_page = {
207	                let page = pager.read_page(current_id)?;
208	                let next =
209	                    u32::from_le_bytes([page.data[2], page.data[3], page.data[4], page.data[5]]);
210	                next
211	            };
212	
213	            // Try inserting on current page
214	            {
215	                let page = pager.read_page_mut(current_id)?;
216	                let mut hp = HeapPage::new(&mut page.data);
217	                if let Some(slot) = hp.insert(row_data) {
218	                    page.dirty = true;
219	                    return Ok((current_id, slot));
220	                }
221	            }
222	
223	            if next_page == 0 {
224	                // Allocate new page
225	                let new_id = pager.allocate_page()?;
226	                // Link current -> new
227	                {
228	                    let page = pager.read_page_mut(current_id)?;
229	                    let new_id_u32 = new_id.as_u64() as u32;
230	                    page.data[2] = new_id_u32.to_le_bytes()[0];
231	                    page.data[3] = new_id_u32.to_le_bytes()[1];
232	                    page.data[4] = new_id_u32.to_le_bytes()[2];
233	                    page.data[5] = new_id_u32.to_le_bytes()[3];
234	                    page.mark_dirty();
235	                }
236	                // Initialize new page
237	                {
238	                    let page = pager.read_page_mut(new_id)?;
239	                    page.data[0..2].copy_from_slice(&0u16.to_le_bytes());
240	                    page.data[2..6].copy_from_slice(&0u32.to_le_bytes());
241	                    page.mark_dirty();
242	                }
243	                current_id = new_id;
244	            } else {
245	                current_id = PageId(next_page as u64);
246	            }
247	        }
248	    }

