215	fn replay_wal(
216	    mut ctx: ExecutionContext,
217	    wal_path: &Path,
218	    db_path: &Path,
219	) -> Result<ExecutionContext> {
220	    if !wal_path.exists() {
221	        return Ok(ctx);
222	    }
223	
224	    let wal = Wal::open(wal_path)?;
225	    let records = wal.replay()?;
226	    if records.is_empty() {
227	        return Ok(ctx);
228	    }
229	
230	    log::info!("replaying {} WAL records", records.len());
231	
232	    let committed_ops = crate::storage::wal::collect_committed_ops(&records);
233	
234	    for record in committed_ops {
235	        match record {
236	            WalRecord::CatalogChange { payload, .. } => {
237	                ctx.catalog = Catalog::deserialize(payload)?;
238	            }
239	            WalRecord::InsertRow {
240	                table,
241	                row_id,
242	                data,
243	                ..
244	            } => {
245	                if let Ok(table_meta) = ctx.catalog.get_table(table) {
246	                    let heap_root = crate::storage::PageId(table_meta.heap_root);
247	                    let heap = crate::storage::Heap::open(heap_root);
248	                    let _ = heap.insert_row(&mut ctx.pager, data);
249	                }
250	            }
251	            WalRecord::DeleteRow { table, row_id, .. } => {
252	                if let Ok(table_meta) = ctx.catalog.get_table(table) {
253	                    let heap_root = crate::storage::PageId(table_meta.heap_root);
254	                    let heap = crate::storage::Heap::open(heap_root);
255	                    let rid = *row_id;
256	                    let mut target: Option<(crate::storage::PageId, u16)> = None;
257	                    let _ = heap.scan(&mut ctx.pager, |pid, slot, data| {
258	                        if data.len() >= 8 {
259	                            let r = u64::from_le_bytes(data[..8].try_into().unwrap());
260	                            if r == rid {
261	                                target = Some((pid, slot));
262	                                return Ok(false);
263	                            }
264	                        }
265	                        Ok(true)
266	                    });
267	                    if let Some((pid, slot)) = target {
268	                        let _ = heap.delete_row(&mut ctx.pager, pid, slot);
269	                    }
270	                }
271	            }
272	            WalRecord::UpdateRow {
273	                table,
274	                row_id,
275	                new_data,
276	                ..
277	            } => {
278	                if let Ok(table_meta) = ctx.catalog.get_table(table) {
279	                    let heap_root = crate::storage::PageId(table_meta.heap_root);
280	                    let heap = crate::storage::Heap::open(heap_root);
281	                    let rid = *row_id;
282	                    let nd = new_data.clone();
283	                    let mut target: Option<(crate::storage::PageId, u16)> = None;
284	                    let _ = heap.scan(&mut ctx.pager, |pid, slot, data| {
285	                        if data.len() >= 8 {
286	                            let r = u64::from_le_bytes(data[..8].try_into().unwrap());
287	                            if r == rid {
288	                                target = Some((pid, slot));
289	                                return Ok(false);
290	                            }
291	                        }
292	                        Ok(true)
293	                    });
294	                    if let Some((pid, slot)) = target {
295	                        let _ = heap.update_row(&mut ctx.pager, pid, slot, &nd);
296	                    }
297	                }
298	            }
299	            _ => {}
300	        }
301	    }
302	
303	    ctx.pager.flush_all()?;
304	    Ok(ctx)

