167	/// Replay WAL records to find committed transactions.
168	/// Returns only records belonging to committed transactions,
169	/// in order, excluding Begin/Commit/Rollback control records.
170	pub fn collect_committed_ops(records: &[WalRecord]) -> Vec<&WalRecord> {
171	    use std::collections::HashSet;
172	
173	    let mut committed_txns: HashSet<u64> = HashSet::new();
174	    let mut rolled_back: HashSet<u64> = HashSet::new();
175	
176	    for record in records {
177	        match record {
178	            WalRecord::Commit { txn_id } => {
179	                committed_txns.insert(*txn_id);
180	            }
181	            WalRecord::Rollback { txn_id } => {
182	                rolled_back.insert(*txn_id);
183	            }
184	            _ => {}
185	        }
186	    }
187	
188	    records
189	        .iter()
190	        .filter(|r| {
191	            if let Some(tid) = r.txn_id() {
192	                committed_txns.contains(&tid)
193	                    && !matches!(
194	                        r,
195	                        WalRecord::Begin { .. }
196	                            | WalRecord::Commit { .. }
197	                            | WalRecord::Rollback { .. }
198	                    )
199	            } else {
200	                false
201	            }
202	        })
203	        .collect()
204	}

112	    /// Flush all dirty pages to disk
113	    pub fn flush_all(&mut self) -> Result<()> {
114	        let dirty_ids: Vec<u64> = self
115	            .cache
116	            .values()
117	            .filter(|p| p.dirty)
118	            .map(|p| p.id.as_u64())
119	            .collect();
120	
121	        for id in dirty_ids {
122	            let page = self.cache.get_mut(&id).unwrap();
123	            let offset = id * PAGE_SIZE as u64;
124	            self.file.seek(SeekFrom::Start(offset))?;
125	            self.file.write_all(page.as_slice())?;
126	            page.dirty = false;
127	        }
128	
129	        self.file.flush()?;
130	        Ok(())
131	    }
