338	    fn parse_insert(&mut self) -> Result<InsertStmt> {
339	        self.expect(&Token::Insert)?;
340	        self.expect(&Token::Into)?;
341	        let table = self.expect_ident()?;
342	
343	        let columns = if self.eat_if(&Token::LParen) {
344	            let mut cols = Vec::new();
345	            loop {
346	                cols.push(self.expect_ident()?);
347	                if !self.eat_if(&Token::Comma) {
348	                    break;
349	                }
350	            }
351	            self.expect(&Token::RParen)?;
352	            Some(cols)
353	        } else {
354	            None
355	        };
356	
357	        self.expect(&Token::Values)?;
358	
359	        let mut value_rows = Vec::new();
360	        loop {
361	            self.expect(&Token::LParen)?;
362	            let mut vals = Vec::new();
363	            loop {
364	                vals.push(self.parse_expr()?);
365	                if !self.eat_if(&Token::Comma) {
366	                    break;
367	                }
368	            }
369	            self.expect(&Token::RParen)?;
370	            value_rows.push(vals);
371	            if !self.eat_if(&Token::Comma) {
372	                break;
373	            }
374	        }
375	
376	        Ok(InsertStmt {
377	            table,
378	            columns,
379	            values: value_rows,
380	        })

