1135	                        if let Some(heap) = self.heaps.get(&table.to_lowercase()) {
1136	                            let h = heap.clone_ref();
1137	                            if h.get(&mut self.page_manager, rid, &types)?.is_none() {
1138	                                // Row missing, re-insert from WAL
1139	                                // Parse the row data from WAL
1140	                                let row = crate::storage::wal::decode_row_pos(
1141	                                    &rec.data, &mut pos, &types,
1142	                                )?;
1143	                                let mut hr = heap.clone();
1144	                                let mut heap_file = hr.clone_ref();
1145	                                heap_file.insert(&mut self.page_manager, &row)?;
1146	                            }
1147	                        }
1148	                    }
1149	                }
1150	                _ => {} // Other record types handled elsewhere
1151	            }
1152	        }
1153	        Ok(())

