194	
195	    pub fn write_record(&mut self, rec: &WalRecord) -> Result<()> {
196	        let mut body = Vec::new();
197	        let rtype = match &rec.body {
198	            WalRecordBody::Begin => WalRecordType::Begin as u8,
199	            WalRecordBody::Commit => WalRecordType::Commit as u8,
200	            WalRecordBody::Rollback => WalRecordType::Rollback as u8,
201	            WalRecordBody::Insert { .. } => WalRecordType::Insert as u8,
202	            WalRecordBody::Delete { .. } => WalRecordType::Delete as u8,
203	            WalRecordBody::Update { .. } => WalRecordType::Update as u8,
204	            WalRecordBody::Checkpoint => WalRecordType::Checkpoint as u8,
205	            WalRecordBody::IndexInsert { .. } => WalRecordType::IndexInsert as u8,
206	            WalRecordBody::IndexDelete { .. } => WalRecordType::IndexDelete as u8,
207	        };
208	        body.push(rtype);
209	        body.extend_from_slice(&rec.txn_id.to_le_bytes());
210	
211	        match &rec.body {
212	            WalRecordBody::Begin
213	            | WalRecordBody::Commit
214	            | WalRecordBody::Rollback
215	            | WalRecordBody::Checkpoint => {}
216	            WalRecordBody::Insert { table, row_id, row } => {
217	                encode_string(&mut body, table);
218	                encode_row_id(&mut body, *row_id);
219	                encode_row_with_types(&mut body, row);
220	            }
221	            WalRecordBody::Delete { table, row_id, row } => {
222	                encode_string(&mut body, table);
223	                encode_row_id(&mut body, *row_id);
224	                encode_row_with_types(&mut body, row);
225	            }
226	            WalRecordBody::Update {
227	                table,
228	                row_id,
229	                before,
230	                after,
231	                new_row_id,
232	            } => {
233	                encode_string(&mut body, table);
234	                encode_row_id(&mut body, *row_id);
235	                encode_row_id(&mut body, *new_row_id);
236	                encode_row_with_types(&mut body, before);
237	                encode_row_with_types(&mut body, after);
238	            }
239	            WalRecordBody::IndexInsert {
240	                index,
241	                key_bytes,
242	                row_id,
243	            }
244	            | WalRecordBody::IndexDelete {
245	                index,
246	                key_bytes,
247	                row_id,
248	            } => {
249	                encode_string(&mut body, index);
250	                encode_row_id(&mut body, *row_id);
251	                body.extend_from_slice(&(key_bytes.len() as u16).to_le_bytes());
252	                body.extend_from_slice(key_bytes);
253	            }
254	        }
255	
256	        // Compute CRC over body
257	        let crc = crc32fast::hash(&body);
258	
259	        // Write: [total_len: u32][crc32: u32][body...]
260	        let total_len = (4 + body.len()) as u32; // crc(4) + body
261	        self.file.write_all(&total_len.to_le_bytes())?;
262	        self.file.write_all(&crc.to_le_bytes())?;
263	        self.file.write_all(&body)?;
264	        self.seq += 1;
265	        Ok(())
266	    }
267	
268	    pub fn flush(&mut self) -> Result<()> {
269	        self.file.flush()?;
270	        Ok(())
271	    }

282	/// Read all raw records from the WAL without interpreting schema.
283	pub fn read_raw_records(path: &Path) -> Result<Vec<RawWalRecord>> {
284	    if !path.exists() {
285	        return Ok(vec![]);
286	    }
287	    let mut file = File::open(path)?;
288	    let mut records = Vec::new();
289	
290	    loop {
291	        let mut len_buf = [0u8; 4];
292	        match file.read_exact(&mut len_buf) {
293	            Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
294	            Err(e) => return Err(e.into()),
295	            Ok(_) => {}
296	        }
297	        let total_len = u32::from_le_bytes(len_buf) as usize;
298	        if total_len < 4 {
299	            break; // truncated
300	        }
301	
302	        let mut rest = vec![0u8; total_len];
303	        match file.read_exact(&mut rest) {
304	            Err(_) => break, // torn record
305	            Ok(_) => {}
306	        }
307	
308	        let stored_crc = u32::from_le_bytes(rest[0..4].try_into().unwrap());
309	        let body = &rest[4..];
310	        let computed_crc = crc32fast::hash(body);
311	
312	        if stored_crc != computed_crc {
313	            log::warn!("WAL CRC mismatch, stopping replay");
314	            break; // torn/corrupted record
315	        }
316	
317	        if body.is_empty() {
318	            break;
319	        }
320	
321	        let rtype = match WalRecordType::from_u8(body[0]) {
322	            Some(t) => t,
323	            None => {
324	                log::warn!("Unknown WAL record type {}, stopping", body[0]);
325	                break;
326	            }
327	        };
328	
329	        if body.len() < 9 {
330	            break;
331	        }
332	        let txn_id = u64::from_le_bytes(body[1..9].try_into().unwrap());
333	        let data = body[9..].to_vec();
334	
335	        records.push(RawWalRecord {
336	            txn_id,
337	            rtype,
338	            data,
339	        });
340	    }
341	
342	    Ok(records)
343	}
