1114	        }
1115	
1116	        let committed = committed_txns(&records);
1117	        log::info!(
1118	            "WAL replay: {} records, {} committed txns",
1119	            records.len(),
1120	            committed.len()
1121	        );
1122	
1123	        for rec in &records {
1124	            if !committed.contains(&rec.txn_id) {
1125	                continue; // skip uncommitted
1126	            }
1127	            match rec.rtype {
1128	                WalRecordType::Insert => {
1129	                    let mut pos = 0usize;
1130	                    let table = crate::storage::wal::decode_string_pos(&rec.data, &mut pos)?;
1131	                    let rid = crate::storage::wal::decode_row_id_pos(&rec.data, &mut pos)?;
1132	                    if let Some(ts) = self.catalog.get_table(&table) {
