354	        for item in &self.projections {
355	            match item {
356	                SelectItem::Star => {
357	                    out_cols.extend(in_schema.columns.clone());
358	                }
359	                SelectItem::TableStar(tbl) => {
360	                    for (name, dt) in &in_schema.columns {
361	                        let prefix = format!("{}.", tbl.to_lowercase());
362	                        if name.to_lowercase().starts_with(&prefix)
363	                            || name.to_lowercase() == tbl.to_lowercase()
364	                        {
365	                            let short = name.splitn(2, '.').last().unwrap_or(name).to_string();
366	                            out_cols.push((short, dt.clone()));
367	                        }
368	                    }
369	                }
370	                SelectItem::Expr(expr, alias) => {
371	                    let col_name = alias.clone().unwrap_or_else(|| expr_name(expr));
372	                    // Determine type from expr (best-effort)
373	                    let dt = infer_expr_type(expr, &in_schema);
374	                    out_cols.push((col_name, dt));
375	                }
376	            }
377	        }
378	        self.out_schema = Schema::new(out_cols);
