1156	    pub fn execute_plan(&mut self, plan: PhysicalPlan) -> Result<QueryResult> {
1157	        match plan {
1158	            PhysicalPlan::Begin => {
1159	                self.txn_manager.begin()?;
1160	                self.explicit_txn = true;
1161	                Ok(QueryResult::with_message("transaction started"))
1162	            }
1163	            PhysicalPlan::Commit => {
1164	                self.txn_manager.commit(&mut self.wal)?;
1165	                self.explicit_txn = false;
1166	                self.catalog.save()?;
1167	                Ok(QueryResult::with_message("committed"))
1168	            }
1169	            PhysicalPlan::Rollback => {
1170	                // For rollback, we need to undo changes made during the txn
1171	                // In our simplified model, we just mark as rolled back
1172	                self.txn_manager.rollback(&mut self.wal)?;
1173	                self.explicit_txn = false;
1174	                Ok(QueryResult::with_message("rolled back"))
1175	            }
1176	            PhysicalPlan::CreateTable { stmt } => self.exec_create_table(stmt),
1177	            PhysicalPlan::DropTable { name, if_exists } => self.exec_drop_table(&name, if_exists),
1178	            PhysicalPlan::CreateIndex { stmt } => self.exec_create_index(stmt),
1179	            PhysicalPlan::DropIndex { name, if_exists } => self.exec_drop_index(&name, if_exists),
1180	            PhysicalPlan::MetaCommand(mc) => self.exec_meta(mc),
1181	            plan => {
1182	                // DML: build operator tree and execute
1183	                let mut op = self.build_operator(plan)?;
1184	                op.open(self)?;
1185	                let schema = op.schema();
1186	                let mut rows = Vec::new();
1187	                while let Some(row) = op.next()? {
1188	                    rows.push(row);
1189	                }
1190	                op.close();
1191	
1192	                let affected = if schema.columns.len() == 1
1193	                    && (schema.columns[0].0 == "rows_inserted"
1194	                        || schema.columns[0].0 == "rows_updated"
1195	                        || schema.columns[0].0 == "rows_deleted")
1196	                {
1197	                    rows.first().and_then(|r| r.first()).and_then(|v| {
1198	                        if let Value::Int(i) = v {
1199	                            Some(*i as usize)
1200	                        } else {
1201	                            None
1202	                        }
1203	                    })
1204	                } else {
1205	                    None
1206	                };
1207	
1208	                if affected.is_some() {
1209	                    if !self.explicit_txn {
1210	                        self.catalog.save()?;
1211	                    }
1212	                    Ok(QueryResult::affected(affected.unwrap()))
1213	                } else {
1214	                    Ok(QueryResult {
1215	                        schema,
1216	                        rows,
1217	                        affected_rows: None,
1218	                        message: None,
1219	                    })
1220	                }
1221	            }
1222	        }
1223	    }
