211	            let mut new_root = InternalNode::new();
212	            new_root.keys.push(split_key);
213	            new_root.children.push(self.root);
214	            new_root.children.push(right_page);
215	            let new_root_id = pm.alloc_page()?;
216	            pm.write_page(new_root_id, &new_root.to_page())?;
