703	                let key_val = &row[col_idx];
704	                let idx_def = db
705	                    .catalog
706	                    .get_index(idx_name)
707	                    .ok_or_else(|| MiniDbError::NoSuchIndex(idx_name.clone()))?;
708	
709	                if idx_def.unique || schema.columns[col_idx].primary_key {
710	                    let existing = {
711	                        let mut btree = BTreeIndex {
712	                            root: PageId(idx_def.root_page),
713	                        };
714	                        btree.eq_scan(&mut db.page_manager, key_val)?
715	                    };
