436	impl PhysicalOperator for NestedLoopJoin {
437	    fn open(&mut self, db: &mut Database) -> Result<()> {
438	        self.left.open(db)?;
439	        self.right.open(db)?;
440	
441	        let left_schema = self.left.schema();
442	        let right_schema = self.right.schema();
443	        self.out_schema = left_schema.append(&right_schema, None);
444	
445	        // Collect left
446	        let mut left_rows = Vec::new();
447	        while let Some(r) = self.left.next()? {
448	            left_rows.push(r);
449	        }
450	        // Collect right
451	        let mut right_rows = Vec::new();
452	        while let Some(r) = self.right.next()? {
453	            right_rows.push(r);
454	        }
455	
456	        // Cross product with optional condition
457	        for l in &left_rows {
458	            for r in &right_rows {
459	                let combined: Row = l.iter().chain(r.iter()).cloned().collect();
460	                if let Some(cond) = &self.condition {
461	                    if eval_predicate(cond, &combined, &self.out_schema)? {
462	                        self.buffer.push(combined);
463	                    }
464	                } else {
465	                    self.buffer.push(combined);
466	                }
467	            }
468	        }
469	
470	        self.left.close();
471	        self.right.close();
472	        self.pos = 0;
473	        Ok(())
474	    }
