243	    /// Try to produce an IndexScan for a filter over a scan, if possible.
244	    fn try_index_scan(
245	        &self,
246	        input: &LogicalPlan,
247	        predicate: &Expr,
248	    ) -> Result<Option<PhysicalPlan>> {
249	        let (table, alias) = match input {
250	            LogicalPlan::Scan { table, alias } => (table.clone(), alias.clone()),
251	            _ => return Ok(None),
252	        };
253	
254	        // Look for predicates of the form: col OP literal or literal OP col
255	        if let Some((col, op, val)) = extract_simple_predicate(predicate) {
256	            if let Some(idx) = self.catalog.find_index(&table, &col) {
257	                return Ok(Some(PhysicalPlan::IndexScan {
258	                    table: table.clone(),
259	                    index: idx.name.clone(),
260	                    column: col.clone(),
261	                    op,
262	                    value: val,
263	                    alias,
264	                }));
265	            }
266	        }
