209	    /// Allocate a new page and return its ID.
210	    pub fn alloc_page(&mut self) -> Result<PageId> {
211	        let id = PageId(self.num_pages);
212	        self.num_pages += 1;
213	        // Write blank page
214	        let page = Page::new();
215	        self.write_page(id, &page)?;
216	        Ok(id)
217	    }
