219	    pub fn read_page(&mut self, id: PageId) -> Result<Page> {
220	        if id.0 >= self.num_pages {
221	            return Err(MiniDbError::Internal(format!(
222	                "page {} out of range (have {})",
223	                id.0, self.num_pages
224	            )));
225	        }
226	        let offset = id.0 * PAGE_SIZE as u64;
227	        self.file.seek(SeekFrom::Start(offset))?;
228	        let mut page = Page::new();
229	        self.file.read_exact(&mut page.data)?;
230	        Ok(page)
231	    }
232	
233	    pub fn write_page(&mut self, id: PageId, page: &Page) -> Result<()> {
234	        let offset = id.0 * PAGE_SIZE as u64;
235	        self.file.seek(SeekFrom::Start(offset))?;
236	        self.file.write_all(&page.data)?;
237	        Ok(())
238	    }

 73	    /// Insert a row. Returns the assigned RowId.
 74	    pub fn insert(&mut self, pm: &mut PageManager, row: &Row) -> Result<RowId> {
 75	        // First, assign a preliminary row_id (we'll finalize after slot assignment)
 76	        // We use a placeholder; after getting the slot, we re-encode.
 77	        // Actually, we need the final RowId before encoding... Let's use a two-pass approach:
 78	        // 1. Estimate slot on last page
 79	        // 2. Assign RowId based on that, then write
 80	
 81	        // Try to insert into the last page
 82	        let encoded_row = serialize_row(row);
 83	        let record_len = 8 + encoded_row.len();
 84	
 85	        // Check if last page has space
 86	        let mut page = pm.read_page(self.last_page)?;
 87	        let slot;
 88	
 89	        if page.available_space() >= record_len {
 90	            // Will fit on last page
 91	            let placeholder_rid = RowId::new(self.last_page, page.num_slots() as usize);
 92	            let record = Self::encode_record(placeholder_rid, row);
 93	            slot = page.insert_record(&record)?;
 94	            // Update the stored row_id in the record to match actual slot
 95	            let actual_rid = RowId::new(self.last_page, slot);
 96	            if actual_rid != placeholder_rid {
 97	                // Re-encode with correct rid and update in place
 98	                let new_record = Self::encode_record(actual_rid, row);
 99	                page.update_record(slot, &new_record)?;
100	            }
101	            pm.write_page(self.last_page, &page)?;
102	            Ok(actual_rid)
103	        } else {
104	            // Allocate a new page
105	            let new_page_id = pm.alloc_page()?;
106	            let mut new_page = Page::new();
107	            new_page.init_heap();
108	
109	            let actual_rid = RowId::new(new_page_id, 0);
110	            let record = Self::encode_record(actual_rid, row);
111	            let s = new_page.insert_record(&record)?;
112	            debug_assert_eq!(s, 0);
113	            pm.write_page(new_page_id, &new_page)?;
114	
115	            // Update last page to point to new page
116	            page.set_next_page(new_page_id);
117	            pm.write_page(self.last_page, &page)?;
118	
119	            self.last_page = new_page_id;
120	            Ok(actual_rid)
121	        }

