104	    /// Commit the current transaction: write WAL and flush.
105	    /// Returns whether this was an auto-commit (for callers).
106	    pub fn commit(&mut self, wal: &mut WalWriter) -> Result<()> {
107	        let txn_id = match &self.state {
108	            TxnState::Active(id) => *id,
109	            TxnState::Idle => return Err(MiniDbError::TxnError("no active transaction".into())),
110	        };
111	
112	        // Write begin record
113	        wal.write_record(&WalRecord {
114	            txn_id,
115	            body: WalRecordBody::Begin,
116	        })?;
117	
118	        // Write all pending ops
119	        let ops = std::mem::take(&mut self.pending_ops);
120	        for op in &ops {
121	            let body = match op {
122	                TxnOp::Insert { table, row_id, row } => WalRecordBody::Insert {
123	                    table: table.clone(),
124	                    row_id: *row_id,
125	                    row: row.clone(),
126	                },
127	                TxnOp::Delete { table, row_id, row } => WalRecordBody::Delete {
128	                    table: table.clone(),
129	                    row_id: *row_id,
130	                    row: row.clone(),
131	                },
132	                TxnOp::Update {
133	                    table,
134	                    row_id,
135	                    new_row_id,
136	                    before,
137	                    after,
138	                } => WalRecordBody::Update {
139	                    table: table.clone(),
140	                    row_id: *row_id,
141	                    before: before.clone(),
142	                    after: after.clone(),
143	                    new_row_id: *new_row_id,
144	                },
145	                TxnOp::IndexInsert {
146	                    index,
147	                    key_bytes,
148	                    row_id,
149	                } => WalRecordBody::IndexInsert {
150	                    index: index.clone(),
151	                    key_bytes: key_bytes.clone(),
152	                    row_id: *row_id,
153	                },
154	                TxnOp::IndexDelete {
155	                    index,
156	                    key_bytes,
157	                    row_id,
158	                } => WalRecordBody::IndexDelete {
159	                    index: index.clone(),
160	                    key_bytes: key_bytes.clone(),
161	                    row_id: *row_id,
162	                },
163	            };
164	            wal.write_record(&WalRecord { txn_id, body })?;
165	        }
166	
167	        // Write commit record
168	        wal.write_record(&WalRecord {
169	            txn_id,
170	            body: WalRecordBody::Commit,
171	        })?;
172	        wal.flush()?;
173	
174	        self.state = TxnState::Idle;
175	        Ok(())

256	        // Compute CRC over body
257	        let crc = crc32fast::hash(&body);
258	
259	        // Write: [total_len: u32][crc32: u32][body...]
260	        let total_len = (4 + body.len()) as u32; // crc(4) + body
261	        self.file.write_all(&total_len.to_le_bytes())?;
262	        self.file.write_all(&crc.to_le_bytes())?;
263	        self.file.write_all(&body)?;
264	        self.seq += 1;
265	        Ok(())
266	    }
