64	    pub fn append(&mut self, record: &WalRecord) -> Result<()> {
65	        let data_len = record.data.len() as u32;
66	        let body_len = WAL_RECORD_HEADER_SIZE + record.data.len() + WAL_CRC_SIZE;
67	
68	        let mut buf = Vec::with_capacity(4 + body_len);
69	        buf.extend_from_slice(&(body_len as u32).to_le_bytes());
70	        buf.push(record.record_type as u8);
71	        buf.extend_from_slice(&record.txn_id.to_le_bytes());
72	        buf.extend_from_slice(&record.page_id.to_le_bytes());
73	        buf.extend_from_slice(&data_len.to_le_bytes());
74	        buf.extend_from_slice(&record.data);
75	
76	        let mut hasher = Hasher::new();
77	        hasher.update(&buf[4..]);
78	        let crc = hasher.finalize();
79	        buf.extend_from_slice(&crc.to_le_bytes());
80	
81	        self.file.write_all(&buf)?;
82	        Ok(())
83	    }
