 91	    pub fn replay<P: AsRef<Path>>(path: P) -> Result<Vec<WalRecord>> {
 92	        let mut file = match File::open(path.as_ref()) {
 93	            Ok(f) => f,
 94	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
 95	            Err(e) => return Err(e.into()),
 96	        };
 97	
 98	        file.seek(SeekFrom::Start(0))?;
 99	        let mut records = Vec::new();
100	        let mut buf = Vec::new();
101	        file.read_to_end(&mut buf)?;
102	        let mut pos = 0;
103	
104	        while pos + 4 <= buf.len() {
105	            let body_len = u32::from_le_bytes(buf[pos..pos + 4].try_into().unwrap()) as usize;
106	            pos += 4;
107	
108	            if pos + body_len > buf.len() {
109	                warn!("WAL: truncated record at offset {}", pos - 4);
110	                break;
111	            }
112	
113	            let record_bytes = &buf[pos..pos + body_len];
114	            let data_portion = &record_bytes[..body_len - WAL_CRC_SIZE];
115	            let stored_crc =
116	                u32::from_le_bytes(record_bytes[body_len - WAL_CRC_SIZE..].try_into().unwrap());
117	
118	            let mut hasher = Hasher::new();
119	            hasher.update(data_portion);
120	            let computed_crc = hasher.finalize();
121	
122	            if stored_crc != computed_crc {
123	                warn!(
124	                    "WAL: CRC mismatch at offset {} (stored={}, computed={}), stopping replay",
125	                    pos - 4,
126	                    stored_crc,
127	                    computed_crc
128	                );
129	                break;
130	            }

