 54	    fn open(&mut self) -> Result<()> {
 55	        let eng = unsafe { &mut *self.engine };
 56	
 57	        // Evaluate index predicate to get row_ids
 58	        let row_ids = match &self.predicate {
 59	            IndexPredicate::Eq(expr) => {
 60	                let key = eval_literal(expr);
 61	                eng.index_lookup_eq(&self.index_name, &key)
 62	            }
 63	            IndexPredicate::Range {
 64	                low,
 65	                low_inclusive,
 66	                high,
 67	                high_inclusive,
 68	            } => {
 69	                let low_val = low.as_ref().map(eval_literal);
 70	                let high_val = high.as_ref().map(eval_literal);
 71	                eng.index_lookup_range(
 72	                    &self.index_name,
 73	                    low_val.as_ref(),
 74	                    *low_inclusive,
 75	                    high_val.as_ref(),
 76	                    *high_inclusive,
 77	                )
 78	            }
 79	        };
 80	
 81	        // Fetch rows
 82	        let mut rows = Vec::new();
 83	        for rid in row_ids {
 84	            if let Some(row) = eng.get_row(&self.table, rid)? {
 85	                rows.push((rid, row));
 86	            }
 87	        }
 88	        self.rows = rows;
 89	        self.cursor = 0;
 90	        Ok(())
 91	    }
 92	
 93	    fn next(&mut self) -> Result<Option<Row>> {
 94	        if self.cursor >= self.rows.len() {
 95	            return Ok(None);
 96	        }
 97	        let (_, row) = self.rows[self.cursor].clone();
 98	        self.cursor += 1;
 99	        Ok(Some(row))
100	    }

