423	fn postprocess_meta_commands(tokens: Vec<TokenWithPos>) -> Vec<TokenWithPos> {
424	    let mut result = Vec::with_capacity(tokens.len());
425	    let mut i = 0;
426	    while i < tokens.len() {
427	        // Check for Dot followed by Ident at statement start (first token or after Semicolon)
428	        let is_stmt_start = result
429	            .last()
430	            .map(|t: &TokenWithPos| t.token == Token::Semicolon)
431	            .unwrap_or(true);
432	        if is_stmt_start && tokens[i].token == Token::Dot && i + 1 < tokens.len() {
433	            if let Token::Ident(ref name) = tokens[i + 1].token {
434	                let line = tokens[i].line;
435	                let col = tokens[i].col;
436	                let meta_tok = match name.to_lowercase().as_str() {
437	                    "schema" => Some(Token::MetaSchema),
438	                    "tables" => Some(Token::MetaTables),
439	                    "indexes" => Some(Token::MetaIndexes),
440	                    "exit" | "quit" => Some(Token::MetaExit),
441	                    "format" => Some(Token::MetaFormat),
442	                    _ => None,
443	                };
444	                if let Some(tok) = meta_tok {
445	                    result.push(TokenWithPos {
446	                        token: tok,
447	                        line,
448	                        col,
449	                    });
450	                    // If MetaFormat, the next token after the ident is the format name
451	                    i += 2;
452	                    continue;
453	                }
454	            }
455	        }
456	        result.push(tokens[i].clone());
457	        i += 1;
458	    }
459	    result

