 52	    fn insert_into_chain(&self, pm: &mut PageManager, data: &[u8]) -> Result<RowId> {
 53	        let mut current_pid = self.root_page;
 54	        loop {
 55	            // Ensure page exists
 56	            while pm.num_pages <= current_pid {
 57	                pm.alloc_page()?;
 58	            }
 59	            let pid = PageId(current_pid);
 60	            let page = pm.read_page(pid)?;
 61	
 62	            if page.page_type() != Some(PageType::Heap) {
 63	                let mut hp = HeapPage::new(page);
 64	                hp.init();
 65	            }
 66	
 67	            let next_page = {
 68	                let page = pm.read_page(PageId(current_pid))?;
 69	                let hp = HeapPage { page };
 70	                hp.next_page()
 71	            };
 72	
 73	            {
 74	                let page = pm.read_page(PageId(current_pid))?;
 75	                let mut hp = HeapPage { page };
 76	                if hp.can_fit(data.len()) {
 77	                    let slot = hp.insert_row(data).ok_or_else(|| {
 78	                        MiniDbError::Storage("failed to insert row into heap page".to_string())
 79	                    })?;
 80	                    return Ok(encode_row_id(current_pid, slot));
 81	                }
 82	            }
 83	
 84	            if next_page == 0 {
 85	                // Allocate new page
 86	                let new_pid = pm.alloc_page()?;
 87	                {
 88	                    let page = pm.read_page(PageId(current_pid))?;
 89	                    let mut hp = HeapPage { page };
 90	                    hp.set_next_page(new_pid.0);
 91	                }
 92	                {
