248	    pub fn execute_statement(&mut self, stmt: Statement) -> Result<ExecResult> {
249	        match &stmt {
250	            Statement::Begin => {
251	                self.txn.begin(&mut self.wal)?;
252	                self.auto_commit = false;
253	                return Ok(ExecResult {
254	                    schema: Schema::new(vec![]),
255	                    rows: vec![],
256	                    rows_affected: 0,
257	                    kind: ResultKind::Txn,
258	                });
259	            }
260	            Statement::Commit => {
261	                if self.txn.is_active() {
262	                    self.txn.commit(&mut self.wal)?;
263	                    self.persist_all()?;
264	                }
265	                self.auto_commit = true;
266	                return Ok(ExecResult {
267	                    schema: Schema::new(vec![]),
268	                    rows: vec![],
269	                    rows_affected: 0,
270	                    kind: ResultKind::Txn,
271	                });
272	            }
273	            Statement::Rollback => {
274	                if self.txn.is_active() {
275	                    let undo = self.txn.rollback(&mut self.wal)?;
276	                    self.apply_undo(undo)?;
277	                }
278	                self.auto_commit = true;
279	                return Ok(ExecResult {
280	                    schema: Schema::new(vec![]),
281	                    rows: vec![],
282	                    rows_affected: 0,
283	                    kind: ResultKind::Txn,
284	                });
285	            }
286	            Statement::MetaSchema
287	            | Statement::MetaTables
288	            | Statement::MetaIndexes
289	            | Statement::MetaExit
290	            | Statement::MetaFormat(_) => {
291	                return self.execute_meta(&stmt);
292	            }
293	            _ => {}
294	        }
295	
296	        // Auto-begin if needed
297	        let was_auto = if !self.txn.is_active() {
298	            self.txn.begin(&mut self.wal)?;
299	            true
300	        } else {
301	            false
302	        };
303	
304	        let result = self.execute_dml_ddl(stmt);
305	
306	        match result {
307	            Ok(res) => {
308	                if was_auto {
309	                    self.txn.commit(&mut self.wal)?;
310	                    self.persist_all()?;
311	                }
312	                Ok(res)
313	            }
314	            Err(e) => {
315	                if was_auto && self.txn.is_active() {
316	                    let undo = self.txn.rollback(&mut self.wal).unwrap_or_default();
317	                    let _ = self.apply_undo(undo);
318	                }
319	                Err(e)
320	            }
321	        }

