176	/// Replay WAL: returns committed transaction records grouped by txn_id
177	pub fn replay_committed(records: &[WalRecord]) -> Vec<&WalRecord> {
178	    // Find committed txn IDs
179	    let committed: std::collections::HashSet<u64> = records
180	        .iter()
181	        .filter_map(|r| {
182	            if matches!(r, WalRecord::Commit { .. }) {
183	                Some(r.txn_id())
184	            } else {
185	                None
186	            }
187	        })
188	        .collect();
189	    records
190	        .iter()
191	        .filter(|r| committed.contains(&r.txn_id()))
192	        .collect()
193	}

 47	    pub fn open(path: &Path) -> Result<Self> {
 48	        let wal_path = path.with_extension("wal");
 49	        let mut wal = Wal::open(&wal_path)?;
 50	
 51	        // Replay WAL
 52	        let records = Wal::read_all(&wal_path)?;
 53	        let committed = replay_committed(&records);
 54	
 55	        // Load catalog from file or build empty
 56	        let catalog_path = path.with_extension("catalog");
 57	        let mut catalog = if catalog_path.exists() {
 58	            let data = std::fs::read(&catalog_path)?;
 59	            Catalog::deserialize(&data)?
 60	        } else {
 61	            Catalog::new()
 62	        };
 63	
 64	        // Load heaps from files
 65	        let mut heaps: HashMap<String, Heap> = HashMap::new();
 66	        let mut btrees: HashMap<String, BTree> = HashMap::new();
 67	
 68	        for tbl_name in catalog.tables.keys().cloned().collect::<Vec<_>>() {
 69	            let heap_path = heap_path(path, &tbl_name);
 70	            let heap = if heap_path.exists() {
 71	                let data = std::fs::read(&heap_path)?;
 72	                Heap::from_bytes(&data)?
 73	            } else {
 74	                Heap::new()
 75	            };
 76	            heaps.insert(tbl_name, heap);
 77	        }
 78	
 79	        for idx_name in catalog.indexes.keys().cloned().collect::<Vec<_>>() {
 80	            let bt_path = btree_path(path, &idx_name);
 81	            let bt = if bt_path.exists() {
 82	                let data = std::fs::read(&bt_path)?;
 83	                BTree::from_bytes(&data)?
 84	            } else {
 85	                BTree::new()
 86	            };
 87	            btrees.insert(idx_name, bt);
 88	        }
 89	
 90	        let mut db = Database {
 91	            path: path.to_path_buf(),
 92	            catalog,
 93	            heaps,
 94	            btrees,
 95	            wal,
 96	            txn: TxnManager::new(),
 97	            auto_commit: true,
 98	        };
 99	
100	        // Replay committed WAL records
101	        let mut max_txn_id = 0u64;
102	        for record in &committed {
103	            max_txn_id = max_txn_id.max(record.txn_id());
104	            db.apply_wal_record(record)?;
105	        }
106	        db.txn.set_min_txn_id(max_txn_id);
107	
108	        // Persist state after replay
109	        if !records.is_empty() {
110	            db.persist_all()?;
111	            db.wal.truncate()?;
112	        }
113	
114	        Ok(db)

