111	    /// Read all valid records from the WAL file
112	    pub fn read_all(path: &Path) -> Result<Vec<WalRecord>> {
113	        let mut file = match File::open(path) {
114	            Ok(f) => f,
115	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
116	            Err(e) => return Err(e.into()),
117	        };
118	        let mut records = Vec::new();
119	        let mut buf4 = [0u8; 4];
120	        loop {
121	            // Read length
122	            match file.read_exact(&mut buf4) {
123	                Ok(()) => {}
124	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
125	                Err(e) => return Err(e.into()),
126	            }
127	            let len = u32::from_le_bytes(buf4) as usize;
128	            let mut data = vec![0u8; len];
129	            match file.read_exact(&mut data) {
130	                Ok(()) => {}
131	                Err(_) => {
132	                    log::warn!("WAL: truncated record, stopping replay");
133	                    break;
134	                }
135	            }
136	            // Read CRC
137	            match file.read_exact(&mut buf4) {
138	                Ok(()) => {}
139	                Err(_) => {
140	                    log::warn!("WAL: truncated CRC, stopping replay");
141	                    break;
142	                }
143	            }
144	            let stored_crc = u32::from_le_bytes(buf4);
145	            // Verify CRC
146	            let mut hasher = Hasher::new();
147	            hasher.update(&(len as u32).to_le_bytes());
148	            hasher.update(&data);
149	            let computed_crc = hasher.finalize();
150	            if computed_crc != stored_crc {
151	                log::warn!("WAL: CRC mismatch, stopping replay (torn write detected)");
152	                break;
153	            }
154	            match serde_json::from_slice::<WalRecord>(&data) {
155	                Ok(record) => records.push(record),
156	                Err(e) => {
157	                    log::warn!("WAL: failed to deserialize record: {}", e);
158	                    break;
159	                }
160	            }
161	        }
162	        Ok(records)

