338	    fn execute_select(&self, sel: &SelectStmt) -> Result<ExecResult> {
339	        // Plan
340	        let planner = Planner::new(&self.catalog);
341	        let plan = planner.plan_statement(&Statement::Select(sel.clone()))?;
342	
343	        // Build operator tree
344	        let mut op = self.build_operator(plan)?;
345	        op.open()?;
346	
347	        let schema = op.schema().clone();
348	        let mut rows = Vec::new();
349	        while let Some(row) = op.next()? {
350	            rows.push(row);
351	        }
352	        op.close()?;
353	
354	        Ok(ExecResult {
355	            schema,
356	            rows,
357	            rows_affected: 0,
358	            kind: ResultKind::Select,
359	        })
360	    }
