362	    fn build_operator(&self, plan: LogicalPlan) -> Result<Box<dyn PhysicalOperator>> {
363	        match plan {
364	            LogicalPlan::Scan { table } => {
365	                let schema_def = self.catalog.get_table(&table)?.columns.clone();
366	                let heap = self.heaps.get(&table).ok_or_else(|| {
367	                    MiniDbError::Storage(format!("heap for '{}' not found", table))
368	                })?;
369	                Ok(Box::new(SeqScan::new(&table, heap, &schema_def)))
370	            }
371	            LogicalPlan::IndexScan {
372	                table,
373	                index,
374	                column,
375	                predicate,
376	            } => {
377	                let schema_def = self.catalog.get_table(&table)?.columns.clone();
378	                let heap = self.heaps.get(&table).ok_or_else(|| {
379	                    MiniDbError::Storage(format!("heap for '{}' not found", table))
380	                })?;
381	                let btree = self.btrees.get(&index).ok_or_else(|| {
382	                    MiniDbError::Storage(format!("btree for '{}' not found", index))
383	                })?;
384	                Ok(Box::new(IndexScan::new(
385	                    &table,
386	                    heap,
387	                    btree,
388	                    &predicate,
389	                    &schema_def,
390	                )))
391	            }
392	            LogicalPlan::Filter { input, predicate } => {
393	                let child = self.build_operator(*input)?;
394	                Ok(Box::new(Filter::new(child, predicate)))
395	            }
396	            LogicalPlan::Project { input, columns } => {
397	                let child = self.build_operator(*input)?;
398	                Ok(Box::new(Project::new(child, columns)))
399	            }
400	            LogicalPlan::Join {
401	                left,
402	                right,
403	                condition,
404	            } => {
405	                let left_op = self.build_operator(*left)?;
406	                let right_op = self.build_operator(*right)?;
407	                let right_schema = right_op.schema().clone();
408	                // Materialize right side
409	                let mut right_op = right_op;
410	                right_op.open()?;
411	                let mut right_rows = Vec::new();
412	                while let Some(r) = right_op.next()? {
413	                    right_rows.push(r);
414	                }
415	                right_op.close()?;
416	                Ok(Box::new(NestedLoopJoinBuilder::new(
417	                    left_op,
418	                    right_rows,
419	                    right_schema,
420	                    condition,
421	                )))
422	            }
423	            LogicalPlan::Sort { input, keys } => {
424	                let child = self.build_operator(*input)?;
425	                Ok(Box::new(Sort::new(child, keys)))
426	            }
427	            LogicalPlan::Limit {
428	                input,
429	                limit,
430	                offset,
431	            } => {
432	                let child = self.build_operator(*input)?;
433	                Ok(Box::new(Limit::new(child, limit, offset)))
434	            }

464	    fn execute_insert(&mut self, ins: &InsertStmt) -> Result<ExecResult> {
465	        let schema = self.catalog.get_table(&ins.table)?.clone();
466	        let txn_id = self.txn.active_id().unwrap_or(0);
467	        let empty_eval_schema = Schema::new(vec![]);
468	        let mut total = 0usize;
469	
470	        for value_row in &ins.values {
471	            let values: Vec<Value> = value_row
472	                .iter()
473	                .map(|e| Evaluator::eval(e, &[], &empty_eval_schema))
474	                .collect::<Result<_>>()?;
475	
476	            // Build full row
477	            let named: Vec<(String, Value)> = if let Some(cols) = &ins.columns {
478	                cols.iter()
479	                    .zip(values.iter())
480	                    .map(|(c, v)| (c.clone(), v.clone()))
481	                    .collect()
482	            } else {
483	                schema
484	                    .columns
485	                    .iter()
486	                    .zip(values.iter())
487	                    .map(|(c, v)| (c.name.clone(), v.clone()))
488	                    .collect()
489	            };
490	
491	            let row = schema.build_row(&named)?;
492	
493	            // Check UNIQUE constraints
494	            self.check_unique_constraints(&ins.table, &schema, &row, None)?;
495	            // Check CHECK constraints (simplified - skip for now as we'd need expression storage)
496	
497	            let data = serialize_row(&row)?;
498	            let heap = self
499	                .heaps
500	                .entry(ins.table.clone())
501	                .or_insert_with(Heap::new);
502	            let row_id = heap.insert_row(&row)?;
503	
504	            self.wal.append(&WalRecord::InsertRow {
505	                txn_id,
506	                table: ins.table.clone(),
507	                row_id,
508	                data: data.clone(),
509	            })?;
510	
511	            self.txn.log_insert(&ins.table, row_id);
512	
513	            // Update indexes
514	            self.update_indexes_insert(&ins.table, row_id, &row);
515	            total += 1;
516	        }
517	
518	        Ok(ExecResult {
519	            schema: Schema::new(vec![]),
520	            rows: vec![],
521	            rows_affected: total,
522	            kind: ResultKind::Insert,
523	        })
524	    }

588	    fn execute_update(&mut self, upd: &UpdateStmt) -> Result<ExecResult> {
589	        let schema = self.catalog.get_table(&upd.table)?.clone();
590	        let txn_id = self.txn.active_id().unwrap_or(0);
591	        let col_schema = Schema::new(
592	            schema
593	                .columns
594	                .iter()
595	                .map(|c| OutputColumn {
596	                    name: c.name.clone(),
597	                    table: Some(upd.table.clone()),
598	                    dtype: Some(c.dtype.clone()),
599	                })
600	                .collect(),
601	        );
602	
603	        let heap = self
604	            .heaps
605	            .get(&upd.table)
606	            .ok_or_else(|| MiniDbError::TableNotFound(upd.table.clone()))?;
607	
608	        // Find matching rows
609	        let matching: Vec<(u64, Row)> = heap
610	            .scan()
611	            .filter(|(_, row)| {
612	                if let Some(pred) = &upd.where_clause {
613	                    Evaluator::eval_bool(pred, row, &col_schema).unwrap_or(false)
614	                } else {
615	                    true
616	                }
617	            })
618	            .collect();
619	
620	        let mut affected = 0usize;
621	        for (row_id, mut row) in matching {
622	            let old_data = serialize_row(&row)?;
623	
624	            // Apply assignments
625	            for (col_name, expr) in &upd.assignments {
626	                let ci = schema
627	                    .col_index(col_name)
628	                    .ok_or_else(|| MiniDbError::ColumnNotFound(col_name.clone()))?;
629	                row[ci] = Evaluator::eval(expr, &row, &col_schema)?;
630	                // Coerce type
631	                row[ci] = row[ci].coerce_to(&schema.columns[ci].dtype)?;
632	            }
633	
634	            // Check NOT NULL
635	            for (i, col) in schema.columns.iter().enumerate() {
636	                if col.not_null && row[i].is_null() {
637	                    return Err(MiniDbError::Constraint(format!(
638	                        "column '{}' cannot be NULL",
639	                        col.name
640	                    )));
641	                }
642	            }
643	
644	            // Check UNIQUE
645	            self.check_unique_constraints(&upd.table, &schema, &row, Some(row_id))?;
646	
647	            let new_data = serialize_row(&row)?;
648	
649	            // Remove old index entries
650	            let old_row = deserialize_row(&old_data)?;
651	            self.update_indexes_delete(&upd.table, row_id, &old_row);
652	
653	            let heap = self.heaps.get_mut(&upd.table).unwrap();
654	            heap.update_row(row_id, &row)?;
655	
656	            self.wal.append(&WalRecord::UpdateRow {
657	                txn_id,
658	                table: upd.table.clone(),
659	                row_id,
660	                old_data: old_data.clone(),
661	                new_data: new_data.clone(),
662	            })?;
663	            self.txn.log_update(&upd.table, row_id, old_data);
664	
665	            // Add new index entries
666	            self.update_indexes_insert(&upd.table, row_id, &row);
667	            affected += 1;
668	        }
669	
670	        Ok(ExecResult {
671	            schema: Schema::new(vec![]),
672	            rows: vec![],
673	            rows_affected: affected,
674	            kind: ResultKind::Update,
675	        })
676	    }
677	
678	    fn execute_delete(&mut self, del: &DeleteStmt) -> Result<ExecResult> {
679	        let schema = self.catalog.get_table(&del.table)?.clone();
680	        let txn_id = self.txn.active_id().unwrap_or(0);
681	        let col_schema = Schema::new(
682	            schema
683	                .columns
684	                .iter()
685	                .map(|c| OutputColumn {
686	                    name: c.name.clone(),
687	                    table: Some(del.table.clone()),
688	                    dtype: Some(c.dtype.clone()),
689	                })
690	                .collect(),
691	        );
692	
693	        let heap = self
694	            .heaps
695	            .get(&del.table)
696	            .ok_or_else(|| MiniDbError::TableNotFound(del.table.clone()))?;
697	
698	        let matching: Vec<(u64, Vec<u8>)> = heap
699	            .scan_raw()
700	            .filter(|slot| {
701	                if let Some(pred) = &del.where_clause {
702	                    if let Ok(row) = deserialize_row(&slot.data) {
703	                        Evaluator::eval_bool(pred, &row, &col_schema).unwrap_or(false)
704	                    } else {
705	                        false
706	                    }
707	                } else {
708	                    true
709	                }
710	            })
711	            .map(|slot| (slot.row_id, slot.data.clone()))
712	            .collect();
713	
714	        let mut affected = 0usize;
715	        for (row_id, data) in matching {
716	            // Update indexes
717	            if let Ok(row) = deserialize_row(&data) {
718	                self.update_indexes_delete(&del.table, row_id, &row);
719	            }
720	
721	            let heap = self.heaps.get_mut(&del.table).unwrap();
722	            heap.delete_row(row_id)?;
723	
724	            self.wal.append(&WalRecord::DeleteRow {
725	                txn_id,
726	                table: del.table.clone(),
727	                row_id,
728	            })?;
729	            self.txn.log_delete(&del.table, row_id, data);
730	            affected += 1;
731	        }
732	
733	        Ok(ExecResult {
734	            schema: Schema::new(vec![]),
735	            rows: vec![],
736	            rows_affected: affected,
737	            kind: ResultKind::Delete,
738	        })
739	    }

