330	
331	impl NestedLoopJoin {
332	    pub fn new(
333	        left: Box<dyn PhysicalOperator>,
334	        right: Box<dyn PhysicalOperator>,
335	        condition: Expr,
336	    ) -> Self {
337	        let mut left_cols = left.schema().columns.clone();
338	        let right_cols = right.schema().columns.clone();
339	        let mut all_cols = left_cols.clone();
340	        all_cols.extend(right_cols.iter().cloned());
341	        let schema = Schema::new(all_cols);
342	
343	        // Materialize right side
344	        let right_schema_cols = right_cols;
345	        NestedLoopJoin {
346	            left,
347	            right_rows: Vec::new(),
348	            right_schema_cols,
349	            condition,
350	            schema,
351	            current_left: None,
352	            right_pos: 0,
353	            right_source: Vec::new(),
354	        }
355	    }
356	}
357	
358	impl PhysicalOperator for NestedLoopJoin {
359	    fn schema(&self) -> &Schema {
360	        &self.schema
361	    }
362	
363	    fn open(&mut self) -> Result<()> {
364	        self.left.open()?;
365	        Ok(())
366	    }
367	
368	    fn next(&mut self) -> Result<Option<Row>> {
369	        loop {
370	            if self.current_left.is_none() {
371	                self.current_left = self.left.next()?;
372	                if self.current_left.is_none() {
373	                    return Ok(None);
374	                }
375	                self.right_pos = 0;
376	            }
377	
378	            let left_row = self.current_left.as_ref().unwrap().clone();
379	
380	            while self.right_pos < self.right_source.len() {
381	                let right_row = self.right_source[self.right_pos].clone();
382	                self.right_pos += 1;
383	                let mut combined = left_row.clone();
384	                combined.extend(right_row.iter().cloned());
385	                if Evaluator::eval_bool(&self.condition, &combined, &self.schema)? {
386	                    return Ok(Some(combined));
387	                }
388	            }
389	
390	            // Exhausted right side for this left row
391	            self.current_left = None;
392	        }
393	    }
394	
395	    fn close(&mut self) -> Result<()> {
396	        self.left.close()
397	    }
398	}
