 1	/// Heap file storage: stores variable-length rows
 2	/// Format: rows stored as (row_id: u64, len: u32, data: [u8; len], deleted: u8)
 3	/// We keep a simple in-memory store backed by serialized append-only file.
 4	use crate::error::{MiniDbError, Result};
 5	use crate::types::{Row, Value};
