23	    slots: BTreeMap<RowId, HeapSlot>,
24	    next_row_id: RowId,
25	}

134	    /// Serialize heap to bytes for persistence
135	    pub fn to_bytes(&self) -> Vec<u8> {
136	        let mut out = Vec::new();
137	        out.extend_from_slice(&self.next_row_id.to_le_bytes());
138	        for slot in self.slots.values() {
139	            let deleted = if slot.deleted { 1u8 } else { 0u8 };
140	            out.extend_from_slice(&slot.row_id.to_le_bytes());
141	            out.extend_from_slice(&(slot.data.len() as u32).to_le_bytes());
142	            out.extend_from_slice(&slot.data);
143	            out.push(deleted);
144	        }
145	        out
146	    }
147	
148	    /// Deserialize heap from bytes
149	    pub fn from_bytes(data: &[u8]) -> Result<Self> {
150	        if data.len() < 8 {
151	            return Ok(Heap::new());
152	        }
153	        let next_row_id = u64::from_le_bytes(data[0..8].try_into().unwrap());
154	        let mut pos = 8;
155	        let mut slots = BTreeMap::new();
156	        while pos + 13 <= data.len() {
157	            let row_id = u64::from_le_bytes(data[pos..pos + 8].try_into().unwrap());
158	            pos += 8;
159	            let len = u32::from_le_bytes(data[pos..pos + 4].try_into().unwrap()) as usize;
160	            pos += 4;
161	            if pos + len + 1 > data.len() {
162	                break;
163	            }
164	            let row_data = data[pos..pos + len].to_vec();
165	            pos += len;
166	            let deleted = data[pos] != 0;
167	            pos += 1;
168	            slots.insert(
169	                row_id,
170	                HeapSlot {
171	                    row_id,
172	                    data: row_data,
173	                    deleted,
174	                },
175	            );
176	        }
177	        Ok(Heap { slots, next_row_id })

