262	                    self.txn.commit(&mut self.wal)?;
263	                    self.persist_all()?;
264	                }

176	/// Replay WAL: returns committed transaction records grouped by txn_id
177	pub fn replay_committed(records: &[WalRecord]) -> Vec<&WalRecord> {
178	    // Find committed txn IDs
179	    let committed: std::collections::HashSet<u64> = records
180	        .iter()
181	        .filter_map(|r| {
182	            if matches!(r, WalRecord::Commit { .. }) {
183	                Some(r.txn_id())
184	            } else {
185	                None
186	            }
187	        })
188	        .collect();
189	    records
190	        .iter()
191	        .filter(|r| committed.contains(&r.txn_id()))
192	        .collect()
193	}

