 36	    pub fn run_interactive(&mut self) -> Result<()> {
 37	        let mut rl =
 38	            rustyline::DefaultEditor::new().map_err(|e| MiniDbError::Runtime(e.to_string()))?;
 39	
 40	        println!(
 41	            "minidb v{} - type SQL statements or .help for meta-commands",
 42	            env!("CARGO_PKG_VERSION")
 43	        );
 44	
 45	        let mut buf = String::new();
 46	        loop {
 47	            let prompt = if buf.is_empty() {
 48	                "minidb> "
 49	            } else {
 50	                "   ...> "
 51	            };
 52	            match rl.readline(prompt) {
 53	                Ok(line) => {
 54	                    let trimmed = line.trim();
 55	                    if trimmed.is_empty() {
 56	                        continue;
 57	                    }
 58	
 59	                    // Meta-commands don't need semicolons
 60	                    if trimmed.starts_with('.') {
 61	                        let _ = rl.add_history_entry(trimmed);
 62	                        if let Err(e) = self.execute_line(trimmed) {
 63	                            eprintln!("Error: {}", e);
 64	                        }
 65	                        continue;
 66	                    }
 67	
 68	                    buf.push_str(&line);
 69	                    buf.push('\n');
 70	
 71	                    // Execute when we see a semicolon at end of trimmed line
 72	                    if trimmed.ends_with(';')
 73	                        || trimmed == "COMMIT"
 74	                        || trimmed == "ROLLBACK"
 75	                        || trimmed.to_uppercase().starts_with("BEGIN")
 76	                        || trimmed.to_uppercase() == "COMMIT"
 77	                        || trimmed.to_uppercase() == "ROLLBACK"
 78	                    {
 79	                        let sql = buf.trim().to_string();
 80	                        buf.clear();
 81	                        let _ = rl.add_history_entry(&sql);
 82	                        if let Err(e) = self.execute_line(&sql) {
 83	                            eprintln!("Error: {}", e);
 84	                        }
 85	                    }
 86	                }
 87	                Err(rustyline::error::ReadlineError::Eof) => {
 88	                    if !buf.trim().is_empty() {
 89	                        let sql = buf.trim().to_string();
 90	                        let _ = self.execute_line(&sql);
 91	                    }
 92	                    break;
 93	                }
 94	                Err(rustyline::error::ReadlineError::Interrupted) => {
 95	                    buf.clear();
 96	                    eprintln!("^C");
 97	                }
 98	                Err(e) => {
 99	                    eprintln!("readline error: {}", e);
100	                    break;
101	                }
102	            }
103	        }
104	        Ok(())
105	    }
