107	    fn execute_line(&mut self, sql: &str) -> Result<()> {
108	        // Check for .exit
109	        if sql.trim() == ".exit" || sql.trim() == ".quit" {
110	            std::process::exit(0);
111	        }
112	
113	        // Check for .format command
114	        if sql.trim().starts_with(".format") {
115	            let parts: Vec<&str> = sql.trim().splitn(2, ' ').collect();
116	            if parts.len() == 2 {
117	                if let Some(fmt) = OutputFormat::from_str(parts[1].trim()) {
118	                    self.format = fmt;
119	                    if !self.quiet {
120	                        eprintln!("ok output format set");
121	                    }
122	                } else {
123	                    eprintln!("Error: unknown format '{}'", parts[1].trim());
124	                }
125	            }
126	            return Ok(());
127	        }
128	
129	        match self.db.execute_sql(sql) {
130	            Ok(results) => {
131	                for res in results {
132	                    self.print_result(&res)?;
133	                }
134	                Ok(())
135	            }
