126	            }
127	            let len = u32::from_le_bytes(buf4) as usize;
128	            let mut data = vec![0u8; len];
129	            match file.read_exact(&mut data) {
130	                Ok(()) => {}
131	                Err(_) => {
132	                    log::warn!("WAL: truncated record, stopping replay");
133	                    break;
