141	                    break;
142	                }
143	            }
144	            let stored_crc = u32::from_le_bytes(buf4);
145	            // Verify CRC
146	            let mut hasher = Hasher::new();
147	            hasher.update(&(len as u32).to_le_bytes());
148	            hasher.update(&data);
149	            let computed_crc = hasher.finalize();
