342	    pub fn execute_in_txn<F, T>(&mut self, sql: &str, mut f: F) -> Result<T>
343	    where
344	        F: FnMut(&mut DatabaseState) -> Result<T>,
345	    {
346	        if self.active.is_some() {
347	            self.record_sql(sql)?;
348	            let snapshot = self.state().clone();
349	            match f(self.state_mut()) {
350	                Ok(result) => Ok(result),
351	                Err(err) => {
352	                    if let Some(active) = self.active.as_mut() {
353	                        active.sql_log.pop();
354	                        active.state = snapshot;
355	                    }
356	                    Err(err)
357	                }
358	            }
359	        } else {
360	            self.begin()?;
361	            self.record_sql(sql)?;
362	            let snapshot = self.state().clone();
363	            match f(self.state_mut()) {
364	                Ok(result) => {
365	                    self.commit()?;
366	                    Ok(result)
367	                }
368	                Err(err) => {
369	                    if let Some(active) = self.active.as_mut() {
370	                        active.sql_log.pop();
371	                        active.state = snapshot;
372	                    }
373	                    let _ = self.rollback();
374	                    Err(err)
375	                }
376	            }
377	        }

183	    pub fn open(base_path: impl Into<PathBuf>) -> Result<Self> {
184	        let base_path = base_path.into();
185	        let page_manager = PageManager::new(&base_path);
186	        let wal = Wal::new(wal_path(&base_path));
187	        let mut committed = if let Some((snapshot_lsn, payload)) = page_manager.load_snapshot()? {
188	            let mut state: DatabaseState = bincode::deserialize(&payload)
189	                .map_err(|err| MiniDbError::Corrupt(err.to_string()))?;
190	            state.last_committed_txid = snapshot_lsn;
191	            state
192	        } else {
193	            DatabaseState::default()
194	        };
195	        let records = wal.read_all()?;
196	        let mut max_txid = committed.last_committed_txid;
197	        let mut tx_buffer: BTreeMap<u64, Vec<String>> = BTreeMap::new();
198	        let mut seen_commit: BTreeMap<u64, bool> = BTreeMap::new();
199	        for record in records {
200	            max_txid = max_txid.max(record.txid);
201	            match record.kind {
202	                WalKind::Begin => {
203	                    tx_buffer.entry(record.txid).or_default();
204	                }
205	                WalKind::Statement { sql } => {
206	                    tx_buffer.entry(record.txid).or_default().push(sql);
207	                }
208	                WalKind::Commit => {
209	                    seen_commit.insert(record.txid, true);
210	                }
211	                WalKind::Rollback => {
212	                    tx_buffer.remove(&record.txid);
213	                    seen_commit.remove(&record.txid);
214	                }
215	            }
216	        }
217	        for (txid, statements) in tx_buffer {
218	            if txid <= committed.last_committed_txid {
219	                continue;
220	            }
221	            if !seen_commit.get(&txid).copied().unwrap_or(false) {
222	                continue;
223	            }
224	            for sql in statements {
225	                // Recovery replays committed statement text through the normal engine.
226	                let stmt = crate::parser::parse(&sql)?;
227	                for statement in stmt {
228	                    crate::plan::apply_statement_without_wal(&mut committed, &statement)?;
229	                }
230	            }
231	            committed.last_committed_txid = txid;
232	        }

302	    pub fn commit(&mut self) -> Result<()> {
303	        let active = self
304	            .active
305	            .take()
306	            .ok_or_else(|| MiniDbError::Runtime("no transaction open".into()))?;
307	        for sql in &active.sql_log {
308	            self.wal.append(&WalRecord {
309	                txid: active.txid,
310	                kind: WalKind::Statement { sql: sql.clone() },
311	            })?;
312	        }
313	        self.wal.append(&WalRecord {
314	            txid: active.txid,
315	            kind: WalKind::Commit,
316	        })?;
317	        self.committed = active.state;
318	        self.persist_committed(active.txid)?;
319	        Ok(())
320	    }
321	
322	    pub fn rollback(&mut self) -> Result<()> {
323	        let active = self
324	            .active
325	            .take()
326	            .ok_or_else(|| MiniDbError::Runtime("no transaction open".into()))?;
327	        self.wal.append(&WalRecord {
328	            txid: active.txid,
329	            kind: WalKind::Rollback,
330	        })?;
331	        Ok(())
332	    }
