334	    fn persist_committed(&mut self, txid: u64) -> Result<()> {
335	        self.committed.last_committed_txid = txid;
336	        let payload = bincode::serialize(&self.committed)
337	            .map_err(|err| MiniDbError::Storage(err.to_string()))?;
338	        self.page_manager.store_snapshot(txid, &payload)?;
339	        Ok(())

