 21	pub fn apply_statement_without_wal(
 22	    state: &mut DatabaseState,
 23	    statement: &Statement,
 24	) -> Result<StatementOutcome> {
 25	    match statement {
 26	        Statement::CreateTable {
 27	            name,
 28	            columns,
 29	            table_constraints,
 30	        } => {
 31	            let schema = TableSchema {
 32	                name: name.clone(),
 33	                columns: columns
 34	                    .iter()
 35	                    .map(|col| Column {
 36	                        name: col.name.clone(),
 37	                        col_type: col.col_type,
 38	                        constraints: col.constraints.clone(),
 39	                    })
 40	                    .collect(),
 41	                table_constraints: table_constraints.clone(),
 42	            };
 43	            state.create_table(schema)?;
 44	            Ok(StatementOutcome::Affected(0))
 45	        }
 46	        Statement::DropTable { name } => {
 47	            state.drop_table(name)?;
 48	            Ok(StatementOutcome::Affected(0))
 49	        }
 50	        Statement::CreateIndex {
 51	            name,
 52	            table,
 53	            column,
 54	        } => {
 55	            state.create_index(IndexSchema {
 56	                name: name.clone(),
 57	                table: table.clone(),
 58	                column: column.clone(),
 59	            })?;
 60	            Ok(StatementOutcome::Affected(0))
 61	        }
 62	        Statement::DropIndex { name } => {
 63	            state.drop_index(name)?;
 64	            Ok(StatementOutcome::Affected(0))
 65	        }
 66	        Statement::Insert {
 67	            table,
 68	            columns,
 69	            values,
 70	        } => {
 71	            let affected = insert_rows(state, table, columns.as_ref(), values)?;
 72	            Ok(StatementOutcome::Affected(affected))
 73	        }
 74	        Statement::Select(select) => {
 75	            let result = execute_select(state, select)?;
 76	            Ok(StatementOutcome::Query(result))
 77	        }
 78	        Statement::Update {
 79	            table,
 80	            assignments,
 81	            selection,
 82	        } => {
 83	            let affected = execute_update(state, table, assignments, selection.as_ref())?;
 84	            Ok(StatementOutcome::Affected(affected))
 85	        }
 86	        Statement::Delete { table, selection } => {
 87	            let affected = execute_delete(state, table, selection.as_ref())?;
 88	            Ok(StatementOutcome::Affected(affected))
 89	        }
 90	        Statement::Meta(meta) => match meta {
 91	            MetaCommand::Schema { table } => Ok(StatementOutcome::Message(
 92	                state.catalog.schema_text(table.as_deref()),
 93	            )),
 94	            MetaCommand::Tables => Ok(StatementOutcome::Message(format!(
 95	                "{}\n",
 96	                state.catalog.list_tables().join("\n")
 97	            ))),
 98	            MetaCommand::Indexes => Ok(StatementOutcome::Message(format!(
 99	                "{}\n",
100	                state.catalog.list_indexes().join("\n")
101	            ))),
102	            MetaCommand::Format { .. } => Ok(StatementOutcome::None),
103	            MetaCommand::Exit => Ok(StatementOutcome::None),
104	        },
105	        Statement::Begin | Statement::Commit | Statement::Rollback => Ok(StatementOutcome::None),
106	    }
107	}

