115	fn plan_select(state: &DatabaseState, select: &SelectStmt) -> Result<PlanNode> {
116	    let _from_table = state.table(&select.from.name)?;
117	    let scan = if let Some((column, predicate)) =
118	        choose_index_predicate(state, &select.from, select.selection.as_ref())?
119	    {
120	        PlanNode::IndexScan(IndexScan::new(select.from.clone(), column, predicate))
121	    } else {
122	        PlanNode::SeqScan(SeqScan::new(select.from.clone()))
123	    };
124	
125	    let mut root = scan;
126	    if let Some(pred) = &select.selection {
127	        root = PlanNode::Filter(Filter {
128	            child: Box::new(root),
129	            predicate: pred.clone(),
130	            schema: Vec::new(),
131	            rows: Vec::new(),
132	            pos: 0,
133	        });
134	    }
135	
136	    for join in &select.joins {
137	        root = PlanNode::NestedLoopJoin(NestedLoopJoin {
138	            left: Box::new(root),
139	            right: Box::new(PlanNode::SeqScan(SeqScan::new(join.table.clone()))),
140	            on: join.on.clone(),
141	            schema: Vec::new(),
142	            rows: Vec::new(),
143	            pos: 0,
144	        });
145	    }
146	
147	    root = PlanNode::Project(Project {
148	        child: Box::new(root),
149	        items: select.projection.clone(),
150	        schema: Vec::new(),
151	        rows: Vec::new(),
152	        pos: 0,
153	    });
154	
155	    if let Some(order_by) = &select.order_by {
156	        root = PlanNode::Sort(Sort {
157	            child: Box::new(root),
158	            order_by: order_by.clone(),
159	            schema: Vec::new(),
160	            rows: Vec::new(),
161	            pos: 0,
162	        });
163	    }
164	
165	    if let Some(limit) = &select.limit {
166	        root = PlanNode::Limit(OpLimit {
167	            child: Box::new(root),
168	            limit: limit.limit,
169	            offset: limit.offset,
170	            schema: Vec::new(),
171	            rows: Vec::new(),
172	            pos: 0,
173	        });
174	    }
175	
176	    Ok(root)

