314	    fn parse_select(&mut self) -> Result<Statement> {
315	        self.expect_kw("SELECT")?;
316	        let projection = self.parse_select_list()?;
317	        self.expect_kw("FROM")?;
318	        let from = self.parse_table_ref()?;
319	        let mut joins = Vec::new();
320	        while matches!(self.current().kind, TokenKind::Keyword(ref k) if k == "INNER") {
321	            self.advance();
322	            self.expect_kw("JOIN")?;
323	            let table = self.parse_table_ref()?;
324	            self.expect_kw("ON")?;
325	            let on = self.parse_expr()?;
326	            joins.push(Join { table, on });
327	        }
328	        let selection = if matches!(self.current().kind, TokenKind::Keyword(ref k) if k == "WHERE")
329	        {
330	            self.advance();
331	            Some(self.parse_expr()?)
332	        } else {
333	            None
334	        };
335	        let order_by = if matches!(self.current().kind, TokenKind::Keyword(ref k) if k == "ORDER") {
336	            self.advance();
337	            self.expect_kw("BY")?;
338	            Some(self.parse_order_by_list()?)
339	        } else {
340	            None
341	        };
342	        let limit = if matches!(self.current().kind, TokenKind::Keyword(ref k) if k == "LIMIT") {
343	            self.advance();
344	            let value = self.parse_usize_literal()?;
345	            let offset = if matches!(self.current().kind, TokenKind::Keyword(ref k) if k == "OFFSET")
346	            {
347	                self.advance();
348	                Some(self.parse_usize_literal()?)
349	            } else {
350	                None
351	            };
352	            Some(Limit {
353	                limit: value,
354	                offset: offset.unwrap_or(0),
355	            })
356	        } else {
357	            None
358	        };
359	        Ok(Statement::Select(SelectStmt {
360	            projection,
361	            from,
362	            joins,
363	            selection,
364	            order_by,
365	            limit,
366	        }))
367	    }

