179	fn choose_index_predicate(
180	    state: &DatabaseState,
181	    table: &TableRef,
182	    selection: Option<&Expr>,
183	) -> Result<Option<(String, IndexPredicate)>> {
184	    let selection = match selection {
185	        Some(selection) => selection,
186	        None => return Ok(None),
187	    };
188	    let conjuncts = flatten_and(selection);
189	    for expr in conjuncts {
190	        if let Some((column, predicate)) = extract_index_predicate(state, table, expr)? {
191	            return Ok(Some((column, predicate)));
192	        }
193	    }
194	    Ok(None)
195	}
196	
197	fn extract_index_predicate(
198	    state: &DatabaseState,
199	    table: &TableRef,
200	    expr: &Expr,
201	) -> Result<Option<(String, IndexPredicate)>> {
202	    match expr {
203	        Expr::Binary { left, op, right } => {
204	            if let Some(column) = extract_column_name(table, left) {
205	                if let Some(index) = state.catalog.index_on_column(&table.name, &column) {
206	                    let value = match evaluate(right, None) {
207	                        Ok(value) => value,
208	                        Err(_) => return Ok(None),
209	                    };
210	                    let predicate = match op {
211	                        BinaryOp::Eq => Some(IndexPredicate::Eq(value)),
212	                        BinaryOp::Lt => Some(IndexPredicate::Lt(value)),
213	                        BinaryOp::Lte => Some(IndexPredicate::Lte(value)),
214	                        BinaryOp::Gt => Some(IndexPredicate::Gt(value)),
215	                        BinaryOp::Gte => Some(IndexPredicate::Gte(value)),
216	                        _ => None,
217	                    };
218	                    if let Some(predicate) = predicate {
219	                        return Ok(Some((index.column.clone(), predicate)));
220	                    }
221	                }
222	            }
223	            if let Some(column) = extract_column_name(table, right) {
224	                if let Some(index) = state.catalog.index_on_column(&table.name, &column) {
225	                    let value = match evaluate(left, None) {
226	                        Ok(value) => value,
227	                        Err(_) => return Ok(None),
228	                    };
229	                    let predicate = match op {
230	                        BinaryOp::Eq => Some(IndexPredicate::Eq(value)),
231	                        BinaryOp::Lt => Some(IndexPredicate::Gt(value)),
232	                        BinaryOp::Lte => Some(IndexPredicate::Gte(value)),
233	                        BinaryOp::Gt => Some(IndexPredicate::Lt(value)),
234	                        BinaryOp::Gte => Some(IndexPredicate::Lte(value)),
235	                        _ => None,
236	                    };
237	                    if let Some(predicate) = predicate {
238	                        return Ok(Some((index.column.clone(), predicate)));
239	                    }
240	                }
241	            }
242	            Ok(None)
243	        }
244	        _ => Ok(None),
245	    }

