 44	    pub fn load_snapshot(&self) -> Result<Option<(u64, Vec<u8>)>> {
 45	        if !self.path.exists() {
 46	            return Ok(None);
 47	        }
 48	        let mut file = self.open_rw()?;
 49	        let mut header_bytes = vec![0u8; PAGE_SIZE];
 50	        if file.read_exact(&mut header_bytes).is_err() {
 51	            return Ok(None);
 52	        }
 53	        let header_len =
 54	            u32::from_le_bytes(header_bytes[0..4].try_into().unwrap_or([0; 4])) as usize;
 55	        if header_len == 0 || header_len > PAGE_SIZE - 4 {
 56	            return Ok(None);
 57	        }
 58	        let header: SnapshotHeader = match bincode::deserialize(&header_bytes[4..4 + header_len]) {
 59	            Ok(header) => header,
 60	            Err(_) => return Ok(None),
 61	        };
 62	        if &header.magic != b"MINIDB\0\0" {
 63	            return Ok(None);
 64	        }
 65	        let payload_len = header.payload_len as usize;
 66	        let mut payload = vec![0u8; payload_len];
 67	        let mut read = 0usize;
 68	        while read < payload_len {
 69	            let page_index = 1 + read / PAGE_SIZE;
 70	            let mut page = vec![0u8; PAGE_SIZE];
 71	            file.seek(SeekFrom::Start((page_index * PAGE_SIZE) as u64))?;
 72	            let n = file.read(&mut page)?;
 73	            if n == 0 {
 74	                break;
 75	            }
 76	            let to_copy = (payload_len - read).min(PAGE_SIZE).min(n);
 77	            payload[read..read + to_copy].copy_from_slice(&page[..to_copy]);
 78	            read += to_copy;
 79	        }
 80	        payload.truncate(payload_len);
 81	        Ok(Some((header.snapshot_lsn, payload)))
 82	    }
