 84	    pub fn store_snapshot(&self, snapshot_lsn: u64, payload: &[u8]) -> Result<()> {
 85	        let header = SnapshotHeader {
 86	            magic: *b"MINIDB\0\0",
 87	            version: 1,
 88	            snapshot_lsn,
 89	            payload_len: payload.len() as u64,
 90	        };
 91	        let serialized_header =
 92	            bincode::serialize(&header).map_err(|err| MiniDbError::Storage(err.to_string()))?;
 93	        let mut header_bytes = vec![0u8; PAGE_SIZE];
 94	        let len = serialized_header.len().min(PAGE_SIZE - 4);
 95	        header_bytes[0..4].copy_from_slice(&(len as u32).to_le_bytes());
 96	        header_bytes[4..4 + len].copy_from_slice(&serialized_header[..len]);
 97	        let mut file = self.open_rw()?;
 98	        file.set_len(0)?;
 99	        file.seek(SeekFrom::Start(0))?;
100	        file.write_all(&header_bytes)?;
101	        let mut offset = 0usize;
102	        while offset < payload.len() {
103	            let mut page = vec![0u8; PAGE_SIZE];
104	            let chunk = (payload.len() - offset).min(PAGE_SIZE);
105	            page[..chunk].copy_from_slice(&payload[offset..offset + chunk]);
106	            file.write_all(&page)?;
107	            offset += chunk;
108	        }
109	        file.flush()?;
110	        Ok(())

