140	fn run_script(session: &mut Session, script: &str, continue_on_error: bool) -> Result<()> {
141	    let (mut statements, remainder) = split_complete_statements(script);
142	    if !remainder.trim().is_empty() {
143	        statements.push(remainder);
144	    }
145	    let mut saw_error = false;
146	    for stmt in statements {
147	        if stmt.trim().is_empty() {
148	            continue;
149	        }
150	        if stmt.trim_start().starts_with('.') {
151	            if handle_meta(session, stmt.trim())? {
152	                return Ok(());
153	            }
154	            continue;
155	        }
156	        if let Err(err) = execute_sql_chunk(session, &stmt) {
157	            saw_error = true;
158	            eprintln!("{err}");
159	            if !continue_on_error {
160	                return Err(err);
161	            }
162	        }
163	    }
164	    if saw_error && !continue_on_error {
165	        Err(MiniDbError::runtime("script failed"))
166	    } else {
167	        Ok(())
168	    }

