 93	        match statement {
 94	            Statement::Begin => {
 95	                self.begin()?;
 96	                Ok(ExecutionResult::Message("transaction started".into()))
 97	            }
 98	            Statement::Commit => self.commit(),
 99	            Statement::Rollback => self.rollback(),
100	            statement => {
101	                if self.active.is_some() {
102	                    self.execute_in_active(statement)
103	                } else {
104	                    self.execute_autocommit(statement)
105	                }
106	            }
