124	    fn execute_autocommit(&mut self, statement: Statement) -> Result<ExecutionResult> {
125	        let txid = self.allocate_txid();
126	        let mut state = self.storage.state.clone();
127	        let result = apply_statement_direct(&mut state, &statement)?;
128	        self.storage
129	            .wal_mut()
130	            .append_record(&WalRecord::Begin { txid })?;
131	        if statement_mutates(&statement) {
132	            self.storage
133	                .wal_mut()
134	                .append_record(&WalRecord::Statement {
135	                    txid,
136	                    statement: statement.clone(),
137	                })?;
138	        }
139	        self.storage
140	            .wal_mut()
141	            .append_record(&WalRecord::Commit { txid })?;
142	        self.storage.state = state;
143	        self.storage.state.applied_txid = txid;
144	        self.storage.save()?;
145	        Ok(result)

