 60	            let mut crc_bytes = [0u8; 4];
 61	            if file.read_exact(&mut crc_bytes).is_err() {
 62	                break;
 63	            }
 64	            let len = u32::from_le_bytes(len_bytes) as usize;
 65	            let expected_crc = u32::from_le_bytes(crc_bytes);
 66	            let mut payload = vec![0u8; len];
 67	            if file.read_exact(&mut payload).is_err() {
 68	                break;
 69	            }
 70	            let mut hasher = Hasher::new();
 71	            hasher.update(&payload);
 72	            if hasher.finalize() != expected_crc {
 73	                break;
 74	            }
 75	            let record: WalRecord = match bincode::deserialize(&payload) {
 76	                Ok(record) => record,
 77	                Err(_) => break,
 78	            };
 79	            match record {
 80	                WalRecord::Begin { txid } => {
 81	                    active.entry(txid).or_default();
 82	                }
 83	                WalRecord::Statement { txid, statement } => {
 84	                    active.entry(txid).or_default().push(statement);
 85	                }
 86	                WalRecord::Commit { txid } => {
 87	                    committed.insert(txid, true);
 88	                }
 89	                WalRecord::Rollback { txid } => {
 90	                    active.remove(&txid);
 91	                    committed.remove(&txid);
 92	                }
 93	            }
 94	        }
 95	        let mut txids: Vec<u64> = active.keys().copied().collect();
 96	        txids.sort_unstable();
 97	        for txid in txids {
 98	            if txid <= state.applied_txid {
 99	                continue;
100	            }
101	            if committed.get(&txid).copied().unwrap_or(false) {
102	                if let Some(statements) = active.get(&txid) {
103	                    for statement in statements {
104	                        crate::exec::apply_statement_direct(state, statement)?;
105	                    }
106	                    state.applied_txid = txid;
107	                }
108	            }
109	        }
110	        Ok(())

