311	impl PhysicalOperator for NestedLoopJoin {
312	    fn open(&mut self, ctx: &mut ExecContext<'_>) -> Result<()> {
313	        self.left.open(ctx)?;
314	        self.right.open(ctx)?;
315	        let mut left_rows = Vec::new();
316	        while let Some(tuple) = self.left.next(ctx)? {
317	            left_rows.push(tuple);
318	        }
319	        let mut right_rows = Vec::new();
320	        while let Some(tuple) = self.right.next(ctx)? {
321	            right_rows.push(tuple);
322	        }
323	        let mut pairs = Vec::new();
324	        for left in &left_rows {
325	            for right in &right_rows {
326	                let tuple = join_tuples(left, right);
327	                if eval_truthy(&self.on, &tuple)? {
328	                    pairs.push(tuple);
329	                }
330	            }
331	        }
332	        self.pairs = pairs;
333	        self.cursor = 0;
334	        Ok(())
335	    }
336	
337	    fn next(&mut self, _ctx: &mut ExecContext<'_>) -> Result<Option<Tuple>> {
338	        if self.cursor >= self.pairs.len() {
339	            return Ok(None);
340	        }
341	        let tuple = self.pairs[self.cursor].clone();
342	        self.cursor += 1;
343	        Ok(Some(tuple))
344	    }
