236	    fn parse_select(&mut self) -> Result<Select> {
237	        self.expect_keyword(Keyword::Select)?;
238	        let mut projection = Vec::new();
239	        loop {
240	            projection.push(self.parse_select_item()?);
241	            if self.match_kind(&TokenKind::Comma) {
242	                self.advance()?;
243	            } else {
244	                break;
245	            }
246	        }
247	        self.expect_keyword(Keyword::From)?;
248	        let left = self.parse_table_ref()?;
249	        let join = if self.match_keyword(Keyword::Join) || self.match_keyword(Keyword::Inner) {
250	            if self.match_keyword(Keyword::Inner) {
251	                self.advance()?;
252	                self.expect_keyword(Keyword::Join)?;
253	            } else {
254	                self.advance()?;
255	            }
256	            let right = self.parse_table_ref()?;
257	            self.expect_keyword(Keyword::On)?;
258	            let on = self.parse_expr()?;
259	            Some(JoinClause { right, on })
260	        } else {
261	            None
262	        };
263	        let selection = if self.consume_if_keyword(Keyword::Where)? {
264	            Some(self.parse_expr()?)
265	        } else {
266	            None
267	        };
268	        let mut order_by = Vec::new();
269	        if self.consume_if_keyword(Keyword::Order)? {
270	            self.expect_keyword(Keyword::By)?;
271	            loop {
272	                let expr = self.parse_expr()?;
273	                let asc = if self.consume_if_keyword(Keyword::Desc)? {
274	                    false
275	                } else {
276	                    let _ = self.consume_if_keyword(Keyword::Asc)?;
277	                    true
278	                };
279	                order_by.push(OrderByExpr { expr, asc });
280	                if self.match_kind(&TokenKind::Comma) {
281	                    self.advance()?;
282	                } else {
283	                    break;
284	                }
285	            }
286	        }
287	        let limit = if self.consume_if_keyword(Keyword::Limit)? {
288	            let limit = self.parse_usize_literal()?;
289	            let offset = if self.consume_if_keyword(Keyword::Offset)? {
290	                self.parse_usize_literal()?
291	            } else {
292	                0
293	            };
294	            Some(LimitClause { limit, offset })
295	        } else {
296	            None
297	        };
298	        Ok(Select {
299	            projection,
300	            from: FromClause { left, join },
301	            selection,
302	            order_by,
303	            limit,
304	        })
305	    }

1252	fn execute_select(state: &mut DatabaseState, select: &Select) -> Result<ResultSet> {
1253	    let plan = crate::plan::physical::build_select_plan(state, select)?;
1254	    let mut ctx = ExecContext { state };
1255	    let mut root = plan.root;
1256	    root.open(&mut ctx)?;
1257	    let schema = root.schema();
1258	    let columns = schema.columns.iter().map(|c| c.name.clone()).collect();
1259	    let mut rows = Vec::new();
1260	    while let Some(tuple) = root.next(&mut ctx)? {
1261	        rows.push(tuple.values);
1262	    }
1263	    root.close(&mut ctx)?;
1264	    Ok(ResultSet { columns, rows })

14	pub fn build_select_plan(state: &DatabaseState, select: &Select) -> Result<PhysicalPlan> {
15	    let left_schema = table_schema_for_ref(state, &select.from.left)?;
16	    let mut root: Box<dyn PhysicalOperator> = choose_scan(
17	        state,
18	        &select.from.left,
19	        select.selection.as_ref(),
20	        &left_schema,
21	    )?;
22	    if let Some(join) = &select.from.join {
23	        let right_schema = table_schema_for_ref(state, &join.right)?;
24	        let right = choose_scan(state, &join.right, None, &right_schema)?;
25	        root = Box::new(NestedLoopJoin::new(root, right, join.on.clone()));
26	    }
27	    if let Some(selection) = &select.selection {
28	        if select.from.join.is_some()
29	            || !predicate_used_for_index(state, &select.from.left, selection)
30	        {
31	            root = Box::new(Filter::new(root, selection.clone()));
32	        }
33	    }
34	    if !select.order_by.is_empty() {
35	        root = Box::new(Sort::new(root, select.order_by.clone()));
36	    }
37	    root = Box::new(Project::new(root, select.projection.clone()));
38	    if let Some(limit) = &select.limit {
39	        root = Box::new(Limit::new(root, limit.limit, limit.offset));
40	    }
41	    Ok(PhysicalPlan { root })

73	fn choose_scan(
74	    state: &DatabaseState,
75	    table_ref: &TableRef,
76	    predicate: Option<&Expr>,
77	    schema: &Schema,
78	) -> Result<Box<dyn PhysicalOperator>> {
79	    if let Some(predicate) = predicate {
80	        if let Some((index, index_predicate)) = find_index_predicate(state, table_ref, predicate)? {
81	            return Ok(Box::new(IndexScan::new(
82	                &table_ref.name,
83	                table_ref.alias.clone(),
84	                index,
85	                schema.clone(),
86	                index_predicate,
87	            )));
88	        }
89	    }
90	    Ok(Box::new(SeqScan::new(
91	        &table_ref.name,
92	        table_ref.alias.clone(),
93	        schema.clone(),
94	    )))
95	}

