335	    pub fn execute(&mut self, stmt: Statement) -> Result<ExecResult, MiniDbError> {
336	        match stmt {
337	            Statement::CreateTable { name, elements } => {
338	                let mut cols = Vec::new();
339	                let mut checks = Vec::new();
340	                for el in elements {
341	                    match el {
342	                        TableElement::Column(c) => cols.push(Column {
343	                            table: Some(name.clone()),
344	                            name: c.name,
345	                            col_type: c.col_type,
346	                            primary_key: c.primary_key,
347	                            not_null: c.not_null,
348	                            unique: c.unique,
349	                            default: c.default,
350	                        }),
351	                        TableElement::Check(e) => checks.push(e),
352	                    }
353	                }
354	                self.storage.snapshot_mut().catalog.tables.insert(
355	                    name.clone(),
356	                    TableMetadata {
357	                        name,
358	                        columns: cols,
359	                        checks,
360	                    },
361	                );
362	                self.persist()?;
363	                Ok(ExecResult::Message("table created".into(), 0))
364	            }
365	            Statement::DropTable { name } => {
366	                self.storage.snapshot_mut().catalog.tables.remove(&name);
367	                self.storage.snapshot_mut().rows.remove(&name);
368	                self.persist()?;
369	                Ok(ExecResult::Message("table dropped".into(), 0))
370	            }
371	            Statement::CreateIndex {
372	                name,
373	                table,
374	                column,
