474	    fn select(
475	        &mut self,
476	        items: Vec<SelectItem>,
477	        from: String,
478	        join: Option<Join>,
479	        filter: Option<Expr>,
480	        order_by: Option<OrderBy>,
481	        limit: Option<(usize, usize)>,
482	    ) -> Result<ExecResult, MiniDbError> {
483	        let meta = self
484	            .storage
485	            .snapshot()
486	            .catalog
487	            .tables
488	            .get(&from)
489	            .cloned()
490	            .ok_or_else(|| MiniDbError::sql("unknown table"))?;
491	        let mut rows = self
492	            .storage
493	            .snapshot()
494	            .rows
495	            .get(&from)
496	            .cloned()
497	            .unwrap_or_default();
498	        let schema = meta.columns;
499	        if let Some(join) = join {
500	            let right_meta = self
501	                .storage
502	                .snapshot()
503	                .catalog
504	                .tables
505	                .get(&join.right)
506	                .cloned()
507	                .ok_or_else(|| MiniDbError::sql("unknown table"))?;
508	            let right_rows = self
509	                .storage
510	                .snapshot()
511	                .rows
512	                .get(&join.right)
513	                .cloned()
514	                .unwrap_or_default();
515	            let mut joined = Vec::new();
516	            for l in rows {
517	                for r in &right_rows {
518	                    let mut v = l.0.clone();
519	                    v.extend(r.0.clone());
520	                    let row = Row(v);
521	                    if eval_truth(&join.on, Some(&row), &schema, Some(&right_meta.columns))?
522	                        == TruthValue::True
523	                    {
524	                        joined.push(row);
525	                    }
526	                }
527	            }
528	            rows = joined;
529	        }
530	        if let Some(expr) = filter {
531	            rows = rows
532	                .into_iter()
533	                .filter(|r| {
534	                    eval_truth(&expr, Some(r), &schema, None).unwrap_or(TruthValue::False)
535	                        == TruthValue::True
536	                })
537	                .collect();
538	        }
539	        if let Some(ord) = order_by {
540	            rows.sort_by(|a, b| {
541	                compare_values(
542	                    &eval_expr(&ord.expr, Some(a), &schema).unwrap_or(Value::Null),
543	                    &eval_expr(&ord.expr, Some(b), &schema).unwrap_or(Value::Null),
544	                )
545	                .unwrap_or(Ordering::Equal)
546	            });
547	            if ord.desc {
548	                rows.reverse();
549	            }
550	        }
551	        if let Some((lim, off)) = limit {
552	            rows = rows.into_iter().skip(off).take(lim).collect();
553	        }
554	        let out_rows: Vec<Vec<Value>> = rows
555	            .iter()
556	            .map(|r| {
557	                if items.len() == 1 && matches!(items[0], SelectItem::Star) {
558	                    r.0.clone()
559	                } else {
560	                    items
561	                        .iter()
562	                        .map(|it| match it {
563	                            SelectItem::Star => Value::Null,
564	                            SelectItem::Expr(e) => {
565	                                eval_expr(e, Some(r), &schema).unwrap_or(Value::Null)
566	                            }
567	                        })
568	                        .collect()
569	                }
570	            })
571	            .collect();
572	        Ok(ExecResult::Rows {
573	            columns: if items.len() == 1 && matches!(items[0], SelectItem::Star) {
574	                schema.into_iter().map(|c| c.name).collect()
575	            } else {
576	                items
577	                    .iter()
578	                    .enumerate()
579	                    .map(|(i, _)| format!("c{}", i + 1))
580	                    .collect()
581	            },
582	            rows: out_rows,
583	        })

