458	                    row[i] = d.clone();
459	                }
460	            }
461	            if col.not_null && row[i].is_null() {
462	                return Err(MiniDbError::sql(format!("{} cannot be null", col.name)));
463	            }
464	        }
465	        self.storage
466	            .snapshot_mut()
467	            .rows
468	            .entry(table.to_string())
469	            .or_default()
470	            .push(Row(row));
