198	    pub fn new(mut left: L, mut right: R) -> Result<Self, MiniDbError> {
199	        let mut rows = Vec::new();
200	        left.open()?;
201	        right.open()?;
202	        let mut lrows = Vec::new();
203	        while let Some(r) = left.next()? {
204	            lrows.push(r);
205	        }
206	        let mut rrows = Vec::new();
207	        while let Some(r) = right.next()? {
208	            rrows.push(r);
209	        }
210	        for l in &lrows {
211	            for r in &rrows {
212	                let mut v = l.0.clone();
213	                v.extend(r.0.clone());
214	                rows.push(Row(v));
215	            }
216	        }
217	        let mut schema = left.schema().to_vec();
218	        schema.extend_from_slice(right.schema());
219	        let _ = (left, right);
220	        Ok(Self {
221	            rows,
222	            idx: 0,
223	            schema,
224	            _marker: std::marker::PhantomData,
225	        })
226	    }
227	}
