249	    fn parse_select(&mut self) -> Result<Statement, MiniDbError> {
250	        self.expect_keyword("SELECT")?;
251	        let mut items = Vec::new();
252	        if self.eat(TokenKind::Star) {
253	            items.push(SelectItem::Star);
254	        } else {
255	            loop {
256	                items.push(SelectItem::Expr(self.parse_expr()?));
257	                if self.eat(TokenKind::Comma) {
258	                    continue;
259	                }
260	                break;
261	            }
262	        }
263	        self.expect_keyword("FROM")?;
264	        let from = self.expect_ident()?;
265	        let join = if self.eat_keyword("INNER") {
266	            self.expect_keyword("JOIN")?;
267	            let right = self.expect_ident()?;
268	            self.expect_keyword("ON")?;
269	            let on = self.parse_expr()?;
270	            Some(Join { right, on })
271	        } else {
272	            None
273	        };
274	        let filter = if self.eat_keyword("WHERE") {
275	            Some(self.parse_expr()?)
276	        } else {
277	            None
278	        };
279	        let order_by = if self.eat_keyword("ORDER") {
280	            self.expect_keyword("BY")?;
281	            let expr = self.parse_expr()?;
282	            let desc = self.eat_keyword("DESC");
283	            if !desc {
284	                self.eat_keyword("ASC");
285	            }
286	            Some(OrderBy { expr, desc })
287	        } else {
288	            None
289	        };
290	        let limit = if self.eat_keyword("LIMIT") {
291	            let n = self.parse_int_literal()?;
292	            let offset = if self.eat_keyword("OFFSET") {
293	                Some(self.parse_int_literal()?)
294	            } else {
295	                None
296	            };
297	            Some((n, offset.unwrap_or(0)))
298	        } else {
299	            None
300	        };
301	        Ok(Statement::Select {
302	            items,
303	            from,
304	            join,
305	            filter,
306	            order_by,
307	            limit,
308	        })

