45	    fn err(&self, msg: impl Into<String>) -> MiniDbError {
46	        let t = &self.tokens[self.idx.min(self.tokens.len() - 1)];
47	        MiniDbError::Parse {
48	            line: t.line,
49	            column: t.column,
50	            message: msg.into(),
