54	    pub fn parse_script(&mut self) -> Result<Vec<Statement>, MiniDbError> {
55	        let mut out = Vec::new();
56	        while !matches!(self.peek(), TokenKind::EOF) {
57	            out.push(self.parse_statement()?);
58	            if matches!(self.peek(), TokenKind::Semi) {
59	                self.idx += 1;
60	            } else if !matches!(self.peek(), TokenKind::EOF) {
61	                return Err(self.err("expected ';'"));
62	            }
63	        }
64	        Ok(out)

