 86	fn repl_loop(executor: &mut Executor, fmt: OutputFormat, quiet: bool) -> Result<i32, MiniDbError> {
 87	    let mut input = String::new();
 88	    loop {
 89	        input.clear();
 90	        print!("minidb> ");
 91	        io::stdout().flush().ok();
 92	        if io::stdin().read_line(&mut input)? == 0 {
 93	            return Ok(0);
 94	        }
 95	        if input.trim() == ".exit" {
 96	            return Ok(0);
 97	        }
 98	        if input.trim() == ".tables" {
 99	            println!(
100	                "{}",
101	                executor
102	                    .storage
103	                    .snapshot()
104	                    .catalog
105	                    .tables
106	                    .keys()
107	                    .cloned()
108	                    .collect::<Vec<_>>()
109	                    .join(" ")
110	            );
111	            continue;
112	        }
113	        if input.trim() == ".schema" {
114	            println!("{:#?}", executor.storage.snapshot().catalog);
115	            continue;
116	        }
117	        if input.trim() == ".indexes" {
118	            println!(
119	                "{}",
120	                executor
121	                    .storage
122	                    .snapshot()
123	                    .catalog
124	                    .indexes
125	                    .keys()
126	                    .cloned()
127	                    .collect::<Vec<_>>()
128	                    .join(" ")
129	            );
130	            continue;
131	        }
132	        if input.trim().starts_with(".format ") {
133	            continue;
134	        }
135	        if input.trim().is_empty() {
136	            continue;
137	        }
138	        match run_sql(executor, &input, fmt.clone(), quiet) {
139	            Ok(_) => {}
140	            Err(e) => eprintln!("{e}"),
141	        }
142	    }
143	}

145	fn emit(res: ExecResult, fmt: OutputFormat) -> Result<String, MiniDbError> {
146	    let summary = match &res {
147	        ExecResult::Rows { rows, .. } => format!("ok {} rows", rows.len()),
148	        ExecResult::Message(_, n) if *n == 1 => "ok 1 row affected".to_string(),
149	        ExecResult::Message(_, n) => format!("ok {n} rows affected"),
150	    };
151	    match res {
152	        ExecResult::Rows { columns, rows } => match fmt {
153	            OutputFormat::Table => {
154	                println!("{}", columns.join(" | "));
155	                for row in rows {
156	                    println!(
157	                        "{}",
158	                        row.into_iter()
159	                            .map(|v| v.to_string())
160	                            .collect::<Vec<_>>()
161	                            .join(" | ")
162	                    );
163	                }
164	            }
165	            OutputFormat::Csv => {
166	                let mut w = csv::Writer::from_writer(io::stdout());
167	                w.write_record(columns)
168	                    .map_err(|e| MiniDbError::cli(e.to_string()))?;
169	                for row in rows {
170	                    w.write_record(row.into_iter().map(|v| v.to_string()))
171	                        .map_err(|e| MiniDbError::cli(e.to_string()))?;
172	                }
173	                w.flush().map_err(|e| MiniDbError::cli(e.to_string()))?;
174	            }
175	            OutputFormat::Json => {
176	                let objs: Vec<serde_json::Value> = rows
177	                    .into_iter()
178	                    .map(|r| {
179	                        let map: serde_json::Map<String, serde_json::Value> = columns
180	                            .iter()
181	                            .cloned()
182	                            .zip(
183	                                r.into_iter()
184	                                    .map(|v| serde_json::Value::String(v.to_string())),
185	                            )
186	                            .collect();
187	                        serde_json::Value::Object(map)
188	                    })
189	                    .collect();
190	                println!(
191	                    "{}",
192	                    serde_json::to_string(&objs).unwrap_or_else(|_| "[]".into())
193	                );
194	            }
195	        },
196	        ExecResult::Message(msg, _) => println!("{msg}"),
197	    }
198	    Ok(summary)

