136	    fn with_auto_tx<F>(&mut self, f: F) -> Result<QueryResult>
137	    where
138	        F: FnOnce(&mut Database) -> Result<QueryResult>,
139	    {
140	        let auto = !self.db.in_transaction();
141	        if auto {
142	            self.db.begin()?;
143	        }
144	        let before = self.db.state.clone();
145	        let result = f(&mut self.db);
146	        match result {
147	            Ok(value) => {
148	                if auto {
149	                    self.db.commit()?;
150	                }
151	                Ok(value)
152	            }
153	            Err(err) => {
154	                self.db.state = before;
155	                if auto && self.db.in_transaction() {
156	                    let _ = self.db.rollback();
157	                }
158	                Err(err)
159	            }
160	        }
161	    }

