 54	impl Wal {
 55	    pub fn append(path: &Path, record: &WalRecord) -> Result<()> {
 56	        if let Some(parent) = path.parent() {
 57	            fs::create_dir_all(parent)?;
 58	        }
 59	        let mut file = OpenOptions::new().create(true).append(true).open(path)?;
 60	        let payload = serde_json::to_vec(record)?;
 61	        let len = payload.len() as u32;
 62	        let crc = crc32(&payload);
 63	        file.write_all(&len.to_le_bytes())?;
 64	        file.write_all(&payload)?;
 65	        file.write_all(&crc.to_le_bytes())?;
 66	        Ok(())
 67	    }
 68	
 69	    pub fn read_all(path: &Path) -> Result<Vec<WalRecord>> {
 70	        let mut file = match File::open(path) {
 71	            Ok(file) => file,
 72	            Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
 73	            Err(err) => return Err(err.into()),
 74	        };
 75	        let mut bytes = Vec::new();
 76	        file.read_to_end(&mut bytes)?;
 77	        let mut pos = 0usize;
 78	        let mut records = Vec::new();
 79	        while pos < bytes.len() {
 80	            if bytes.len() - pos < 8 {
 81	                break;
 82	            }
 83	            let len =
 84	                u32::from_le_bytes([bytes[pos], bytes[pos + 1], bytes[pos + 2], bytes[pos + 3]])
 85	                    as usize;
 86	            pos += 4;
 87	            if bytes.len() - pos < len + 4 {
 88	                break;
 89	            }
 90	            let payload = &bytes[pos..pos + len];
 91	            pos += len;
 92	            let expected =
 93	                u32::from_le_bytes([bytes[pos], bytes[pos + 1], bytes[pos + 2], bytes[pos + 3]]);
 94	            pos += 4;
 95	            let actual = crc32(payload);
 96	            if actual != expected {
 97	                return Err(MiniDbError::Storage("WAL checksum mismatch".into()));
 98	            }
 99	            records.push(serde_json::from_slice(payload)?);
100	        }
101	        Ok(records)
102	    }
103	
104	    pub fn sync(path: &Path) -> Result<()> {
105	        let file = OpenOptions::new().create(true).append(true).open(path)?;
106	        file.sync_all()?;
107	        Ok(())
108	    }
