110	    pub fn truncate(path: &Path) -> Result<()> {
111	        File::create(path)?;
112	        Ok(())
113	    }

64	    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
65	        let path = path.as_ref().to_path_buf();
66	        if !path.exists() {
67	            write_checkpoint(&path, &DatabaseState::default())?;
68	        }
69	        let wal_path = wal_path_for(&path);
70	        let mut state = read_checkpoint(&path)?;
71	        let mut max_tx = state.applied_tx;
72	        if wal_path.exists() {
73	            let records = Wal::read_all(&wal_path)?;
74	            let committed = committed_ops(&records);
75	            for (tx, ops) in committed {
76	                max_tx = max_tx.max(tx);
77	                if tx <= state.applied_tx {
78	                    continue;
79	                }
80	                for op in ops {
81	                    apply_op_to_state(&mut state, op)?;
82	                }
83	                state.applied_tx = tx;
84	            }
85	            state.rebuild_indexes()?;
86	            if state.applied_tx > 0 {
87	                write_checkpoint(&path, &state)?;
88	            }
89	        }

257	fn committed_ops(records: &[WalRecord]) -> BTreeMap<u64, Vec<&WalOp>> {
258	    let mut pending: BTreeMap<u64, Vec<&WalOp>> = BTreeMap::new();
259	    let mut committed = BTreeMap::new();
260	    for record in records {
261	        match record {
262	            WalRecord::Begin { tx } => {
263	                pending.entry(*tx).or_default();
264	            }
265	            WalRecord::Operation { tx, op } => {
266	                pending.entry(*tx).or_default().push(op);
267	            }
268	            WalRecord::Commit { tx } => {
269	                if let Some(ops) = pending.remove(tx) {
270	                    committed.insert(*tx, ops);
271	                }
272	            }
273	            WalRecord::Rollback { tx } => {
274	                pending.remove(tx);
275	            }
276	        }
277	    }
278	    committed
279	}

