164	fn execute_select_plan(state: &DatabaseState, plan: PhysicalPlan) -> Result<QueryResult> {
165	    let mut op = build_operator(state, plan)?;
166	    op.open()?;
167	    let columns = op.schema().into_iter().map(|c| c.name).collect::<Vec<_>>();
168	    let mut rows = Vec::new();
169	    while let Some(row) = op.next()? {
170	        rows.push(row.values);
171	    }
172	    op.close()?;
173	    Ok(QueryResult {
174	        columns,
175	        rows,
176	        affected: None,
177	    })
178	}
