180	fn build_operator(state: &DatabaseState, plan: PhysicalPlan) -> Result<Box<dyn PhysicalOperator>> {
181	    match plan {
182	        PhysicalPlan::SeqScan { table } => Ok(Box::new(SeqScan::new(state, table)?)),
183	        PhysicalPlan::IndexScan {
184	            table,
185	            index,
186	            column,
187	            op,
188	            value,
189	        } => Ok(Box::new(IndexScan::new(
190	            state, table, index, column, op, value,
191	        )?)),
192	        PhysicalPlan::Filter { input, predicate } => Ok(Box::new(Filter::new(
193	            build_operator(state, *input)?,
194	            predicate,
195	        ))),
196	        PhysicalPlan::Project { input, select } => Ok(Box::new(Project::new(
197	            build_operator(state, *input)?,
198	            select,
199	        ))),
200	        PhysicalPlan::NestedLoopJoin { left, right, on } => Ok(Box::new(NestedLoopJoin::new(
201	            build_operator(state, *left)?,
202	            build_operator(state, *right)?,
203	            on,
204	        ))),
205	        PhysicalPlan::Sort { input, select } => {
206	            Ok(Box::new(Sort::new(build_operator(state, *input)?, select)))
207	        }
208	        PhysicalPlan::Limit {
209	            input,
210	            limit,
211	            offset,
212	        } => Ok(Box::new(Limit::new(
213	            build_operator(state, *input)?,
214	            limit,
215	            offset,
216	        ))),
217	    }

