 54	    pub fn plan_select(state: &DatabaseState, select: &SelectStmt) -> PhysicalPlan {
 55	        let mut root = match &select.from {
 56	            From::Table { name } => scan_for_table(state, name, select.where_clause.as_ref()),
 57	            From::Join { left, right, on } => PhysicalPlan::NestedLoopJoin {
 58	                left: Box::new(scan_for_table(state, left, None)),
 59	                right: Box::new(scan_for_table(state, right, None)),
 60	                on: on.clone(),
 61	            },
 62	        };
 63	        if let Some(predicate) = &select.where_clause {
 64	            root = PhysicalPlan::Filter {
 65	                input: Box::new(root),
 66	                predicate: predicate.clone(),
 67	            };
 68	        }
 69	        if !select.order_by.is_empty() {
 70	            root = PhysicalPlan::Sort {
 71	                input: Box::new(root),
 72	                select: select.clone(),
 73	            };
 74	        }
 75	        if select.limit.is_some() || select.offset.is_some() {
 76	            root = PhysicalPlan::Limit {
 77	                input: Box::new(root),
 78	                limit: select.limit,
 79	                offset: select.offset,
 80	            };
 81	        }
 82	        PhysicalPlan::Project {
 83	            input: Box::new(root),
 84	            select: select.clone(),
 85	        }
 86	    }
 87	}
 88	
 89	fn scan_for_table(state: &DatabaseState, table: &str, predicate: Option<&Expr>) -> PhysicalPlan {
 90	    if let Some((column, op, value)) = predicate.and_then(single_indexable_predicate) {
 91	        if let Some(index) = state.catalog.index_on_column(table, &column) {
 92	            return PhysicalPlan::IndexScan {
 93	                table: table.to_string(),
 94	                index: index.name.clone(),
 95	                column,
 96	                op,
 97	                value,
 98	            };
 99	        }
100	    }
101	    PhysicalPlan::SeqScan {
102	        table: table.to_string(),
103	    }
104	}

107	    pub fn index_on_column(&self, table: &str, column: &str) -> Option<&IndexSchema> {
108	        let table_key = normalize(table);
109	        let col_key = normalize(column);
110	        self.indexes
111	            .values()
112	            .find(|idx| normalize(&idx.table) == table_key && normalize(&idx.column) == col_key)
113	    }

