42	    pub fn execute(&mut self, statement: Statement) -> Result<QueryOutput> {
43	        match statement {
44	            Statement::Begin => {
45	                self.begin()?;
46	                Ok(QueryOutput::ok())
47	            }
48	            Statement::Commit => {
49	                self.commit()?;
50	                Ok(QueryOutput::ok())
51	            }
52	            Statement::Rollback => {
53	                self.rollback()?;
54	                Ok(QueryOutput::ok())
55	            }
56	            Statement::Select(select) => {
57	                if let Some(active) = self.active.as_mut() {
58	                    execute_statement(&mut active.working, Statement::Select(select))
59	                } else {
60	                    execute_statement(&mut self.state, Statement::Select(select))
61	                }
62	            }
63	            other => {
64	                if self.active.is_some() {
65	                    self.execute_in_active(other)
66	                } else {
67	                    self.execute_auto(other)
68	                }
69	            }

126	    fn execute_auto(&mut self, statement: Statement) -> Result<QueryOutput> {
127	        let id = self.allocate_tx();
128	        let mut candidate = self.state.clone();
129	        let output = execute_statement(&mut candidate, statement.clone())?;
130	        append(self.store.wal_path(), &WalRecord::Begin { tx: id })?;
131	        append(
132	            self.store.wal_path(),
133	            &WalRecord::Statement { tx: id, statement },
134	        )?;
135	        append(self.store.wal_path(), &WalRecord::Commit { tx: id })?;
136	        self.state = candidate;
137	        Ok(output)

