40	pub fn recover(path: &Path) -> Result<DatabaseState> {
41	    let mut state = DatabaseState::default();
42	    if !path.exists() {
43	        return Ok(state);
44	    }
45	    let records = read_records(path)?;
46	    let mut pending: BTreeMap<u64, Vec<Statement>> = BTreeMap::new();
47	    for record in records {
48	        match record {
49	            WalRecord::Begin { tx } => {
50	                pending.entry(tx).or_default();
51	            }
52	            WalRecord::Statement { tx, statement } => {
53	                pending.entry(tx).or_default().push(statement);
54	            }
55	            WalRecord::Commit { tx } => {
56	                if let Some(statements) = pending.remove(&tx) {
57	                    for statement in statements {
58	                        crate::exec::apply_recovered_statement(&mut state, statement)?;
59	                    }
60	                }
61	            }
62	            WalRecord::Rollback { tx } => {
63	                pending.remove(&tx);
64	            }
65	        }
66	    }
67	    Ok(state)

