70	fn read_records(path: &Path) -> Result<Vec<WalRecord>> {
71	    let mut file = OpenOptions::new().read(true).open(path)?;
72	    let mut records = Vec::new();
73	    loop {
74	        let mut header = [0u8; 8];
75	        match file.read_exact(&mut header) {
76	            Ok(()) => {}
77	            Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
78	            Err(e) => return Err(e.into()),
79	        }
80	        let mut len_bytes = [0u8; 4];
81	        len_bytes.copy_from_slice(&header[0..4]);
82	        let mut crc_bytes = [0u8; 4];
83	        crc_bytes.copy_from_slice(&header[4..8]);
84	        let len = u32::from_le_bytes(len_bytes) as usize;
85	        let expected_crc = u32::from_le_bytes(crc_bytes);
86	        let mut payload = vec![0u8; len];
87	        if file.read_exact(&mut payload).is_err() {
88	            break;
89	        }
90	        let mut hasher = Hasher::new();
91	        hasher.update(&payload);
92	        if hasher.finalize() != expected_crc {
93	            break;
94	        }
95	        let record = serde_json::from_slice::<WalRecord>(&payload)
96	            .map_err(|e| MiniDbError::Storage(format!("decode WAL record: {e}")))?;
97	        records.push(record);
98	    }
99	    Ok(records)

