811	pub fn run_select(state: &mut DatabaseState, select: Select) -> Result<QueryOutput> {
812	    let mut root: Box<dyn PhysicalOperator> = match &select.from {
813	        TableRef::Table(table) => build_single_table_scan(state, table, select.selection.as_ref())?,
814	        TableRef::Join { left, right, on } => Box::new(NestedLoopJoin::new(
815	            Box::new(SeqScan::new(normalize(left))),
816	            Box::new(SeqScan::new(normalize(right))),
817	            on.clone(),
818	        )),
819	    };
820	    if let Some(predicate) = select.selection.clone() {
821	        root = Box::new(Filter::new(root, predicate));
822	    }
823	    if !select.order_by.is_empty() {
824	        root = Box::new(Sort::new(root, select.order_by));
825	    }
826	    if let Some(limit) = select.limit {
827	        root = Box::new(Limit::new(root, limit.limit, limit.offset));
828	    }
829	    root = Box::new(Project::new(root, select.projection));
830	    root.open(state)?;
831	    let columns = root.schema();
832	    let mut rows = Vec::new();
833	    while let Some(row) = root.next(state)? {
834	        rows.push(row.fields.into_iter().map(|f| f.value).collect());
835	    }
836	    root.close()?;
837	    Ok(QueryOutput {
838	        columns,
839	        rows,
840	        affected: None,
841	        mutation: false,
842	    })
843	}
