845	fn build_single_table_scan(
846	    state: &DatabaseState,
847	    table: &str,
848	    selection: Option<&Expr>,
849	) -> Result<Box<dyn PhysicalOperator>> {
850	    let table = normalize(table);
851	    ensure_table_exists(state, &table)?;
852	    if let Some((index, op, value)) =
853	        selection.and_then(|expr| usable_index_predicate(state, &table, expr))
854	    {
