611	pub fn apply_statement(state: &mut DatabaseState, statement: Statement) -> Result<usize> {
612	    match statement {
613	        Statement::CreateTable {
614	            name,
615	            columns,
616	            checks,
617	        } => {
618	            let name = normalize(&name);
619	            if state.catalog.tables.contains_key(&name) {
620	                return Err(MiniDbError::sql(format!("table {name} already exists")));
621	            }
622	            let cols: Vec<Column> = columns.into_iter().map(Into::into).collect();
623	            let mut seen = std::collections::BTreeSet::new();
624	            for col in &cols {
625	                if !seen.insert(normalize(&col.name)) {
626	                    return Err(MiniDbError::sql(format!("duplicate column {}", col.name)));
627	                }
628	            }
629	            state.catalog.tables.insert(
630	                name.clone(),
631	                TableSchema {
632	                    name: name.clone(),
633	                    columns: cols,
634	                    checks,
635	                },
636	            );
637	            state.tables.insert(name, TableData::default());
638	            Ok(0)
639	        }
640	        Statement::DropTable { name } => {
641	            let name = normalize(&name);
642	            ensure_table_exists(state, &name)?;
643	            state.catalog.tables.remove(&name);
644	            state.tables.remove(&name);
645	            let indexes: Vec<String> = state
646	                .catalog
647	                .indexes
648	                .iter()
649	                .filter(|(_, idx)| idx.table == name)
650	                .map(|(n, _)| n.clone())
651	                .collect();
652	            for idx in indexes {
653	                state.catalog.indexes.remove(&idx);
654	                state.indexes.remove(&idx);
655	            }
656	            Ok(0)
657	        }
658	        Statement::CreateIndex {
659	            name,
660	            table,
661	            column,
662	        } => {
663	            let name = normalize(&name);
664	            let table = normalize(&table);
665	            let column = normalize(&column);
666	            if state.catalog.indexes.contains_key(&name) {
667	                return Err(MiniDbError::sql(format!("index {name} already exists")));
668	            }
669	            let schema = table_schema(state, &table)?.clone();
670	            if schema.column_index(&column).is_none() {
671	                return Err(MiniDbError::sql(format!("column {column} not found")));
672	            }
673	            state.catalog.indexes.insert(
674	                name.clone(),
675	                IndexSchema {
