868	            (Expr::Column { table: t, name }, Expr::Literal(v))
869	                if t.as_ref().is_none_or(|x| normalize(x) == table) =>
870	            {
871	                let range = range_op(*op)?;
872	                (normalize(name), range, v.clone())
873	            }
874	            (Expr::Literal(v), Expr::Column { table: t, name })
875	                if t.as_ref().is_none_or(|x| normalize(x) == table) =>
876	            {
877	                let range = reverse_range_op(*op)?;
878	                (normalize(name), range, v.clone())
879	            }
880	            _ => return None,
881	        },
882	        _ => return None,
883	    };
884	    state
885	        .catalog
886	        .indexes
887	        .iter()
888	        .find(|(_, idx)| idx.table == table && idx.column == col)
