179	    fn parse_select(&mut self) -> Result<Statement> {
180	        let projection = if self.eat_symbol('*') {
181	            vec![SelectItem::Wildcard]
182	        } else {
183	            let mut items = Vec::new();
184	            loop {
185	                let expr = self.parse_expr()?;
186	                let alias = if self.eat_keyword("AS") {
187	                    Some(self.expect_ident()?)
188	                } else {
189	                    None
190	                };
191	                items.push(SelectItem::Expr { expr, alias });
192	                if self.eat_symbol(',') {
193	                    continue;
194	                }
195	                break;
196	            }
197	            items
198	        };
199	        self.expect_keyword("FROM")?;
200	        let from = self.parse_table_ref()?;
201	        let selection = if self.eat_keyword("WHERE") {
202	            Some(self.parse_expr()?)
203	        } else {
204	            None
205	        };
206	        let mut order_by = Vec::new();
207	        if self.eat_keyword("ORDER") {
208	            self.expect_keyword("BY")?;
209	            loop {
210	                let expr = self.parse_expr()?;
211	                let asc = if self.eat_keyword("DESC") {
212	                    false
213	                } else {
214	                    let _ = self.eat_keyword("ASC");
215	                    true
216	                };
217	                order_by.push(OrderBy { expr, asc });
218	                if self.eat_symbol(',') {
219	                    continue;
220	                }
221	                break;
222	            }
223	        }
224	        let limit = if self.eat_keyword("LIMIT") {
225	            let n = self.expect_u64()?;
226	            let offset = if self.eat_keyword("OFFSET") {
227	                self.expect_u64()?
228	            } else {
229	                0
230	            };
231	            Some(Limit { limit: n, offset })
232	        } else {
233	            None
234	        };
235	        Ok(Statement::Select(Select {
236	            projection,
237	            from,
238	            selection,
239	            order_by,
240	            limit,
241	        }))

