702	fn apply_insert_statement(state: &mut DatabaseState, statement: &Statement) -> Result<usize> {
703	    let Statement::Insert {
704	        table,
705	        columns,
706	        values,
707	    } = statement
708	    else {
709	        return Err(MiniDbError::sql("not an insert statement"));
710	    };
711	    let table = normalize(table);
712	    let schema = table_schema(state, &table)?.clone();
713	    let mut row = schema
714	        .columns
715	        .iter()
716	        .map(|c| c.default.clone())
717	        .collect::<Vec<_>>();
718	    if let Some(cols) = columns {
719	        if cols.len() != values.len() {
720	            return Err(MiniDbError::sql("column list and value list length differ"));
721	        }
722	        for (col, expr) in cols.iter().zip(values.iter()) {
723	            let idx = schema
724	                .column_index(col)
725	                .ok_or_else(|| MiniDbError::sql(format!("column {col} not found")))?;
726	            row[idx] = eval_expr(expr, &DataRow::empty())?.cast_to(schema.columns[idx].ty)?;
727	        }
728	    } else {
729	        if values.len() != schema.columns.len() {
730	            return Err(MiniDbError::sql(
731	                "positional insert must provide every column",
732	            ));
733	        }
734	        for (idx, expr) in values.iter().enumerate() {
735	            row[idx] = eval_expr(expr, &DataRow::empty())?.cast_to(schema.columns[idx].ty)?;
736	        }
737	    }
738	    validate_row(state, &schema, &row, None)?;
739	    state
740	        .tables
741	        .get_mut(&table)
742	        .ok_or_else(|| MiniDbError::sql(format!("table {table} not found")))?
743	        .insert(row);
744	    rebuild_indexes(state)?;
745	    Ok(1)

