 90	    pub fn replay(&self) -> Result<Vec<Vec<WalOp>>> {
 91	        let mut f = OpenOptions::new().read(true).open(&self.path)?;
 92	        let mut txs = Vec::new();
 93	        let mut cur: Option<Vec<WalOp>> = None;
 94	        loop {
 95	            let mut header = [0u8; 8];
 96	            match f.read_exact(&mut header) {
 97	                Ok(()) => {}
 98	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
 99	                Err(e) => return Err(e.into()),
100	            }
101	            let len = u32::from_le_bytes(
102	                header[0..4]
103	                    .try_into()
104	                    .map_err(|_| MiniDbError::Storage("bad wal header".into()))?,
105	            ) as usize;
106	            let crc = u32::from_le_bytes(
107	                header[4..8]
108	                    .try_into()
109	                    .map_err(|_| MiniDbError::Storage("bad wal header".into()))?,
110	            );
111	            let mut payload = vec![0; len];
112	            if f.read_exact(&mut payload).is_err() {
113	                break;
114	            }
115	            let mut h = Hasher::new();
116	            h.update(&payload);
117	            if h.finalize() != crc {
118	                break;
119	            }
120	            match serde_json::from_slice::<WalRecord>(&payload)? {
121	                WalRecord::Begin => cur = Some(Vec::new()),
122	                WalRecord::Op(op) => {
123	                    if let Some(c) = &mut cur {
124	                        c.push(op);
125	                    }
126	                }
127	                WalRecord::Commit => {
128	                    if let Some(c) = cur.take() {
129	                        txs.push(c);
130	                    }
131	                }
132	            }
133	        }
134	        Ok(txs)

