20	pub fn physical(db: &StorageEngine, plan: LogicalPlan) -> Result<PhysicalPlan> {
21	    match plan {
22	        LogicalPlan::Select(s) => {
23	            let mut root = exec::scan_for_select(db, &s.from, &s.selection)?;
24	            if let Some(j) = s.join.clone() {
25	                let right = exec::scan_for_select(db, &j.right, &None)?;
26	                root = Box::new(exec::NestedLoopJoin::new(root, right, j.on)?);
27	            }
28	            if let Some(w) = s.selection.clone() {
29	                root = Box::new(exec::Filter::new(root, w));
30	            }
31	            if let Some(o) = s.order.clone() {
32	                root = Box::new(exec::Sort::new(root, o.expr, o.asc));
33	            }
34	            root = Box::new(exec::Project::new(root, s.projection));
35	            if s.limit.is_some() || s.offset.is_some() {
36	                root = Box::new(exec::Limit::new(root, s.limit, s.offset.map_or(0, |v| v)));
37	            }
38	            Ok(PhysicalPlan { root })

