278	    fn update(
279	        &mut self,
280	        table: &str,
281	        assigns: Vec<(String, Expr)>,
282	        selection: Option<Expr>,
283	    ) -> Result<StatementResult> {
284	        let schema = self.db.catalog().table(table)?.clone();
285	        let names = exec::names_for(&schema);
286	        let mut ops = Vec::new();
287	        for (id, old) in self.db.table_rows(table)? {
288	            if selection
289	                .as_ref()
290	                .map(|e| exec::eval(e, &names, &old).map(|v| v.as_truth().is_true()))
291	                .transpose()?
292	                .map_or(true, |v| v)
293	            {
294	                let mut row = old.clone();
295	                for (c, e) in &assigns {
296	                    let pos = schema
297	                        .columns
298	                        .iter()
299	                        .position(|x| x.name.eq_ignore_ascii_case(c))
300	                        .ok_or_else(|| MiniDbError::Sql(format!("unknown column {c}")))?;
301	                    row[pos] = exec::eval(e, &names, &old)?.cast_for(&schema.columns[pos].ty)?;
302	                }
303	                validate_row(&schema, &self.db.table_rows(table)?, Some(id), &row)?;
304	                ops.push(WalOp::Update {
305	                    table: table.into(),
306	                    row_id: id,
307	                    row,
308	                });
309	            }
310	        }
311	        let n = ops.len();
312	        self.apply_ops(ops)?;
313	        Ok(summary(&format!("{n} rows affected"), Some(n)))
314	    }
