20	pub fn physical(db: &StorageEngine, plan: LogicalPlan) -> Result<PhysicalPlan> {
21	    match plan {
22	        LogicalPlan::Select(s) => {
23	            let mut root = exec::scan_for_select(db, &s.from, &s.selection)?;
24	            if let Some(j) = s.join.clone() {
25	                let right = exec::scan_for_select(db, &j.right, &None)?;
26	                root = Box::new(exec::NestedLoopJoin::new(root, right, j.on)?);
27	            }
28	            if let Some(w) = s.selection.clone() {
29	                root = Box::new(exec::Filter::new(root, w));
30	            }
31	            if let Some(o) = s.order.clone() {
32	                root = Box::new(exec::Sort::new(root, o.expr, o.asc));
33	            }
34	            root = Box::new(exec::Project::new(root, s.projection));
35	            if s.limit.is_some() || s.offset.is_some() {
36	                root = Box::new(exec::Limit::new(root, s.limit, s.offset.map_or(0, |v| v)));
37	            }
38	            Ok(PhysicalPlan { root })

505	pub fn scan_for_select(
506	    db: &StorageEngine,
507	    table: &str,
508	    pred: &Option<Expr>,
509	) -> Result<Box<dyn PhysicalOperator>> {
510	    let schema = db.catalog().table(table)?;
511	    let names = names_for(schema);
512	    let all = db.table_rows(table)?;
513	    if let Some((col, val, op)) = simple_index_pred(pred) {
514	        if db.catalog().index_on(table, &col).is_some() {
515	            let idx = storage::indexed_rows(db.image(), table, &col)?;
516	            let ids = if op == BinaryOp::Eq {
517	                idx.eq(&val)
518	            } else {
519	                idx.range(
520	                    if matches!(op, BinaryOp::Gt | BinaryOp::Ge) {
521	                        Some(&val)
522	                    } else {
523	                        None
524	                    },
525	                    if matches!(op, BinaryOp::Lt | BinaryOp::Le) {
526	                        Some(&val)
527	                    } else {
528	                        None
529	                    },
530	                )
531	            };
532	            let rows = all.into_iter().filter(|(id, _)| ids.contains(id)).collect();
533	            return Ok(Box::new(IndexScan::new(names, rows)));
534	        }
535	    }
536	    Ok(Box::new(SeqScan::new(names, all)))
537	}

