318	    fn select(&mut self, select: &Select) -> Result<QueryResult> {
319	        let (mut rows, schema) = self.source_rows(&select.from)?;
320	        if let Some(w) = &select.where_clause {
321	            rows.retain(|r| {
322	                matches!(
323	                    eval(w, r, &schema).and_then(|v| v.as_truth()),
324	                    Ok(Truth::True)
325	                )
326	            });
327	        }
328	        if !select.order_by.is_empty() {
329	            rows.sort_by(|a, b| {
330	                for ob in &select.order_by {
331	                    let av = eval(&ob.expr, a, &schema).map_or(Value::Null, |v| v);
332	                    let bv = eval(&ob.expr, b, &schema).map_or(Value::Null, |v| v);
333	                    let ord = compare(&av, &bv).map_or(Ordering::Equal, |o| o);
334	                    if ord != Ordering::Equal {
335	                        return if ob.desc { ord.reverse() } else { ord };
336	                    }
337	                }
338	                Ordering::Equal
339	            });
340	        }
341	        let offset = select.offset.map_or(0, |v| v);
342	        let limit = select.limit.map_or(usize::MAX, |v| v);
343	        rows = rows.into_iter().skip(offset).take(limit).collect();
344	        let mut out_cols = Vec::new();
345	        let mut out_rows = Vec::new();
346	        for row in &rows {
347	            let mut out = Vec::new();
348	            for item in &select.projection {
349	                match item {
350	                    SelectItem::Star => {
351	                        if out_cols.is_empty() {
352	                            out_cols.extend(schema.columns.clone());
353	                        }
354	                        out.extend(row.clone());
355	                    }
356	                    SelectItem::Expr { expr, alias } => {
357	                        if out_cols.len() < select.projection.len() {
358	                            out_cols.push(alias.clone().map_or_else(|| expr_name(expr), |a| a));
359	                        }
360	                        out.push(eval(expr, row, &schema)?);
361	                    }
362	                }
363	            }
364	            out_rows.push(out);
365	        }
366	        if rows.is_empty() {
367	            for item in &select.projection {
368	                match item {
369	                    SelectItem::Star => out_cols.extend(schema.columns.clone()),
370	                    SelectItem::Expr { expr, alias } => {
371	                        out_cols.push(alias.clone().map_or_else(|| expr_name(expr), |a| a))
372	                    }
373	                }
374	            }
375	        }
376	        let n = out_rows.len();
377	        Ok(QueryResult {
378	            columns: out_cols,
379	            rows: out_rows,
380	            affected: None,
381	            message: format!("ok {n} {}", if n == 1 { "row" } else { "rows" }),
382	        })
383	    }
