182	    fn parse_select(&mut self) -> Result<Select> {
183	        let mut projection = Vec::new();
184	        loop {
185	            if self.consume_symbol('*') {
186	                projection.push(SelectItem::Star);
187	            } else {
188	                projection.push(SelectItem::Expr {
189	                    expr: self.expr()?,
190	                    alias: None,
191	                });
192	            }
193	            if !self.consume_symbol(',') {
194	                break;
195	            }
196	        }
197	        self.expect_kw("from")?;
198	        let left = self.expect_ident()?;
199	        let from = if self.consume_kw("inner") || self.consume_kw("join") {
200	            if !matches!(self.prev_ident().as_deref(), Some("join")) {
201	                self.expect_kw("join")?;
202	            }
203	            let right = self.expect_ident()?;
204	            self.expect_kw("on")?;
205	            From::Join {
206	                left,
207	                right,
208	                on: self.expr()?,
209	            }
210	        } else {
211	            From::Table(left)
212	        };
213	        let where_clause = if self.consume_kw("where") {
214	            Some(self.expr()?)
215	        } else {
216	            None
217	        };
218	        let mut order_by = Vec::new();
219	        if self.consume_kw("order") {
220	            self.expect_kw("by")?;
221	            loop {
222	                let expr = self.expr()?;
223	                let desc = if self.consume_kw("desc") {
224	                    true
225	                } else {
226	                    self.consume_kw("asc");
227	                    false
228	                };
229	                order_by.push(OrderBy { expr, desc });
230	                if !self.consume_symbol(',') {
231	                    break;
232	                }
233	            }
234	        }
235	        let limit = if self.consume_kw("limit") {
236	            Some(self.expect_usize()?)
237	        } else {
238	            None
239	        };
240	        let offset = if self.consume_kw("offset") {
241	            Some(self.expect_usize()?)
242	        } else {
243	            None
244	        };
245	        Ok(Select {
246	            projection,
247	            from,
248	            where_clause,
249	            order_by,
250	            limit,
251	            offset,
252	        })
253	    }

