 47	    pub fn read_records(&self) -> Result<Vec<WalRecord>> {
 48	        let mut f = File::open(&self.path)?;
 49	        let mut out = Vec::new();
 50	        loop {
 51	            let mut hdr = [0u8; 8];
 52	            match f.read_exact(&mut hdr) {
 53	                Ok(()) => {}
 54	                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
 55	                Err(e) => return Err(e.into()),
 56	            }
 57	            let len = u32::from_le_bytes([hdr[0], hdr[1], hdr[2], hdr[3]]) as usize;
 58	            let crc = u32::from_le_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
 59	            let mut data = vec![0u8; len];
 60	            if f.read_exact(&mut data).is_err() {
 61	                break;
 62	            }
 63	            let mut hasher = Hasher::new();
 64	            hasher.update(&data);
 65	            if hasher.finalize() != crc {
 66	                break;
 67	            }
 68	            out.push(
 69	                serde_json::from_slice(&data).map_err(|e| MiniDbError::Storage(e.to_string()))?,
 70	            );
 71	        }
 72	        Ok(committed_prefix(out))
 73	    }
