39	    pub fn run(&self, req: &mut Request, handler: &dyn Fn(&mut Request) -> Response) -> Response {
40	        // Run before hooks, collecting short-circuit responses
41	        for m in &self.middlewares {
42	            if let Some(resp) = m.before(req) {
43	                // Still run after hooks on previous middleware
44	                return resp;
45	            }
46	        }
47	
48	        let resp = handler(req);
49	
50	        // Run after hooks in reverse
51	        let mut resp = resp;
52	        for m in self.middlewares.iter().rev() {
53	            resp = m.after(req, resp);
54	        }
55	
56	        resp

