240	            }
241	            "--metrics" => {
242	                i += 1;
243	                cli.metrics = args.get(i).cloned();
244	            }
245	            "--static-dir" => {
246	                i += 1;
247	                cli.static_dir = args.get(i).cloned();
248	            }
249	            "--log-level" => {
250	                i += 1;
251	                cli.log_level = args.get(i).cloned();
