 21	fn render(template: &str, context: &Value) -> String {
 22	    let mut output = String::new();
 23	    let bytes = template.as_bytes();
 24	    let len = bytes.len();
 25	    let mut i = 0;
 26	
 27	    while i < len {
 28	        if bytes[i] == b'{' && i + 1 < len && bytes[i + 1] == b'{' {
 29	            // Find the closing }}
 30	            let tag_start = i;
 31	            i += 2;
 32	            let mut tag = String::new();
 33	            while i + 1 < len && !(bytes[i] == b'}' && bytes[i + 1] == b'}') {
 34	                tag.push(bytes[i] as char);
 35	                i += 1;
 36	            }
 37	            if i + 1 < len {
 38	                i += 2; // skip }}
 39	            }
 40	            let tag = tag.trim();
 41	
 42	            if let Some(section_name) = tag.strip_prefix('#') {
 43	                // Find the matching closing tag, accounting for nesting
 44	                let (section_body, after) = find_section_body(template, tag_start, section_name);
 45	                let value = get_value(context, section_name);
 46	                match &value {
 47	                    Value::Array(arr) => {
 48	                        for item in arr {
 49	                            output.push_str(&render(&section_body, item));
 50	                        }
 51	                    }
 52	                    Value::Bool(true) => {
 53	                        output.push_str(&render(&section_body, context));
 54	                    }
 55	                    Value::Null | Value::Bool(false) => {}
 56	                    _ => {
 57	                        output.push_str(&render(&section_body, context));
 58	                    }
 59	                }
 60	                return output + &render(&after, context);
 61	            } else if let Some(section_name) = tag.strip_prefix('^') {
 62	                let (section_body, after) = find_section_body(template, tag_start, section_name);
 63	                let value = get_value(context, section_name);
 64	                match &value {
 65	                    Value::Null | Value::Bool(false) => {
 66	                        output.push_str(&render(&section_body, context));
 67	                    }
 68	                    _ => {}
 69	                }
 70	                return output + &render(&after, context);
 71	            } else if tag.starts_with('/') {
 72	                // Closing tag reached at top level - shouldn't happen in well-formed template
 73	                // Return what we have so far
 74	                return output;
 75	            } else {
 76	                // Variable
 77	                let value = get_value(context, tag);
 78	                let rendered = match &value {
 79	                    Value::String(s) => s.clone(),
 80	                    Value::Null => String::new(),
 81	                    Value::Number(n) => n.to_string(),
 82	                    Value::Bool(b) => b.to_string(),
 83	                    Value::Array(arr) => arr
 84	                        .iter()
 85	                        .map(|v| match v {
 86	                            Value::String(s) => s.clone(),
 87	                            other => other.to_string(),
 88	                        })
 89	                        .collect::<Vec<_>>()
 90	                        .join(" "),
 91	                    Value::Object(map) => serde_json::to_string(map).unwrap_or_default(),
 92	                };
 93	                output.push_str(&rendered);
 94	            }
 95	        } else {
 96	            output.push(bytes[i] as char);
 97	            i += 1;
 98	        }
 99	    }
100	
101	    output

104	/// Find the body of a section and the remainder after the closing tag.
105	/// Handles nested sections with the same name.
106	fn find_section_body(template: &str, tag_start: usize, section_name: &str) -> (String, String) {
107	    let open_tag_with_hash = format!("{{{{#{section_name}}}}}");
108	    let open_tag_with_caret = format!("{{{{^{section_name}}}}}");
109	    let close_tag = format!("{{{{/{section_name}}}}}");
110	
111	    // Find the end of the opening tag (could be # or ^)
112	    let open_tag = if template[tag_start..].starts_with(&open_tag_with_hash) {
113	        &open_tag_with_hash
114	    } else {
115	        &open_tag_with_caret
116	    };
117	    let open_pos = tag_start + open_tag.len();
118	
119	    // Find the matching close tag, counting nesting
120	    let mut depth = 1;
121	    let mut pos = open_pos;
122	    let body_end;
123	    let after;
124	
125	    loop {
126	        let next_open_hash = template[pos..].find(&open_tag_with_hash);
127	        let next_open_caret = template[pos..].find(&open_tag_with_caret);
128	        let next_close = template[pos..].find(&close_tag);
129	
130	        let next_open = match (next_open_hash, next_open_caret) {
131	            (Some(a), Some(b)) => Some(a.min(b)),
132	            (a, None) => a,
133	            (None, b) => b,
134	        };
135	
136	        match (next_open, next_close) {
137	            (Some(o), Some(c)) if o < c => {
138	                depth += 1;
139	                pos += o + open_tag_with_hash.len();
140	            }
141	            (Some(_), Some(c)) => {
142	                depth -= 1;
143	                if depth == 0 {
144	                    body_end = pos + c;
145	                    after = template[body_end + close_tag.len()..].to_string();
146	                    let body = template[open_pos..body_end].to_string();
147	                    return (body, after);
148	                }
149	                pos += c + close_tag.len();
150	            }
151	            (None, Some(c)) => {
152	                depth -= 1;
153	                if depth == 0 {
154	                    body_end = pos + c;
155	                    after = template[body_end + close_tag.len()..].to_string();
156	                    let body = template[open_pos..body_end].to_string();
157	                    return (body, after);
158	                }
159	                pos += c + close_tag.len();
160	            }
161	            _ => {
162	                break;
163	            }
164	        }
165	    }
166	
167	    // No matching close tag
168	    let body = template[open_pos..].to_string();
169	    (body, String::new())
170	}
