26	    fn before(&self, req: &mut Request) -> Option<Response> {
27	        match req.header("authorization") {
28	            Some(auth) if auth.starts_with("Basic ") => {
29	                let encoded = &auth[6..];
30	                use base64::Engine;
31	                if let Ok(decoded) = base64::engine::general_purpose::STANDARD.decode(encoded) {
32	                    if let Ok(s) = std::str::from_utf8(&decoded) {
33	                        if let Some((user, pass)) = s.split_once(':') {
34	                            if user == self.username && pass == self.password {
35	                                return None;
36	                            }
37	                        }
38	                    }
39	                }
40	                unauthorized(&self.realm)
41	            }
42	            _ => unauthorized(&self.realm),
43	        }
44	    }
