148	pub fn find_chunked_end(data: &[u8]) -> Option<usize> {
149	    // Chunked encoding ends with "0\r\n\r\n" (possibly with trailers)
150	    let pattern = b"0\r\n\r\n";
151	    if let Some(pos) = data.windows(5).position(|w| w == pattern) {
152	        return Some(pos + 5);
153	    }
154	    // Also handle "0\r\n" followed by trailers then "\r\n"
155	    let pattern2 = b"0\r\n";
156	    let mut i = 0;
157	    while i + 4 <= data.len() {
158	        if &data[i..i + 4] == pattern2 {
159	            // Check for end after trailers
160	            let rest = &data[i + 4..];
161	            if let Some(end) = rest.windows(2).position(|w| w == b"\r\n") {
162	                return Some(i + 4 + end + 2);
163	            }
164	        }
165	        i += 1;
166	    }
167	    None
168	}
