170	fn decode_chunked(data: &[u8]) -> Vec<u8> {
171	    let mut result = Vec::new();
172	    let mut pos = 0;
173	
174	    while pos < data.len() {
175	        // Read chunk size line
176	        let line_end = match data[pos..].windows(2).position(|w| w == b"\r\n") {
177	            Some(e) => e,
178	            None => break,
179	        };
180	        let size_str = str::from_utf8(&data[pos..pos + line_end]).unwrap_or("0");
181	        let size = usize::from_str_radix(size_str.trim(), 16).unwrap_or(0);
182	
183	        if size == 0 {
184	            break;
185	        }
186	
187	        pos += line_end + 2;
188	        let chunk_end = pos + size;
189	        if chunk_end <= data.len() {
190	            result.extend_from_slice(&data[pos..chunk_end]);
191	        }
192	        pos = chunk_end + 2; // skip trailing \r\n
193	    }
194	
195	    result
196	}
