 68	pub fn parse_request(buf: &BytesMut) -> Result<Option<RawHttpRequest>> {
 69	    let data = buf.as_ref();
 70	    // Find the end of headers (double CRLF)
 71	    let header_end = find_header_end(data)?;
 72	
 73	    // Not found yet - need more data
 74	    if header_end == usize::MAX {
 75	        return Ok(None);
 76	    }
 77	
 78	    let header_bytes = &data[..header_end];
 79	    let header_str = std::str::from_utf8(header_bytes)
 80	        .map_err(|e| NanowebError::HttpParse(format!("invalid UTF-8 in headers: {e}")))?;
 81	
 82	    let mut lines = header_str.split("\r\n");
 83	
 84	    // Parse request line
 85	    let request_line_str = lines
 86	        .next()
 87	        .ok_or_else(|| NanowebError::HttpParse("empty request".into()))?;
 88	    let request_line = parse_request_line(request_line_str)?;
 89	
 90	    // Parse headers
 91	    let mut headers = HashMap::new();
 92	    for line in lines {
 93	        if line.is_empty() {
 94	            break;
 95	        }
 96	        if let Some((key, value)) = line.split_once(':') {
 97	            headers.insert(key.trim().to_lowercase(), value.trim().to_string());
 98	        }
 99	    }
100	
101	    // Determine body encoding
102	    let body_start = header_end + 4; // skip \r\n\r\n
103	    let available = data.len() - body_start;
104	
105	    let body_encoding = if let Some(cl) = headers.get("content-length") {
106	        let len: usize = cl
107	            .parse()
108	            .map_err(|_| NanowebError::HttpParse("invalid Content-Length".into()))?;
109	        BodyEncoding::Length(len)
110	    } else if headers.get("transfer-encoding").map(|s| s.as_str()) == Some("chunked") {
111	        BodyEncoding::Chunked
112	    } else {
113	        BodyEncoding::None
114	    };
115	
116	    match body_encoding {
117	        BodyEncoding::None => Ok(Some(RawHttpRequest {
118	            request_line,
119	            headers,
120	            body: Vec::new(),
121	        })),
122	        BodyEncoding::Length(len) => {
123	            if available < len {
124	                return Ok(None); // need more data
125	            }
126	            let body = data[body_start..body_start + len].to_vec();
127	            Ok(Some(RawHttpRequest {
128	                request_line,
129	                headers,
130	                body,
131	            }))
132	        }
133	        BodyEncoding::Chunked => parse_chunked_body(data, body_start, &request_line, headers),
134	    }
135	}

