24	#[derive(Debug, Clone, PartialEq)]
25	enum Token {
26	    Text(String),
27	    Variable(String),
28	    SectionStart(String),
29	    SectionEnd(String),
30	    InvertedSectionStart(String),
31	}
32	
33	fn tokenize(template: &str) -> Vec<Token> {
34	    let mut tokens = Vec::new();
35	    let mut chars = template.chars().peekable();
36	    let mut current_text = String::new();
37	
38	    while let Some(&ch) = chars.peek() {
39	        if ch == '{' {
40	            chars.next();
41	            if let Some(&'{') = chars.peek() {
42	                chars.next();
43	                let mut tag = String::new();
44	                let mut closed = false;
45	                while let Some(&ch) = chars.peek() {
46	                    if ch == '}' {
47	                        chars.next();
48	                        if let Some(&'}') = chars.peek() {
49	                            chars.next();
50	                            closed = true;
51	                            break;
52	                        } else {
53	                            tag.push('}');
54	                        }
55	                    } else {
56	                        tag.push(ch);
57	                        chars.next();
58	                    }
59	                }
60	
61	                if !current_text.is_empty() {
62	                    tokens.push(Token::Text(current_text.clone()));
63	                    current_text.clear();
64	                }
65	
66	                let tag = tag.trim().to_string();
67	                if tag.starts_with('#') {
68	                    tokens.push(Token::SectionStart(tag[1..].to_string()));
69	                } else if tag.starts_with('^') {
70	                    tokens.push(Token::InvertedSectionStart(tag[1..].to_string()));
71	                } else if tag.starts_with('/') {
72	                    tokens.push(Token::SectionEnd(tag[1..].to_string()));
73	                } else {
74	                    tokens.push(Token::Variable(tag));
75	                }
76	
77	                if !closed {
78	                    current_text.push_str("{{");
79	                }
80	            } else {
81	                current_text.push('{');
82	            }
83	        } else {
84	            current_text.push(ch);
85	            chars.next();
86	        }
87	    }
88	
89	    if !current_text.is_empty() {
90	        tokens.push(Token::Text(current_text));
91	    }
92	
93	    tokens
94	}

 96	fn render_tokens(tokens: &[Token], context: &Value) -> Result<String> {
 97	    let mut output = String::new();
 98	    let mut i = 0;
 99	
100	    while i < tokens.len() {
101	        match &tokens[i] {
102	            Token::Text(text) => {
103	                output.push_str(text);
104	            }
105	            Token::Variable(name) => {
106	                if let Some(val) = resolve_variable(context, name) {
107	                    output.push_str(&val);
108	                }
109	            }
110	            Token::SectionStart(name) => {
111	                let mut depth = 1;
112	                let mut j = i + 1;
113	                let mut section_tokens = Vec::new();
114	                while j < tokens.len() && depth > 0 {
115	                    match &tokens[j] {
116	                        Token::SectionStart(_) => {
117	                            depth += 1;
118	                            section_tokens.push(tokens[j].clone());
119	                        }
120	                        Token::SectionEnd(_) => {
121	                            depth -= 1;
122	                            if depth > 0 {
123	                                section_tokens.push(tokens[j].clone());
124	                            }
125	                        }
126	                        other => {
127	                            section_tokens.push(other.clone());
128	                        }
129	                    }
130	                    j += 1;
131	                }
132	
133	                match context.get(name) {
134	                    Some(Value::Bool(false)) | Some(Value::Null) => {}
135	                    Some(Value::Array(arr)) => {
136	                        for item in arr {
137	                            output.push_str(&render_tokens(&section_tokens, item)?);
138	                        }
139	                    }
140	                    Some(_) => {
141	                        output.push_str(&render_tokens(&section_tokens, context)?);
142	                    }
143	                    None => {}
144	                }
145	
146	                i = j;
147	                continue;
148	            }
149	            Token::InvertedSectionStart(name) => {
150	                let mut depth = 1;
151	                let mut j = i + 1;
152	                let mut section_tokens = Vec::new();
153	                while j < tokens.len() && depth > 0 {
154	                    match &tokens[j] {
155	                        Token::InvertedSectionStart(_) | Token::SectionStart(_) => {
156	                            depth += 1;
157	                            section_tokens.push(tokens[j].clone());
158	                        }
159	                        Token::SectionEnd(_) => {
160	                            depth -= 1;
161	                            if depth > 0 {
162	                                section_tokens.push(tokens[j].clone());
163	                            }
164	                        }
165	                        other => {
166	                            section_tokens.push(other.clone());
167	                        }
168	                    }
169	                    j += 1;
170	                }
171	
172	                match context.get(name) {
173	                    None | Some(Value::Bool(false)) | Some(Value::Null) => {
174	                        output.push_str(&render_tokens(&section_tokens, context)?);
175	                    }
176	                    _ => {}
177	                }
178	
179	                i = j;
180	                continue;
181	            }
182	            Token::SectionEnd(_) => {}
183	        }
184	        i += 1;
185	    }
186	
187	    Ok(output)

