11	pub fn parse_request(buf: &[u8]) -> Result<(Request, usize)> {
12	    let headers_end = find_headers_end(buf)
13	        .ok_or_else(|| NanowebError::Http("Could not find end of headers".into()))?;
14	
15	    let header_bytes = &buf[..headers_end];
16	    let (method, path, version) = parse_request_line(header_bytes)?;
17	
18	    let headers = parse_headers(header_bytes)?;
19	    let body_encoding = determine_body_encoding(&headers)?;
20	    let (body, consumed) = read_body(buf, headers_end + 4, body_encoding, &headers)?;
21	
22	    let (base_path, query) = super::types::parse_query_string(&path);
23	
24	    let mut request = Request::new(method, base_path);
25	    request.version = version;
26	    request.headers = headers;
27	    request.body = body;
28	    request.query = query;
29	
30	    Ok((request, consumed))

