 9	pub fn load_tls_config(cert_path: &Path, key_path: &Path) -> Result<Arc<rustls::ServerConfig>> {
10	    let cert_file = File::open(cert_path)
11	        .map_err(|e| NanowebError::Tls(format!("Cannot open cert file: {}", e)))?;
12	    let mut cert_reader = BufReader::new(cert_file);
13	    let certs: Vec<_> = rustls_pemfile::certs(&mut cert_reader)
14	        .filter_map(|r| r.ok())
15	        .collect();
16	
17	    let key_file = File::open(key_path)
18	        .map_err(|e| NanowebError::Tls(format!("Cannot open key file: {}", e)))?;
19	    let mut key_reader = BufReader::new(key_file);
20	    let key = rustls_pemfile::private_key(&mut key_reader)
21	        .map_err(|e| NanowebError::Tls(format!("Cannot parse key: {}", e)))?
22	        .ok_or_else(|| NanowebError::Tls("No private key found".into()))?;
23	
24	    let config = rustls::ServerConfig::builder()
25	        .with_no_client_auth()
26	        .with_single_cert(certs, key)
27	        .map_err(|e| NanowebError::Tls(format!("TLS config error: {}", e)))?;
28	
29	    Ok(Arc::new(config))
30	}
