 30	    pub fn record_request(&self, method: &str, status: u16, route: &str, duration_secs: f64) {
 31	        let status_class = format!("{}xx", status / 100);
 32	        let key = MetricKey {
 33	            method: method.to_string(),
 34	            status_class,
 35	            route: route.to_string(),
 36	        };
 37	
 38	        self.request_count
 39	            .lock()
 40	            .unwrap()
 41	            .entry(key)
 42	            .or_insert_with(|| AtomicU64::new(0))
 43	            .fetch_add(1, Ordering::Relaxed);
 44	
 45	        self.duration_sum
 46	            .lock()
 47	            .unwrap()
 48	            .entry(route.to_string())
 49	            .and_modify(|v| *v += duration_secs)
 50	            .or_insert(duration_secs);
 51	
 52	        self.duration_count
 53	            .lock()
 54	            .unwrap()
 55	            .entry(route.to_string())
 56	            .and_modify(|v| *v += 1)
 57	            .or_insert(1);
 58	    }
