 21	pub fn render(template: &str, context: &Value) -> String {
 22	    let mut output = String::new();
 23	    let chars: Vec<char> = template.chars().collect();
 24	    let len = chars.len();
 25	    let mut i = 0;
 26	
 27	    while i < len {
 28	        if i + 1 < len && chars[i] == '{' && chars[i + 1] == '{' {
 29	            // Find the closing }}
 30	            if let Some(end) = find_closing(&chars, i + 2) {
 31	                let tag: String = chars[i + 2..end].iter().collect();
 32	                let tag = tag.trim();
 33	
 34	                if tag.starts_with('#') {
 35	                    // Section tag: {{#name}}...{{/name}}
 36	                    let name = tag[1..].trim();
 37	                    let close_tag = format!("{{{{/{}}}}}", name);
 38	                    if let Some(close_pos) = template[end + 2..].find(&close_tag) {
 39	                        let section_content = &template[end + 2..end + 2 + close_pos];
 40	                        let value = get_value(context, name);
 41	                        match value {
 42	                            Value::Bool(true) | Value::Number(_) => {
 43	                                output.push_str(&render(section_content, context));
 44	                            }
 45	                            Value::Array(arr) => {
 46	                                for item in arr {
 47	                                    let mut item_ctx = context.clone();
 48	                                    if let Value::Object(map) = &mut item_ctx {
 49	                                        map.insert(".".into(), item.clone());
 50	                                        if let Value::Object(ref item_map) = item {
 51	                                            for (k, v) in item_map {
 52	                                                map.insert(k.clone(), v.clone());
 53	                                            }
 54	                                        }
 55	                                        if let Value::String(ref s) = item {
 56	                                            map.insert(name.to_string(), Value::String(s.clone()));
 57	                                        }
 58	                                    }
 59	                                    output.push_str(&render(section_content, &item_ctx));
 60	                                }
 61	                            }
 62	                            Value::Null | Value::Bool(false) => {}
 63	                            _ => {}
 64	                        }
 65	                        i = end + 2 + close_pos + close_tag.len();
 66	                        continue;
 67	                    }
 68	                } else if tag.starts_with('^') {
 69	                    // Inverted section: {{^name}}...{{/name}}
 70	                    let name = tag[1..].trim();
 71	                    let close_tag = format!("{{{{/{}}}}}", name);
 72	                    if let Some(close_pos) = template[end + 2..].find(&close_tag) {
 73	                        let section_content = &template[end + 2..end + 2 + close_pos];
 74	                        let value = get_value(context, name);
 75	                        match value {
 76	                            Value::Null | Value::Bool(false) => {
 77	                                output.push_str(&render(section_content, context));
 78	                            }
 79	                            _ => {}
 80	                        }
 81	                        i = end + 2 + close_pos + close_tag.len();
 82	                        continue;
 83	                    }
 84	                } else {
 85	                    // Variable tag: {{name}}
 86	                    let value = get_value(context, tag);
 87	                    match value {
 88	                        Value::String(s) => output.push_str(&s),
 89	                        Value::Number(n) => output.push_str(&n.to_string()),
 90	                        Value::Bool(b) => output.push_str(&b.to_string()),
 91	                        Value::Null => {}
 92	                        Value::Array(_) => output.push_str("[array]"),
 93	                        Value::Object(_) => output.push_str("[object]"),
 94	                    }
 95	                    i = end + 2;
 96	                    continue;
 97	                }
 98	            }
 99	        }
100	
101	        output.push(chars[i]);
102	        i += 1;
103	    }
104	
105	    output

117	fn get_value(context: &Value, name: &str) -> Value {
118	    if name == "." {
119	        if let Some(val) = context.get(".") {
120	            return val.clone();
121	        }
122	    }
123	    if let Some(val) = context.get(name) {
124	        return val.clone();
125	    }
126	    // Support dotted paths like "user.name"
127	    let parts: Vec<&str> = name.split('.').collect();
128	    let mut current = context;
129	    for part in &parts {
130	        match current.get(*part) {
131	            Some(val) => current = val,
132	            None => return Value::Null,
133	        }
134	    }
135	    current.clone()
136	}

