 5	/// Maximum allowed header size (8KB).
 6	const MAX_HEADER_SIZE: usize = 8192;
 7	/// Maximum allowed body size (16MB default).
 8	pub const MAX_BODY_SIZE: usize = 16 * 1024 * 1024;
 9	
10	/// Parse a raw HTTP/1.1 request from bytes.
11	pub fn parse_request(raw: &[u8]) -> Result<Request, NanowebError> {
12	    // Find the end of headers
13	    let header_end = find_header_end(raw)
14	        .ok_or_else(|| NanowebError::HttpParse("Could not find end of headers".into()))?;
15	
16	    let header_bytes = &raw[..header_end];
17	    if header_bytes.len() > MAX_HEADER_SIZE {
18	        return Err(NanowebError::HttpParse(
19	            "Headers exceed maximum size".into(),
20	        ));
21	    }
22	
23	    let header_str = std::str::from_utf8(header_bytes)
24	        .map_err(|_| NanowebError::HttpParse("Invalid UTF-8 in headers".into()))?;
25	
26	    let mut lines = header_str.split("\r\n");
27	
28	    // Parse request line
29	    let request_line = lines
30	        .next()
31	        .ok_or_else(|| NanowebError::HttpParse("Empty request".into()))?;
32	    let (method, target, version) = parse_request_line(request_line)?;
33	
34	    // Parse headers
35	    let mut headers = HeaderMap::new();
36	    for line in lines {
37	        if line.is_empty() {
38	            break;
39	        }
40	        let colon_pos = line
41	            .find(':')
42	            .ok_or_else(|| NanowebError::HttpParse("Invalid header line".into()))?;
43	        let name = line[..colon_pos].trim().to_string();
44	        let value = line[colon_pos + 1..].trim().to_string();
45	        headers.append(name, value);
46	    }
47	
48	    // Parse body based on transfer encoding and content-length
49	    let body_start = header_end + 4; // Skip \r\n\r\n
50	    let body = if headers
51	        .get("transfer-encoding")
52	        .map(|v| v.to_lowercase().contains("chunked"))
53	        .unwrap_or(false)
54	    {
55	        parse_chunked_body(&raw[body_start..])?
56	    } else if let Some(content_length) = headers.get("content-length") {
57	        let len: usize = content_length
58	            .parse()
59	            .map_err(|_| NanowebError::HttpParse("Invalid Content-Length".into()))?;
60	        if len > MAX_BODY_SIZE {
61	            return Err(NanowebError::HttpParse("Body exceeds maximum size".into()));
62	        }
63	        if body_start + len > raw.len() {
64	            return Err(NanowebError::HttpParse("Incomplete body".into()));
65	        }
66	        raw[body_start..body_start + len].to_vec()
67	    } else {
68	        Vec::new()
69	    };
70	
71	    // Parse path and query from target
72	    let (path, query) = parse_target(&target);
73	
74	    Ok(Request {
75	        method,
76	        target,
77	        path,
78	        version,
79	        headers,
80	        body,
81	        query,
82	        params: HashMap::new(),
83	        request_id: String::new(),
84	        session_data: HashMap::new(),
85	    })

