44	        let segments: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
45	        let mut node = &mut self.root;
46	
47	        for seg in segments {
48	            if seg.starts_with('*') {
49	                // Wildcard segment
50	                let name = seg[1..].to_string();
51	                if node.wildcard_child.is_none() {
52	                    node.wildcard_child = Some((name, Box::new(TrieNode::default())));
53	                }
54	                node = node.wildcard_child.as_mut().unwrap().1.as_mut();
55	                break; // Wildcard consumes the rest
56	            } else if seg.starts_with(':') {
57	                // Parameter segment
58	                let name = seg[1..].to_string();
59	                if node.param_child.is_none() {
60	                    node.param_child = Some((name, Box::new(TrieNode::default())));
61	                } else {
62	                    // Update name if different
63	                    node.param_child.as_mut().unwrap().0 = name;
64	                }
65	                node = node.param_child.as_mut().unwrap().1.as_mut();
66	            } else {
67	                // Literal segment
68	                node = node
69	                    .children
70	                    .entry(seg.to_string())
71	                    .or_insert_with(TrieNode::default);
72	            }
73	        }
74	
75	        node.handlers.insert(method, handler);
76	    }
