145	    fn collect_methods(
146	        &self,
147	        node: &TrieNode,
148	        segments: &[&str],
149	        idx: usize,
150	        methods: &mut Vec<Method>,
151	    ) {
152	        if idx == segments.len() {
153	            methods.extend(node.handlers.keys().copied());
154	            return;
155	        }
156	
157	        let seg = segments[idx];
158	
159	        if let Some(child) = node.children.get(seg) {
160	            self.collect_methods(child, segments, idx + 1, methods);
161	        }
162	
163	        if let Some((_, ref child)) = node.param_child {
164	            self.collect_methods(child, segments, idx + 1, methods);
165	        }
166	
167	        if let Some((_, ref child)) = node.wildcard_child {
168	            methods.extend(child.handlers.keys().copied());
169	        }
170	    }

