13	pub trait MiddlewareDyn: Send + Sync {
14	    fn before<'a>(
15	        &'a self,
16	        request: Request,
17	    ) -> Pin<Box<dyn Future<Output = Result<Request, Response>> + Send + 'a>>;
18	    fn after<'a>(
19	        &'a self,
20	        request: &'a Request,
21	        response: Response,
22	    ) -> Pin<Box<dyn Future<Output = Response> + Send + 'a>>;
23	}
