19	    /// Build a rustls ServerConfig from PEM cert and key files.
20	    pub fn build_server_config(&self) -> Result<rustls::ServerConfig, NanowebError> {
21	        use rustls::pki_types::CertificateDer;
22	        use std::io::BufReader;
23	
24	        let cert_file = std::fs::File::open(&self.cert_path)
25	            .map_err(|e| NanowebError::Tls(format!("Failed to open cert file: {}", e)))?;
26	        let mut cert_reader = BufReader::new(cert_file);
27	        let certs: Vec<CertificateDer<'static>> = rustls_pemfile::certs(&mut cert_reader)
28	            .collect::<Result<Vec<_>, _>>()
29	            .map_err(|e| NanowebError::Tls(format!("Failed to parse certs: {}", e)))?;
30	
31	        let key_file = std::fs::File::open(&self.key_path)
32	            .map_err(|e| NanowebError::Tls(format!("Failed to open key file: {}", e)))?;
33	        let mut key_reader = BufReader::new(key_file);
34	        let key = rustls_pemfile::private_key(&mut key_reader)
35	            .map_err(|e| NanowebError::Tls(format!("Failed to parse key: {}", e)))?
36	            .ok_or_else(|| NanowebError::Tls("No private key found".into()))?;
37	
38	        let config = rustls::ServerConfig::builder()
39	            .with_no_client_auth()
40	            .with_single_cert(certs, key)
41	            .map_err(|e| NanowebError::Tls(format!("TLS config error: {}", e)))?;
42	
43	        Ok(config)
44	    }
45	}
