 49	    /// Increment a counter by the given value.
 50	    pub fn inc_counter(&self, name: &str, help: &str, value: f64) {
 51	        let mut counters = self.counters.lock().unwrap();
 52	        let counter = counters.entry(name.to_string()).or_insert_with(|| Counter {
 53	            help: help.to_string(),
 54	            value: 0.0,
