 59	    /// Record a request with method, status, and route.
 60	    pub fn record_request(&self, method: &str, status: u16, route: &str, duration: f64) {
 61	        let status_class = format!("{}xx", status / 100);
 62	
 63	        // Increment request counter
 64	        let counter_name = format!(
 65	            "nanoweb_http_requests_total{{method=\"{}\",status_class=\"{}\",route=\"{}\"}}",
 66	            method, status_class, route
 67	        );
 68	        self.inc_counter(&counter_name, "Total HTTP requests", 1.0);
 69	
 70	        // Record duration in histogram
 71	        let mut histograms = self.histograms.lock().unwrap();
 72	        if let Some(hist) = histograms.get_mut("nanoweb_request_duration_seconds") {
 73	            for (i, &bucket) in hist.buckets.iter().enumerate() {
 74	                if duration <= bucket {
 75	                    hist.counts[i] += 1;
 76	                }
 77	            }
 78	            hist.counts[hist.buckets.len()] += 1; // +Inf
 79	            hist.sum += duration;
 80	            hist.count += 1;
 81	        }
 82	    }
