 84	    /// Render metrics in Prometheus text exposition format.
 85	    pub fn render(&self) -> String {
 86	        let mut output = String::new();
 87	
 88	        // Render counters
 89	        let counters = self.counters.lock().unwrap();
 90	        for (name, counter) in counters.iter() {
 91	            let _ = writeln!(output, "# HELP {} {}", name, counter.help);
 92	            let _ = writeln!(output, "# TYPE {} counter", name);
 93	            let _ = writeln!(output, "{} {}", name, counter.value);
 94	        }
 95	
 96	        // Render histograms
 97	        let histograms = self.histograms.lock().unwrap();
 98	        for (name, hist) in histograms.iter() {
 99	            let _ = writeln!(output, "# HELP {} {}", name, hist.help);
100	            let _ = writeln!(output, "# TYPE {} histogram", name);
101	            for (i, &bucket) in hist.buckets.iter().enumerate() {
102	                let _ = writeln!(
103	                    output,
104	                    "{}_bucket{{le=\"{}\"}} {}",
105	                    name, bucket, hist.counts[i]
106	                );
107	            }
108	            let _ = writeln!(
109	                output,
110	                "{}_bucket{{le=\"+Inf\"}} {}",
111	                name,
112	                hist.counts[hist.buckets.len()]
113	            );
114	            let _ = writeln!(output, "{}_sum {}", name, hist.sum);
115	            let _ = writeln!(output, "{}_count {}", name, hist.count);
116	        }
117	
118	        output
119	    }

