17	    fn before<'a>(
18	        &'a self,
19	        mut req: Request,
20	    ) -> Pin<Box<dyn Future<Output = Result<Request, Response>> + Send + 'a>> {
21	        Box::pin(async move {
22	            tracing::info!(
23	                request_id = %req.request_id,
24	                method = %req.method,
25	                path = %req.path,
26	                "incoming request"
27	            );
28	            // Store start time in a header for duration tracking
29	            let start = Instant::now();
30	            req.headers
31	                .insert("x-start-time", format!("{:?}", start.elapsed()));
32	            // We store the start time as a nanosecond timestamp
33	            let nanos = std::time::SystemTime::now()
34	                .duration_since(std::time::UNIX_EPOCH)
35	                .unwrap_or_default()
36	                .as_nanos();
37	            req.headers.insert("x-request-start", nanos.to_string());
38	            Ok(req)
39	        })
40	    }
