44	        req: &'a Request,
45	        resp: Response,
46	    ) -> Pin<Box<dyn Future<Output = Response> + Send + 'a>> {
47	        Box::pin(async move {
48	            let start_nanos: u128 = req
49	                .header("x-request-start")
50	                .and_then(|s| s.parse().ok())
51	                .unwrap_or(0);
52	            let now_nanos = std::time::SystemTime::now()
53	                .duration_since(std::time::UNIX_EPOCH)
54	                .unwrap_or_default()
55	                .as_nanos();
56	            let duration_ms = (now_nanos.saturating_sub(start_nanos)) / 1_000_000;
57	
58	            tracing::info!(
59	                request_id = %req.request_id,
60	                method = %req.method,
61	                path = %req.path,
62	                status = resp.status.0,
63	                duration_ms = duration_ms,
64	                "request completed"
65	            );
66	            resp
67	        })
68	    }

