 14	fn render_template(template: &str, context: &Value) -> Result<String, NanowebError> {
 15	    let mut output = String::new();
 16	    let bytes = template.as_bytes();
 17	    let mut pos = 0;
 18	
 19	    while pos < bytes.len() {
 20	        let start = match find_pattern(bytes, pos, b"{{") {
 21	            Some(s) => s,
 22	            None => {
 23	                output.push_str(&template[pos..]);
 24	                break;
 25	            }
 26	        };
 27	
 28	        output.push_str(&template[pos..start]);
 29	
 30	        let end = match find_pattern(bytes, start + 2, b"}}") {
 31	            Some(e) => e,
 32	            None => {
 33	                output.push_str(&template[start..]);
 34	                break;
 35	            }
 36	        };
 37	
 38	        let tag = template[start + 2..end].trim();
 39	
 40	        if tag.starts_with('#') {
 41	            let section_name = tag[1..].trim();
 42	            let section_end = find_section_end(template, end + 2, section_name)?;
 43	            let section_body = &template[end + 2..section_end];
 44	
 45	            if let Some(val) = context_value(context, section_name) {
 46	                match val {
 47	                    Value::Array(arr) => {
 48	                        for item in arr {
 49	                            output.push_str(&render_template(section_body, item)?);
 50	                        }
 51	                    }
 52	                    Value::Bool(true) => {
 53	                        output.push_str(&render_template(section_body, context)?);
 54	                    }
 55	                    Value::Null => {}
 56	                    _ => {
 57	                        output.push_str(&render_template(section_body, context)?);
 58	                    }
 59	                }
 60	            }
 61	
 62	            pos = advance_past_close_tag(bytes, section_end, section_name)?;
 63	        } else if tag.starts_with('^') {
 64	            let section_name = tag[1..].trim();
 65	            let section_end = find_section_end(template, end + 2, section_name)?;
 66	            let section_body = &template[end + 2..section_end];
 67	
 68	            if let Some(val) = context_value(context, section_name) {
 69	                match val {
 70	                    Value::Null | Value::Bool(false) => {
 71	                        output.push_str(&render_template(section_body, context)?);
 72	                    }
 73	                    Value::Array(arr) if arr.is_empty() => {
 74	                        output.push_str(&render_template(section_body, context)?);
 75	                    }
 76	                    _ => {}
 77	                }
 78	            } else {
 79	                output.push_str(&render_template(section_body, context)?);
 80	            }
 81	
 82	            pos = advance_past_close_tag(bytes, section_end, section_name)?;
 83	        } else if tag.starts_with('!') {
 84	            pos = end + 2;
 85	        } else if tag.starts_with('{') && tag.ends_with('}') {
 86	            let name = tag.trim_matches('{').trim_matches('}').trim();
 87	            if let Some(val) = context_value(context, name) {
 88	                output.push_str(&value_to_string(val));
 89	            }
 90	            pos = end + 2;
 91	        } else {
 92	            let name = tag;
 93	            if let Some(val) = context_value(context, name) {
 94	                output.push_str(&html_escape(&value_to_string(val)));
 95	            }
 96	            pos = end + 2;
 97	        }
 98	    }
 99	
100	    Ok(output)

118	fn find_section_end(
119	    template: &str,
120	    start: usize,
121	    section_name: &str,
122	) -> Result<usize, NanowebError> {
123	    let mut depth = 1;
124	    let mut pos = start;
125	    let bytes = template.as_bytes();
126	
127	    while pos < bytes.len() {
128	        if let Some(tag_start) = find_pattern(bytes, pos, b"{{") {
129	            if let Some(tag_end) = find_pattern(bytes, tag_start + 2, b"}}") {
130	                let tag = template[tag_start + 2..tag_end].trim();
131	
132	                if tag == format!("#{}", section_name) {
133	                    depth += 1;
134	                } else if tag == format!("/{}", section_name) {
135	                    depth -= 1;
136	                    if depth == 0 {
137	                        return Ok(tag_start);
138	                    }
139	                }
140	                pos = tag_end + 2;
141	            } else {
142	                break;
143	            }
144	        } else {
145	            break;
146	        }
147	    }
148	
149	    Err(NanowebError::Template(format!(
150	        "Unclosed section: {}",
151	        section_name
152	    )))
153	}
