155	fn context_value<'a>(context: &'a Value, key: &str) -> Option<&'a Value> {
156	    let parts: Vec<&str> = key.split('.').collect();
157	    let mut current = context;
158	    for part in parts {
159	        match current {
160	            Value::Object(map) => {
161	                current = map.get(part)?;
162	            }
163	            _ => return None,
164	        }
165	    }
166	    Some(current)
167	}

