70	
71	        // Wait for in-flight requests with timeout
72	        let timeout = std::time::Duration::from_secs(self.config.graceful_timeout_s);
73	        let _ = tokio::time::timeout(timeout, async {
74	            // Give connections time to finish
75	            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
76	        })
77	        .await;
78	
79	        tracing::info!("Server shut down cleanly");
80	        Ok(())

