 38	
 39	impl RequestParser {
 40	    /// Try to parse the request head from `buf`. Returns `Ok(Some(head))` if a
 41	    /// complete head is present, `Ok(None)` if more data is required, or an
 42	    /// `Err` for malformed requests.
 43	    pub fn parse_head(buf: &[u8]) -> ParseResult<Option<ParsedHead>> {
 44	        if buf.len() > MAX_HEAD_SIZE {
 45	            return Err(ParseError("request head too large".into()));
 46	        }
 47	        let head_end = match find_double_crlf(buf) {
 48	            Some(idx) => idx,
 49	            None => return Ok(None),
 50	        };
 51	        let head = &buf[..head_end];
 52	        let head_str =
 53	            std::str::from_utf8(head).map_err(|_| ParseError("non-utf8 in request head".into()))?;
 54	
 55	        let mut lines = head_str.split("\r\n");
 56	        let request_line = lines
 57	            .next()
 58	            .ok_or_else(|| ParseError("missing request line".into()))?;
 59	        let mut parts = request_line.split(' ');
 60	        let method_s = parts
 61	            .next()
 62	            .ok_or_else(|| ParseError("missing method".into()))?;
 63	        let target = parts
 64	            .next()
 65	            .ok_or_else(|| ParseError("missing target".into()))?;
 66	        let version_s = parts
 67	            .next()
 68	            .ok_or_else(|| ParseError("missing http version".into()))?;
 69	        if parts.next().is_some() {
 70	            return Err(ParseError("malformed request line".into()));
 71	        }
 72	        let method = Method::from_str(method_s).map_err(ParseError)?;
 73	        if target.is_empty() || !target.starts_with('/') && target != "*" {
 74	            return Err(ParseError("invalid request target".into()));
 75	        }
 76	        let version = match version_s {
 77	            "HTTP/1.0" => Version::Http10,
 78	            "HTTP/1.1" => Version::Http11,
 79	            other => return Err(ParseError(format!("unsupported version: {}", other))),
 80	        };
 81	
 82	        let mut headers = HeaderMap::new();
 83	        for line in lines {
 84	            if line.is_empty() {
 85	                break;
 86	            }
 87	            let colon = line
 88	                .find(':')
 89	                .ok_or_else(|| ParseError("malformed header line".into()))?;
 90	            let name = &line[..colon];
 91	            if name.is_empty() || !is_valid_token(name) {
 92	                return Err(ParseError("invalid header name".into()));
 93	            }
 94	            let value = line[colon + 1..].trim();
 95	            headers.append(name, value);
 96	        }
 97	
 98	        let mut body_kind = BodyKind::None;
 99	        let te = headers.get("Transfer-Encoding").map(|s| s.to_string());
100	        let cl = headers.get("Content-Length").map(|s| s.to_string());
101	        if let Some(te) = te {
102	            if te.to_ascii_lowercase().contains("chunked") {
103	                if cl.is_some() {
104	                    return Err(ParseError(
105	                        "both Content-Length and Transfer-Encoding present".into(),
106	                    ));
107	                }
108	                body_kind = BodyKind::Chunked;
109	            } else {
110	                return Err(ParseError(format!("unsupported Transfer-Encoding: {}", te)));
111	            }
112	        } else if let Some(cl) = cl {
113	            let n: usize = cl
114	                .trim()
115	                .parse()
116	                .map_err(|_| ParseError("invalid Content-Length".into()))?;
117	            body_kind = BodyKind::ContentLength(n);
118	        }
119	
120	        let keep_alive = match version {
121	            Version::Http11 => headers
122	                .get("Connection")
123	                .map(|c| !c.eq_ignore_ascii_case("close"))
124	                .unwrap_or(true),
125	            Version::Http10 => headers
126	                .get("Connection")
127	                .map(|c| c.eq_ignore_ascii_case("keep-alive"))
128	                .unwrap_or(false),
129	        };
130	
131	        Ok(Some(ParsedHead {
132	            method,
133	            target: target.to_string(),
134	            version,
135	            headers,
136	            body_kind,
137	            keep_alive,
138	            head_len: head_end + 4,
139	        }))
140	    }

