236	                let resp = build_error_response(StatusCode::BAD_REQUEST, "request head too large");
237	                write_response(&mut stream, &resp, false, false).await.ok();
238	                return Ok(());
239	            }
240	            tokio::select! {
241	                _ = shutdown.changed() => {
242	                    if *shutdown.borrow() && buf.is_empty() {
243	                        return Ok(());
244	                    }
245	                }
246	                n = stream.read(&mut tmp) => {
247	                    let n = match n {
248	                        Ok(0) => return Ok(()),
249	                        Ok(n) => n,
250	                        Err(_) => return Ok(()),
251	                    };
252	                    buf.extend_from_slice(&tmp[..n]);
253	                }
254	            }
255	        };
256	
257	        let body = match read_body(&mut stream, &mut buf, &head).await {
258	            Ok(b) => b,
259	            Err(e) => {
260	                let resp = build_error_response(StatusCode::BAD_REQUEST, &e.to_string());
261	                write_response(&mut stream, &resp, false, false).await.ok();
262	                return Ok(());
263	            }
264	        };
265	
266	        let keep_alive = head.keep_alive;
267	        let head_method = head.method;
268	        let request = build_full_request(head, body, addr);
269	        let head_request_was_head = request.method == Method::Head;
270	        let is_options = request.method == Method::Options;
271	
272	        let started = Instant::now();
273	        let route_label;
274	        let resp_status;
275	        let mut resp;
276	
277	        // Dispatch: routes first, then static files, then 404.
278	        let lookup_method = if head_method == Method::Head {
279	            Method::Get
280	        } else {
281	            head_method
282	        };
283	        let _ = lookup_method;
284	        let lookup = app.router.lookup(request.method, &request.path);
285	        match lookup {
286	            Lookup::Found(m) => {
287	                let mut req = request.clone();
288	                for (k, v) in m.params.iter() {
289	                    req.params.insert(k.clone(), v.clone());
290	                }
291	                let route_name = req.path.clone();
292	                route_label = route_name;
293	                let head_fb = m.head_fallback;
294	                let handler = m.handler.clone();
295	                resp = middleware::run(&app.chain, req, |r| async move { handler.handle(r).await })

