128	    pub fn add(&mut self, method: Method, path: &str, handler: SharedHandler) {
129	        let segments: Vec<&str> = split_path(path);
130	        let mut node = &mut self.root;
131	        let mut i = 0;
132	        while i < segments.len() {
133	            let seg = segments[i];
134	            if let Some(rest) = seg.strip_prefix('*') {
135	                // wildcard MUST be the last segment
136	                assert!(
137	                    i == segments.len() - 1,
138	                    "wildcard segment must be last in path"
139	                );
140	                let name = rest.to_string();
141	                let entry = node
142	                    .wildcard
143	                    .get_or_insert_with(|| (name.clone(), MethodHandlers::default()));
144	                entry.0 = name;
145	                entry.1.insert(method, handler);
146	                return;
147	            } else if let Some(rest) = seg.strip_prefix(':') {
148	                let name = rest.to_string();
149	                if node.param.is_none() {
150	                    node.param = Some((name.clone(), Box::new(TrieNode::default())));
151	                } else if let Some((existing, _)) = &node.param {
152	                    assert_eq!(existing, &name, "conflicting parameter name");
153	                }
154	                let next = &mut node.param.as_mut().unwrap().1;
155	                node = next;
156	            } else {
157	                let entry = node
158	                    .literals
159	                    .entry(seg.to_string())
160	                    .or_insert_with(TrieNode::default);
161	                node = entry;
162	            }
163	            i += 1;
164	        }
165	        node.handlers.insert(method, handler);
166	    }

168	    pub fn lookup<'a>(&'a self, method: Method, path: &str) -> Lookup<'a> {
169	        let segments: Vec<&str> = split_path(path);
170	        let mut params: Vec<(String, String)> = Vec::new();
171	        return walk(&self.root, &segments, 0, &mut params, method);
172	
173	        #[allow(clippy::too_many_arguments)]
174	        fn walk<'a>(
175	            node: &'a TrieNode,
176	            segments: &[&str],
177	            depth: usize,
178	            params: &mut Vec<(String, String)>,
179	            method: Method,
180	        ) -> Lookup<'a> {
181	            if depth == segments.len() {
182	                if let Some(h) = node.handlers.get(method) {
183	                    return Lookup::Found(Match {
184	                        handler: h,
185	                        params: std::mem::take(params),
186	                        head_fallback: false,
187	                    });
188	                }
189	                if method == Method::Head {
190	                    if let Some(h) = node.handlers.get(Method::Get) {
191	                        return Lookup::Found(Match {
192	                            handler: h,
193	                            params: std::mem::take(params),
194	                            head_fallback: true,
195	                        });
196	                    }
197	                }
198	                if !node.handlers.is_empty() {
199	                    return Lookup::MethodNotAllowed(AllowedMatch {
200	                        allowed: node.handlers.allowed(),
201	                        params: std::mem::take(params),
202	                    });
203	                }
204	                // fallback to wildcard at this node with empty path
205	                if let Some((name, h)) = &node.wildcard {
206	                    if let Some(handler) = h.get(method) {
207	                        params.push((name.clone(), String::new()));
208	                        return Lookup::Found(Match {
209	                            handler,
210	                            params: std::mem::take(params),
211	                            head_fallback: false,
212	                        });
213	                    }
214	                    if method == Method::Head {
215	                        if let Some(handler) = h.get(Method::Get) {
216	                            params.push((name.clone(), String::new()));
217	                            return Lookup::Found(Match {
218	                                handler,
219	                                params: std::mem::take(params),
220	                                head_fallback: true,
221	                            });
222	                        }
223	                    }
224	                    return Lookup::MethodNotAllowed(AllowedMatch {
225	                        allowed: h.allowed(),
226	                        params: std::mem::take(params),
227	                    });
228	                }
229	                return Lookup::NotFound;
230	            }
231	            let seg = segments[depth];
232	            // literal first
233	            if let Some(child) = node.literals.get(seg) {
234	                let saved = params.clone();
235	                let sub = walk(child, segments, depth + 1, params, method);
236	                if matches!(sub, Lookup::Found(_) | Lookup::MethodNotAllowed(_)) {
237	                    return sub;
238	                }
239	                *params = saved;
240	            }
241	            // param
242	            if let Some((name, child)) = &node.param {
243	                let saved = params.clone();
244	                params.push((name.clone(), seg.to_string()));
245	                let sub = walk(child, segments, depth + 1, params, method);
246	                if matches!(sub, Lookup::Found(_) | Lookup::MethodNotAllowed(_)) {
247	                    return sub;
248	                }
249	                *params = saved;
250	            }
251	            // wildcard
252	            if let Some((name, h)) = &node.wildcard {
253	                let rest = segments[depth..].join("/");
254	                params.push((name.clone(), rest));
255	                if let Some(handler) = h.get(method) {
256	                    return Lookup::Found(Match {
257	                        handler,
258	                        params: std::mem::take(params),
259	                        head_fallback: false,
260	                    });
261	                }
262	                if method == Method::Head {
263	                    if let Some(handler) = h.get(Method::Get) {
264	                        return Lookup::Found(Match {
265	                            handler,
266	                            params: std::mem::take(params),
267	                            head_fallback: true,
268	                        });
269	                    }
270	                }
271	                return Lookup::MethodNotAllowed(AllowedMatch {
272	                    allowed: h.allowed(),
273	                    params: std::mem::take(params),
274	                });
275	            }
276	            Lookup::NotFound
277	        }
278	    }
279	}
