295	                resp = middleware::run(&app.chain, req, |r| async move { handler.handle(r).await })
296	                    .await;
297	                if head_fb {
298	                    resp.body.clear();
299	                }
300	            }
301	            Lookup::MethodNotAllowed(am) => {
302	                if is_options {
303	                    let allow = am
304	                        .allowed
305	                        .iter()
306	                        .map(|m| m.as_str())
307	                        .collect::<Vec<_>>()
308	                        .join(", ");
309	                    let mut r = Response::new(StatusCode::NO_CONTENT);
310	                    r.headers.insert("Allow", allow);
311	                    resp =
312	                        middleware::run(&app.chain, request.clone(), |_r| async move { r }).await;
313	                } else {
314	                    let allow = am
315	                        .allowed
316	                        .iter()
317	                        .map(|m| m.as_str())
318	                        .collect::<Vec<_>>()
319	                        .join(", ");
320	                    let mut r = Response::new(StatusCode::METHOD_NOT_ALLOWED);
321	                    r.headers.insert("Allow", allow);
322	                    r.body = b"method not allowed".to_vec();
323	                    resp = r;
324	                }
325	                route_label = request.path.clone();
326	            }
327	            Lookup::NotFound => {
328	                // Static fallback.
329	                if let Some(sf) = &app.static_files {
330	                    if let Some(rest) = request.path.strip_prefix("/static/") {
331	                        let r = sf.serve(&request, rest).await;
332	                        let r = middleware::run(&app.chain, request.clone(), |_r| async move { r })
333	                            .await;
334	                        resp = r;
335	                    } else {
336	                        let mut r = Response::new(StatusCode::NOT_FOUND);
337	                        r.body = b"not found".to_vec();
338	                        resp = r;
339	                    }
340	                } else {
341	                    let mut r = Response::new(StatusCode::NOT_FOUND);
342	                    r.body = b"not found".to_vec();
343	                    resp = r;
344	                }
345	                route_label = request.path.clone();
346	            }
347	        }
348	
349	        // Always set X-Request-Id.
350	        if !request.request_id.is_empty() {
351	            resp.headers
352	                .insert("X-Request-Id", request.request_id.clone());
353	        }
354	
355	        resp_status = resp.status.as_u16();
356	        let elapsed = started.elapsed().as_secs_f64();
357	        app.metrics
358	            .record(head_method, resp_status, &route_label, elapsed);
359	
360	        write_response(&mut stream, &resp, head_request_was_head, false).await?;

368	fn build_full_request(head: ParsedHead, body: Vec<u8>, addr: SocketAddr) -> Request {
369	    let target = head.target.clone();
370	    let mut req = Request::new(head.method, target, head.version);
371	    req.headers = head.headers;
372	    req.body = body;
373	    req.remote_addr = Some(addr);
374	    req.request_id = req
375	        .header("X-Request-Id")
376	        .map(|s| s.to_string())
377	        .unwrap_or_else(generate_request_id);
378	    req
379	}
380	
381	fn generate_request_id() -> String {
382	    let mut buf = [0u8; 12];
383	    rand::thread_rng().fill_bytes(&mut buf);
384	    hex::encode(buf)
385	}

