 4	/// A minimal mustache-like template engine. Supports:
 5	/// - `{{name}}` interpolation (HTML escape by default)
 6	/// - `{{{name}}}` raw interpolation (no escape)
 7	/// - `{{#section}}...{{/section}}` (truthy / iteration)
 8	/// - `{{^inverse}}...{{/inverse}}` (rendered when value is falsy)
 9	#[derive(Default, Clone)]
10	pub struct Renderer;
