17	    pub fn render(&self, template: &str, context: &Value) -> Result<String> {
18	        let tokens = tokenize(template)?;
19	        let (rendered, _consumed) = render_tokens(&tokens, 0, &[context], false)?;
20	        Ok(rendered)
21	    }

33	fn tokenize(s: &str) -> Result<Vec<Token>> {
34	    let bytes = s.as_bytes();
35	    let mut tokens = Vec::new();
36	    let mut i = 0;
37	    let mut last = 0;
38	    while i + 1 < bytes.len() {
39	        if bytes[i] == b'{' && bytes[i + 1] == b'{' {
40	            if last < i {
41	                tokens.push(Token::Text(s[last..i].to_string()));
42	            }
43	            // Determine whether triple-stash
44	            let triple = i + 2 < bytes.len() && bytes[i + 2] == b'{';
45	            let open = if triple { i + 3 } else { i + 2 };
46	            let close_pat: &[u8] = if triple { b"}}}" } else { b"}}" };
47	            let mut close = None;
48	            let mut j = open;
49	            while j + close_pat.len() <= bytes.len() {
50	                if &bytes[j..j + close_pat.len()] == close_pat {
51	                    close = Some(j);
52	                    break;
53	                }
54	                j += 1;
55	            }
56	            let close = close.ok_or_else(|| NanowebError::Template("unterminated tag".into()))?;
57	            let inner = s[open..close].trim();
58	            let consumed_to = close + close_pat.len();
59	            if triple {
60	                tokens.push(Token::Var {
61	                    name: inner.to_string(),
62	                    escape: false,
63	                });
64	            } else if let Some(name) = inner.strip_prefix('#') {
65	                tokens.push(Token::SectionOpen(name.trim().to_string()));
66	            } else if let Some(name) = inner.strip_prefix('^') {
67	                tokens.push(Token::InverseOpen(name.trim().to_string()));
68	            } else if let Some(name) = inner.strip_prefix('/') {
69	                tokens.push(Token::SectionClose(name.trim().to_string()));
70	            } else if let Some(name) = inner.strip_prefix('&') {
71	                tokens.push(Token::Var {
72	                    name: name.trim().to_string(),
73	                    escape: false,
74	                });
75	            } else if inner.starts_with('!') {
76	                // comment
77	            } else {
78	                tokens.push(Token::Var {
79	                    name: inner.to_string(),
80	                    escape: true,
81	                });
82	            }
83	            i = consumed_to;
84	            last = consumed_to;
85	        } else {
86	            i += 1;
87	        }
88	    }
89	    if last < bytes.len() {
90	        tokens.push(Token::Text(s[last..].to_string()));
91	    }
92	    Ok(tokens)

 95	fn render_tokens(
 96	    tokens: &[Token],
 97	    start: usize,
 98	    stack: &[&Value],
 99	    inside_inverted: bool,
100	) -> Result<(String, usize)> {
101	    let _ = inside_inverted;
102	    let mut out = String::new();
103	    let mut i = start;
104	    while i < tokens.len() {
105	        match &tokens[i] {
106	            Token::Text(t) => out.push_str(t),
107	            Token::Var { name, escape } => {
108	                let v = lookup(stack, name);
109	                let s = stringify(v);
110	                if *escape {
111	                    out.push_str(&html_escape(&s));
112	                } else {
113	                    out.push_str(&s);
114	                }
115	            }
116	            Token::SectionOpen(name) => {
117	                let block_start = i + 1;
118	                let block_end = find_close(tokens, block_start, name)?;
119	                let v = lookup(stack, name);
120	                if let Some(items) = as_array(v) {
121	                    let segment_tokens = &tokens[block_start..block_end];
122	                    for item in items {
123	                        let mut new_stack: Vec<&Value> = stack.to_vec();
124	                        new_stack.insert(0, item);
125	                        let (rendered, _) = render_tokens(segment_tokens, 0, &new_stack, false)?;
126	                        out.push_str(&rendered);
127	                    }
128	                } else if is_truthy(v) {
129	                    let segment_tokens = &tokens[block_start..block_end];
130	                    let mut new_stack: Vec<&Value> = stack.to_vec();
131	                    if let Some(obj) = v {
132	                        if obj.is_object() {
133	                            new_stack.insert(0, obj);
134	                        }
135	                    }
136	                    let (rendered, _) = render_tokens(segment_tokens, 0, &new_stack, false)?;
137	                    out.push_str(&rendered);
138	                }
139	                i = block_end;
140	            }
141	            Token::InverseOpen(name) => {
142	                let block_start = i + 1;
143	                let block_end = find_close(tokens, block_start, name)?;
144	                let v = lookup(stack, name);
145	                let truthy = if let Some(arr) = as_array(v) {
146	                    !arr.is_empty()
147	                } else {
148	                    is_truthy(v)
149	                };
150	                if !truthy {
151	                    let segment_tokens = &tokens[block_start..block_end];
152	                    let (rendered, _) = render_tokens(segment_tokens, 0, stack, true)?;
153	                    out.push_str(&rendered);
154	                }
155	                i = block_end;
156	            }
157	            Token::SectionClose(_) => {
158	                return Ok((out, i));
159	            }
160	        }
161	        i += 1;
162	    }
163	    Ok((out, i))

