108	fn walk<'a>(
109	    node: &'a Node,
110	    segs: &[&str],
111	    idx: usize,
112	    params: &mut HashMap<String, String>,
113	) -> Option<&'a Node> {
114	    if idx == segs.len() {
115	        return Some(node);
116	    }
117	    let seg = segs[idx];
118	    if let Some(child) = node.literal.get(seg) {
119	        if let Some(n) = walk(child, segs, idx + 1, params) {
120	            return Some(n);
121	        }
122	    }
123	    if let Some((name, child)) = &node.param {
124	        params.insert(name.clone(), seg.to_string());
125	        if let Some(n) = walk(child, segs, idx + 1, params) {
126	            return Some(n);
127	        }
128	        params.remove(name);
129	    }
130	    if let Some((name, child)) = &node.wildcard {
131	        let rest = segs[idx..].join("/");
132	        params.insert(name.clone(), rest);
133	        return Some(child);
134	    }
135	    None
136	}
