49	    pub fn route(&self, method: Method, pattern: &str, handler: Handler) {
50	        let segments = split_path(pattern);
51	        let mut root = self.root.write().expect("router lock poisoned");
52	        let mut node: &mut Node = &mut root;
53	        for (i, seg) in segments.iter().enumerate() {
54	            if let Some(name) = seg.strip_prefix(':') {
55	                let exists = node.param.is_some();
56	                if !exists {
57	                    node.param = Some((name.to_string(), Box::new(Node::new())));
58	                }
59	                node = node.param.as_mut().expect("param node").1.as_mut();
60	            } else if let Some(name) = seg.strip_prefix('*') {
61	                if i + 1 != segments.len() {
62	                    panic!("wildcard segment must be last in route pattern");
63	                }
64	                if node.wildcard.is_none() {
65	                    node.wildcard = Some((name.to_string(), Box::new(Node::new())));
66	                }
67	                node = node.wildcard.as_mut().expect("wildcard node").1.as_mut();
68	            } else {
69	                node = node
70	                    .literal
71	                    .entry((*seg).to_string())
72	                    .or_insert_with(Node::new);
73	            }
74	        }
75	        node.handlers.insert(method, handler);

