23	/// `Next` represents the rest of the chain (later middleware + the handler).
24	pub struct Next<'a> {
25	    chain: &'a [Arc<dyn Middleware>],
26	    handler: &'a HandlerFn,
27	}
28	
29	impl<'a> Next<'a> {
30	    pub fn new(chain: &'a [Arc<dyn Middleware>], handler: &'a HandlerFn) -> Self {
31	        Self { chain, handler }
32	    }
33	
34	    pub fn run<'r>(self, req: &'r mut Request) -> BoxFuture<'r, Result<Response>>
35	    where
36	        'a: 'r,
37	    {
38	        if let Some((first, rest)) = self.chain.split_first() {
39	            let next = Next::new(rest, self.handler);
40	            first.handle(req, next)
41	        } else {
42	            (self.handler)(req)
43	        }
44	    }
45	}
