50	/// returning a response without calling `next.run(req)`, or mutate the
51	/// response returned by `next.run(req)` before returning.
52	pub trait Middleware: Send + Sync {
53	    fn handle<'a>(
54	        &'a self,
55	        req: &'a mut Request,
56	        next: Next<'a>,
57	    ) -> BoxFuture<'a, Result<Response>>;
58	}
