299	    use tokio::signal::unix::{signal, SignalKind};
300	    let mut sigterm = signal(SignalKind::terminate()).expect("install SIGTERM handler");
301	    let mut sigint = signal(SignalKind::interrupt()).expect("install SIGINT handler");
302	    tokio::select! {
303	        _ = sigterm.recv() => {},
304	        _ = sigint.recv() => {},
305	    }
306	}

310	async fn accept_loop_plain(
311	    listener: TcpListener,
312	    app: Arc<App>,
313	    shutdown: Arc<Notify>,
314	) -> Result<()> {
315	    let active = Arc::new(tokio::sync::Semaphore::new(0)); // tracks in-flight connections
316	    let active_count = Arc::new(std::sync::atomic::AtomicUsize::new(0));
317	    let shutdown_inner = shutdown.clone();
318	    loop {
319	        tokio::select! {
320	            _ = shutdown_inner.notified() => {
321	                log::info("plain listener stopping accept loop");
322	                drop(listener);
323	                break;
324	            }
325	            res = listener.accept() => {
326	                let (stream, peer) = match res {
327	                    Ok(v) => v,
328	                    Err(e) => {
329	                        log::error(&format!("accept error: {}", e));
330	                        continue;
331	                    }
332	                };
333	                let app = app.clone();
334	                let active_count = active_count.clone();
335	                active_count.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
336	                tokio::spawn(async move {
337	                    if let Err(e) = handle_connection(stream, peer, app).await {
338	                        log::debug(&format!("connection ended: {}", e));
339	                    }
340	                    active_count.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
341	                });
342	            }
343	        }
344	    }
345	    drop(active);
346	    // Wait for in-flight connections to complete (bounded by graceful timeout).
347	    let deadline = Instant::now() + app.graceful_timeout;
348	    while active_count.load(std::sync::atomic::Ordering::SeqCst) > 0 {
349	        if Instant::now() >= deadline {
350	            log::warn("graceful shutdown deadline reached; aborting in-flight connections");
351	            break;
352	        }
353	        tokio::time::sleep(Duration::from_millis(50)).await;
354	    }
355	    Ok(())

