21	fn tokenize(template: &str) -> Result<Vec<Token>> {
22	    let mut tokens = Vec::new();
23	    let bytes = template.as_bytes();
24	    let mut i = 0;
25	    let mut last = 0;
26	    while i + 1 < bytes.len() {
27	        if bytes[i] == b'{' && bytes[i + 1] == b'{' {
28	            if i > last {
29	                tokens.push(Token::Text(template[last..i].to_string()));
30	            }
31	            let triple = i + 2 < bytes.len() && bytes[i + 2] == b'{';
32	            let open_len = if triple { 3 } else { 2 };
33	            let close_pat: &[u8] = if triple { b"}}}" } else { b"}}" };
34	            let mut j = i + open_len;
35	            let mut found = None;
36	            while j + close_pat.len() <= bytes.len() {
37	                if &bytes[j..j + close_pat.len()] == close_pat {
38	                    found = Some(j);
39	                    break;
40	                }
41	                j += 1;
42	            }
43	            let close =
44	                found.ok_or_else(|| NanowebError::Template("unterminated mustache tag".into()))?;
45	            let inner = template[i + open_len..close].trim();
46	            if let Some(name) = inner.strip_prefix('#') {
47	                tokens.push(Token::SectionStart {
48	                    name: name.trim().to_string(),
49	                    inverted: false,
50	                });
51	            } else if let Some(name) = inner.strip_prefix('^') {
52	                tokens.push(Token::SectionStart {
53	                    name: name.trim().to_string(),
54	                    inverted: true,
55	                });
56	            } else if let Some(name) = inner.strip_prefix('/') {
57	                tokens.push(Token::SectionEnd {
58	                    name: name.trim().to_string(),
59	                });
60	            } else if inner.starts_with('!') {
61	                tokens.push(Token::Comment);
62	            } else {
63	                tokens.push(Token::Var {
64	                    name: inner.to_string(),
65	                    escaped: !triple,
66	                });
67	            }
68	            i = close + close_pat.len();
69	            last = i;
70	        } else {
71	            i += 1;
72	        }
73	    }
74	    if last < template.len() {
75	        tokens.push(Token::Text(template[last..].to_string()));
76	    }
77	    Ok(tokens)

138	fn render_tokens<'a>(tokens: &[Token], stack: &mut Vec<&'a Value>, out: &mut String) -> Result<()> {
139	    let mut i = 0;
140	    while i < tokens.len() {
141	        match &tokens[i] {
142	            Token::Text(t) => {
143	                out.push_str(t);
144	                i += 1;
145	            }
146	            Token::Comment => {
147	                i += 1;
148	            }
149	            Token::Var { name, escaped } => {
150	                let s = lookup(stack, name).map(render_value).unwrap_or_default();
151	                if *escaped {
152	                    out.push_str(&html_escape(&s));
153	                } else {
154	                    out.push_str(&s);
155	                }
156	                i += 1;
157	            }
158	            Token::SectionStart { name, inverted } => {
159	                let end = find_section_end(tokens, i, name)?;
160	                let inner = &tokens[i + 1..end];
161	                let v = lookup(stack, name);
162	                let is_truthy = v.map(truthy).unwrap_or(false);
163	                if *inverted {
164	                    if !is_truthy {
165	                        render_tokens(inner, stack, out)?;
166	                    }
167	                } else if let Some(v) = v {
168	                    if is_truthy {
169	                        match v {
170	                            Value::Array(items) => {
171	                                for item in items {
172	                                    stack.push(item);
173	                                    let r = render_tokens(inner, stack, out);
174	                                    stack.pop();
175	                                    r?;
176	                                }
177	                            }
178	                            Value::Object(_) => {
179	                                stack.push(v);
180	                                let r = render_tokens(inner, stack, out);
181	                                stack.pop();
182	                                r?;
183	                            }
184	                            _ => {
185	                                render_tokens(inner, stack, out)?;
186	                            }
187	                        }
188	                    }
189	                }
190	                i = end + 1;
191	            }
192	            Token::SectionEnd { name } => {
193	                return Err(NanowebError::Template(format!(
194	                    "unexpected section end: {}",
195	                    name
196	                )));
197	            }
198	        }
199	    }
200	    Ok(())
201	}
202	
203	fn find_section_end(tokens: &[Token], start: usize, name: &str) -> Result<usize> {
204	    let mut depth = 0usize;
205	    for (j, tok) in tokens.iter().enumerate().skip(start + 1) {
206	        match tok {
207	            Token::SectionStart { name: n, .. } if n == name => depth += 1,
208	            Token::SectionEnd { name: n } if n == name => {
209	                if depth == 0 {
210	                    return Ok(j);
211	                }
212	                depth -= 1;
213	            }
214	            _ => {}
215	        }
216	    }
217	    Err(NanowebError::Template(format!(
218	        "section {} not closed",
219	        name
220	    )))
221	}

