13	struct Bucket {
14	    tokens: f64,
15	    last: Instant,
16	}
17	
18	pub struct RateLimitMiddleware {
19	    capacity: f64,
20	    refill_per_sec: f64,
21	    buckets: Mutex<HashMap<String, Bucket>>,
22	}
23	
24	impl RateLimitMiddleware {
25	    pub fn new(capacity: u32, refill_per_sec: f64) -> Self {
26	        Self {
27	            capacity: capacity as f64,
28	            refill_per_sec,
29	            buckets: Mutex::new(HashMap::new()),
30	        }
31	    }
32	
33	    fn allow(&self, ip: &str) -> bool {
34	        let now = Instant::now();
35	        let mut buckets = self.buckets.lock().expect("rate limit lock");
36	        let bucket = buckets.entry(ip.to_string()).or_insert(Bucket {
37	            tokens: self.capacity,
38	            last: now,
39	        });
40	        let elapsed = now.duration_since(bucket.last).as_secs_f64();
41	        bucket.tokens = (bucket.tokens + elapsed * self.refill_per_sec).min(self.capacity);
42	        bucket.last = now;
43	        if bucket.tokens >= 1.0 {
44	            bucket.tokens -= 1.0;
45	            true
46	        } else {
47	            false
48	        }
49	    }

