213	/// Run the HTTP and (optionally) HTTPS listeners until shutdown is requested.
214	pub async fn run(cfg: Config, app: Arc<App>) -> Result<()> {
215	    log::info(&format!("starting nanoweb on {}", cfg.listen));
216	    app.health.set_ready(true);
217	
218	    let shutdown = Arc::new(Notify::new());
219	    let shutdown_signal = shutdown.clone();
220	    let signal_task = tokio::spawn(async move {
221	        wait_for_shutdown_signal().await;
222	        log::info("shutdown signal received");
223	        shutdown_signal.notify_waiters();
224	    });
225	
226	    let mut tasks: Vec<JoinHandle<Result<()>>> = Vec::new();
227	
228	    let plain_addr: SocketAddr = cfg
229	        .listen
230	        .parse()
231	        .map_err(|e| NanowebError::Config(format!("bad listen address {}: {}", cfg.listen, e)))?;
232	    let plain_listener = TcpListener::bind(plain_addr).await?;
233	    log::info(&format!("plain HTTP listening on {}", plain_addr));
234	    let app_plain = app.clone();
235	    let shutdown_plain = shutdown.clone();
236	    tasks.push(tokio::spawn(async move {
237	        accept_loop_plain(plain_listener, app_plain, shutdown_plain).await
238	    }));
239	
240	    if let (Some(cert), Some(key)) = (&cfg.tls_cert, &cfg.tls_key) {
241	        spawn_tls_listener(
242	            &app,
243	            cert.clone(),
244	            key.clone(),
245	            shutdown.clone(),
246	            &mut tasks,
247	        )?;
248	    } else if cfg.tls_cert.is_some() || cfg.tls_key.is_some() {
249	        return Err(NanowebError::Tls(
250	            "both --tls-cert and --tls-key must be supplied for HTTPS".into(),
251	        ));
252	    }
253	
254	    for t in tasks {
255	        match t.await {
256	            Ok(Ok(())) => {}
257	            Ok(Err(e)) => log::error(&format!("listener error: {}", e)),
258	            Err(e) => log::error(&format!("listener join error: {}", e)),
259	        }
260	    }
261	    signal_task.abort();
262	    app.health.set_ready(false);
263	    Ok(())

630	async fn dispatch(app: &App, req: &mut Request) -> Result<Response> {
631	    let start = Instant::now();
632	    let (lookup, allowed) = app.router.lookup(req.method, &req.path);
633	    let response = match lookup {
634	        Some((handler, params)) => {
635	            req.params = params;
636	            let handler = handler.clone();
637	            // Wrap the router handler as our middleware HandlerFn.
638	            let chain = app.middleware.clone();
639	            let route = req.path.clone();
640	            // Dispatch through middleware chain.
641	            // Construct a closure that calls the handler.
642	            let wrapped: Box<HandlerFn> = Box::new(move |r: &mut Request| {
643	                let h = handler.clone();
644	                h(r)
645	            });
646	            crate::middleware::run_chain(&chain, wrapped.as_ref(), req)
647	                .await
648	                .map(|mut resp| {
649	                    // Record metrics.
650	                    app.metrics.record_request(
651	                        req.method.as_str(),
652	                        resp.status.class(),
653	                        &route,
654	                        start.elapsed(),
655	                    );
656	                    if req.method == Method::Head {
657	                        // Body suppression handled at write time.
658	                    }
659	                    resp.headers.insert("server", "nanoweb/0.1");
660	                    resp
661	                })
662	        }
663	        None => {
664	            if !allowed.is_empty() {
665	                if req.method == Method::Options {
666	                    let mut methods: Vec<String> =
667	                        allowed.iter().map(|m| m.as_str().to_string()).collect();
668	                    if !methods.iter().any(|m| m == "OPTIONS") {
669	                        methods.push("OPTIONS".into());
670	                    }
671	                    if !methods.iter().any(|m| m == "HEAD") && allowed.contains(&Method::Get) {
672	                        methods.push("HEAD".into());
673	                    }
674	                    methods.sort();
675	                    methods.dedup();
676	                    let mut resp = Response::new(StatusCode::NO_CONTENT);
677	                    resp.headers.insert("allow", methods.join(", "));
678	                    app.metrics.record_request(
679	                        req.method.as_str(),
680	                        resp.status.class(),
681	                        &req.path,
682	                        start.elapsed(),
683	                    );
684	                    return Ok(resp);
685	                }
686	                let mut methods: Vec<String> =
687	                    allowed.iter().map(|m| m.as_str().to_string()).collect();
688	                methods.sort();
689	                let mut resp =
690	                    Response::new(StatusCode::METHOD_NOT_ALLOWED).text("method not allowed");
691	                resp.headers.insert("allow", methods.join(", "));
692	                app.metrics.record_request(
693	                    req.method.as_str(),
694	                    resp.status.class(),
695	                    &req.path,
696	                    start.elapsed(),
697	                );
698	                Ok(resp)
699	            } else {
700	                let resp = Response::new(StatusCode::NOT_FOUND).text("not found");
701	                app.metrics.record_request(
702	                    req.method.as_str(),
703	                    resp.status.class(),
704	                    &req.path,
705	                    start.elapsed(),
706	                );
707	                Ok(resp)
708	            }
709	        }
710	    };
711	    // Suppress unused.
712	    let _ = parse_query;
713	    response
714	}
