20	pub fn parse_request_head(buf: &[u8]) -> Result<(Request, usize)> {
21	    let head_end =
22	        find_double_crlf(buf).ok_or_else(|| NanowebError::Parse("incomplete head".into()))?;
23	    if head_end > MAX_HEAD_SIZE {
24	        return Err(NanowebError::Parse("head too large".into()));
25	    }
26	    let head = &buf[..head_end];
27	    let mut lines = split_crlf(head);
28	    let start_line = lines
29	        .next()
30	        .ok_or_else(|| NanowebError::Parse("empty start-line".into()))?;
31	    let (method, target, version) = parse_request_line(start_line)?;
32	
33	    let mut headers = Headers::new();
34	    for line in lines {
35	        if line.is_empty() {
36	            continue;
37	        }
38	        let (name, value) = parse_header_line(line)?;
39	        headers.append(name, value);
40	    }
41	
42	    let (path, query) = match target.find('?') {
43	        Some(i) => (target[..i].to_string(), target[i + 1..].to_string()),
44	        None => (target.to_string(), String::new()),
45	    };
46	
47	    let mut req = Request::new();
48	    req.method = method;
49	    req.target = target.to_string();
50	    req.path = path;
51	    req.query = query;
52	    req.version = version;
53	    req.headers = headers;
54	    Ok((req, head_end + 4))
55	}

