406	    let mut buf: Vec<u8> = Vec::with_capacity(8 * 1024);
407	    let mut tmp = [0u8; 8 * 1024];
408	
409	    loop {
410	        // Read request head into buffer.
411	        let head_used;
412	        let request_partial = loop {
413	            // Try to find an end-of-head in current buf.
414	            if let Some(end) = find_double_crlf(&buf) {
415	                match parse_request_head(&buf[..end + 4]) {
416	                    Ok((req, used)) => {
417	                        head_used = used;
418	                        break req;
419	                    }
420	                    Err(e) => {
421	                        let resp = Response::new(StatusCode::BAD_REQUEST)
422	                            .text(format!("{}", e))
423	                            .header("connection", "close");
424	                        stream.write_all(&resp.to_bytes(false)).await?;
425	                        stream.flush().await?;
426	                        return Ok(());
427	                    }
428	                }
429	            }
430	            if buf.len() > crate::http::parser::MAX_HEAD_SIZE {
431	                let resp = Response::new(StatusCode::BAD_REQUEST).text("head too large");
432	                stream.write_all(&resp.to_bytes(false)).await?;
433	                stream.flush().await?;
434	                return Ok(());
435	            }
436	            let n = stream.read(&mut tmp).await?;
437	            if n == 0 {
438	                return Ok(());
439	            }
440	            buf.extend_from_slice(&tmp[..n]);
441	        };

