260	async fn handle_stream<S>(
261	    app: Arc<App>,
262	    stream: S,
263	    peer: SocketAddr,
264	    mut shutdown_rx: watch::Receiver<bool>,
265	) -> Result<(), NanowebError>
266	where
267	    S: AsyncRead + AsyncWrite + Unpin,
268	{
269	    let (rd, mut wr) = tokio::io::split(stream);
270	    let mut reader = BufReader::new(rd);
271	    loop {
272	        if *shutdown_rx.borrow() {
273	            break;
274	        }
275	        let req = tokio::select! {
276	            r = read_request(&mut reader) => r,
277	            _ = shutdown_rx.changed() => { break; }
278	        };
279	        let mut req = match req {
280	            Ok(Some(r)) => r,
281	            Ok(None) => break,
282	            Err(e) => {
283	                let mut bad = Response::new(StatusCode::BAD_REQUEST);
284	                bad.body = format!("bad request: {}\n", e).into_bytes();
285	                bad.headers
286	                    .insert("Content-Type", "text/plain; charset=utf-8");
287	                bad.headers.insert("Connection", "close");
288	                let _ = wr.write_all(&write_response(&bad, false)).await;
289	                break;
290	            }
291	        };
292	        req.remote_addr = Some(peer);
293	        req.request_id = new_request_id();
294	        let want_close = req
295	            .header("connection")
296	            .map(|h| h.eq_ignore_ascii_case("close"))
297	            .unwrap_or(false);
298	        let resp = process(&app, &mut req).await;

 16	pub async fn read_request<R>(stream: &mut BufReader<R>) -> Result<Option<Request>, NanowebError>
 17	where
 18	    R: tokio::io::AsyncRead + Unpin,
 19	{
 20	    let mut request_line = Vec::new();
 21	    let n = stream
 22	        .read_until(b'\n', &mut request_line)
 23	        .await
 24	        .map_err(NanowebError::Io)?;
 25	    if n == 0 {
 26	        return Ok(None);
 27	    }
 28	    if request_line.len() > MAX_LINE {
 29	        return Err(NanowebError::Parse("request line too long".into()));
 30	    }
 31	    let line = strip_crlf(&request_line);
 32	    let line_str = std::str::from_utf8(line)
 33	        .map_err(|_| NanowebError::Parse("non-utf8 request line".into()))?;
 34	    let mut parts = line_str.splitn(3, ' ');
 35	    let method_s = parts
 36	        .next()
 37	        .ok_or_else(|| NanowebError::Parse("missing method".into()))?;
 38	    let target = parts
 39	        .next()
 40	        .ok_or_else(|| NanowebError::Parse("missing target".into()))?;
 41	    let version = parts
 42	        .next()
 43	        .ok_or_else(|| NanowebError::Parse("missing version".into()))?;
 44	    if !version.starts_with("HTTP/1.") {
 45	        return Err(NanowebError::Parse("unsupported version".into()));
 46	    }
 47	    let method = Method::from_str(method_s)
 48	        .map_err(|_| NanowebError::Parse(format!("bad method: {}", method_s)))?;
 49	
 50	    let mut headers = Headers::new();
 51	    let mut total = 0usize;
 52	    loop {
 53	        let mut buf = Vec::new();
 54	        let n = stream
 55	            .read_until(b'\n', &mut buf)
 56	            .await
 57	            .map_err(NanowebError::Io)?;
 58	        if n == 0 {
 59	            return Err(NanowebError::Parse("eof in headers".into()));
 60	        }
 61	        total += n;
 62	        if total > MAX_HEADERS_BYTES {
 63	            return Err(NanowebError::Parse("headers too large".into()));
 64	        }
 65	        let line = strip_crlf(&buf);
 66	        if line.is_empty() {
 67	            break;
 68	        }
 69	        let s =
 70	            std::str::from_utf8(line).map_err(|_| NanowebError::Parse("non-utf8 header".into()))?;
 71	        let (k, v) = s
 72	            .split_once(':')
 73	            .ok_or_else(|| NanowebError::Parse("bad header".into()))?;
 74	        if k.is_empty() || k.contains(' ') {
 75	            return Err(NanowebError::Parse("bad header name".into()));
 76	        }
 77	        headers.append(k.trim(), v.trim());
 78	    }
 79	
 80	    let (path, query) = match target.split_once('?') {
 81	        Some((p, q)) => (p.to_string(), q.to_string()),
 82	        None => (target.to_string(), String::new()),
 83	    };
 84	
 85	    let mut body = Vec::new();
 86	    let te = headers
 87	        .get("transfer-encoding")
 88	        .map(|s| s.to_ascii_lowercase());
 89	    let cl = headers
 90	        .get("content-length")
 91	        .and_then(|s| s.trim().parse::<usize>().ok());
 92	
 93	    if let Some(te) = te.as_deref() {
 94	        if te == "chunked" {
 95	            read_chunked(stream, &mut body).await?;
 96	        } else if te != "identity" {
 97	            return Err(NanowebError::Parse("unsupported transfer-encoding".into()));
 98	        }
 99	    } else if let Some(len) = cl {
100	        if len > MAX_BODY {
101	            return Err(NanowebError::Parse("body too large".into()));
102	        }
103	        body.resize(len, 0);
104	        if len > 0 {
105	            stream
106	                .read_exact(&mut body)
107	                .await
108	                .map_err(NanowebError::Io)?;
109	        }
110	    }
111	
112	    Ok(Some(Request {
113	        method,
114	        target: target.to_string(),
115	        path,
116	        query,
117	        version: version.to_string(),
118	        headers,
119	        body,
120	        params: Default::default(),
121	        remote_addr: None,
122	        request_id: String::new(),
123	        extensions: Default::default(),
124	    }))

