 83	        let segments: Vec<&str> = path
 84	            .trim_start_matches('/')
 85	            .split('/')
 86	            .filter(|s| !s.is_empty())
 87	            .collect();
 88	        let mut params = HashMap::new();
 89	        let leaf = match_node(&self.root, &segments, 0, &mut params)?;
 90	        let allowed: Vec<Method> = leaf.handlers.keys().copied().collect();
 91	        if let Some(h) = leaf.handlers.get(&method) {
 92	            return Some(Match {
 93	                handler: h.clone(),
 94	                method,
 95	                head_fallback: false,
 96	                allowed,
 97	                params,
 98	            });
 99	        }
100	        if method == Method::Head {
101	            if let Some(h) = leaf.handlers.get(&Method::Get) {
102	                return Some(Match {
103	                    handler: h.clone(),
104	                    method: Method::Get,
105	                    head_fallback: true,
106	                    allowed,
107	                    params,
108	                });
109	            }
110	        }
111	        // Method not allowed but path matched: signal via empty handler? Use OPTIONS list.
112	        // For simplicity, return None and let server check by calling allowed_for.
