135	fn match_node<'a>(
136	    node: &'a Node,
137	    segments: &[&str],
138	    idx: usize,
139	    params: &mut HashMap<String, String>,
140	) -> Option<&'a Node> {
141	    if idx == segments.len() {
142	        if !node.handlers.is_empty() {
143	            return Some(node);
144	        }
145	        // wildcard with empty match
146	        if let Some((name, child)) = &node.wildcard {
147	            params.insert(name.clone(), String::new());
148	            if !child.handlers.is_empty() {
149	                return Some(child);
150	            }
151	            params.remove(name);
152	        }
153	        return None;
154	    }
155	    let seg = segments[idx];
156	    if let Some(child) = node.literals.get(seg) {
157	        if let Some(m) = match_node(child, segments, idx + 1, params) {
158	            return Some(m);
159	        }
160	    }
161	    if let Some((name, child)) = &node.param {
162	        params.insert(name.clone(), seg.to_string());
163	        if let Some(m) = match_node(child, segments, idx + 1, params) {
164	            return Some(m);
165	        }
166	        params.remove(name);
167	    }
168	    if let Some((name, child)) = &node.wildcard {
169	        let rest = segments[idx..].join("/");
170	        params.insert(name.clone(), rest);
171	        if !child.handlers.is_empty() {
172	            return Some(child);
173	        }
174	        params.remove(name);
175	    }
176	    None

