 40	fn parse(input: &str) -> Result<Vec<Node>, NanowebError> {
 41	    let (nodes, rest) = parse_until(input, None)?;
 42	    if !rest.is_empty() {
 43	        return Err(NanowebError::Template("unexpected closing tag".into()));
 44	    }
 45	    Ok(nodes)
 46	}
 47	
 48	fn parse_until<'a>(
 49	    mut input: &'a str,
 50	    closing: Option<&str>,
 51	) -> Result<(Vec<Node>, &'a str), NanowebError> {
 52	    let mut nodes = Vec::new();
 53	    while !input.is_empty() {
 54	        if let Some(idx) = input.find("{{") {
 55	            if idx > 0 {
 56	                nodes.push(Node::Text(input[..idx].to_string()));
 57	            }
 58	            let after = &input[idx + 2..];
 59	            let end = after
 60	                .find("}}")
 61	                .ok_or_else(|| NanowebError::Template("unclosed tag".into()))?;
 62	            let tag = after[..end].trim();
 63	            let rest = &after[end + 2..];
 64	            if let Some(name) = tag.strip_prefix('#') {
 65	                let (body, after_body) = parse_until(rest, Some(name.trim()))?;
 66	                nodes.push(Node::Section {
 67	                    key: name.trim().to_string(),
 68	                    inverted: false,
 69	                    body,
 70	                });
 71	                input = after_body;
 72	            } else if let Some(name) = tag.strip_prefix('^') {
 73	                let (body, after_body) = parse_until(rest, Some(name.trim()))?;
 74	                nodes.push(Node::Section {
 75	                    key: name.trim().to_string(),
 76	                    inverted: true,
 77	                    body,
 78	                });
 79	                input = after_body;
 80	            } else if let Some(name) = tag.strip_prefix('/') {
 81	                if Some(name.trim()) != closing {
 82	                    return Err(NanowebError::Template(format!(
 83	                        "mismatched close: {}",
 84	                        name
 85	                    )));
 86	                }
 87	                return Ok((nodes, rest));
 88	            } else {
 89	                nodes.push(Node::Var(tag.to_string()));
 90	                input = rest;
 91	            }
 92	        } else {
 93	            nodes.push(Node::Text(input.to_string()));
 94	            input = "";
 95	        }
 96	    }
 97	    if closing.is_some() {
 98	        return Err(NanowebError::Template("unterminated section".into()));
 99	    }
100	    Ok((nodes, ""))

126	fn render_nodes(nodes: &[Node], stack: &[&Value], out: &mut String) {
127	    for node in nodes {
128	        match node {
129	            Node::Text(s) => out.push_str(s),
130	            Node::Var(k) => {
131	                if let Some(v) = lookup(stack, k) {
132	                    match v {
133	                        Value::String(s) => out.push_str(&html_escape(s)),
134	                        _ => out.push_str(&html_escape(&v.to_string())),
135	                    }
136	                }
137	            }
138	            Node::Section {
139	                key,
140	                inverted,
141	                body,
142	            } => {
143	                let v = lookup(stack, key);
144	                let t = v.map(truthy).unwrap_or(false);
145	                if *inverted {
146	                    if !t {
147	                        render_nodes(body, stack, out);
148	                    }
149	                } else if t {
150	                    if let Some(Value::Array(items)) = v {
151	                        for item in items {
152	                            let mut new_stack = stack.to_vec();
153	                            new_stack.push(item);
154	                            render_nodes(body, &new_stack, out);
155	                        }
156	                    } else if let Some(val) = v {
157	                        let mut new_stack = stack.to_vec();
158	                        new_stack.push(val);
159	                        render_nodes(body, &new_stack, out);
160	                    }
161	                }
162	            }
163	        }
164	    }
165	}

