31	impl Middleware for RateLimit {
32	    async fn before(&self, req: &mut Request) -> Result<Option<Response>, NanowebError> {
33	        let key = req
34	            .remote_addr
35	            .map(|a| a.ip().to_string())
36	            .unwrap_or_else(|| "unknown".to_string());
37	        let now = Instant::now();
38	        let mut state = self.state.lock().unwrap();
39	        let bucket = state.entry(key).or_insert(Bucket {
40	            tokens: self.capacity,
41	            last: now,
42	        });
43	        let dt = now.duration_since(bucket.last).as_secs_f64();
44	        bucket.tokens = (bucket.tokens + dt * self.refill_per_sec).min(self.capacity);
45	        bucket.last = now;
46	        if bucket.tokens >= 1.0 {
47	            bucket.tokens -= 1.0;
48	            Ok(None)
49	        } else {
50	            let mut r = Response::new(StatusCode::TOO_MANY_REQUESTS);
51	            r.headers
52	                .insert("Content-Type", "text/plain; charset=utf-8");
53	            r.body = b"rate limit exceeded".to_vec();
54	            Ok(Some(r))
55	        }
56	    }

