127	async fn read_chunked<R>(stream: &mut BufReader<R>, out: &mut Vec<u8>) -> Result<(), NanowebError>
128	where
129	    R: tokio::io::AsyncRead + Unpin,
130	{
131	    loop {
132	        let mut size_line = Vec::new();
133	        stream
134	            .read_until(b'\n', &mut size_line)
135	            .await
136	            .map_err(NanowebError::Io)?;
137	        let s = strip_crlf(&size_line);
138	        let s = std::str::from_utf8(s).map_err(|_| NanowebError::Parse("bad chunk size".into()))?;
139	        let s = s.split(';').next().unwrap_or("").trim();
140	        let size = usize::from_str_radix(s, 16)
141	            .map_err(|_| NanowebError::Parse("bad chunk size".into()))?;
142	        if size == 0 {
143	            // discard trailers up to blank line
144	            loop {
145	                let mut t = Vec::new();
146	                let n = stream
147	                    .read_until(b'\n', &mut t)
148	                    .await
149	                    .map_err(NanowebError::Io)?;
150	                if n == 0 || strip_crlf(&t).is_empty() {
151	                    break;
152	                }
153	            }
154	            return Ok(());
155	        }
156	        if out.len() + size > MAX_BODY {
157	            return Err(NanowebError::Parse("body too large".into()));
158	        }
159	        let start = out.len();
160	        out.resize(start + size, 0);
161	        stream
162	            .read_exact(&mut out[start..])
163	            .await
164	            .map_err(NanowebError::Io)?;
165	        // CRLF after chunk
166	        let mut crlf = [0u8; 2];
167	        stream
168	            .read_exact(&mut crlf)
169	            .await
170	            .map_err(NanowebError::Io)?;
171	        if &crlf != b"\r\n" {
172	            return Err(NanowebError::Parse("bad chunk terminator".into()));
173	        }
174	    }
175	}

