 71	    let mut headers = Headers::new();
 72	    let mut count = 0usize;
 73	    loop {
 74	        let mut hl = String::new();
 75	        let n = reader.read_line(&mut hl).await?;
 76	        if n == 0 {
 77	            return Err(NanowebError::BadRequest("eof in headers".into()));
 78	        }
 79	        if n > MAX_LINE {
 80	            return Err(NanowebError::BadRequest("header line too long".into()));
 81	        }
 82	        let trimmed = hl.trim_end_matches(['\r', '\n']);
 83	        if trimmed.is_empty() {
 84	            break;
 85	        }
 86	        if count >= MAX_HEADERS {
 87	            return Err(NanowebError::BadRequest("too many headers".into()));
 88	        }
 89	        let (name, value) = parse_header_line(trimmed)?;
 90	        headers.append(name, value);
 91	        count += 1;
