102	pub async fn read_body<R>(reader: &mut BufReader<R>, headers: &Headers) -> Result<Vec<u8>>
103	where
104	    R: tokio::io::AsyncRead + Unpin,
105	{
106	    if let Some(te) = headers.get("Transfer-Encoding") {
107	        if te.eq_ignore_ascii_case("chunked") {
108	            return read_chunked(reader).await;
109	        } else {
110	            return Err(NanowebError::BadRequest(format!(
111	                "unsupported transfer-encoding {}",
112	                te
113	            )));
114	        }
115	    }
116	    if let Some(cl) = headers.get("Content-Length") {
117	        let n: usize = cl
118	            .trim()
119	            .parse()
120	            .map_err(|_| NanowebError::BadRequest("bad content-length".into()))?;
121	        if n > MAX_BODY {
122	            return Err(NanowebError::BadRequest("body too large".into()));
123	        }
124	        let mut buf = vec![0u8; n];
125	        reader.read_exact(&mut buf).await?;
126	        return Ok(buf);
127	    }
128	    Ok(Vec::new())
129	}

