 73	    /// Bind to `addr` plus the optional TLS listener configured on the app, then run until shutdown is signalled.
 74	    pub async fn run(self, addr: SocketAddr) -> Result<()> {
 75	        let app = self.app.clone();
 76	        let shutdown = Arc::new(Notify::new());
 77	        let shutdown_clone = shutdown.clone();
 78	        // Signal handler
 79	        tokio::spawn(async move {
 80	            let mut sigterm =
 81	                match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
 82	                    Ok(s) => s,
 83	                    Err(_) => return,
 84	                };
 85	            tokio::select! {
 86	                _ = tokio::signal::ctrl_c() => {}
 87	                _ = sigterm.recv() => {}
 88	            }
 89	            tracing::info!("shutdown signal received");
 90	            shutdown_clone.notify_waiters();
 91	        });
 92	
 93	        let mut tasks: JoinSet<()> = JoinSet::new();
 94	
 95	        // Plain HTTP listener
 96	        let listener = TcpListener::bind(addr).await?;
 97	        tracing::info!("listening on http://{}", addr);
 98	        app.health.set_ready(true);
 99	
100	        let plain_app = app.clone();
101	        let plain_shutdown = shutdown.clone();
102	        tasks.spawn(async move {
103	            run_accept_loop(listener, plain_app, plain_shutdown, false, None).await;
104	        });
105	
106	        #[cfg(feature = "tls")]
107	        if let Some((tls_addr, acceptor)) = app.tls.clone() {
108	            let tls_listener = TcpListener::bind(tls_addr).await?;
109	            tracing::info!("listening on https://{}", tls_addr);
110	            let tls_app = app.clone();
111	            let tls_shutdown = shutdown.clone();
112	            tasks.spawn(async move {
113	                run_accept_loop(tls_listener, tls_app, tls_shutdown, true, Some(acceptor)).await;
114	            });
115	        }
116	
117	        // Wait for shutdown
118	        shutdown.notified().await;
119	        app.health.shutdown();
120	        let timeout = app.graceful_timeout;
121	        tracing::info!("graceful shutdown, draining for up to {:?}", timeout);
122	        let drain = async { while tasks.join_next().await.is_some() {} };
123	        let _ = tokio::time::timeout(timeout, drain).await;
124	        Ok(())
125	    }

133	async fn run_accept_loop(
134	    listener: TcpListener,
135	    app: Arc<App>,
136	    shutdown: Arc<Notify>,
137	    _is_tls: bool,
138	    acceptor: TlsAcceptorOpt,
139	) {
140	    let mut conns: JoinSet<()> = JoinSet::new();
141	    loop {
142	        tokio::select! {
143	            _ = shutdown.notified() => {
144	                tracing::info!("accept loop stopping");
145	                break;
146	            }
147	            res = listener.accept() => {
148	                match res {
149	                    Ok((stream, peer)) => {
150	                        let app = app.clone();
151	                        let acceptor_clone = acceptor.clone();
152	                        conns.spawn(async move {
153	                            if let Err(e) = handle_connection(stream, peer, app, acceptor_clone).await {
154	                                tracing::debug!("conn error: {}", e);
155	                            }
156	                        });
157	                    }
158	                    Err(e) => {
159	                        tracing::warn!("accept error: {}", e);
160	                    }
161	                }
162	            }
163	        }
164	    }
165	    while conns.join_next().await.is_some() {}
166	}

