32	    pub fn record_request(&self, method: Method, status: u16, route: &str, dur: Duration) {
33	        let mut g = self.inner.lock();
34	        let class = format!("{}xx", status / 100);
35	        let key = (method.as_str().to_string(), class, route.to_string());
36	        *g.requests.entry(key).or_insert(0) += 1;
37	        let secs = dur.as_secs_f64();
38	        let entry = g
39	            .duration_buckets
40	            .entry(route.to_string())
41	            .or_insert([0; 9]);
42	        for (i, b) in BUCKETS.iter().enumerate() {
43	            if secs <= *b {
44	                entry[i] += 1;
45	            }
46	        }
47	        *g.duration_sum.entry(route.to_string()).or_insert(0.0) += secs;
48	        *g.duration_count.entry(route.to_string()).or_insert(0) += 1;
49	    }

 51	    pub fn render(&self) -> String {
 52	        let g = self.inner.lock();
 53	        let mut out = String::new();
 54	        writeln!(
 55	            out,
 56	            "# HELP nanoweb_http_requests_total Total HTTP requests"
 57	        )
 58	        .ok();
 59	        writeln!(out, "# TYPE nanoweb_http_requests_total counter").ok();
 60	        for ((method, class, route), count) in g.requests.iter() {
 61	            writeln!(
 62	                out,
 63	                "nanoweb_http_requests_total{{method=\"{}\",status=\"{}\",route=\"{}\"}} {}",
 64	                method, class, route, count
 65	            )
 66	            .ok();
 67	        }
 68	        writeln!(
 69	            out,
 70	            "# HELP nanoweb_http_request_duration_seconds Request duration"
 71	        )
 72	        .ok();
 73	        writeln!(
 74	            out,
 75	            "# TYPE nanoweb_http_request_duration_seconds histogram"
 76	        )
 77	        .ok();
 78	        for (route, buckets) in g.duration_buckets.iter() {
 79	            let mut cumulative = 0u64;
 80	            for (i, b) in BUCKETS.iter().enumerate() {
 81	                cumulative += buckets[i];
 82	                writeln!(
 83	                    out,
 84	                    "nanoweb_http_request_duration_seconds_bucket{{route=\"{}\",le=\"{}\"}} {}",
 85	                    route, b, cumulative
 86	                )
 87	                .ok();
 88	            }
 89	            let count = g.duration_count.get(route).copied().unwrap_or(0);
 90	            let sum = g.duration_sum.get(route).copied().unwrap_or(0.0);
 91	            writeln!(
 92	                out,
 93	                "nanoweb_http_request_duration_seconds_bucket{{route=\"{}\",le=\"+Inf\"}} {}",
 94	                route, count
 95	            )
 96	            .ok();
 97	            writeln!(
 98	                out,
 99	                "nanoweb_http_request_duration_seconds_sum{{route=\"{}\"}} {}",
100	                route, sum
101	            )
102	            .ok();
103	            writeln!(
104	                out,
105	                "nanoweb_http_request_duration_seconds_count{{route=\"{}\"}} {}",
106	                route, count
