189	async fn handle_io<S>(stream: S, peer: SocketAddr, app: Arc<App>) -> Result<()>
190	where
191	    S: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin,
192	{
193	    let (rd, mut wr) = tokio::io::split(stream);
194	    let mut reader = BufReader::new(rd);
195	    loop {
196	        // Peek a byte to detect close
197	        let head = match read_request_head(&mut reader).await {
198	            Ok(h) => h,
199	            Err(NanowebError::BadRequest(msg)) => {
200	                let mut r = Response::new(StatusCode::BAD_REQUEST);
201	                r.body = msg.into_bytes();
202	                let _ = wr.write_all(&r.serialize(false)).await;
203	                return Ok(());
204	            }
205	            Err(NanowebError::Io(e)) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
206	                return Ok(());
207	            }
208	            Err(_) => return Ok(()),
209	        };
210	        let body = read_body(&mut reader, &head.headers).await?;
211	        let (path, query) = split_target(&head.target);
212	        let request_id = generate_request_id();
213	        let mut req = Request {
214	            method: head.method,
215	            target: head.target.clone(),
216	            path,
217	            query,
218	            version: head.version,
219	            headers: head.headers,
220	            body,
221	            params: Default::default(),
222	            remote_addr: Some(peer),
223	            request_id: request_id.clone(),
224	            extensions: Default::default(),
225	        };
226	
227	        let keep_alive = should_keep_alive(&req);
228	        let started = Instant::now();
229	        let mut route_label = req.path.clone();
230	
231	        let (mut response, suppress_body) = dispatch(&app, &mut req, &mut route_label).await;
232	        // Always include X-Request-Id
233	        response.headers.insert("X-Request-Id", request_id);
234	        if !keep_alive {
235	            response.headers.insert("Connection", "close");
236	        } else {
237	            response.headers.insert("Connection", "keep-alive");
238	        }
239	        // Record metric
240	        app.metrics.record_request(
241	            req.method,
242	            response.status.0,
243	            &route_label,
244	            started.elapsed(),
245	        );

