39	fn tokenize(tpl: &str) -> Vec<Token> {
40	    let mut tokens = Vec::new();
41	    let mut rest = tpl;
42	    while !rest.is_empty() {
43	        if let Some(idx) = rest.find("{{") {
44	            if idx > 0 {
45	                tokens.push(Token::Text(rest[..idx].to_string()));
46	            }
47	            let after = &rest[idx + 2..];
48	            let end = match after.find("}}") {
49	                Some(e) => e,
50	                None => {
51	                    tokens.push(Token::Text(rest.to_string()));
52	                    return tokens;
53	                }
54	            };
55	            let tag = after[..end].trim();
56	            if let Some(name) = tag.strip_prefix('#') {
57	                tokens.push(Token::SectionOpen(name.trim().to_string()));
58	            } else if let Some(name) = tag.strip_prefix('^') {
59	                tokens.push(Token::InverseOpen(name.trim().to_string()));
60	            } else if let Some(name) = tag.strip_prefix('/') {
61	                tokens.push(Token::SectionClose(name.trim().to_string()));
62	            } else {
63	                tokens.push(Token::Var(tag.to_string()));
64	            }
65	            rest = &after[end + 2..];
66	        } else {
67	            tokens.push(Token::Text(rest.to_string()));
68	            break;
69	        }
70	    }
71	    tokens

 74	fn render_tokens(
 75	    tokens: &[Token],
 76	    i: &mut usize,
 77	    ctx: &Value,
 78	    out: &mut String,
 79	    stop: Option<&str>,
 80	) {
 81	    while *i < tokens.len() {
 82	        match &tokens[*i] {
 83	            Token::Text(t) => {
 84	                out.push_str(t);
 85	                *i += 1;
 86	            }
 87	            Token::Var(name) => {
 88	                let v = lookup(ctx, name);
 89	                out.push_str(&value_to_string(&v));
 90	                *i += 1;
 91	            }
 92	            Token::SectionOpen(name) => {
 93	                *i += 1;
 94	                // capture inner tokens until matching close
 95	                let start = *i;
 96	                let inner = collect_until(tokens, i, name);
 97	                let v = lookup(ctx, name);
 98	                if is_truthy(&v) {
 99	                    match v {
100	                        Value::Array(items) => {
101	                            for item in items {
102	                                let mut j = 0usize;
103	                                render_tokens(&inner, &mut j, &item, out, None);
104	                            }
105	                        }
106	                        _ => {
107	                            let mut j = 0usize;
108	                            render_tokens(&inner, &mut j, &v, out, None);
109	                        }
110	                    }
111	                }
112	                let _ = start;
113	            }
114	            Token::InverseOpen(name) => {
115	                *i += 1;
116	                let inner = collect_until(tokens, i, name);
117	                let v = lookup(ctx, name);
118	                if !is_truthy(&v) {
119	                    let mut j = 0usize;
120	                    render_tokens(&inner, &mut j, ctx, out, None);
121	                }
122	            }

