 8	pub fn parse_body<T: DeserializeOwned>(req: &Request) -> Result<T> {
 9	    let ct = req
10	        .header("Content-Type")
11	        .unwrap_or("application/json")
12	        .to_ascii_lowercase();
13	    if ct.starts_with("application/json") {
14	        return Ok(serde_json::from_slice(&req.body)?);
15	    }
16	    if ct.starts_with("application/x-www-form-urlencoded") {
17	        let pairs = form::parse_urlencoded(&req.body);
18	        let map: std::collections::HashMap<String, String> = pairs.into_iter().collect();
19	        let v = serde_json::to_value(map)?;
20	        return Ok(serde_json::from_value(v)?);
21	    }
22	    if ct.starts_with("multipart/form-data") {
23	        let boundary = ct
24	            .split(';')
25	            .find_map(|p| {
26	                let p = p.trim();
27	                p.strip_prefix("boundary=")
28	                    .map(|s| s.trim_matches('"').to_string())
29	            })
30	            .ok_or_else(|| NanowebError::BadRequest("missing multipart boundary".into()))?;
31	        let parts = multipart::parse(&req.body, &boundary)?;
32	        let mut map = serde_json::Map::new();
33	        for p in parts {
34	            map.insert(
35	                p.name,
36	                serde_json::Value::String(String::from_utf8_lossy(&p.data).into_owned()),
37	            );
38	        }
39	        return Ok(serde_json::from_value(serde_json::Value::Object(map))?);
40	    }
41	    Err(NanowebError::BadRequest(format!(
42	        "unsupported content-type: {}",
43	        ct
44	    )))
45	}

