102	pub async fn read_body<R>(reader: &mut BufReader<R>, headers: &Headers) -> Result<Vec<u8>>
103	where
104	    R: tokio::io::AsyncRead + Unpin,
105	{
106	    if let Some(te) = headers.get("Transfer-Encoding") {
107	        if te.eq_ignore_ascii_case("chunked") {
108	            return read_chunked(reader).await;
109	        } else {
110	            return Err(NanowebError::BadRequest(format!(
111	                "unsupported transfer-encoding {}",
112	                te
113	            )));
114	        }
115	    }
116	    if let Some(cl) = headers.get("Content-Length") {
117	        let n: usize = cl
118	            .trim()
119	            .parse()
120	            .map_err(|_| NanowebError::BadRequest("bad content-length".into()))?;
121	        if n > MAX_BODY {
122	            return Err(NanowebError::BadRequest("body too large".into()));
123	        }
124	        let mut buf = vec![0u8; n];
125	        reader.read_exact(&mut buf).await?;
126	        return Ok(buf);
127	    }
128	    Ok(Vec::new())
129	}
130	
131	async fn read_chunked<R>(reader: &mut BufReader<R>) -> Result<Vec<u8>>
132	where
133	    R: tokio::io::AsyncRead + Unpin,
134	{
135	    let mut out = Vec::new();
136	    loop {
137	        let mut size_line = String::new();
138	        let n = reader.read_line(&mut size_line).await?;
139	        if n == 0 {
140	            return Err(NanowebError::BadRequest("eof in chunk size".into()));
141	        }
142	        let size_str = size_line.trim().split(';').next().unwrap_or("");
143	        let size = usize::from_str_radix(size_str, 16)
144	            .map_err(|_| NanowebError::BadRequest("bad chunk size".into()))?;
145	        if size == 0 {
146	            // trailing CRLF (and optional trailers ignored)
147	            loop {
148	                let mut t = String::new();
149	                let m = reader.read_line(&mut t).await?;
150	                if m == 0 {
151	                    break;
152	                }
153	                if t.trim().is_empty() {
154	                    break;
155	                }
156	            }
157	            return Ok(out);
158	        }
159	        if out.len() + size > MAX_BODY {
160	            return Err(NanowebError::BadRequest("body too large".into()));
161	        }
162	        let mut buf = vec![0u8; size];
163	        reader.read_exact(&mut buf).await?;
164	        out.extend_from_slice(&buf);
165	        let mut crlf = [0u8; 2];
166	        reader.read_exact(&mut crlf).await?;
167	        if crlf != *b"\r\n" {
168	            return Err(NanowebError::BadRequest("missing chunk crlf".into()));
169	        }
170	    }
171	}

