166	fn lookup_node<'a, V>(
167	    node: &'a TrieNode<V>,
168	    parts: &[&str],
169	    params: &mut HashMap<String, String>,
170	) -> Option<&'a V> {
171	    if parts.is_empty() {
172	        if let Some(v) = &node.value {
173	            return Some(v);
174	        }
175	        // Allow wildcard to match empty remainder too
176	        if let Some((name, v)) = &node.wildcard {
177	            params.insert(name.clone(), String::new());
178	            return Some(v);
179	        }
180	        return None;
181	    }
182	
183	    let head = parts[0];
184	    let tail = &parts[1..];
185	
186	    // 1. Try literal match first (highest priority)
187	    if let Some(child) = node.literal_children.get(head) {
188	        let result = lookup_node(child, tail, params);
189	        if result.is_some() {
190	            return result;
191	        }
192	    }
193	
194	    // 2. Try parameter match
195	    if let Some((name, child)) = &node.param_child {
196	        let saved = params.get(name).cloned();
197	        params.insert(name.clone(), head.to_string());
198	        let result = lookup_node(child, tail, params);
199	        if result.is_some() {
200	            return result;
201	        }
202	        // Backtrack
203	        match saved {
204	            Some(v) => {
205	                params.insert(name.clone(), v);
206	            }
207	            None => {
208	                params.remove(name);
209	            }
210	        }
211	    }
212	
213	    // 3. Try wildcard (matches remaining path)
214	    if let Some((name, v)) = &node.wildcard {
215	        let wildcard_value = parts.join("/");
216	        params.insert(name.clone(), wildcard_value);
217	        return Some(v);
218	    }

