 94	fn render_section(template: &str, ctx: &Context) -> Result<String, NanowebError> {
 95	    let mut output = String::with_capacity(template.len());
 96	    let mut pos = 0;
 97	    let bytes = template.as_bytes();
 98	
 99	    while pos < bytes.len() {
100	        // Look for next `{{`
101	        if let Some(open) = find_open(&template[pos..]) {
102	            output.push_str(&template[pos..pos + open]);
103	            let rest = &template[pos + open + 2..]; // after {{
104	
105	            // Find closing `}}`
106	            let close = rest
107	                .find("}}")
108	                .ok_or_else(|| NanowebError::Template("Unclosed {{ in template".into()))?;
109	
110	            let tag = &rest[..close].trim();
111	            pos = pos + open + 2 + close + 2; // advance past }}
112	
113	            if let Some(section_name) = tag.strip_prefix('#') {
114	                // Section: {{#name}}...{{/name}}
115	                let section_name = section_name.trim();
116	                let (section_body, after) = find_section(template, pos, section_name)?;
117	
118	                match ctx.get(section_name) {
119	                    Some(Value::List(items)) => {
120	                        for item_ctx in items {
121	                            output.push_str(&render_section(section_body, item_ctx)?);
122	                        }
123	                    }
124	                    Some(Value::Bool(true)) | Some(Value::String(_)) => {
125	                        output.push_str(&render_section(section_body, ctx)?);
126	                    }
127	                    _ => {} // Empty or false: skip
128	                }
129	
130	                pos = after;
131	            } else if let Some(section_name) = tag.strip_prefix('^') {
132	                // Inverted section: {{^name}}...{{/name}}
133	                let section_name = section_name.trim();
134	                let (section_body, after) = find_section(template, pos, section_name)?;
135	
136	                let is_absent = match ctx.get(section_name) {
137	                    None | Some(Value::Bool(false)) | Some(Value::Null) => true,
138	                    Some(Value::List(items)) => items.is_empty(),
139	                    _ => false,
140	                };
141	
142	                if is_absent {
143	                    output.push_str(&render_section(section_body, ctx)?);
144	                }
145	
146	                pos = after;
147	            } else if let Some(closing) = tag.strip_prefix('/') {
148	                // Closing tag encountered out of context - shouldn't happen in well-formed templates
149	                return Err(NanowebError::Template(format!(
150	                    "Unexpected closing tag: {}",
151	                    closing
152	                )));
153	            } else {
154	                // Variable substitution: {{name}}
155	                match ctx.get(tag) {
156	                    Some(Value::String(s)) => output.push_str(&html_escape(s)),
157	                    Some(Value::Bool(b)) => output.push_str(if *b { "true" } else { "false" }),
158	                    Some(Value::Null) | None => {} // Empty
159	                    Some(Value::List(_)) => {}     // Lists not interpolated directly
160	                }
161	            }
162	        } else {
163	            output.push_str(&template[pos..]);
164	            break;
165	        }
166	    }
167	
168	    Ok(output)
169	}

175	fn find_section<'a>(
176	    template: &'a str,
177	    start: usize,
178	    name: &str,
179	) -> Result<(&'a str, usize), NanowebError> {
180	    let open_tag = format!("{{{{#{}}}}}", name);
181	    let close_tag = format!("{{{{/{}}}}}", name);
182	
183	    let rest = &template[start..];
184	
185	    // Find matching close tag (handling nesting)
186	    let mut depth = 1;
187	    let mut search_pos = 0;
188	
189	    while search_pos < rest.len() {
190	        if let Some(open) = rest[search_pos..].find(&open_tag) {
191	            if let Some(close) = rest[search_pos..].find(&close_tag) {
192	                if open < close {
193	                    depth += 1;
194	                    search_pos += open + open_tag.len();
195	                } else {
196	                    depth -= 1;
197	                    if depth == 0 {
198	                        let body = &rest[..search_pos + close];
199	                        let after = start + search_pos + close + close_tag.len();
200	                        return Ok((body, after));
201	                    }
202	                    search_pos += close + close_tag.len();
203	                }
204	            } else {
205	                // No close at all
206	                break;
207	            }
208	        } else if let Some(close) = rest[search_pos..].find(&close_tag) {
209	            depth -= 1;
210	            if depth == 0 {
211	                let body = &rest[..search_pos + close];
212	                let after = start + search_pos + close + close_tag.len();
213	                return Ok((body, after));
214	            }
215	            search_pos += close + close_tag.len();
216	        } else {
217	            break;
218	        }
219	    }
220	
221	    Err(NanowebError::Template(format!(
222	        "Unclosed section: {}",
223	        name
224	    )))
225	}

