 50	
 51	impl RateLimitMiddleware {
 52	    /// Create rate limiter: max_requests burst, refill_rate tokens/second.
 53	    pub fn new(max_requests: u32, refill_rate: f64) -> Self {
 54	        Self {
 55	            buckets: Arc::new(Mutex::new(HashMap::new())),
 56	            max_tokens: max_requests as f64,
 57	            refill_rate,
 58	            cleanup_interval: Duration::from_secs(60),
 59	            last_cleanup: Mutex::new(Instant::now()),
 60	        }
 61	    }
 62	
 63	    fn check_and_consume(&self, ip: IpAddr) -> bool {
 64	        let mut buckets = self.buckets.lock().unwrap();
 65	
 66	        // Periodic cleanup of old entries
 67	        {
 68	            let mut last = self.last_cleanup.lock().unwrap();
 69	            if last.elapsed() > self.cleanup_interval {
 70	                buckets.retain(|_, b| {
 71	                    let elapsed = b.last_refill.elapsed().as_secs_f64();
 72	                    let projected = b.tokens + elapsed * b.refill_rate;
 73	                    projected < b.max_tokens // Keep if not fully refilled (was recently used)
 74	                });
 75	                *last = Instant::now();
 76	            }
 77	        }
 78	
 79	        let bucket = buckets
 80	            .entry(ip)
 81	            .or_insert_with(|| TokenBucket::new(self.max_tokens, self.refill_rate));
 82	
 83	        bucket.try_consume(1.0)
 84	    }
 85	}
