18	/// Parses a complete HTTP/1.1 request from a byte slice.
19	/// Returns the parsed request and the number of bytes consumed.
20	pub fn parse_request(buf: &[u8]) -> Result<Option<(ParsedRequest, usize)>, NanowebError> {
21	    // Find the end of headers (CRLFCRLF)
22	    let header_end = find_double_crlf(buf);
23	    let header_end = match header_end {
24	        Some(pos) => pos,
25	        None => {
26	            if buf.len() > MAX_HEADER_SIZE {
27	                return Err(NanowebError::BadRequest("Headers too large".into()));
28	            }
29	            return Ok(None); // Need more data
30	        }
31	    };
32	
33	    let header_section = &buf[..header_end];
34	    if header_section.len() > MAX_HEADER_SIZE {
35	        return Err(NanowebError::BadRequest("Headers too large".into()));
36	    }
37	
38	    // Parse request line + headers
39	    let (method, target, version, headers) = parse_headers(header_section)?;
40	
41	    // Determine body length
42	    let headers_total = header_end + 4; // +4 for the CRLFCRLF
43	    let body_start = headers_total;
44	    let remaining = &buf[body_start..];
45	
46	    let (body, total_consumed) = if let Some(te) = headers.get("transfer-encoding") {
47	        if te.to_lowercase().contains("chunked") {
48	            match parse_chunked_body(remaining)? {
49	                Some((body, consumed)) => (body, body_start + consumed),
50	                None => return Ok(None), // Need more data
51	            }
52	        } else {
53	            return Err(NanowebError::BadRequest(format!(
54	                "Unsupported transfer-encoding: {}",
55	                te
56	            )));
57	        }
58	    } else if let Some(cl) = headers.get("content-length") {
59	        let content_length: usize = cl
60	            .trim()
61	            .parse()
62	            .map_err(|_| NanowebError::BadRequest("Invalid Content-Length".into()))?;
63	        if content_length > MAX_BODY_SIZE {
64	            return Err(NanowebError::BodyTooLarge);
65	        }
66	        if remaining.len() < content_length {
67	            return Ok(None); // Need more data
68	        }
69	        let body = remaining[..content_length].to_vec();
70	        (body, body_start + content_length)
71	    } else {
72	        // No body
73	        (Vec::new(), body_start)
74	    };
75	
76	    Ok(Some((
77	        ParsedRequest {
78	            method,
79	            target,
80	            version,
81	            headers,
82	            body,
83	        },
84	        total_consumed,
85	    )))

