19	pub async fn read_request<R: AsyncBufRead + Unpin>(
20	    reader: &mut R,
21	) -> Result<RawParsed, NanowebError> {
22	    // Read request line
23	    let mut request_line = String::new();
24	    let n = reader
25	        .read_line(&mut request_line)
26	        .await
27	        .map_err(NanowebError::Io)?;
28	    if n == 0 {
29	        return Err(NanowebError::ConnectionClosed);
30	    }
31	    if n > MAX_HEADER_SIZE {
32	        return Err(NanowebError::BadRequest("Request line too long".into()));
33	    }
34	
35	    let request_line = request_line.trim_end_matches(|c| c == '\r' || c == '\n');
36	    let (method, target, version) = parse_request_line(request_line)?;
37	
38	    let (path, query) = split_target(&target);
39	
40	    // Read headers
41	    let mut headers: Vec<(String, String)> = Vec::new();
42	    let mut total_header_size = n;
43	    loop {
44	        let mut line = String::new();
45	        let n = reader
46	            .read_line(&mut line)
47	            .await
48	            .map_err(NanowebError::Io)?;
49	        if n == 0 {
50	            return Err(NanowebError::Parse("Unexpected EOF in headers".into()));
51	        }
52	        total_header_size += n;
53	        if total_header_size > MAX_HEADER_SIZE {
54	            return Err(NanowebError::BadRequest("Headers too large".into()));
55	        }
56	
57	        let trimmed = line.trim_end_matches(|c| c == '\r' || c == '\n');
58	        if trimmed.is_empty() {
59	            break;
60	        }
61	
62	        if let Some(colon) = trimmed.find(':') {
63	            let name = trimmed[..colon].trim().to_lowercase();
64	            let value = trimmed[colon + 1..].trim().to_string();
65	            if name.is_empty() {
66	                return Err(NanowebError::BadRequest("Empty header name".into()));
67	            }
68	            headers.push((name, value));
69	        } else {
70	            return Err(NanowebError::BadRequest(format!(
71	                "Malformed header: {}",
72	                trimmed
73	            )));
74	        }
75	    }
76	
77	    // Determine body reading strategy
78	    let body = read_body(reader, &headers).await?;
79	
80	    Ok(RawParsed {
81	        method,
82	        target,
83	        path,
84	        query,
85	        version,
86	        headers,
87	        body,
88	    })
89	}

