 94	    pub fn lookup(&self, method: &Method, path: &str) -> Option<RouteMatch> {
 95	        let path_parts: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
 96	
 97	        let mut params = HashMap::new();
 98	        let node = Self::lookup_node(&self.root, &path_parts, &mut params)?;
 99	
100	        let method_str = method.as_str();
101	
102	        // Collect allowed methods
103	        let allowed_methods: Vec<String> = node.handlers.keys().cloned().collect();
104	
105	        // HEAD falls back to GET
106	        let handler = if method == &Method::Head {
107	            node.handlers
108	                .get("HEAD")
109	                .or_else(|| node.handlers.get("GET"))
110	                .cloned()
111	        } else if method == &Method::Options {
112	            // Auto-generate OPTIONS handler
113	            return Some(RouteMatch {
114	                handler: Arc::new(OptionsHandler {
115	                    allowed: allowed_methods.clone(),
116	                }),
117	                middleware: node.middleware.clone(),
118	                params,
119	                allowed_methods,
120	            });
121	        } else {
122	            node.handlers.get(method_str).cloned()
123	        };
124	
125	        handler.map(|h| RouteMatch {
126	            handler: h,
127	            middleware: node.middleware.clone(),
128	            params,
129	            allowed_methods,
130	        })

