151	
152	        let seg = segments[0];
153	        let rest = &segments[1..];
154	
155	        // Try literal match first
156	        if let Some(child) = node.literal_children.get(seg) {
157	            let result = Self::lookup_node(child, rest, params);
158	            if result.is_some() {
159	                return result;
160	            }
161	        }
162	
163	        // Try param match
164	        if let Some((name, child)) = &node.param_child {
165	            let saved = params.get(name.as_str()).cloned();
166	            params.insert(name.clone(), seg.to_string());
167	            let result = Self::lookup_node(child, rest, params);
168	            if result.is_some() {
169	                return result;
170	            }
171	            // Restore
172	            if let Some(v) = saved {
173	                params.insert(name.clone(), v);
174	            } else {
175	                params.remove(name.as_str());
176	            }
177	        }
178	
179	        // Try wildcard match (captures rest of path)
180	        if let Some((name, child)) = &node.wildcard_child {
181	            let wildcard_value = std::iter::once(seg)
182	                .chain(rest.iter().copied())
