 30	fn render_template(template: &str, context: &Context) -> String {
 31	    let mut result = String::with_capacity(template.len());
 32	    let mut chars = template.chars().peekable();
 33	    let bytes = template.as_bytes();
 34	    let mut pos = 0;
 35	
 36	    while pos < bytes.len() {
 37	        if bytes[pos] == b'{' && bytes.get(pos + 1) == Some(&b'{') {
 38	            // Find closing }}
 39	            let start = pos + 2;
 40	            if let Some(end) = find_close(bytes, start) {
 41	                let tag = template[start..end].trim();
 42	                let after = end + 2;
 43	
 44	                if let Some(section_name) = tag.strip_prefix('#') {
 45	                    // Section tag {{#name}}
 46	                    let section_name = section_name.trim();
 47	                    let close_tag = format!("{{{{/{}}}}}", section_name);
 48	                    if let Some(close_pos) = template[after..].find(&close_tag) {
 49	                        let inner = &template[after..after + close_pos];
 50	                        match context.get(section_name) {
 51	                            Some(Value::Bool(true)) => {
 52	                                result.push_str(&render_template(inner, context));
 53	                            }
 54	                            Some(Value::List(items)) if !items.is_empty() => {
 55	                                for item_ctx in items {
 56	                                    result.push_str(&render_template(inner, item_ctx));
 57	                                }
 58	                            }
 59	                            Some(Value::Str(s)) if !s.is_empty() => {
 60	                                result.push_str(&render_template(inner, context));
 61	                            }
 62	                            _ => {}
 63	                        }
 64	                        pos = after + close_pos + close_tag.len();
 65	                        continue;
 66	                    }
 67	                } else if let Some(section_name) = tag.strip_prefix('^') {
 68	                    // Inverted section {{^name}}
 69	                    let section_name = section_name.trim();
 70	                    let close_tag = format!("{{{{/{}}}}}", section_name);
 71	                    if let Some(close_pos) = template[after..].find(&close_tag) {
 72	                        let inner = &template[after..after + close_pos];
 73	                        let is_falsy = match context.get(section_name) {
 74	                            None => true,
 75	                            Some(Value::Bool(false)) => true,
 76	                            Some(Value::List(items)) if items.is_empty() => true,
 77	                            Some(Value::Str(s)) if s.is_empty() => true,
 78	                            _ => false,
 79	                        };
 80	                        if is_falsy {
 81	                            result.push_str(&render_template(inner, context));
 82	                        }
 83	                        pos = after + close_pos + close_tag.len();
 84	                        continue;
 85	                    }
 86	                } else if tag.starts_with('/') {
 87	                    // Closing tag - skip (handled by section parsing)
 88	                    pos = after;
 89	                    continue;
 90	                } else {
 91	                    // Variable substitution {{name}}
 92	                    match context.get(tag) {
 93	                        Some(Value::Str(s)) => result.push_str(&html_escape(s)),
 94	                        Some(Value::Bool(b)) => result.push_str(if *b { "true" } else { "false" }),
 95	                        _ => {}
 96	                    }
 97	                    pos = after;
 98	                    continue;
 99	                }
100	            }
101	        }
102	        // Regular character
103	        result.push(bytes[pos] as char);
104	        pos += 1;
105	    }
106	
107	    result

