73	                            // Could also look in form body but we keep it simple
74	                            None
75	                        });
76	
77	                match (&cookie_token, &request_token) {
78	                    (Some(c), Some(r)) if c == r => {}
79	                    _ => return Err(NanowebError::Forbidden),
80	                }
81	            }
82	
83	            let mut resp = next.run(req).await?;
84	
85	            // Set CSRF token cookie if not present
86	            if cookie_token.is_none() {
87	                let token = generate_token();
88	                resp.add_header(
89	                    "Set-Cookie",
90	                    &format!("{}={}; Path=/; SameSite=Strict", cookie_name, token),
91	                );
92	            }
