19	pub async fn read_request<R: AsyncBufRead + Unpin>(
20	    reader: &mut R,
21	) -> Result<RawParsed, NanowebError> {
22	    // Read request line
23	    let mut request_line = String::new();
24	    let n = reader
25	        .read_line(&mut request_line)
26	        .await
27	        .map_err(NanowebError::Io)?;
28	    if n == 0 {
29	        return Err(NanowebError::ConnectionClosed);
30	    }
31	    if n > MAX_HEADER_SIZE {
32	        return Err(NanowebError::BadRequest("Request line too long".into()));
33	    }
34	
35	    let request_line = request_line.trim_end_matches(|c| c == '\r' || c == '\n');
36	    let (method, target, version) = parse_request_line(request_line)?;
37	
38	    let (path, query) = split_target(&target);
39	
40	    // Read headers
41	    let mut headers: Vec<(String, String)> = Vec::new();
42	    let mut total_header_size = n;
43	    loop {
44	        let mut line = String::new();
45	        let n = reader
46	            .read_line(&mut line)
47	            .await
48	            .map_err(NanowebError::Io)?;
49	        if n == 0 {
50	            return Err(NanowebError::Parse("Unexpected EOF in headers".into()));
51	        }
52	        total_header_size += n;
53	        if total_header_size > MAX_HEADER_SIZE {
54	            return Err(NanowebError::BadRequest("Headers too large".into()));
55	        }
56	
57	        let trimmed = line.trim_end_matches(|c| c == '\r' || c == '\n');
58	        if trimmed.is_empty() {
59	            break;
60	        }
61	
62	        if let Some(colon) = trimmed.find(':') {
63	            let name = trimmed[..colon].trim().to_lowercase();
64	            let value = trimmed[colon + 1..].trim().to_string();
65	            if name.is_empty() {
66	                return Err(NanowebError::BadRequest("Empty header name".into()));
67	            }
68	            headers.push((name, value));
69	        } else {
70	            return Err(NanowebError::BadRequest(format!(
71	                "Malformed header: {}",
72	                trimmed
73	            )));
74	        }
75	    }
76	
77	    // Determine body reading strategy
78	    let body = read_body(reader, &headers).await?;
79	
80	    Ok(RawParsed {
81	        method,
82	        target,
83	        path,
84	        query,
85	        version,
86	        headers,
87	        body,
88	    })
89	}

 91	async fn read_body<R: AsyncBufRead + Unpin>(
 92	    reader: &mut R,
 93	    headers: &[(String, String)],
 94	) -> Result<Vec<u8>, NanowebError> {
 95	    let transfer_encoding = headers
 96	        .iter()
 97	        .find(|(k, _)| k == "transfer-encoding")
 98	        .map(|(_, v)| v.as_str())
 99	        .unwrap_or("");
100	
101	    if transfer_encoding.to_lowercase().contains("chunked") {
102	        return read_chunked_body(reader).await;
103	    }
104	
105	    let content_length = headers
106	        .iter()
107	        .find(|(k, _)| k == "content-length")
108	        .and_then(|(_, v)| v.parse::<usize>().ok())
109	        .unwrap_or(0);
110	
111	    if content_length == 0 {
112	        return Ok(Vec::new());
113	    }
114	
115	    if content_length > MAX_BODY_SIZE {
116	        return Err(NanowebError::BadRequest("Body too large".into()));
117	    }
118	
119	    let mut body = vec![0u8; content_length];
120	    reader
121	        .read_exact(&mut body)
122	        .await
123	        .map_err(NanowebError::Io)?;
124	    Ok(body)
125	}
126	
127	async fn read_chunked_body<R: AsyncBufRead + Unpin>(
128	    reader: &mut R,
129	) -> Result<Vec<u8>, NanowebError> {
130	    let mut body = Vec::new();
131	
132	    loop {
133	        let mut size_line = String::new();
134	        reader
135	            .read_line(&mut size_line)
136	            .await
137	            .map_err(NanowebError::Io)?;
138	        let size_str = size_line.trim().split(';').next().unwrap_or("").trim();
139	        let chunk_size = usize::from_str_radix(size_str, 16)
140	            .map_err(|_| NanowebError::Parse(format!("Invalid chunk size: {}", size_str)))?;
141	
142	        if chunk_size == 0 {
143	            // Read trailing CRLF
144	            let mut trailing = String::new();
145	            reader
146	                .read_line(&mut trailing)
147	                .await
148	                .map_err(NanowebError::Io)?;
149	            break;
150	        }
151	
152	        if body.len() + chunk_size > MAX_BODY_SIZE {
153	            return Err(NanowebError::BadRequest("Chunked body too large".into()));
154	        }
155	
156	        let mut chunk = vec![0u8; chunk_size];
157	        reader
158	            .read_exact(&mut chunk)
159	            .await
160	            .map_err(NanowebError::Io)?;
161	        body.extend_from_slice(&chunk);
162	
163	        // Read trailing CRLF after chunk
164	        let mut crlf = [0u8; 2];
165	        reader
166	            .read_exact(&mut crlf)
167	            .await
168	            .map_err(NanowebError::Io)?;
169	        if crlf != [b'\r', b'\n'] {
170	            return Err(NanowebError::Parse("Missing CRLF after chunk data".into()));
171	        }
172	    }
173	
174	    Ok(body)
175	}

