 32	    /// Parse a complete HTTP/1.1 request from bytes.
 33	    /// Returns (Request, bytes_consumed) on success.
 34	    pub fn parse(buf: &[u8]) -> Result<(Request, usize), ParseError> {
 35	        if buf.len() > MAX_HEADER_SIZE * 10 {
 36	            return Err(ParseError::TooLarge);
 37	        }
 38	
 39	        // Find end of headers (\r\n\r\n)
 40	        let header_end = find_double_crlf(buf).ok_or(ParseError::Incomplete)?;
 41	        let header_section = &buf[..header_end];
 42	
 43	        if header_section.len() > MAX_REQUEST_LINE + MAX_HEADERS * 256 {
 44	            return Err(ParseError::TooLarge);
 45	        }
 46	
 47	        // Split into lines
 48	        let mut lines = split_crlf(header_section);
 49	        if lines.is_empty() {
 50	            return Err(ParseError::InvalidRequestLine("empty request".to_string()));
 51	        }
 52	
 53	        // Parse request line
 54	        let request_line = lines.remove(0);
 55	        let (method, path, query, version) = parse_request_line(request_line)?;
 56	
 57	        // Parse headers
 58	        let mut headers = HashMap::new();
 59	        for line in lines {
 60	            if line.is_empty() {
 61	                continue;
 62	            }
 63	            let (name, value) = parse_header(line)?;
 64	            headers.insert(name.to_lowercase(), value);
 65	        }
 66	
 67	        let body_start = header_end + 4; // skip \r\n\r\n
 68	
 69	        // Determine body length
 70	        let body = if let Some(cl) = headers.get("content-length") {
 71	            let len: usize = cl
 72	                .trim()
 73	                .parse()
 74	                .map_err(|_| ParseError::InvalidHeader("invalid content-length".to_string()))?;
 75	            if body_start + len > buf.len() {
 76	                return Err(ParseError::Incomplete);
 77	            }
 78	            buf[body_start..body_start + len].to_vec()
 79	        } else if headers
 80	            .get("transfer-encoding")
 81	            .map(|v| v.to_lowercase().contains("chunked"))
 82	            .unwrap_or(false)
 83	        {
 84	            parse_chunked_body(&buf[body_start..])?
 85	        } else {
 86	            Vec::new()
 87	        };
 88	
 89	        let body_len = if headers
 90	            .get("transfer-encoding")
 91	            .map(|v| v.to_lowercase().contains("chunked"))
 92	            .unwrap_or(false)
 93	        {
 94	            // For chunked, find the end
 95	            let consumed = find_chunked_end(&buf[body_start..]).unwrap_or(buf.len() - body_start);
 96	            consumed
 97	        } else {
 98	            body.len()
 99	        };
100	
101	        let total_consumed = body_start + body_len;
102	
103	        let mut req = Request::new(method, path);
104	        req.query = query;
105	        req.version = version;
106	        req.headers = headers;
107	        req.body = body;
108	
109	        Ok((req, total_consumed))

