14	pub struct Next<'a> {
15	    pub(crate) middlewares: &'a [Arc<dyn Middleware>],
16	    pub(crate) handler: &'a (dyn Fn(
17	        Request,
18	    ) -> std::pin::Pin<
19	        Box<dyn std::future::Future<Output = Result<Response, NanowebError>> + Send>,
20	    > + Send
