24	impl<'a> Next<'a> {
25	    pub async fn run(self, req: Request) -> Result<Response, NanowebError> {
26	        if let Some((first, rest)) = self.middlewares.split_first() {
27	            let next = Next {
28	                middlewares: rest,
29	                handler: self.handler,
30	            };
31	            first.handle(req, next).await
32	        } else {
33	            (self.handler)(req).await
34	        }
35	    }
36	}
