 35	    pub fn record_request(&self, method: &str, status_class: &str, route: &str) {
 36	        let key = (
 37	            method.to_string(),
 38	            status_class.to_string(),
 39	            route.to_string(),
 40	        );
 41	        let mut inner = self.inner.lock().unwrap();
 42	        *inner.request_counts.entry(key).or_insert(0) += 1;
 43	    }
 44	
 45	    pub fn record_duration(&self, method: &str, route: &str, duration_secs: f64) {
 46	        let key = (method.to_string(), route.to_string());
 47	        let mut inner = self.inner.lock().unwrap();
 48	
 49	        *inner.request_duration_sum.entry(key.clone()).or_insert(0.0) += duration_secs;
 50	        *inner.request_duration_count.entry(key.clone()).or_insert(0) += 1;
 51	
 52	        let buckets = inner
 53	            .request_duration_buckets
 54	            .entry(key)
 55	            .or_insert_with(|| HISTOGRAM_BUCKETS.iter().map(|&b| (b, 0u64)).collect());
 56	        for (bound, count) in buckets.iter_mut() {
 57	            if duration_secs <= *bound {
 58	                *count += 1;
 59	            }
 60	        }
 61	    }
