 63	    pub fn render_text(&self) -> String {
 64	        let inner = self.inner.lock().unwrap();
 65	        let mut out = String::new();
 66	
 67	        // http_requests_total
 68	        out.push_str("# HELP http_requests_total Total HTTP requests\n");
 69	        out.push_str("# TYPE http_requests_total counter\n");
 70	        for ((method, status_class, route), count) in &inner.request_counts {
 71	            out.push_str(&format!(
 72	                "http_requests_total{{method=\"{}\",status_class=\"{}\",route=\"{}\"}} {}\n",
 73	                method, status_class, route, count
 74	            ));
 75	        }
 76	
 77	        // http_request_duration_seconds
 78	        out.push_str("# HELP http_request_duration_seconds HTTP request duration in seconds\n");
 79	        out.push_str("# TYPE http_request_duration_seconds histogram\n");
 80	        for ((method, route), buckets) in &inner.request_duration_buckets {
 81	            let sum = inner
 82	                .request_duration_sum
 83	                .get(&(method.clone(), route.clone()))
 84	                .copied()
 85	                .unwrap_or(0.0);
 86	            let count = inner
 87	                .request_duration_count
 88	                .get(&(method.clone(), route.clone()))
 89	                .copied()
 90	                .unwrap_or(0);
 91	
 92	            for (bound, bucket_count) in buckets {
 93	                out.push_str(&format!(
 94	                    "http_request_duration_seconds_bucket{{method=\"{}\",route=\"{}\",le=\"{}\"}} {}\n",
 95	                    method, route, bound, bucket_count
 96	                ));
 97	            }
 98	            out.push_str(&format!(
 99	                "http_request_duration_seconds_bucket{{method=\"{}\",route=\"{}\",le=\"+Inf\"}} {}\n",
100	                method, route, count
101	            ));
102	            out.push_str(&format!(
103	                "http_request_duration_seconds_sum{{method=\"{}\",route=\"{}\"}} {}\n",
104	                method, route, sum
105	            ));
106	            out.push_str(&format!(
107	                "http_request_duration_seconds_count{{method=\"{}\",route=\"{}\"}} {}\n",
108	                method, route, count
109	            ));
110	        }
111	
112	        out
113	    }
