 63	fn render_template(
 64	    template: &str,
 65	    context: &HashMap<String, Value>,
 66	) -> Result<String, NanowebError> {
 67	    let mut output = String::new();
 68	    let mut chars = template.char_indices().peekable();
 69	
 70	    while let Some((i, c)) = chars.next() {
 71	        if c == '{' {
 72	            if let Some(&(_, '{')) = chars.peek() {
 73	                chars.next(); // consume second {
 74	
 75	                // Read tag
 76	                let rest = &template[i + 2..];
 77	                let close = rest
 78	                    .find("}}")
 79	                    .ok_or_else(|| NanowebError::Template("unclosed template tag".to_string()))?;
 80	                let tag = rest[..close].trim();
 81	
 82	                // Skip past the tag in main iterator
 83	                for _ in 0..close + 4 - 2 {
 84	                    chars.next();
 85	                }
 86	
 87	                if let Some(name) = tag.strip_prefix('#') {
 88	                    // Block section {{#name}}...{{/name}}
 89	                    let name = name.trim();
 90	                    let section_end = format!("{{{{/{}}}}}", name);
 91	                    let current_pos = i + 2 + close + 2;
 92	                    let remaining = &template[current_pos..];
 93	                    let end = remaining.find(&section_end).ok_or_else(|| {
 94	                        NanowebError::Template(format!("unclosed section: {}", name))
 95	                    })?;
 96	                    let section_body = &remaining[..end];
 97	
 98	                    // Skip the section in the main iterator
 99	                    for _ in 0..end + section_end.len() {
100	                        chars.next();
101	                    }
102	
103	                    if let Some(val) = context.get(name) {
104	                        if let Value::List(items) = val {
105	                            for item in items {
106	                                let rendered = render_template(section_body, item)?;
107	                                output.push_str(&rendered);
108	                            }
109	                        } else if val.is_truthy() {
110	                            let rendered = render_template(section_body, context)?;
111	                            output.push_str(&rendered);
112	                        }
113	                    }
114	                } else if let Some(name) = tag.strip_prefix('^') {
115	                    // Inverted section {{^name}}...{{/name}}
116	                    let name = name.trim();
117	                    let section_end = format!("{{{{/{}}}}}", name);
118	                    let current_pos = i + 2 + close + 2;
119	                    let remaining = &template[current_pos..];
120	                    let end = remaining.find(&section_end).ok_or_else(|| {
121	                        NanowebError::Template(format!("unclosed inverted section: {}", name))
122	                    })?;
123	                    let section_body = &remaining[..end];
124	
125	                    for _ in 0..end + section_end.len() {
126	                        chars.next();
127	                    }
128	
129	                    let render = context.get(name).map(|v| !v.is_truthy()).unwrap_or(true);
130	                    if render {
131	                        let rendered = render_template(section_body, context)?;
132	                        output.push_str(&rendered);
133	                    }
134	                } else if tag.starts_with('/') {
135	                    // End tag - should have been consumed above
136	                    return Err(NanowebError::Template(format!(
137	                        "unexpected end tag: {}",
138	                        tag
139	                    )));
140	                } else {
141	                    // Variable substitution {{name}}
142	                    if let Some(val) = context.get(tag) {
143	                        match val {
144	                            Value::String(s) => output.push_str(s),
145	                            Value::Bool(b) => output.push_str(&b.to_string()),
146	                            _ => output.push_str("[object]"),
147	                        }
148	                    }
149	                }
150	                continue;
151	            }
152	        }
153	        output.push(c);
154	    }
155	
156	    Ok(output)

