29	        self.tokens = (self.tokens + elapsed * self.rate).min(self.capacity);
30	        self.last_refill = now;
31	
32	        if self.tokens >= 1.0 {
33	            self.tokens -= 1.0;
34	            true
35	        } else {
36	            false
37	        }
38	    }
