172	fn parse_header(line: &[u8]) -> Result<(String, String), ParseError> {
173	    let s = std::str::from_utf8(line)
174	        .map_err(|_| ParseError::InvalidHeader("invalid UTF-8 in header".to_string()))?;
175	
176	    let colon_pos = s
177	        .find(':')
178	        .ok_or_else(|| ParseError::InvalidHeader(format!("no colon in header: {}", s)))?;
179	
180	    let name = s[..colon_pos].trim().to_string();
181	    let value = s[colon_pos + 1..].trim().to_string();
182	
183	    if name.is_empty() {
184	        return Err(ParseError::InvalidHeader("empty header name".to_string()));
185	    }
186	
187	    Ok((name, value))
188	}
