190	fn parse_chunked_body(buf: &[u8]) -> Result<Vec<u8>, ParseError> {
191	    let mut body = Vec::new();
192	    let mut pos = 0;
193	
194	    loop {
195	        // Read chunk size line
196	        let line_end = find_crlf(&buf[pos..]).ok_or(ParseError::Incomplete)?;
197	        let size_str = std::str::from_utf8(&buf[pos..pos + line_end])
198	            .map_err(|_| ParseError::InvalidBody("invalid chunk size".to_string()))?;
199	        // Chunk size may have extensions after semicolon
200	        let size_str = size_str.split(';').next().unwrap_or("").trim();
201	        let chunk_size = usize::from_str_radix(size_str, 16).map_err(|_| {
202	            ParseError::InvalidBody(format!("invalid chunk size hex: {}", size_str))
203	        })?;
204	
205	        pos += line_end + 2; // skip \r\n
206	
207	        if chunk_size == 0 {
208	            // Last chunk, skip trailing \r\n
209	            break;
210	        }
211	
212	        if pos + chunk_size > buf.len() {
213	            return Err(ParseError::Incomplete);
214	        }
215	
216	        body.extend_from_slice(&buf[pos..pos + chunk_size]);
217	        pos += chunk_size + 2; // skip chunk data + \r\n
218	    }
219	
220	    Ok(body)
221	}
222	
223	fn find_chunked_end(buf: &[u8]) -> Option<usize> {
224	    let mut pos = 0;
225	    loop {
226	        let line_end = find_crlf(&buf[pos..])?;
227	        let size_str = std::str::from_utf8(&buf[pos..pos + line_end]).ok()?;
228	        let size_str = size_str.split(';').next().unwrap_or("").trim();
229	        let chunk_size = usize::from_str_radix(size_str, 16).ok()?;
230	        pos += line_end + 2;
231	
232	        if chunk_size == 0 {
233	            // last chunk: skip optional trailers, then \r\n
234	            if pos + 2 <= buf.len() && &buf[pos..pos + 2] == b"\r\n" {
235	                return Some(pos + 2);
236	            }
237	            return Some(pos);
238	        }
239	
240	        if pos + chunk_size + 2 > buf.len() {
241	            return None;
242	        }
243	        pos += chunk_size + 2;
244	    }
245	}
246	
247	fn find_crlf(buf: &[u8]) -> Option<usize> {
248	    buf.windows(2).position(|w| w == b"\r\n")
249	}

