123	        stream: &mut (impl tokio::io::AsyncRead + Unpin),
124	        parsed: &mut ParsedRequest,
125	        already_read: &[u8],
126	    ) -> Result<(), ParseError> {
127	        use tokio::io::AsyncReadExt;
128	
129	        // Check transfer-encoding
130	        let is_chunked = parsed
131	            .headers
132	            .get("transfer-encoding")
133	            .map(|v| v.to_lowercase().contains("chunked"))
134	            .unwrap_or(false);
135	
136	        if is_chunked {
137	            let mut body = already_read.to_vec();
138	            // Read chunked body
139	            loop {
140	                // Need to read chunk size line
141	                let chunk_size = read_chunk_size(stream, &mut body).await?;
142	                if chunk_size == 0 {
143	                    break;
144	                }
145	                if body.len() + chunk_size > Self::MAX_BODY_SIZE {
146	                    return Err(ParseError::TooLarge);
147	                }
148	                let mut chunk_data = vec![0u8; chunk_size];
149	                stream
150	                    .read_exact(&mut chunk_data)
151	                    .await
152	                    .map_err(|e| ParseError::Invalid(e.to_string()))?;
153	                body.extend_from_slice(&chunk_data);
154	                // Read trailing CRLF
155	                let mut crlf = [0u8; 2];
156	                stream
157	                    .read_exact(&mut crlf)
158	                    .await
159	                    .map_err(|e| ParseError::Invalid(e.to_string()))?;
160	            }
161	            parsed.body = body;
162	        } else if let Some(content_length) = parsed.headers.get("content-length") {
163	            let content_length: usize = content_length
164	                .parse()
165	                .map_err(|_| ParseError::Invalid("Invalid Content-Length".to_string()))?;
166	
167	            if content_length > Self::MAX_BODY_SIZE {
168	                return Err(ParseError::TooLarge);
169	            }
170	
171	            let mut body = already_read.to_vec();
172	            let remaining = content_length.saturating_sub(body.len());
173	
174	            if remaining > 0 {
175	                let mut rest = vec![0u8; remaining];
176	                stream
177	                    .read_exact(&mut rest)
178	                    .await
179	                    .map_err(|e| ParseError::Invalid(e.to_string()))?;
180	                body.extend_from_slice(&rest);
181	            }
182	
183	            parsed.body = body[..content_length].to_vec();
184	        }
185	        // Otherwise no body
186	
187	        Ok(())
