161	        // Read data
162	        let n = match stream.read(&mut buf).await {
163	            Ok(0) => break,
164	            Ok(n) => n,
165	            Err(e) => {
166	                error!("Read error: {}", e);
167	                break;
168	            }
169	        };
170	
171	        read_buf.extend_from_slice(&buf[..n]);
172	
173	        // Try to parse headers
174	        match HttpParser::parse_headers(&read_buf) {
175	            Ok(Some((mut parsed, body_start))) => {
