181	                    let resp = Response::new(StatusCode::BAD_REQUEST)
182	                        .with_body(e.to_string().into_bytes());
183	                    let _ = stream.write_all(&resp.into_bytes()).await;
184	                    break;
185	                }
186	
187	                // Build request
188	                let method = Method::from_str(&parsed.method);
189	                let mut headers = Headers::new();
190	                for (k, v) in parsed.headers {
191	                    headers.set(k, v);
192	                }
193	
