 96	    async fn accept_loop(&self, listener: TcpListener) -> Result<(), NanowebError> {
 97	        let mut shutdown_rx = self.shutdown_rx.clone();
 98	        let graceful_timeout = std::time::Duration::from_secs(self.state.config.graceful_timeout_s);
 99	        let in_flight = Arc::new(tokio::sync::Semaphore::new(10000));
100	
101	        loop {
102	            tokio::select! {
103	                result = listener.accept() => {
104	                    match result {
105	                        Ok((stream, remote_addr)) => {
106	                            let state = self.state.clone();
107	                            let permit = in_flight.clone().acquire_owned().await.unwrap();
108	                            tokio::spawn(async move {
109	                                handle_connection(stream, remote_addr, state).await;
110	                                drop(permit);
111	                            });
112	                        }
113	                        Err(e) => {
114	                            error!("Accept error: {}", e);
115	                        }
116	                    }
117	                }
118	                _ = shutdown_rx.changed() => {
119	                    if *shutdown_rx.borrow() {
120	                        info!("Shutdown signal received, stopping accept loop");
121	                        break;
122	                    }
123	                }
124	            }
125	        }
126	
127	        // Wait for in-flight requests or timeout
128	        info!("Waiting for in-flight requests to complete...");
129	        let wait_start = Instant::now();
130	        loop {
131	            let available = in_flight.available_permits();
132	            if available == 10000 {
133	                break;
134	            }
135	            if wait_start.elapsed() >= graceful_timeout {
136	                info!("Graceful timeout reached, forcing shutdown");
137	                break;
138	            }
139	            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
140	        }
141	
142	        info!("Server shutdown complete");
143	        Ok(())
144	    }
