 13	fn render_value(template: &str, context: &Value) -> Result<String, NanowebError> {
 14	    let mut result = String::new();
 15	    let mut chars = template.char_indices().peekable();
 16	
 17	    while let Some((i, c)) = chars.next() {
 18	        if c == '{' && template[i..].starts_with("{{") {
 19	            // Find closing }}
 20	            let rest = &template[i + 2..];
 21	            if let Some(end) = rest.find("}}") {
 22	                let tag = rest[..end].trim();
 23	
 24	                // Skip past }}
 25	                let skip_to = i + 2 + end + 2;
 26	                // advance chars to skip_to
 27	                // We need to consume chars up to skip_to
 28	                while chars.peek().map(|(j, _)| *j).unwrap_or(usize::MAX) < skip_to {
 29	                    chars.next();
 30	                }
 31	
 32	                if let Some(stripped) = tag.strip_prefix('#') {
 33	                    // Section tag: {{#name}}...{{/name}}
 34	                    let name = stripped.trim();
 35	                    let closing_tag = format!("{{{{/{}}}}}", name);
 36	                    let after_open = &template[skip_to..];
 37	                    if let Some(close_pos) = after_open.find(&closing_tag) {
 38	                        let section_content = &after_open[..close_pos];
 39	                        let after_section = &after_open[close_pos + closing_tag.len()..];
 40	
 41	                        // Advance chars past the section
 42	                        let section_end = skip_to + close_pos + closing_tag.len();
 43	                        while chars.peek().map(|(j, _)| *j).unwrap_or(usize::MAX) < section_end {
 44	                            chars.next();
 45	                        }
 46	
 47	                        // Look up name in context
 48	                        let value = lookup(context, name);
 49	                        match &value {
 50	                            Value::Array(arr) => {
 51	                                for item in arr {
 52	                                    result.push_str(&render_value(section_content, item)?);
 53	                                }
 54	                            }
 55	                            Value::Bool(true) => {
 56	                                result.push_str(&render_value(section_content, context)?);
 57	                            }
 58	                            Value::Bool(false) | Value::Null => {
 59	                                // Don't render
 60	                            }
 61	                            _ => {
 62	                                // Truthy: render once with merged context
 63	                                result.push_str(&render_value(section_content, &value)?);
 64	                            }
 65	                        }
 66	
 67	                        // Now render the remainder
 68	                        result.push_str(&render_value(after_section, context)?);
 69	                        return Ok(result);
 70	                    }
 71	                } else if let Some(stripped) = tag.strip_prefix('^') {
 72	                    // Inverted section: {{^name}}...{{/name}}
 73	                    let name = stripped.trim();
 74	                    let closing_tag = format!("{{{{/{}}}}}", name);
 75	                    let after_open = &template[skip_to..];
 76	                    if let Some(close_pos) = after_open.find(&closing_tag) {
 77	                        let section_content = &after_open[..close_pos];
 78	                        let after_section = &after_open[close_pos + closing_tag.len()..];
 79	
 80	                        let section_end = skip_to + close_pos + closing_tag.len();
 81	                        while chars.peek().map(|(j, _)| *j).unwrap_or(usize::MAX) < section_end {
 82	                            chars.next();
 83	                        }
 84	
 85	                        let value = lookup(context, name);
 86	                        let is_falsy = match &value {
 87	                            Value::Bool(false) | Value::Null => true,
 88	                            Value::Array(arr) => arr.is_empty(),
 89	                            Value::String(s) => s.is_empty(),
 90	                            _ => false,
 91	                        };
 92	
 93	                        if is_falsy {
 94	                            result.push_str(&render_value(section_content, context)?);
 95	                        }
 96	
 97	                        result.push_str(&render_value(after_section, context)?);
 98	                        return Ok(result);
 99	                    }
100	                } else if tag.starts_with('/') {
101	                    // Closing tag - should be handled by section, skip
102	                } else {
103	                    // Variable: {{name}}
104	                    let value = lookup(context, tag);
105	                    result.push_str(&value_to_string(&value));
106	                }
107	            } else {
108	                result.push(c);
109	            }
110	        } else {
111	            result.push(c);
112	        }
113	    }
114	
115	    Ok(result)

