 48	        let header_section = &buf[..header_end];
 49	        let body_start = header_end + 4;
 50	
 51	        // Parse request line
 52	        let line_end = match find_crlf(header_section) {
 53	            Some(pos) => pos,
 54	            None => return Err(ParseError::Invalid("Missing request line".to_string())),
 55	        };
