 80	        while pos < header_section.len() {
 81	            let remaining = &header_section[pos..];
 82	            let (line_end, skip) = match find_crlf(remaining) {
 83	                Some(p) => (p, 2),
 84	                None => {
 85	                    // Last header may not have trailing CRLF (it's included in \r\n\r\n)
 86	                    if remaining.is_empty() {
 87	                        break;
 88	                    }
 89	                    (remaining.len(), 0)
 90	                }
 91	            };
 92	
 93	            if line_end == 0 {
 94	                break;
 95	            }
 96	
 97	            let header_line = std::str::from_utf8(&remaining[..line_end])
 98	                .map_err(|_| ParseError::Invalid("Invalid UTF-8 in header".to_string()))?;
