 43	        .next()
 44	        .ok_or_else(|| ParseError::Protocol("missing version".into()))?
 45	    {
 46	        "HTTP/1.0" => Version::Http10,
 47	        "HTTP/1.1" => Version::Http11,
 48	        other => return Err(ParseError::Protocol(format!("unsupported version {other}"))),
 49	    };
