 52	    }
 53	
 54	    let mut headers = HashMap::new();
 55	    for line in lines {
 56	        if line.is_empty() {
 57	            continue;
 58	        }
 59	        let (name, value) = line
 60	            .split_once(':')
 61	            .ok_or_else(|| ParseError::Protocol("malformed header".into()))?;
 62	        let key = name.trim().to_ascii_lowercase();
 63	        let val = value.trim().to_string();
 64	        if headers.insert(key, val).is_some() {
 65	            // Duplicate header names are allowed generally, but we keep last-value semantics.
 66	        }
