34	impl<'a> Next<'a> {
35	    pub fn new(
36	        middlewares: &'a [Arc<dyn Middleware>],
37	        handler: &'a dyn Handler,
38	        ctx: Arc<AppState>,
39	    ) -> Self {
40	        Self {
41	            middlewares,
42	            handler,
43	            ctx,
44	            index: 0,
45	        }
46	    }
47	
48	    pub async fn run(self, req: Request) -> Result<Response> {
49	        if self.index >= self.middlewares.len() {
50	            self.handler.handle(req, self.ctx).await
51	        } else {
52	            let next = Self {
53	                middlewares: self.middlewares,
54	                handler: self.handler,
55	                ctx: self.ctx.clone(),
56	                index: self.index + 1,
57	            };
58	            self.middlewares[self.index]
59	                .handle(req, self.ctx, next)
60	                .await
61	        }
62	    }

