118	                    );
119	                    response.set_header("x-request-id", req.request_id.clone());
120	                    return Ok(response);
121	                }
122	                let mut chain = self.middleware.clone();
123	                chain.extend(target.middleware.iter().cloned());
124	                let response = Next::new(&chain, target.handler.as_ref(), self.state.clone())
125	                    .run(req)
126	                    .await?;
127	                return Ok(response);

