19	fn render_template(template: &str, scopes: &[Value]) -> String {
20	    let mut out = String::new();
21	    let mut cursor = 0usize;
22	    while let Some(open) = template[cursor..].find("{{") {
23	        let open = cursor + open;
24	        out.push_str(&template[cursor..open]);
25	        let close = template[open + 2..]
26	            .find("}}")
27	            .map(|idx| open + 2 + idx)
28	            .unwrap_or_else(|| template.len());
29	        if close == template.len() {
30	            out.push_str(&template[open..]);
31	            return out;
32	        }
33	        let tag = template[open + 2..close].trim();
34	        if let Some(section) = tag.strip_prefix('#') {
35	            let (inner, end) = extract_section(template, close + 2, section.trim());
36	            if let Some(value) = lookup(scopes, section.trim()) {
37	                if is_truthy(value) {
38	                    match value {
39	                        Value::Array(items) => {
40	                            for item in items {
41	                                let mut next = scopes.to_vec();
42	                                next.push(item.clone());
43	                                out.push_str(&render_template(&inner, &next));
44	                            }
45	                        }
46	                        Value::Object(_) => {
47	                            let mut next = scopes.to_vec();
48	                            next.push(value.clone());
49	                            out.push_str(&render_template(&inner, &next));
50	                        }
51	                        _ => {
52	                            out.push_str(&render_template(&inner, scopes));
53	                        }
54	                    }
55	                }
56	            }
57	            cursor = end;
58	            continue;
59	        }
60	        if let Some(section) = tag.strip_prefix('^') {
61	            let (inner, end) = extract_section(template, close + 2, section.trim());
62	            let should_render = match lookup(scopes, section.trim()) {
63	                Some(value) => !is_truthy(value),
64	                None => true,
65	            };
66	            if should_render {
67	                out.push_str(&render_template(&inner, scopes));
68	            }
69	            cursor = end;
70	            continue;
71	        }
72	        if tag.starts_with('/') {
73	            cursor = close + 2;
74	            continue;
75	        }
76	        if let Some(value) = lookup(scopes, tag) {
77	            out.push_str(&stringify(value));
78	        }
79	        cursor = close + 2;
80	    }
81	    out.push_str(&template[cursor..]);
82	    out

