36	#[async_trait]
37	impl Middleware for RateLimitMiddleware {
38	    async fn handle(&self, req: Request, ctx: Arc<AppState>, next: Next<'_>) -> Result<Response> {
39	        let ip = req
40	            .remote_addr
41	            .map(|addr| addr.ip())
42	            .unwrap_or(std::net::IpAddr::from([127, 0, 0, 1]));
43	        let allowed = {
44	            let mut buckets = self.buckets.lock().unwrap();
45	            let bucket = buckets.entry(ip).or_insert_with(|| Bucket {
46	                tokens: self.burst as f64,
47	                last_refill: Instant::now(),
48	            });
49	            let elapsed = bucket.last_refill.elapsed().as_secs_f64();
50	            bucket.tokens =
51	                (bucket.tokens + elapsed * self.tokens_per_second).min(self.burst as f64);
52	            bucket.last_refill = Instant::now();
53	            if bucket.tokens >= 1.0 {
54	                bucket.tokens -= 1.0;
55	                true
56	            } else {
57	                false
58	            }
59	        };
60	        if !allowed {
61	            return Ok(Response::text(
62	                StatusCode::TooManyRequests,
63	                "rate limit exceeded",
64	            ));
65	        }
66	        let _ = ctx;
67	        next.run(req).await
68	    }

