40	        let cookie = self.read_cookie(&req);
41	        if !req.method.is_safe() {
42	            let header = req.header(&self.header_name).map(|value| value.to_string());
43	            if cookie.is_none() || header.is_none() || cookie != header {
44	                return Ok(Response::text(
45	                    StatusCode::Forbidden,
46	                    "csrf validation failed",
47	                ));
48	            }
49	        }
50	        let mut response = next.run(req).await?;
51	        if cookie.is_none() {
52	            let mut bytes = [0u8; 16];
53	            OsRng.fill_bytes(&mut bytes);
54	            let token = base64::engine::general_purpose::STANDARD.encode(bytes);
55	            response.set_header(
56	                "set-cookie",
57	                format!(
58	                    "{}={}; HttpOnly; Path=/; SameSite=Lax",
59	                    self.cookie_name, token
60	                ),
61	            );
62	        }
63	        let _ = ctx;
64	        Ok(response)

