138	fn parse_chunked(buf: &[u8]) -> Result<(Vec<u8>, usize), ParseError> {
139	    let mut cursor = 0usize;
140	    let mut body = Vec::new();
141	    loop {
142	        let size_end = find_line_end(&buf[cursor..]).ok_or(ParseError::Incomplete)?;
143	        let size_line = std::str::from_utf8(&buf[cursor..cursor + size_end])
144	            .map_err(|_| ParseError::Protocol("invalid chunk size line".into()))?;
145	        let size = size_line
146	            .split(';')
147	            .next()
148	            .ok_or_else(|| ParseError::Protocol("invalid chunk size".into()))?
149	            .trim();
150	        let size = usize::from_str_radix(size, 16)
151	            .map_err(|_| ParseError::Protocol("invalid chunk size".into()))?;
152	        cursor += size_end + 2;
153	        if size == 0 {
154	            if buf[cursor..].starts_with(b"\r\n") {
155	                cursor += 2;
156	                break;
157	            }
158	            let trailer_end = find_header_end(&buf[cursor..]).ok_or(ParseError::Incomplete)?;
159	            cursor += trailer_end + 4;
160	            break;
161	        }
162	        if buf.len() < cursor + size + 2 {
163	            return Err(ParseError::Incomplete);
164	        }
165	        body.extend_from_slice(&buf[cursor..cursor + size]);
166	        cursor += size + 2;
167	        if &buf[cursor - 2..cursor] != b"\r\n" {
168	            return Err(ParseError::Protocol("chunk missing terminator".into()));
169	        }
170	    }
171	    Ok((body, cursor))
172	}
