40	    loop {
41	        let mut line = String::new();
42	        let bytes = reader.read_line(&mut line).await?;
43	        if bytes == 0 {
44	            return Err(NanowebError::Request("unexpected eof in headers".into()));
45	        }
46	        let line = line.trim_end_matches(['\r', '\n']);
47	        if line.is_empty() {
48	            break;
49	        }
50	        let (name, value) = line
51	            .split_once(':')
52	            .ok_or_else(|| NanowebError::Request(format!("invalid header line: {line}")))?;
53	        headers.insert(name.trim(), value.trim().to_string());
54	    }
55	
56	    let transfer_encoding = headers
57	        .get("transfer-encoding")
58	        .map(|v| v.to_ascii_lowercase());
59	    let content_length = headers.get("content-length").map(|v| v.to_string());
60	    if transfer_encoding.is_some() && content_length.is_some() {
61	        return Err(NanowebError::Request(
62	            "content-length and transfer-encoding cannot both be set".into(),
63	        ));
64	    }
65	
66	    let body = if matches!(transfer_encoding.as_deref(), Some("chunked")) {
67	        read_chunked_body(reader).await?
68	    } else if let Some(content_length) = content_length {
69	        let len: usize = content_length
70	            .parse()
71	            .map_err(|_| NanowebError::Request("invalid content-length".into()))?;
72	        let mut body = vec![0u8; len];
73	        reader.read_exact(&mut body).await?;
74	        body
75	    } else {
76	        Vec::new()
77	    };
78	
79	    let (path, query) = split_target(target);
80	    Ok(Some(Request {
81	        method,
82	        target: target.to_string(),
83	        path,
84	        query,
85	        version,
86	        headers,
87	        body,
88	        params: Default::default(),
89	        remote_addr: None,
90	        request_id: String::new(),
91	        session: None,
92	    }))
93	}

