191	fn next_segment(path: &str, start: usize) -> Option<(&str, usize)> {
192	    if start >= path.len() {
193	        return None;
194	    }
195	    let bytes = path.as_bytes();
196	    let mut end = start;
197	    while end < path.len() && bytes[end] != b'/' {
198	        end += 1;
199	    }
200	    let next_start = if end < path.len() { end + 1 } else { end };
201	    Some((&path[start..end], next_start))
202	}

