 74	
 75	impl TrieNode {
 76	    fn insert(&mut self, pattern: &str, method: Method, handler: Arc<dyn Handler>) -> Result<()> {
 77	        let normalized = normalize_path(pattern);
 78	        if normalized.is_empty() {
 79	            self.handlers.insert(method, handler);
 80	            self.pattern = Some(pattern.to_string());
 81	            return Ok(());
 82	        }
 83	
 84	        let mut node = self;
 85	        let mut start = 0;
 86	        while let Some((segment, next_start)) = next_segment(&normalized, start) {
 87	            let is_last = next_start >= normalized.len();
 88	            if let Some(name) = segment.strip_prefix(':') {
 89	                let child = node.param.get_or_insert_with(|| {
 90	                    let mut child = TrieNode::default();
 91	                    child.param_name = Some(name.to_string());
 92	                    Box::new(child)
 93	                });
 94	                if child.param_name.as_deref() != Some(name) {
 95	                    return Err(NanowebError::Router(format!(
 96	                        "conflicting parameter names for pattern {pattern}"
 97	                    )));
 98	                }
 99	                node = child.as_mut();
100	            } else if let Some(name) = segment.strip_prefix('*') {
101	                if !is_last {
102	                    return Err(NanowebError::Router(format!(
103	                        "wildcard must be the final segment in pattern {pattern}"
104	                    )));
105	                }
106	                let child = node.wildcard.get_or_insert_with(|| {
107	                    let mut child = TrieNode::default();
108	                    child.wildcard_name = Some(name.to_string());
109	                    Box::new(child)
110	                });
111	                if child.wildcard_name.as_deref() != Some(name) {
112	                    return Err(NanowebError::Router(format!(
113	                        "conflicting wildcard names for pattern {pattern}"
114	                    )));
115	                }
116	                node = child.as_mut();
117	            } else {
118	                node = node
119	                    .literals
120	                    .entry(segment.to_string())
121	                    .or_insert_with(TrieNode::default);
122	            }
123	            start = next_start;
124	        }
125	
126	        node.handlers.insert(method, handler);
127	        node.pattern = Some(pattern.to_string());
128	        Ok(())
129	    }
