514	async fn dispatch_route(
515	    app: &App,
516	    mut request: Request,
517	    route: &RouteMatch<'_>,
518	) -> Result<Response> {
519	    request.params = route.params.clone();
520	    if matches!(request.method, Method::Options) {
521	        let allow = allowed_methods(route.handlers)
522	            .into_iter()
523	            .map(|method| method.as_str())
524	            .collect::<Vec<_>>()
525	            .join(", ");
526	        return Ok(Response::empty(StatusCode::Ok).with_header("allow", allow));
527	    }
528	
529	    let handler = match route.handlers.get(&request.method) {
530	        Some(handler) => handler.clone(),
531	        None if matches!(request.method, Method::Head) => match route.handlers.get(&Method::Get) {
532	            Some(handler) => handler.clone(),
533	            None => {
534	                let allow = allowed_methods(route.handlers)
535	                    .into_iter()
536	                    .map(|method| method.as_str())
537	                    .collect::<Vec<_>>()
538	                    .join(", ");
539	                return Ok(
540	                    Response::text(StatusCode::MethodNotAllowed, "method not allowed")
541	                        .with_header("allow", allow),
542	                );
543	            }
544	        },
545	        None => {
546	            let allow = allowed_methods(route.handlers)
547	                .into_iter()
548	                .map(|method| method.as_str())
549	                .collect::<Vec<_>>()
550	                .join(", ");
551	            return Ok(
552	                Response::text(StatusCode::MethodNotAllowed, "method not allowed")
553	                    .with_header("allow", allow),
554	            );
555	        }
556	    };
557	
558	    let response = middleware::execute(app.middlewares.as_ref(), handler, request).await?;
559	    Ok(response)
560	}

562	async fn write_response<W: AsyncWrite + Unpin>(
563	    writer: &mut W,
564	    request: &Request,
565	    response: &Response,
566	    close: bool,
567	) -> Result<()> {
568	    let status_line = format!("HTTP/1.1 {}\r\n", response.status);
569	    writer.write_all(status_line.as_bytes()).await?;
570	
571	    let mut headers = response.headers.clone();
572	    if close {
573	        headers.insert("connection", "close");
574	    } else {
575	        headers.insert("connection", "keep-alive");
576	    }
577	
578	    let body_len = if matches!(
579	        response.status,
580	        StatusCode::NoContent | StatusCode::NotModified
581	    ) {
582	        0
583	    } else {
584	        response.body.len()
585	    };
586	    headers.insert("content-length", body_len.to_string());
587	
588	    for (key, value) in headers.iter() {
589	        let header = format!("{key}: {value}\r\n");
590	        writer.write_all(header.as_bytes()).await?;
591	    }
592	    writer.write_all(b"\r\n").await?;
593	    if !matches!(request.method, Method::Head) && body_len > 0 {
594	        writer.write_all(&response.body).await?;
595	    }
596	    writer.flush().await?;
597	    Ok(())

