204	pub fn allowed_methods(handlers: &HashMap<Method, Arc<dyn Handler>>) -> Vec<Method> {
205	    let mut methods: Vec<Method> = handlers.keys().cloned().collect();
206	    if methods.contains(&Method::Get) && !methods.contains(&Method::Head) {
207	        methods.push(Method::Head);
208	    }
209	    methods.push(Method::Options);
210	    methods.sort_by(|a, b| a.as_str().cmp(b.as_str()));
211	    methods.dedup();
212	    methods

