21	pub struct Next<'a> {
22	    middlewares: &'a [Arc<dyn Middleware>],
23	    handler: &'a Arc<dyn Handler>,
24	    index: usize,
25	}
26	
27	impl<'a> Next<'a> {
28	    pub async fn run(self, request: Request) -> Result<Response> {
29	        if self.index >= self.middlewares.len() {
30	            self.handler.handle(request).await
31	        } else {
32	            let middleware = &self.middlewares[self.index];
33	            middleware
34	                .handle(
35	                    request,
36	                    Next {
37	                        middlewares: self.middlewares,
