20	        .ok_or_else(|| NanowebError::Tls("private key missing".into()))?;
21	
22	    let config = ServerConfig::builder()
23	        .with_no_client_auth()
24	        .with_single_cert(cert_chain, key)
25	        .map_err(|err| NanowebError::Tls(err.to_string()))?;
26	    Ok(tokio_rustls::TlsAcceptor::from(Arc::new(config)))
27	}
