17	fn render_template(template: &str, stack: &[Value]) -> Result<String> {
18	    let mut output = String::new();
19	    let mut cursor = 0;
20	    while let Some(start) = template[cursor..].find("{{") {
21	        let absolute_start = cursor + start;
22	        output.push_str(&template[cursor..absolute_start]);
23	        let end = template[absolute_start + 2..]
24	            .find("}}")
25	            .ok_or_else(|| NanowebError::Template("unterminated tag".into()))?
26	            + absolute_start
27	            + 2;
28	        let tag = template[absolute_start + 2..end].trim();
29	        cursor = end + 2;
30	        if let Some(name) = tag.strip_prefix('#') {
31	            let (inner, after) = extract_section(template, cursor, name.trim())?;
32	            if is_truthy(lookup(stack, name.trim())) {
33	                match lookup(stack, name.trim()) {
34	                    Some(Value::Array(items)) => {
35	                        for item in items {
36	                            let mut next_stack = stack.to_vec();
37	                            next_stack.push(item.clone());
38	                            output.push_str(&render_template(inner, &next_stack)?);
39	                        }
40	                    }
41	                    Some(Value::Object(_)) => {
42	                        let mut next_stack = stack.to_vec();
43	                        next_stack.push(lookup(stack, name.trim()).unwrap().clone());
44	                        output.push_str(&render_template(inner, &next_stack)?);
45	                    }
46	                    Some(value) => {
47	                        let mut next_stack = stack.to_vec();
48	                        next_stack.push(value.clone());
49	                        output.push_str(&render_template(inner, &next_stack)?);
50	                    }
51	                    None => {}
52	                }
53	            }
54	            cursor = after;
55	        } else if let Some(name) = tag.strip_prefix('^') {
56	            let (inner, after) = extract_section(template, cursor, name.trim())?;
57	            if !is_truthy(lookup(stack, name.trim())) {
58	                output.push_str(&render_template(inner, stack)?);
59	            }
60	            cursor = after;
61	        } else if tag.starts_with('/') {
62	            return Err(NanowebError::Template("unexpected section close".into()));
63	        } else {
64	            if let Some(value) = lookup(stack, tag) {
65	                output.push_str(&value_to_string(value));
66	            }
67	        }
68	    }
69	    output.push_str(&template[cursor..]);
70	    Ok(output)

 73	fn extract_section<'a>(template: &'a str, start: usize, name: &str) -> Result<(&'a str, usize)> {
 74	    let mut cursor = start;
 75	    let mut depth = 1;
 76	    while let Some(open) = template[cursor..].find("{{") {
 77	        let absolute_open = cursor + open;
 78	        let close = template[absolute_open + 2..]
 79	            .find("}}")
 80	            .ok_or_else(|| NanowebError::Template("unterminated tag".into()))?
 81	            + absolute_open
 82	            + 2;
 83	        let tag = template[absolute_open + 2..close].trim();
 84	        if tag == format!("/{}", name) {
 85	            depth -= 1;
 86	            if depth == 0 {
 87	                return Ok((&template[start..absolute_open], close + 2));
 88	            }
 89	        } else if tag == format!("#{}", name) || tag == format!("^{}", name) {
 90	            depth += 1;
 91	        }
 92	        cursor = close + 2;
 93	    }
 94	    Err(NanowebError::Template(format!(
 95	        "missing closing tag for {name}"
 96	    )))
 97	}
 98	
 99	fn lookup<'a>(stack: &'a [Value], key: &str) -> Option<&'a Value> {
100	    if key == "." {
101	        return stack.last();
102	    }
103	    for value in stack.iter().rev() {
104	        if let Some(found) = value.as_object().and_then(|map| map.get(key)) {
105	            return Some(found);
106	        }
107	    }
108	    None
109	}
110	
111	fn is_truthy(value: Option<&Value>) -> bool {
112	    match value {
113	        Some(Value::Bool(value)) => *value,
114	        Some(Value::Null) | None => false,
115	        Some(Value::Array(values)) => !values.is_empty(),
116	        Some(Value::Object(values)) => !values.is_empty(),
117	        Some(Value::String(value)) => !value.is_empty(),
118	        Some(Value::Number(value)) => value.as_i64().map_or(true, |number| number != 0),
119	    }
120	}
121	
122	fn value_to_string(value: &Value) -> String {
123	    match value {
124	        Value::String(value) => value.clone(),
125	        Value::Number(value) => value.to_string(),
126	        Value::Bool(value) => value.to_string(),
127	        Value::Null => String::new(),
128	        other => other.to_string(),
129	    }

