40	impl Middleware for RateLimit {
41	    async fn handle(&self, request: Request, next: Next<'_>) -> Result<Response> {
42	        let Some(addr) = request.remote_addr.map(|addr| addr.ip()) else {
43	            return next.run(request).await;
44	        };
45	        let allowed = {
46	            let mut buckets = self.buckets.lock();
47	            let bucket = buckets.entry(addr).or_insert_with(|| Bucket {
48	                tokens: self.config.burst,
49	                last_refill: Instant::now(),
50	            });
51	            let now = Instant::now();
52	            let elapsed = now.duration_since(bucket.last_refill).as_secs_f64();
53	            bucket.tokens =
54	                (bucket.tokens + elapsed * self.config.permits_per_second).min(self.config.burst);
55	            bucket.last_refill = now;
56	            if bucket.tokens < 1.0 {
57	                false
58	            } else {
59	                bucket.tokens -= 1.0;
60	                true
61	            }
62	        };
63	        if !allowed {
64	            return Ok(Response::text(
65	                StatusCode::TooManyRequests,
66	                "rate limit exceeded",
67	            ));
68	        }
69	        next.run(request).await
70	    }

