531	        None if matches!(request.method, Method::Head) => match route.handlers.get(&Method::Get) {
532	            Some(handler) => handler.clone(),
533	            None => {
534	                let allow = allowed_methods(route.handlers)
535	                    .into_iter()
536	                    .map(|method| method.as_str())
537	                    .collect::<Vec<_>>()
538	                    .join(", ");
539	                return Ok(
540	                    Response::text(StatusCode::MethodNotAllowed, "method not allowed")
541	                        .with_header("allow", allow),
