122	                    return Err(NanowebError::Request(
123	                        "unexpected eof in chunk trailers".into(),
124	                    ));
125	                }
126	                if trailer.trim_end_matches(['\r', '\n']).is_empty() {
127	                    break;
128	                }
129	            }
130	            break;
131	        }
132	
133	        let mut chunk = vec![0u8; size];
134	        reader.read_exact(&mut chunk).await?;
135	        body.extend_from_slice(&chunk);
