 6	    let header_end =
 7	        find_headers_end(input).ok_or_else(|| NanowebError::parse("incomplete headers"))?;
 8	    let head = &input[..header_end];
 9	    let mut lines = head.split(|b| *b == b'\n').map(|l| trim_cr(l));
10	    let request_line = lines
11	        .next()
12	        .ok_or_else(|| NanowebError::parse("missing request line"))?;
13	    let request_line = std::str::from_utf8(request_line)
14	        .map_err(|_| NanowebError::parse("invalid request line"))?;
15	    let mut parts = request_line.split_whitespace();
16	    let method = parts
17	        .next()
18	        .ok_or_else(|| NanowebError::parse("missing method"))?;
19	    let target = parts
20	        .next()
21	        .ok_or_else(|| NanowebError::parse("missing target"))?;
22	    let version = parts
23	        .next()
24	        .ok_or_else(|| NanowebError::parse("missing version"))?;
25	    if parts.next().is_some() || !version.starts_with("HTTP/1.1") {
26	        return Err(NanowebError::parse("invalid request line"));
27	    }
28	    let mut headers = HashMap::new();
29	    for line in lines {
30	        if line.is_empty() {
31	            continue;
32	        }
33	        let s = std::str::from_utf8(line).map_err(|_| NanowebError::parse("invalid header"))?;
34	        let (name, value) = s
35	            .split_once(':')
36	            .ok_or_else(|| NanowebError::parse("malformed header"))?;
37	        headers.insert(name.trim().to_ascii_lowercase(), value.trim().to_string());
38	    }
39	    let body_start = header_end + 4;
40	    let body;
41	    let consumed;
42	    if let Some(te) = headers.get("transfer-encoding") {
43	        if te.to_ascii_lowercase().contains("chunked") {
44	            let (decoded, used) = parse_chunked(&input[body_start..])?;
45	            body = decoded;
46	            consumed = body_start + used;
47	        } else {
48	            return Err(NanowebError::parse("unsupported transfer encoding"));
49	        }
50	    } else if let Some(cl) = headers.get("content-length") {
51	        let len: usize = cl
52	            .parse()
53	            .map_err(|_| NanowebError::parse("invalid content-length"))?;
54	        if input.len() < body_start + len {
55	            return Err(NanowebError::parse("incomplete body"));
56	        }
57	        body = input[body_start..body_start + len].to_vec();
58	        consumed = body_start + len;
59	    } else {
60	        body = Vec::new();
61	        consumed = body_start;
62	    }
63	    Ok((
64	        Request {
65	            method: Method::from(method),
66	            target: target.to_string(),
67	            version: version.to_string(),
68	            headers,
69	            body,
70	            params: HashMap::new(),
71	            peer_addr: None,
72	            request_id: String::new(),
73	        },
74	        consumed,
75	    ))

