 7	    use rustls::crypto::ring::default_provider;
 8	    use rustls_pemfile::{certs, private_key};
 9	    use rustls_pki_types::{CertificateDer, PrivateKeyDer};
10	    use std::fs::File;
11	    use std::io::BufReader;
12	    use std::sync::Arc;
13	    let certs: Vec<CertificateDer<'static>> = certs(&mut BufReader::new(File::open(cert_path)?))
14	        .collect::<Result<Vec<_>, _>>()
15	        .map_err(|e| NanowebError::Tls(e.to_string()))?;
16	    let key: PrivateKeyDer<'static> = private_key(&mut BufReader::new(File::open(key_path)?))
17	        .map_err(|e| NanowebError::Tls(e.to_string()))?
18	        .ok_or_else(|| NanowebError::Tls("no private key found".into()))?;
19	    Ok(ServerConfig::builder_with_details(
20	        Arc::new(default_provider()),
21	        Arc::new(rustls::time_provider::DefaultTimeProvider),
22	    )
23	    .with_protocol_versions(&[&rustls::version::TLS13])
24	    .map_err(|e: rustls::Error| NanowebError::Tls(e.to_string()))?
25	    .with_no_client_auth()
26	    .with_single_cert(certs, key)
27	    .map_err(|e: rustls::Error| NanowebError::Tls(e.to_string()))?)
28	}
