13	fn render_inner(template: &str, context: &Value) -> Result<String, NanowebError> {
14	    let mut out = String::new();
15	    let mut i = 0;
16	    while let Some(start) = template[i..].find("{{") {
17	        out.push_str(&template[i..i + start]);
18	        let rest = &template[i + start + 2..];
19	        let end = rest
20	            .find("}}")
21	            .ok_or_else(|| NanowebError::parse("unclosed tag"))?;
22	        let tag = rest[..end].trim();
23	        i = i + start + 2 + end + 2;
24	        if let Some(name) = tag.strip_prefix('#') {
25	            let close = format!("{{{{/{}}}}}", name.trim());
26	            let body_end = template[i..]
27	                .find(&close)
28	                .ok_or_else(|| NanowebError::parse("missing close tag"))?;
29	            let inner = &template[i..i + body_end];
30	            if let Some(v) = lookup(context, name.trim()) {
31	                if let Some(arr) = v.as_array() {
32	                    for item in arr {
33	                        out.push_str(&render_inner(inner, item)?);
34	                    }
35	                } else if truthy(v) {
36	                    out.push_str(&render_inner(inner, v)?);
37	                }
38	            }
39	            i += body_end + close.len();
40	        } else if let Some(name) = tag.strip_prefix('^') {
41	            let close = format!("{{{{/{}}}}}", name.trim());
42	            let body_end = template[i..]
43	                .find(&close)
44	                .ok_or_else(|| NanowebError::parse("missing close tag"))?;
45	            let inner = &template[i..i + body_end];
46	            if lookup(context, name.trim()).map_or(true, |v| !truthy(v)) {
47	                out.push_str(&render_inner(inner, context)?);
48	            }
49	            i += body_end + close.len();
50	        } else if let Some(v) = lookup(context, tag) {
51	            let rendered = v
52	                .as_str()
53	                .map(|s| s.to_string())
54	                .unwrap_or_else(|| v.to_string());
55	            out.push_str(&rendered);
56	        }
57	    }
58	    out.push_str(&template[i..]);
59	    Ok(out)
60	}

62	fn lookup<'a>(ctx: &'a Value, key: &str) -> Option<&'a Value> {
63	    ctx.as_object().and_then(|m| m.get(key))
64	}
65	fn truthy(v: &Value) -> bool {
66	    match v {
67	        Value::Null => false,
68	        Value::Bool(b) => *b,
69	        Value::Array(a) => !a.is_empty(),
70	        Value::String(s) => !s.is_empty(),
71	        _ => true,
72	    }

