21	impl Middleware for RateLimit {
22	    fn before(&self, req: &mut Request) -> Result<Option<Response>, crate::NanowebError> {
23	        let key = req
24	            .peer_addr
25	            .map(|a| a.ip().to_string())
26	            .unwrap_or_else(|| "unknown".into());
27	        let mut b = self.buckets.lock().unwrap();
28	        let (tokens, last) = b.entry(key).or_insert((self.burst, Instant::now()));
29	        let now = Instant::now();
30	        let added = now.duration_since(*last).as_secs_f64() * self.rate;
31	        *tokens = (*tokens + added).min(self.burst);
32	        *last = now;
33	        if *tokens < 1.0 {
34	            return Ok(Some(Response::text(429, "rate limit exceeded")));
35	        }
36	        *tokens -= 1.0;
37	        Ok(None)
38	    }

