107	        if input.len() < pos + size + 2 {
108	            return Err(NanowebError::parse("incomplete chunk"));
109	        }
110	        out.extend_from_slice(&input[pos..pos + size]);
111	        pos += size;
112	        if &input[pos..pos + 2] != b"\r\n" {
113	            return Err(NanowebError::parse("invalid chunk terminator"));
114	        }
115	        pos += 2;
116	    }
