 5	pub fn parse_request(
 6	    buf: &[u8],
 7	    remote_addr: Option<std::net::SocketAddr>,
 8	) -> Result<Request, NanowebError> {
 9	    let header_end = find_header_end(buf).ok_or_else(|| "bad request".to_string())?;
10	    let head = &buf[..header_end];
11	    let body = &buf[header_end..];
12	    let head_text = std::str::from_utf8(head).map_err(|_| "bad request".to_string())?;
13	    let mut lines = head_text.split("\r\n");
14	    let request_line = lines.next().ok_or_else(|| "bad request".to_string())?;
15	    let mut parts = request_line.split_whitespace();
16	    let method = parts.next().ok_or_else(|| "bad request".to_string())?;
17	    let target = parts.next().ok_or_else(|| "bad request".to_string())?;
18	    let version = parts.next().ok_or_else(|| "bad request".to_string())?;
19	    if parts.next().is_some() {
20	        return Err("bad request".into());
21	    }
22	    let version = match version {
23	        "HTTP/1.1" => Version::Http11,
24	        "HTTP/1.0" => Version::Http10,
25	        _ => return Err("bad request".into()),
26	    };
27	    let mut headers = HashMap::new();
28	    for line in lines {
29	        if line.is_empty() {
30	            continue;
31	        }
32	        let (k, v) = line
33	            .split_once(':')
34	            .ok_or_else(|| "bad request".to_string())?;
35	        headers.insert(k.trim().to_ascii_lowercase(), v.trim().to_string());
36	    }
37	    let body = if let Some(te) = headers.get("transfer-encoding") {
38	        if te.eq_ignore_ascii_case("chunked") {
39	            parse_chunked(body)?
40	        } else {
41	            return Err("bad request".into());
42	        }
43	    } else if let Some(len) = headers.get("content-length") {
44	        let len: usize = len.parse().map_err(|_| "bad request".to_string())?;
45	        if body.len() < len {
46	            return Err("bad request".into());
47	        }
48	        body[..len].to_vec()
49	    } else {
50	        Vec::new()
51	    };
52	    let (path, query_params) = parse_target(target)?;
53	    Ok(Request {
54	        method: Method::from(method),
55	        target: path,
56	        version,
57	        headers,
58	        body,
59	        path_params: HashMap::new(),
60	        query_params,
61	        remote_addr,
62	        request_id: uuid::Uuid::new_v4().to_string(),
63	    })

