42	    let mut shutting_down = false;
43	    let mut sigterm = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())?;
44	    loop {
45	        tokio::select! {
46	            res = listener.accept(), if !shutting_down => {
47	                let (mut socket, remote) = res?;
48	                let app = app.clone();
49	                tasks.spawn(async move {
50	                    let mut buf = vec![0; 64 * 1024];
51	                    let n = match socket.read(&mut buf).await { Ok(n) => n, Err(_) => return };
52	                    let mut req = match parse_request(&buf[..n], Some(remote)) { Ok(r) => r, Err(_) => { let _ = socket.write_all(b"HTTP/1.1 400 Bad Request\r\nContent-Length: 11\r\n\r\nbad request").await; return; } };
53	                    if req.target == "/healthz" { let _ = write_resp(&mut socket, health::healthz()).await; return; }
54	                    if req.target == "/readyz" { let _ = write_resp(&mut socket, health::readyz(!shutting_down)).await; return; }
55	                    if req.target == app.config.metrics.clone().unwrap_or_else(|| "/metrics".into()) {
