57	                        resp.headers.insert("content-type".into(), "text/plain; version=0.0.4".into());
58	                        let _ = write_resp(&mut socket, resp).await;
59	                        return;
60	                    }
61	                    if let Some(dir) = &app.config.static_dir {
62	                        if req.target.starts_with("/static/") {
63	                            let resp = static_files::serve(std::path::Path::new(dir), req.target.trim_start_matches("/static/"), req.header("if-none-match"));
64	                            let _ = write_resp(&mut socket, resp).await;
65	                            return;
66	                        }
67	                    }
68	                    if let Some(resp) = app.middleware.run_before(&mut req).await { let _ = write_resp(&mut socket, resp).await; return; }
