16	fn render_section(template: &str, context: &Value) -> String {
17	    let mut out = String::new();
18	    let mut rest = template;
19	    while let Some(start) = rest.find("{{") {
20	        out.push_str(&rest[..start]);
21	        let Some(end) = rest[start + 2..].find("}}") else {
22	            out.push_str(&rest[start..]);
23	            return out;
24	        };
25	        let tag = rest[start + 2..start + 2 + end].trim();
26	        let after = &rest[start + 2 + end + 2..];
27	        if let Some(name) = tag.strip_prefix('#') {
28	            if let Some((inner, tail)) = take_block(after, name.trim()) {
29	                if let Some(value) = lookup(context, name.trim()) {
30	                    match value {
31	                        Value::Array(items) => {
32	                            for item in items {
33	                                out.push_str(&render_section(inner, item));
34	                            }
35	                        }
36	                        Value::Bool(true) => out.push_str(&render_section(inner, context)),
37	                        Value::Object(_) => out.push_str(&render_section(inner, value)),
38	                        _ => {}
39	                    }
40	                }
41	                rest = tail;
42	            } else {
43	                rest = after;
44	            }
45	        } else if let Some(name) = tag.strip_prefix('^') {
46	            if let Some((inner, tail)) = take_block(after, name.trim()) {
47	                let render = match lookup(context, name.trim()) {
48	                    None | Some(Value::Null) => true,
49	                    Some(Value::Bool(false)) => true,
50	                    Some(Value::Array(v)) if v.is_empty() => true,
51	                    _ => false,
52	                };
53	                if render {
54	                    out.push_str(&render_section(inner, context));
55	                }
56	                rest = tail;
57	            } else {
58	                rest = after;
59	            }
60	        } else if tag.starts_with('/') {
61	            rest = after;
62	        } else {
63	            if let Some(value) = lookup(context, tag) {
64	                out.push_str(&html_escape(&scalar_to_string(value)));
65	            }
66	            rest = after;
67	        }
68	    }
69	    out.push_str(rest);
70	    out

73	fn take_block<'a>(s: &'a str, name: &str) -> Option<(&'a str, &'a str)> {
74	    let close = format!("{{{{/{name}}}}}");
75	    let idx = s.find(&close)?;
76	    Some((&s[..idx], &s[idx + close.len()..]))
77	}
