43	        bucket.tokens = (bucket.tokens + elapsed * self.refill_per_sec).min(self.capacity);
44	        bucket.last = now;
45	        if bucket.tokens >= 1.0 {
46	            bucket.tokens -= 1.0;
47	            None
48	        } else {
49	            let mut response = Response::text(429, "rate limit exceeded");
50	            response.set_header("Retry-After", Duration::from_secs(1).as_secs().to_string());
51	            Some(response)
52	        }
53	    }

