 99	pub async fn run(config: Config) -> Result<()> {
100	    init_logging(&config.log_level);
101	    let app = Arc::new(app_from_config(&config)?);
102	    let shutdown = shutdown_signal();
103	    let timeout = Duration::from_secs(config.graceful_timeout_s);
104	
105	    match (&config.tls_cert, &config.tls_key, &config.tls_listen) {
106	        (Some(cert), Some(key), Some(tls_addr)) => {
107	            let plain = TcpListener::bind(&config.listen).await?;
108	            let tls = TcpListener::bind(tls_addr).await?;
109	            let acceptor = crate::tls::load_acceptor(cert, key)?;
110	            let (tx, rx) = tokio::sync::watch::channel(false);
111	            tokio::spawn(async move {
112	                shutdown.await;
113	                let _ = tx.send(true);
114	            });
115	            let plain_task =
116	                serve_with_shutdown(plain, app.clone(), wait_for_shutdown(rx.clone()), timeout);
117	            let tls_task =
118	                serve_tls_with_shutdown(tls, acceptor, app, wait_for_shutdown(rx), timeout);
119	            tokio::try_join!(plain_task, tls_task)?;
120	        }
121	        (Some(cert), Some(key), _) => {
122	            let listener = TcpListener::bind(&config.listen).await?;
123	            let acceptor = crate::tls::load_acceptor(cert, key)?;
124	            serve_tls_with_shutdown(listener, acceptor, app, shutdown, timeout).await?;
125	        }
126	        (None, None, _) => {
127	            let listener = TcpListener::bind(&config.listen).await?;
128	            serve_with_shutdown(listener, app, shutdown, timeout).await?;
129	        }
130	        _ => {
131	            return Err(NanowebError::Config(
132	                "both tls_cert and tls_key must be provided".into(),
133	            ));
134	        }
135	    }
136	    Ok(())

 6	pub fn parse_typed<T: DeserializeOwned>(request: &Request) -> Result<T> {
 7	    let content_type = request.header("content-type").unwrap_or("");
 8	    if content_type.starts_with("application/json") {
 9	        Ok(serde_json::from_slice(&request.body)?)
10	    } else if content_type.starts_with("application/x-www-form-urlencoded") {
11	        let value: T = serde_urlencoded::from_bytes(&request.body)
12	            .map_err(|e| crate::error::NanowebError::BadRequest(e.to_string()))?;
13	        Ok(value)
14	    } else if content_type.starts_with("multipart/form-data") {
15	        let boundary = content_type
16	            .split(';')
17	            .find_map(|part| part.trim().strip_prefix("boundary="))
18	            .ok_or_else(|| crate::error::NanowebError::BadRequest("missing boundary".into()))?;
19	        let fields = parse_multipart(&request.body, boundary)?;
20	        let mut map = Map::new();
21	        for (key, val) in fields {
22	            map.insert(key, Value::String(val));
23	        }
24	        Ok(serde_json::from_value(Value::Object(map))?)
25	    } else {
26	        Err(crate::error::NanowebError::BadRequest(
27	            "unsupported content type".into(),
28	        ))
29	    }

