139	pub async fn serve_with_shutdown<S>(
140	    listener: TcpListener,
141	    app: Arc<App>,
142	    shutdown: S,
143	    graceful_timeout: Duration,
144	) -> Result<()>
145	where
146	    S: Future<Output = ()> + Send,
147	{
148	    let mut shutdown = Box::pin(shutdown);
149	    let mut tasks = JoinSet::new();
150	    loop {
151	        tokio::select! {
152	            _ = &mut shutdown => {
153	                app.ready_flag().store(false, std::sync::atomic::Ordering::SeqCst);
154	                break;
155	            }
156	            accepted = listener.accept() => {
157	                let (stream, peer) = accepted?;
158	                let app = app.clone();
159	                tasks.spawn(async move {
160	                    let _ = handle_connection(stream, app, peer).await;
161	                });
162	            }
163	        }
164	    }
165	    drain_tasks(tasks, graceful_timeout).await;
166	    Ok(())

220	async fn drain_tasks(mut tasks: JoinSet<()>, graceful_timeout: Duration) {
221	    let deadline = tokio::time::Instant::now() + graceful_timeout;
222	    while !tasks.is_empty() {
