 87	fn parse_chunked(buf: &[u8]) -> Result<Option<(Vec<u8>, usize)>> {
 88	    let mut pos = 0;
 89	    let mut body = Vec::new();
 90	    loop {
 91	        let line_end = match find_crlf(&buf[pos..]) {
 92	            Some(n) => pos + n,
 93	            None => return Ok(None),
 94	        };
 95	        let line = str::from_utf8(&buf[pos..line_end])
 96	            .map_err(|_| NanowebError::BadRequest("invalid chunk size".into()))?;
 97	        let size_part = line.split(';').next().unwrap_or(line);
 98	        let size = usize::from_str_radix(size_part.trim(), 16)
 99	            .map_err(|_| NanowebError::BadRequest("invalid chunk size".into()))?;
100	        pos = line_end + 2;
101	        if size == 0 {
102	            let trailer_end = match find_header_end(&buf[pos..]) {
103	                Some(n) => pos + n + 4,
104	                None if buf.get(pos..pos + 2) == Some(b"\r\n") => pos + 2,
105	                None => return Ok(None),
106	            };
107	            return Ok(Some((body, trailer_end)));
108	        }
109	        if body.len() + size > MAX_BODY {
110	            return Err(NanowebError::BadRequest("body too large".into()));
111	        }
112	        if buf.len() < pos + size + 2 {
113	            return Ok(None);
114	        }
115	        body.extend_from_slice(&buf[pos..pos + size]);
116	        if &buf[pos + size..pos + size + 2] != b"\r\n" {
117	            return Err(NanowebError::BadRequest("chunk missing terminator".into()));
118	        }
119	        pos += size + 2;
120	    }
121	}
122	
123	fn find_header_end(buf: &[u8]) -> Option<usize> {
124	    buf.windows(4).position(|w| w == b"\r\n\r\n")
125	}
126	
127	fn find_crlf(buf: &[u8]) -> Option<usize> {
128	    buf.windows(2).position(|w| w == b"\r\n")
129	}

