  8	pub fn parse_request(buf: &[u8]) -> Result<Option<(Request, usize)>> {
  9	    let header_end = match find_header_end(buf) {
 10	        Some(pos) => pos,
 11	        None if buf.len() > MAX_HEADERS => {
 12	            return Err(NanowebError::BadRequest("headers too large".into()));
 13	        }
 14	        None => return Ok(None),
 15	    };
 16	    let head = str::from_utf8(&buf[..header_end])
 17	        .map_err(|_| NanowebError::BadRequest("headers are not valid utf-8".into()))?;
 18	    let mut lines = head.split("\r\n");
 19	    let line = lines
 20	        .next()
 21	        .ok_or_else(|| NanowebError::BadRequest("missing request line".into()))?;
 22	    let mut parts = line.split_whitespace();
 23	    let method = parts
 24	        .next()
 25	        .ok_or_else(|| NanowebError::BadRequest("missing method".into()))?
 26	        .parse::<Method>()
 27	        .map_err(|_| NanowebError::BadRequest("invalid method".into()))?;
 28	    let target = parts
 29	        .next()
 30	        .ok_or_else(|| NanowebError::BadRequest("missing target".into()))?;
 31	    let version = parts
 32	        .next()
 33	        .ok_or_else(|| NanowebError::BadRequest("missing version".into()))?;
 34	    if parts.next().is_some() || version != "HTTP/1.1" || !target.starts_with('/') {
 35	        return Err(NanowebError::BadRequest("invalid request line".into()));
 36	    }
 37	
 38	    let mut headers = HeaderMap::new();
 39	    for line in lines {
 40	        if line.is_empty() {
 41	            continue;
 42	        }
 43	        let (name, value) = line
 44	            .split_once(':')
 45	            .ok_or_else(|| NanowebError::BadRequest("malformed header".into()))?;
 46	        if name.is_empty()
 47	            || !name
 48	                .bytes()
 49	                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_'))
 50	        {
 51	            return Err(NanowebError::BadRequest("invalid header name".into()));
 52	        }
 53	        headers.insert(name.to_ascii_lowercase(), value.trim().to_string());
 54	    }
 55	
 56	    let body_start = header_end + 4;
 57	    let transfer = headers
 58	        .get("transfer-encoding")
 59	        .map(|v| v.to_ascii_lowercase());
 60	    let (body, consumed) = if transfer.as_deref().is_some_and(|v| v.contains("chunked")) {
 61	        match parse_chunked(&buf[body_start..])? {
 62	            Some((body, used)) => (body, body_start + used),
 63	            None => return Ok(None),
 64	        }
 65	    } else if let Some(len) = headers.get("content-length") {
 66	        let len = len
 67	            .parse::<usize>()
 68	            .map_err(|_| NanowebError::BadRequest("invalid content-length".into()))?;
 69	        if len > MAX_BODY {
 70	            return Err(NanowebError::BadRequest("body too large".into()));
 71	        }
 72	        if buf.len() < body_start + len {
 73	            return Ok(None);
 74	        }
 75	        (buf[body_start..body_start + len].to_vec(), body_start + len)
 76	    } else {
 77	        (Vec::new(), body_start)
 78	    };
 79	
 80	    let mut request = Request::new(method, target);
 81	    request.version = version.to_string();
 82	    request.headers = headers;
 83	    request.body = body;
 84	    Ok(Some((request, consumed)))
 85	}
