11	pub async fn read_request<R: AsyncRead + Unpin>(reader: &mut R) -> Result<Option<Request>> {
12	    let mut buf = Vec::with_capacity(4096);
13	    let mut tmp = [0_u8; 4096];
14	
15	    loop {
16	        if buf.len() > MAX_HEADER_BYTES + MAX_BODY_BYTES {
17	            return Err(NanowebError::Parse("request too large".into()));
18	        }
19	        match parse_request(&buf)? {
20	            ParseState::Complete(req, _) => return Ok(Some(req)),
21	            ParseState::Incomplete => {
22	                let n = reader.read(&mut tmp).await?;
23	                if n == 0 {
24	                    return if buf.is_empty() {
25	                        Ok(None)
26	                    } else {
27	                        Err(NanowebError::Parse("unexpected EOF".into()))
28	                    };
29	                }
30	                buf.extend_from_slice(&tmp[..n]);
31	            }
32	        }
33	    }

 42	pub fn parse_request(bytes: &[u8]) -> Result<ParseState> {
 43	    let Some(header_end) = find_header_end(bytes) else {
 44	        if bytes.len() > MAX_HEADER_BYTES {
 45	            return Err(NanowebError::Parse("headers too large".into()));
 46	        }
 47	        return Ok(ParseState::Incomplete);
 48	    };
 49	
 50	    let header_text = std::str::from_utf8(&bytes[..header_end])
 51	        .map_err(|_| NanowebError::Parse("headers are not valid UTF-8".into()))?;
 52	    let mut lines = header_text.split("\r\n");
 53	    let request_line = lines
 54	        .next()
 55	        .ok_or_else(|| NanowebError::Parse("missing request line".into()))?;
 56	    let mut parts = request_line.split_whitespace();
 57	    let method = parts
 58	        .next()
 59	        .ok_or_else(|| NanowebError::Parse("missing method".into()))
 60	        .and_then(|m| Method::from_str(m).map_err(NanowebError::Parse))?;
 61	    let target = parts
 62	        .next()
 63	        .ok_or_else(|| NanowebError::Parse("missing target".into()))?;
 64	    let version = parts
 65	        .next()
 66	        .ok_or_else(|| NanowebError::Parse("missing version".into()))?;
 67	    if parts.next().is_some() || version != "HTTP/1.1" || !target.starts_with('/') {
 68	        return Err(NanowebError::Parse("invalid request line".into()));
 69	    }
 70	
 71	    let mut headers = HeaderMap::new();
 72	    for line in lines {
 73	        if line.is_empty() {
 74	            continue;
 75	        }
 76	        let (name, value) = line
 77	            .split_once(':')
 78	            .ok_or_else(|| NanowebError::Parse("malformed header".into()))?;
 79	        if name.is_empty() || !name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
 80	            return Err(NanowebError::Parse("invalid header name".into()));
 81	        }
 82	        headers.insert(name.to_ascii_lowercase(), value.trim().to_string());
 83	    }
 84	
 85	    let body_start = header_end + 4;
 86	    let transfer_encoding = headers
 87	        .get("transfer-encoding")
 88	        .map(|v| v.to_ascii_lowercase())
 89	        .unwrap_or_default();
 90	    let body = if transfer_encoding
 91	        .split(',')
 92	        .any(|v| v.trim().eq_ignore_ascii_case("chunked"))
 93	    {
 94	        match parse_chunked(&bytes[body_start..])? {
 95	            Some((body, consumed)) => {
 96	                return complete(
 97	                    method,
 98	                    target,
 99	                    version,
100	                    headers,
101	                    body,
102	                    body_start + consumed,
103	                );
104	            }
105	            None => return Ok(ParseState::Incomplete),
106	        }
107	    } else if let Some(length) = headers.get("content-length") {
108	        let length = length
109	            .parse::<usize>()
110	            .map_err(|_| NanowebError::Parse("invalid content-length".into()))?;
111	        if length > MAX_BODY_BYTES {
112	            return Err(NanowebError::Parse("body too large".into()));
113	        }
114	        if bytes.len() < body_start + length {
115	            return Ok(ParseState::Incomplete);
116	        }
117	        bytes[body_start..body_start + length].to_vec()
118	    } else {
119	        Vec::new()
120	    };
121	
122	    let consumed = body_start
123	        + headers
124	            .get("content-length")
125	            .and_then(|v| v.parse::<usize>().ok())
126	            .unwrap_or(0);
127	    complete(method, target, version, headers, body, consumed)
128	}
