130	fn complete(
131	    method: Method,
132	    target: &str,
133	    version: &str,
134	    headers: HeaderMap,
135	    body: Vec<u8>,
136	    consumed: usize,
137	) -> Result<ParseState> {
138	    let mut req = Request::new(method, target);
139	    req.version = version.to_string();
140	    req.headers = headers;
141	    req.body = body;
142	    Ok(ParseState::Complete(req, consumed))

