160	fn lookup_node<'a>(
161	    node: &'a Node,
162	    parts: &[&str],
163	    index: usize,
164	    params: &mut RouteParams,
165	) -> Option<&'a Node> {
166	    if index == parts.len() {
167	        return Some(node);
168	    }
169	    let part = parts[index];
170	    if let Some(child) = node.literals.get(part) {
171	        if let Some(found) = lookup_node(child, parts, index + 1, params) {
172	            return Some(found);
173	        }
174	    }
175	    if let Some((name, child)) = &node.param {
176	        params.insert(name.clone(), urlencoding::decode(part).ok()?.into_owned());
177	        if let Some(found) = lookup_node(child, parts, index + 1, params) {
178	            return Some(found);
179	        }
180	        params.remove(name);
181	    }
182	    if let Some((name, child)) = &node.wildcard {
183	        params.insert(name.clone(), parts[index..].join("/"));
184	        return Some(child);
185	    }
186	    None
187	}

