20	fn render_inner(template: &str, context: &Value) -> Result<String> {
21	    let mut out = String::new();
22	    let mut rest = template;
23	    while let Some(open) = rest.find("{{") {
24	        out.push_str(&rest[..open]);
25	        let after = &rest[open + 2..];
26	        let close = after
27	            .find("}}")
28	            .ok_or_else(|| NanowebError::Parse("unclosed template tag".into()))?;
29	        let tag = after[..close].trim();
30	        rest = &after[close + 2..];
31	        if let Some(name) = tag.strip_prefix('#') {
32	            let (body, tail) = section_body(rest, name.trim())?;
33	            if let Some(value) = lookup(context, name.trim()) {
34	                match value {
35	                    Value::Array(items) => {
36	                        for item in items {
37	                            out.push_str(&render_inner(body, item)?);
38	                        }
39	                    }
40	                    other if truthy(other) => out.push_str(&render_inner(body, other)?),
41	                    _ => {}
42	                }
43	            }
44	            rest = tail;
45	        } else if let Some(name) = tag.strip_prefix('^') {
46	            let (body, tail) = section_body(rest, name.trim())?;
47	            if lookup(context, name.trim()).is_none_or(|v| !truthy(v)) {
48	                out.push_str(&render_inner(body, context)?);
49	            }
50	            rest = tail;
51	        } else if tag.starts_with('/') {
52	            return Err(NanowebError::Parse(
53	                "unexpected closing template tag".into(),
54	            ));
55	        } else if let Some(value) = lookup(context, tag) {
56	            out.push_str(&escape(&value_to_string(value)));
57	        }
58	    }
59	    out.push_str(rest);
60	    Ok(out)
61	}
62	
63	fn section_body<'a>(template: &'a str, name: &str) -> Result<(&'a str, &'a str)> {
64	    let close_tag = format!("{{{{/{name}}}}}");
65	    let end = template
66	        .find(&close_tag)
67	        .ok_or_else(|| NanowebError::Parse(format!("missing closing tag for {name}")))?;
68	    Ok((&template[..end], &template[end + close_tag.len()..]))

 71	fn lookup<'a>(context: &'a Value, key: &str) -> Option<&'a Value> {
 72	    if key == "." {
 73	        return Some(context);
 74	    }
 75	    key.split('.').try_fold(context, |value, part| match value {
 76	        Value::Object(map) => map.get(part),
 77	        _ => None,
 78	    })
 79	}
 80	
 81	fn truthy(value: &Value) -> bool {
 82	    match value {
 83	        Value::Null => false,
 84	        Value::Bool(v) => *v,
 85	        Value::Array(v) => !v.is_empty(),
 86	        Value::String(v) => !v.is_empty(),
 87	        _ => true,
 88	    }
 89	}
 90	
 91	fn value_to_string(value: &Value) -> String {
 92	    match value {
 93	        Value::Null => String::new(),
 94	        Value::String(v) => v.clone(),
 95	        Value::Bool(v) => v.to_string(),
 96	        Value::Number(v) => v.to_string(),
 97	        other => other.to_string(),
 98	    }
 99	}
100	
101	fn escape(value: &str) -> String {
102	    value
103	        .replace('&', "&amp;")
104	        .replace('<', "&lt;")
105	        .replace('>', "&gt;")
106	        .replace('"', "&quot;")
107	}

