149	fn parse_chunked(bytes: &[u8]) -> Result<Option<(Vec<u8>, usize)>> {
150	    let mut pos = 0;
151	    let mut body = Vec::new();
152	    loop {
153	        let Some(line_end) = find_crlf(&bytes[pos..]) else {
154	            return Ok(None);
155	        };
156	        let line = std::str::from_utf8(&bytes[pos..pos + line_end])
157	            .map_err(|_| NanowebError::Parse("invalid chunk size".into()))?;
158	        let size_part = line.split(';').next().unwrap_or("").trim();
159	        let size = usize::from_str_radix(size_part, 16)
160	            .map_err(|_| NanowebError::Parse("invalid chunk size".into()))?;
161	        pos += line_end + 2;
162	        if body.len() + size > MAX_BODY_BYTES {
163	            return Err(NanowebError::Parse("body too large".into()));
164	        }
165	        if size == 0 {
166	            if bytes.len() < pos + 2 {
167	                return Ok(None);
168	            }
169	            if &bytes[pos..pos + 2] != b"\r\n" {
170	                return Err(NanowebError::Parse("malformed final chunk".into()));
171	            }
172	            return Ok(Some((body, pos + 2)));
173	        }
174	        if bytes.len() < pos + size + 2 {
175	            return Ok(None);
176	        }
177	        body.extend_from_slice(&bytes[pos..pos + size]);
178	        pos += size;
179	        if &bytes[pos..pos + 2] != b"\r\n" {
180	            return Err(NanowebError::Parse("malformed chunk".into()));
181	        }
182	        pos += 2;
183	    }
184	}
