10	pub async fn parse_request<R: AsyncBufRead + Unpin>(reader: &mut R) -> Result<Request> {
11	    let mut request_line = String::new();
12	    let n = reader.read_line(&mut request_line).await?;
13	    if n == 0 {
14	        return Err(NanowebError::Parse("empty request".into()));
15	    }
16	    if request_line.len() > MAX_LINE || !request_line.ends_with("\r\n") {
17	        return Err(NanowebError::Parse("invalid request line".into()));
18	    }
19	    let parts: Vec<&str> = request_line.trim_end_matches("\r\n").split(' ').collect();
20	    if parts.len() != 3 || parts[2] != "HTTP/1.1" || parts[1].is_empty() {
21	        return Err(NanowebError::Parse("malformed request line".into()));
22	    }
23	
24	    let mut headers = HashMap::new();
25	    loop {
26	        let mut line = String::new();
27	        let n = reader.read_line(&mut line).await?;
28	        if n == 0 {
29	            return Err(NanowebError::Parse("unexpected eof in headers".into()));
30	        }
31	        if line.len() > MAX_LINE {
32	            return Err(NanowebError::Parse("header line too long".into()));
33	        }
34	        if line == "\r\n" {
35	            break;
36	        }
37	        let (name, value) = line
38	            .trim_end_matches("\r\n")
39	            .split_once(':')
40	            .ok_or_else(|| NanowebError::Parse("malformed header".into()))?;
41	        if name.is_empty() || name.bytes().any(|b| b <= b' ' || b == b':') {
42	            return Err(NanowebError::Parse("invalid header name".into()));
43	        }
44	        headers.insert(name.to_ascii_lowercase(), value.trim().to_string());
45	    }
46	
47	    let body = if headers.get("transfer-encoding").is_some_and(|v| {
48	        v.to_ascii_lowercase()
49	            .split(',')
50	            .any(|p| p.trim() == "chunked")
51	    }) {
52	        read_chunked(reader).await?
53	    } else if let Some(len) = headers.get("content-length") {
54	        let len: usize = len
55	            .parse()
56	            .map_err(|_| NanowebError::Parse("invalid content-length".into()))?;
57	        if len > MAX_BODY {
58	            return Err(NanowebError::Parse("body too large".into()));
59	        }
60	        let mut body = vec![0; len];
61	        reader.read_exact(&mut body).await?;
62	        body
63	    } else {
64	        Vec::new()
65	    };
66	
67	    let target = parts[1].to_string();
68	    let (path, query) = match target.split_once('?') {
69	        Some((p, q)) => (p.to_string(), Some(q.to_string())),
70	        None => (target.clone(), None),
71	    };
72	
73	    Ok(Request {
74	        method: Method::from(parts[0]),
75	        target,
76	        path,
77	        query,
78	        version: parts[2].to_string(),
79	        headers,
80	        body,
81	        peer_addr: None,
82	        request_id: rand::thread_rng()
83	            .sample_iter(&Alphanumeric)
84	            .take(16)
85	            .map(char::from)
86	            .collect(),
87	        params: HashMap::new(),
88	    })
89	}

