157	        {
158	            return Lookup::Found(RouteMatch {
159	                handler: handler.clone(),
160	                params,
161	                route: map.pattern.clone(),
162	                suppress_body: true,
163	            });
164	        }
165	    }
166	    match map.handlers.get(method) {
167	        Some(handler) => Lookup::Found(RouteMatch {
168	            handler: handler.clone(),
169	            params,
170	            route: map.pattern.clone(),
171	            suppress_body: false,
172	        }),
173	        None => Lookup::MethodNotAllowed(allowed(&map.handlers)),
174	    }
175	}
