 89	    #[cfg(feature = "tls")]
 90	    pub async fn run_tls(self, tls_config: rustls::ServerConfig) -> Result<()> {
 91	        let addr: SocketAddr = self
 92	            .config
 93	            .listen
 94	            .parse()
 95	            .map_err(|e| NanowebError::Config(format!("invalid listen address: {e}")))?;
 96	        let listener = TcpListener::bind(addr).await?;
 97	        let acceptor = tokio_rustls::TlsAcceptor::from(Arc::new(tls_config));
 98	        let (shutdown_tx, _) = broadcast::channel::<()>(1);
 99	        let sem = Arc::new(Semaphore::new(10_000));
100	        self.health.set_ready(true);
101	
102	        let shutdown_task_tx = shutdown_tx.clone();
103	        tokio::spawn(async move {
104	            wait_shutdown_signal().await;
105	            let _ = shutdown_task_tx.send(());
106	        });
107	
108	        let mut shutdown_rx = shutdown_tx.subscribe();
109	        loop {
110	            tokio::select! {
111	                biased;
112	                _ = shutdown_rx.recv() => {
113	                    self.health.set_ready(false);
114	                    break;
115	                }
116	                accepted = listener.accept() => {
117	                    let (stream, peer) = accepted?;
118	                    let permit = sem.clone().acquire_owned().await.map_err(|e| NanowebError::Server(e.to_string()))?;
119	                    let app = self.app.clone();
120	                    let metrics = self.metrics.clone();
121	                    let acceptor = acceptor.clone();
122	                    tokio::spawn(async move {
123	                        let _permit = permit;
124	                        match acceptor.accept(stream).await {
125	                            Ok(tls_stream) => {
126	                                let _ = handle_connection(tls_stream, peer, app, metrics).await;
127	                            }
128	                            Err(err) => tracing::warn!(error = %err, "tls handshake failed"),
129	                        }
130	                    });
131	                }
132	            }
133	        }
134	        let timeout = Duration::from_secs(self.config.graceful_timeout_s);
135	        let _ = tokio::time::timeout(timeout, async {
136	            loop {
137	                if sem.available_permits() == 10_000 {
138	                    break;
139	                }
140	                tokio::time::sleep(Duration::from_millis(25)).await;
141	            }
142	        })
143	        .await;
144	        Ok(())
145	    }

