 6	#[derive(Default)]
 7	pub struct Metrics {
 8	    requests: Mutex<HashMap<(String, String, String), u64>>,
 9	    durations: Mutex<Vec<f64>>,
10	}
11	
12	impl Metrics {
13	    pub fn record(&self, method: &Method, status: StatusCode, route: &str, duration: Duration) {
14	        *self
15	            .requests
16	            .lock()
17	            .unwrap()
18	            .entry((
19	                method.to_string(),
20	                status.class().to_string(),
21	                route.to_string(),
22	            ))
23	            .or_insert(0) += 1;
24	        self.durations.lock().unwrap().push(duration.as_secs_f64());
25	    }
26	
27	    pub fn render(&self) -> String {
28	        let mut out = String::new();
29	        out.push_str("# TYPE nanoweb_http_requests_total counter\n");
30	        for ((method, class, route), value) in self.requests.lock().unwrap().iter() {
31	            out.push_str(&format!(
32	                "nanoweb_http_requests_total{{method=\"{}\",status_class=\"{}\",route=\"{}\"}} {}\n",
33	                esc(method),
34	                esc(class),
35	                esc(route),
36	                value
37	            ));
38	        }
39	        out.push_str("# TYPE nanoweb_request_duration_seconds histogram\n");
40	        let buckets = [
41	            0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0, 10.0,
42	        ];
43	        let durations = self.durations.lock().unwrap();
44	        for b in buckets {
45	            let count = durations.iter().filter(|v| **v <= b).count();
46	            out.push_str(&format!(
47	                "nanoweb_request_duration_seconds_bucket{{le=\"{b}\"}} {count}\n"
48	            ));
49	        }
50	        out.push_str(&format!(
51	            "nanoweb_request_duration_seconds_bucket{{le=\"+Inf\"}} {}\n",
52	            durations.len()
53	        ));
54	        out.push_str(&format!(
55	            "nanoweb_request_duration_seconds_count {}\n",
56	            durations.len()
57	        ));
58	        out.push_str(&format!(
59	            "nanoweb_request_duration_seconds_sum {}\n",
60	            durations.iter().sum::<f64>()
61	        ));
62	        out
63	    }

