13	fn render_section(template: &str, context: &Value) -> Result<String> {
14	    let mut out = String::new();
15	    let mut rest = template;
16	    while let Some(start) = rest.find("{{") {
17	        out.push_str(&rest[..start]);
18	        let Some(end) = rest[start + 2..].find("}}") else {
19	            return Err(NanowebError::Template("unclosed tag".into()));
20	        };
21	        let tag = rest[start + 2..start + 2 + end].trim();
22	        let after = &rest[start + 2 + end + 2..];
23	        if let Some(name) = tag.strip_prefix('#') {
24	            let close = format!("{{{{/{}}}}}", name.trim());
25	            let Some(close_idx) = after.find(&close) else {
26	                return Err(NanowebError::Template("unclosed section".into()));
27	            };
28	            let inner = &after[..close_idx];
29	            if let Some(Value::Array(items)) = lookup(context, name.trim()) {
30	                for item in items {
31	                    out.push_str(&render_section(inner, item)?);
32	                }
33	            } else if truthy(lookup(context, name.trim())) {
34	                out.push_str(&render_section(inner, context)?);
35	            }
36	            rest = &after[close_idx + close.len()..];
37	        } else if let Some(name) = tag.strip_prefix('^') {
38	            let close = format!("{{{{/{}}}}}", name.trim());
39	            let Some(close_idx) = after.find(&close) else {
40	                return Err(NanowebError::Template("unclosed inverted section".into()));
41	            };
42	            let inner = &after[..close_idx];
43	            if !truthy(lookup(context, name.trim())) {
44	                out.push_str(&render_section(inner, context)?);
45	            }
46	            rest = &after[close_idx + close.len()..];
47	        } else if tag.starts_with('/') {
48	            return Err(NanowebError::Template("unexpected closing tag".into()));
49	        } else {
50	            out.push_str(&escape(&value_to_string(lookup(context, tag))));
51	            rest = after;
52	        }
53	    }
54	    out.push_str(rest);
55	    Ok(out)
56	}
57	
58	fn lookup<'a>(context: &'a Value, key: &str) -> Option<&'a Value> {
59	    if key == "." {
60	        return Some(context);
61	    }
62	    key.split('.').try_fold(context, |cur, part| cur.get(part))
63	}
64	
65	fn value_to_string(value: Option<&Value>) -> String {
66	    match value {
67	        Some(Value::String(v)) => v.clone(),
68	        Some(Value::Number(v)) => v.to_string(),
69	        Some(Value::Bool(v)) => v.to_string(),
70	        _ => String::new(),
71	    }
72	}
73	
74	fn truthy(value: Option<&Value>) -> bool {
75	    match value {
76	        Some(Value::Bool(v)) => *v,
77	        Some(Value::Array(v)) => !v.is_empty(),
78	        Some(Value::Null) | None => false,
79	        Some(Value::String(v)) => !v.is_empty(),
80	        _ => true,
81	    }
82	}
83	
84	fn escape(input: &str) -> String {
85	    input
86	        .replace('&', "&amp;")
87	        .replace('<', "&lt;")
88	        .replace('>', "&gt;")
89	        .replace('"', "&quot;")
90	}

