38	    pub async fn run(&self, mut req: Request) -> Response {
39	        let mut executed = Vec::new();
40	        for (idx, mw) in self.middleware.iter().enumerate() {
41	            if let Some(res) = mw.before(&mut req).await {
42	                return apply_after(&req, res, &self.middleware[..=idx]).await;
43	            }
44	            executed.push(idx);
45	        }
46	        let res = self.handler.call(req.clone()).await;
47	        let chain: Vec<Arc<dyn Middleware>> = executed
48	            .into_iter()
49	            .map(|idx| self.middleware[idx].clone())
50	            .collect();
51	        apply_after_owned(&req, res, &chain).await
52	    }
53	}
