15	    capacity: f64,
16	    refill_per_s: f64,
17	    buckets: Mutex<HashMap<IpAddr, Bucket>>,
18	}
19	
20	impl RateLimit {
21	    pub fn new(capacity: u32, refill_per_s: f64) -> Self {
22	        Self {
23	            capacity: capacity as f64,
24	            refill_per_s,
