30	#[async_trait]
31	impl Middleware for RateLimit {
32	    async fn before(&self, req: &mut Request) -> Option<Response> {
33	        let ip = req
34	            .peer_addr
35	            .map(|a| a.ip())
36	            .unwrap_or_else(|| "127.0.0.1".parse().unwrap());
37	        let mut buckets = self.buckets.lock().unwrap();
38	        let bucket = buckets.entry(ip).or_insert(Bucket {
39	            tokens: self.capacity,
40	            last: Instant::now(),
41	        });
42	        let now = Instant::now();
43	        bucket.tokens = (bucket.tokens
44	            + now.duration_since(bucket.last).as_secs_f64() * self.refill_per_s)
45	            .min(self.capacity);
46	        bucket.last = now;
47	        if bucket.tokens >= 1.0 {
48	            bucket.tokens -= 1.0;
49	            None
50	        } else {
51	            Some(Response::text(
52	                StatusCode::PayloadTooLarge,
53	                "rate limit exceeded",
54	            ))
55	        }

