278	pub async fn handle_connection<S>(
279	    stream: S,
280	    peer: SocketAddr,
281	    app: App,
282	    metrics: Arc<Metrics>,
283	) -> Result<()>
284	where
285	    S: AsyncRead + AsyncWrite + Unpin,
286	{
287	    let mut reader = BufReader::new(stream);
288	    let parsed = parse_request(&mut reader).await;
289	    let stream = reader.get_mut();
290	    match parsed {
291	        Ok(mut req) => {
292	            req.peer_addr = Some(peer);
293	            let start = Instant::now();
294	            let method = req.method.clone();
295	            let request_id = req.request_id.clone();
296	            let (mut res, route, suppress_body) = app.handle(req).await;
297	            res.header("X-Request-Id", request_id);
298	            metrics.record(&method, res.status, &route, start.elapsed());
299	            stream.write_all(&res.to_bytes(suppress_body)).await?;

