 7	const MAX_HEADER_BYTES: usize = 64 * 1024;
 8	const MAX_BODY_BYTES: usize = 16 * 1024 * 1024;
 9	
10	pub async fn read_request<R: AsyncRead + Unpin>(reader: &mut R) -> Result<Request> {
11	    let mut buf = Vec::new();
12	    let header_end = loop {
13	        let mut byte = [0_u8; 1];
14	        let n = reader.read(&mut byte).await?;
15	        if n == 0 {
16	            return Err(NanowebError::Parse(
17	                "connection closed before headers".into(),
18	            ));
19	        }
20	        buf.push(byte[0]);
21	        if buf.len() > MAX_HEADER_BYTES {
22	            return Err(NanowebError::Parse("headers too large".into()));
23	        }
24	        if let Some(pos) = find_header_end(&buf) {
25	            break pos;
26	        }
27	    };
28	    let head = std::str::from_utf8(&buf[..header_end])
29	        .map_err(|_| NanowebError::Parse("headers are not utf-8".into()))?;
30	    let mut lines = head.split("\r\n");
31	    let request_line = lines
32	        .next()
33	        .ok_or_else(|| NanowebError::Parse("missing request line".into()))?;
34	    let mut parts = request_line.split_whitespace();
35	    let method = parts
36	        .next()
37	        .ok_or_else(|| NanowebError::Parse("missing method".into()))?;
38	    let target = parts
39	        .next()
40	        .ok_or_else(|| NanowebError::Parse("missing target".into()))?;
41	    let version = parts
42	        .next()
43	        .ok_or_else(|| NanowebError::Parse("missing version".into()))?;
44	    if parts.next().is_some() || version != "HTTP/1.1" {
45	        return Err(NanowebError::Parse("invalid request line".into()));
46	    }
47	    let mut headers = HashMap::new();
48	    for line in lines {
49	        if line.is_empty() {
50	            continue;
51	        }
52	        let (name, value) = line
53	            .split_once(':')
54	            .ok_or_else(|| NanowebError::Parse("malformed header".into()))?;
55	        headers.insert(name.trim().to_ascii_lowercase(), value.trim().to_string());
56	    }
57	    let already = buf[(header_end + 4)..].to_vec();
58	    let body = if header_eq(&headers, "transfer-encoding", "chunked") {
59	        read_chunked(reader, already).await?
60	    } else if let Some(len) = headers.get("content-length") {
61	        let len: usize = len
62	            .parse()
63	            .map_err(|_| NanowebError::Parse("invalid content-length".into()))?;
64	        if len > MAX_BODY_BYTES {
65	            return Err(NanowebError::Parse("body too large".into()));
66	        }
67	        read_fixed(reader, already, len).await?
68	    } else {
69	        Vec::new()
70	    };
71	    Ok(Request {
72	        method: Method::from(method),
73	        target: target.to_string(),
74	        version: version.to_string(),
75	        headers,
76	        body,
77	        params: HashMap::new(),
78	        client_ip: None,
79	        request_id: Uuid::new_v4().to_string(),
80	    })

