37	    pub async fn run<F, Fut>(&self, mut req: Request, handler: F) -> Result<Response>
38	    where
39	        F: FnOnce(Request) -> Fut,
40	        Fut: std::future::Future<Output = Result<Response>>,
41	    {
42	        for mw in &self.items {
43	            if let Some(res) = mw.before(&mut req).await? {
44	                return Ok(res);
45	            }
46	        }
47	        let snapshot = req.clone();
48	        let mut res = handler(req).await?;
