126	pub(crate) async fn handle_connection<S>(
127	    mut stream: S,
128	    app: Arc<App>,
129	    addr: Option<SocketAddr>,
130	) -> Result<()>
131	where
132	    S: AsyncRead + AsyncWrite + Unpin,
133	{
134	    let parsed = parser::read_request(&mut stream).await;
135	    let (response, suppress) = match parsed {
136	        Ok(mut req) => {
137	            if let Some(addr) = addr {
138	                req.client_ip = Some(addr.ip().to_string());
139	            }
140	            let suppress = matches!(req.method, Method::Head);
141	            let started = Instant::now();
142	            let method = req.method.clone();
143	            let route = req.path().to_string();
144	            let request_id = req.request_id.clone();
145	            let res = dispatch(app.clone(), req).await.unwrap_or_else(|e| {
146	                Response::new(StatusCode::INTERNAL_SERVER_ERROR, e.to_string())
147	            });
148	            app.metrics.observe(&method, &route, res.status, started);
149	            let mut res = res;
150	            res.headers.insert("x-request-id".into(), request_id);
151	            (res, suppress)
152	        }
153	        Err(_) => (Response::new(StatusCode::BAD_REQUEST, "bad request"), false),
154	    };
155	    stream.write_all(&response.serialize(suppress)).await?;
156	    stream.shutdown().await?;
157	    Ok(())
158	}
