12	fn render_section(template: &str, ctx: &Value) -> Result<String> {
13	    let mut out = String::new();
14	    let mut rest = template;
15	    while let Some(start) = rest.find("{{") {
16	        out.push_str(&rest[..start]);
17	        let after = &rest[start + 2..];
18	        let end = after
19	            .find("}}")
20	            .ok_or_else(|| NanowebError::Template("unclosed tag".into()))?;
21	        let tag = after[..end].trim();
22	        rest = &after[end + 2..];
23	        if let Some(name) = tag.strip_prefix('#') {
24	            let close = format!("{{{{/{}}}}}", name.trim());
25	            let pos = rest
26	                .find(&close)
27	                .ok_or_else(|| NanowebError::Template("unclosed section".into()))?;
28	            let inner = &rest[..pos];
29	            rest = &rest[pos + close.len()..];
30	            if let Some(Value::Array(items)) = lookup(ctx, name.trim()) {
31	                for item in items {
32	                    out.push_str(&render_section(inner, item)?);
33	                }
34	            }
35	        } else if let Some(name) = tag.strip_prefix('^') {
36	            let close = format!("{{{{/{}}}}}", name.trim());
37	            let pos = rest
38	                .find(&close)
39	                .ok_or_else(|| NanowebError::Template("unclosed inverted section".into()))?;
40	            let inner = &rest[..pos];
41	            rest = &rest[pos + close.len()..];
42	            if is_absent(lookup(ctx, name.trim())) {
43	                out.push_str(&render_section(inner, ctx)?);
44	            }
45	        } else if tag.starts_with('/') {
46	            return Err(NanowebError::Template("unexpected closing tag".into()));
47	        } else if let Some(v) = lookup(ctx, tag) {
48	            out.push_str(&escape(&value_to_string(v)));
49	        }
50	    }
51	    out.push_str(rest);
52	    Ok(out)
53	}
