59	fn is_absent(v: Option<&Value>) -> bool {
60	    match v {
61	        None | Some(Value::Null) | Some(Value::Bool(false)) => true,
62	        Some(Value::Array(a)) => a.is_empty(),
63	        _ => false,
64	    }
65	}

