37	            let body = route.response.clone();
38	            router.add(
39	                Method::from(route.method.as_str()),
40	                &route.path,
41	                move |_| {
42	                    let body = body.clone();
43	                    async move { Ok(Response::text(body)) }
44	                },
45	            );
46	        }
47	        if let Some(dir) = config.static_dir.clone() {
48	            router.add(Method::Get, "/static/*path", move |req| {
49	                let dir = dir.clone();
50	                async move {
51	                    crate::static_files::serve(dir, &req, "path")
52	                        .await
53	                        .or_else(|_| Ok(Response::new(StatusCode::NOT_FOUND, "not found")))
54	                }
55	            });
56	        }
57	        let mut stack = Stack::new();
58	        let mw = &config.middleware;
59	        if mw.logging {
60	            stack.push(Logging);
61	        }
62	        if mw.gzip {
63	            stack.push(Gzip);
64	        }
65	        if !mw.cors_origins.is_empty() {
66	            stack.push(Cors::new(mw.cors_origins.clone()));
67	        }
68	        if mw.csrf {
69	            stack.push(Csrf);
70	        }
71	        if let (Some(u), Some(p)) = (mw.basic_auth_user.clone(), mw.basic_auth_password.clone()) {
72	            stack.push(BasicAuth::new(u, p));
73	        }
74	        if let Some(cap) = mw.rate_limit_capacity {
75	            stack.push(RateLimit::new(
76	                cap,
77	                mw.rate_limit_refill_per_s.unwrap_or(1.0),
78	            ));
79	        }
80	        Ok(Self {
81	            config: config.clone(),
82	            app: Arc::new(App {
83	                router,
84	                stack,
85	                metrics: Metrics::new()?,
86	                health: Health::default(),
87	                metrics_path: config.metrics.clone(),
88	            }),
89	        })

