109	async fn read_line<R: AsyncRead + Unpin>(reader: &mut R, stash: &mut Vec<u8>) -> Result<String> {
110	    loop {
111	        if let Some(pos) = stash.windows(2).position(|w| w == b"\r\n") {
112	            let line = stash.drain(..pos).collect::<Vec<_>>();
113	            stash.drain(..2);
114	            return String::from_utf8(line)
115	                .map_err(|_| NanowebError::Parse("chunk line is not utf-8".into()));
116	        }
117	        let mut b = [0_u8; 1];
118	        if reader.read(&mut b).await? == 0 {
119	            return Err(NanowebError::Parse("unexpected eof in chunked body".into()));
120	        }
121	        stash.push(b[0]);
122	    }
123	}
