125	async fn read_chunked<R: AsyncRead + Unpin>(reader: &mut R, mut stash: Vec<u8>) -> Result<Vec<u8>> {
126	    let mut body = Vec::new();
127	    loop {
128	        let line = read_line(reader, &mut stash).await?;
129	        let size_hex = line.split(';').next().unwrap_or("").trim();
130	        let size = usize::from_str_radix(size_hex, 16)
131	            .map_err(|_| NanowebError::Parse("invalid chunk size".into()))?;
132	        if size == 0 {
133	            let _ = read_line(reader, &mut stash).await?;
134	            return Ok(body);
135	        }
136	        if body.len() + size > MAX_BODY_BYTES {
137	            return Err(NanowebError::Parse("body too large".into()));
138	        }
139	        while stash.len() < size + 2 {
140	            let mut tmp = vec![0; size + 2 - stash.len()];
141	            reader.read_exact(&mut tmp).await?;
142	            stash.extend(tmp);
143	        }
144	        body.extend(stash.drain(..size));
145	        if stash.drain(..2).collect::<Vec<_>>() != b"\r\n" {
146	            return Err(NanowebError::Parse("missing chunk terminator".into()));
147	        }
148	    }
149	}

